def _folded_audit_post_hazard(tid: str):
    """T-12719 — thin wrapper for the FOLDED shape of the T-0275 hazard state (third sibling of the
    two wrappers beside it). Wires the record's `commit:` equality to THE custody resolver
    `audit.audit_custody_commit` (T-12362/T-12564 — the same three predicates and two bounds `audit
    post`'s default subject and `task close` read) through the module-level `_custody_commit_sha`
    (T-12727 — one wiring, shared with the card-repair admission), tracked-at-HEAD to `git cat-file -e`, and the
    standing-verdict check to `worktree._last_audit_post_for_task` (T-11313 — the reader land's
    currency gate uses). All looked up at CALL time (module-globals / lazy libs), so `-C` rebinds and
    monkeypatching stay honoured."""
    def _tracked(rel: str) -> bool:
        r = _run_git_cap(["cat-file", "-e", f"HEAD:{rel}"], REPO_ROOT)
        return bool(r is not None and r.returncode == 0)

    def _fold_commit(rel: str):
        """The commit that last touched `rel` on this branch — the fold, when the record is clean."""
        r = _run_git_cap(["log", "-1", "--format=%H", "HEAD", "--", rel], REPO_ROOT)
        return (r.stdout or "").strip() if (r is not None and r.returncode == 0) else None

    def _kind_of(t: str, sha: str):
        """The journal's `kind` for THIS task's commit_landed naming `sha` (prefix-wise, the chain
        records short shas); None when no row of this task names it."""
        full = str(sha or "")
        for rec_sha, kind in _task_commit_landed_chain(t):
            rs = str(rec_sha or "")
            if len(rs) >= 7 and (full.startswith(rs) or rs.startswith(full)):
                return kind
        return None

    return task_mod._folded_audit_post_hazard(
        tid, REPO_ROOT=REPO_ROOT, _git_resolve_sha=_git_resolve_sha, _read_yaml=_read_yaml,
        _audited_custody_sha=_custody_commit_sha, _worktree_dirty_paths=_worktree_dirty_paths,
        _path_tracked_at_head=_tracked, _record_fold_commit=_fold_commit, _commit_landed_kind=_kind_of,
        _last_audit_post_event=lambda t: worktree_mod._last_audit_post_for_task(t, EVENTS_PATH),
        # T-13147 — the dirty re-pinned arm re-derives the re-pin through the SAME pure core
        # `task close` re-verifies the `custody_repin` marker with (never the marker itself).
        _repin_ship_admissible=lambda t, ship: not _ship_custody_repin_check(t, ship)[2])


