def _die(msg: str, code: int = 1, abort_class: "str | None" = None,
         abort_detail: "dict | None" = None) -> None:
    print(f"yitc-v2: {msg}", file=sys.stderr)
    # T-0269: carry the abort reason ON the SystemExit (NOT a process-global, per the task's "NO new
    # store/hook/flag" constraint) so cmd_land's centralized terminal-signal can emit `LAND: ABORT
    # <reason>`. Additive + side-effect-free: every other caller ignores the attr; the code/exit is
    # unchanged (still SystemExit(code)).
    e = SystemExit(code)
    e.yitc_reason = msg
    # T-0655: OPTIONAL stable structured abort code, carried the SAME way (on the SystemExit, not a
    # global). The land path tags each abort origin with a fixed code; cmd_land's except handler reads
    # it (getattr) and records it as land_completed{abort_class} so the repeated-abort backstop streaks
    # on a STABLE key, never on the mutable reason text (consult survivor — SPEC-0124 ceiling triage).
    # Every non-land caller leaves it None and is unaffected.
    if abort_class is not None:
        e.yitc_abort_class = abort_class
    # T-9240: OPTIONAL structured abort DETAIL (e.g. land verify-failure's failing test name(s) +
    # verify mode), carried the SAME way (on the SystemExit, not a global). cmd_land's except handler
    # reads it (getattr) and records the keys onto land_completed{abort} so a controller's recovery
    # line names the concrete cause. Every non-land caller leaves it None and is unaffected.
    if abort_detail is not None:
        e.yitc_abort_detail = abort_detail
    raise e


def _utc_now_iso() -> str:
    return _dt.datetime.now(_dt.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


# ── Actor attribution (T-10405) ───────────────────────────────────────────────────────────────────
# The authoring verbs (`task file` / `followup add` / `cross request`) stamp WHO wrote the record.
# Derived from the launch context — never asked for (owner directive 2026-07-11: zero added friction).
# The default value itself is homed in lib/memory.py (one home — CHARTER §P5).


def _registry_text() -> str:
    """The host registry as text — read-only provenance over EXTERNAL territory (D-0019). Unreadable /
    absent => "" (the attribution then degrades to DEFAULT_ACTOR: a record, not a gate)."""
    try:
        return Path(REGISTRY_PATH).read_text(encoding="utf-8")
    except Exception:
        return ""


def _actor(default: str = None) -> str:
    """This session's real actor — `memory_mod.resolve_actor` over the live registry (T-10405). The ONE
    host-side attribution call; the three authoring verbs inject it. The default resolves in the body,
    not the signature (T-11320) — a signature default is evaluated at def time and would import lib.memory
    on every load of this file."""
    return memory_mod.resolve_actor(memory_mod.DEFAULT_ACTOR if default is None else default, _registry_text())


def _server_actor() -> str:
    """This session's SERVER-ISSUED actor — `memory_mod.resolve_server_actor` over the live registry
    (T-11363). The sibling of `_actor()` above, and the difference is load-bearing: this one derives
    from the OS uid (`memory_mod.os_identity`), which no argument and no environment variable can move,
    so it is the only one fit to attribute an ACT. Unresolvable => `UNRESOLVED_ACTOR`, never a silent
    null and never a fabricated `ai-agent` (T-0358).
    """
    return memory_mod.resolve_server_actor(memory_mod.DEFAULT_ACTOR, _registry_text())


def _actor_vocabulary() -> frozenset:
    """The named actors a record may legally carry (the registry users) — `task file`'s `created_by`
    validator admits these BESIDE the TASK_CREATED_BY enum. Unreadable registry => empty => enum only
    (fail-closed: free text never reaches `created_by`)."""
    return memory_mod.actor_vocabulary(_registry_text())


def _lookup_identity_env() -> "tuple[str | None, str]":
    """Registry env-arm lookup (T-0554): the ONE iteration over SESSION_IDENTITY_REGISTRY['env'].

    Returns (carrier_name, value) for the first present (non-empty, stripped) carrier in
    precedence order, or (None, "") when all are absent. NON-dying — the single shared
    iteration site for both the fail-closed resolver and the best-effort config descriptor.
    """
    for var in SESSION_IDENTITY_REGISTRY["env"]:
        val = os.environ.get(var, "").strip()
        if val:
            return var, val
    return None, ""


def _assert_modeled_source_kind(source_kind: str) -> str:
    """Fail-closed registry guard (T-0554, AC2): a RESOLVED session-identity source_kind MUST map to a
    MODELED source class in SESSION_IDENTITY_REGISTRY — exactly `arg` (when the arg carrier is
    modeled) or `env:<NAME>` with NAME a registered env carrier. An unknown / unmodeled or
    ambiguous class is REJECTED (_die), never silently passed downstream. Reads ONLY the
    registry — the single authority on what a valid source class is.

    NOTE (T-10152): this validates a class that RESOLUTION READ FROM a carrier/arg. A freshly-MINTED
    identity (SPEC-0137 Rule 1, `_session_start_identity`) read NO carrier, so its provenance
    `minted_self_ref` is deliberately OUTSIDE this taxonomy and is NEVER routed through this assert —
    it is recorded verbatim on session_started as a non-carrier provenance value, not a resolution class.
    """
    if source_kind == "arg" and SESSION_IDENTITY_REGISTRY.get("arg"):
        return source_kind
    if source_kind.startswith("env:") and source_kind[4:] in SESSION_IDENTITY_REGISTRY["env"]:
        return source_kind
    _die(
        f"unmodeled session-identity source class {source_kind!r} — not in the carrier "
        "registry (T-0554 fail-closed; modeled classes: arg, env:<registered carrier>)"
    )


def _resolve_session_ref_with_source(arg_value: "str | None" = None) -> "tuple[str, str]":
    """Fail-closed session_ref resolution + source classification per D-0030 (T-0554).

    Returns (session_ref, source_kind). source_kind is a registry-MODELED class only (run
    through _assert_modeled_source_kind): `arg` for an explicit CLI --session-ref, else
    `env:<NAME>` for the first present carrier in SESSION_IDENTITY_REGISTRY['env'] precedence
    order. All sources absent → _die. No inference, no process-tree walk, no mtime fallback.
    This IS the source_kind production path — consumed by the live resolver now and by the
    filed session_started source_kind forensic follow-up (T-0557).
    """
    if arg_value is not None:
        v = arg_value.strip()
        if v:
            return v, _assert_modeled_source_kind("arg")
    name, val = _lookup_identity_env()
    if val:
        return val, _assert_modeled_source_kind(f"env:{name}")
    _die(
        "session_ref undetermined — no carried session id (SPEC-0137 Rule 5 fail-closed). Run "
        f"`bin/yitc-v2 session start` to mint one, or carry your session's {SELF_REF_ENV}. NO "
        "provider-carrier fallback exists (Rule 4)."
    )


def _expected_session_ref() -> "str | None":
    """The launcher-assigned `expected` contract value (T-0561) — read ONLY from the explicit
    EXPECTED_SESSION_REF_ENV input, NEVER via the carrier registry (env-resolution fallback for
    `expected` is FORBIDDEN — external concept-audit (3)). Returns the stripped value when the var
    is PRESENT and non-empty; None when the key is absent (interactive — no contract) OR present but
    blank (the AC2 corrupted-contract case — the self-check, not this accessor, decides the ABORT)."""
    if EXPECTED_SESSION_REF_ENV not in os.environ:
        return None
    return os.environ[EXPECTED_SESSION_REF_ENV].strip() or None


def _session_start_identity(arg_value: "str | None" = None) -> "tuple[str, str]":
    """`session start` identity: RESOLVE an explicit carried/worker/arg id, else MINT one (SPEC-0137
    Rule 1, T-10152). Returns (session_ref, source_kind).

    This is the Rule-1 bootstrap that RETIRED the T-10137 mint-and-carry-from-a-provider-carrier flow:
    a fresh interactive session's identity is a freshly-MINTED v2-owned uuid, NOT resolved from a
    PROVIDER env carrier (those were removed from SESSION_IDENTITY_REGISTRY['env'] — Rule 8b), so v2
    depends on no provider harness's env-var name (CHARTER §Principle-4b).

    Resolve-vs-mint precedence — MINT only when expected AND self-ref AND arg are ALL absent:
    - EXPLICIT `--session-ref` arg present → resolve via the untouched forensic reader
      `_resolve_session_ref_with_source(arg_value)` (source_kind `arg`, run through
      `_assert_modeled_source_kind`). Kept so an arg-sourced start is honored, not overridden by a mint.
    - EXPLICIT env identity present — a WORKER's frozen `expected` (dispatch sets both YITC_EXPECTED and
      the carrier YITC_SESSION_REF) OR an interactive session RE-running `session start` while carrying
      its own YITC_SESSION_REF → resolve via `_resolve_session_ref_with_source` (`env:YITC_SESSION_REF`).
      The worker self-check downstream still compares the resolved ref to `expected`.
    - No explicit identity, but the checkout is a STAMPED worktree → ADOPT the T-0362 stamp's ref;
      source_kind `worktree_stamp` (T-10246). SPEC-0137 Rule 3 makes the stamp AUTHORITATIVE for the write
      phase — "a PROJECTION of the one identity into the write locus, NOT a second id" — and Rule 2 already
      ranks it (selector 2) above the runtime records. Minting here would create exactly the second id Rule
      3 forbids, and it did: the anchor landed under the minted ref while `_emit_cli_invoked`'s receipt
      landed under the stamp (`_resolve_session_ref_for_envelope` → selector 2), so NEITHER ref carried both
      and every read-gate keyed on the stamp while the agent carried the mint. Adopting makes this bootstrap
      agree with the resolver it bootstraps. It does NOT re-stamp: a re-stamp IS an adoption of the worktree
      and stays reserved to the explicit, confirmed-dead-gated `worktree adopt` (see `_foreign_hold_report`).
    - No explicit identity (fresh interactive: no arg, no YITC_EXPECTED, no carried YITC_SESSION_REF) →
      MINT a fresh uuid; source_kind `minted_self_ref` — a NON-carrier provenance value (a mint read no
      carrier), deliberately OUTSIDE the env:*/arg carrier taxonomy `_assert_modeled_source_kind`
      validates, so it is recorded verbatim on session_started, NEVER routed through that assert.
      `worktree_stamp` is the same NON-carrier class and is likewise never routed through that assert.
    """
    if arg_value and arg_value.strip():
        return _resolve_session_ref_with_source(arg_value)
    if EXPECTED_SESSION_REF_ENV in os.environ or os.environ.get(SELF_REF_ENV, "").strip():
        return _resolve_session_ref_with_source()
    stamp = _read_worktree_stamp(REPO_ROOT)
    stamp_ref = (stamp or {}).get("session_ref")
    if stamp_ref:
        # FAIL CLOSED on POSITIVE evidence that this locus belongs to a DIFFERENT identity (SPEC-0137
        # Rule 5, audit-pre T-10246 finding 1). `_live_runtime_records` is selector 3's own reader — this
        # locus only, dead records already pruned (Rule 2.4) — so a record naming another session_id is
        # v2-owned proof of a second identity here. Refuse; do NOT mint, which would merely re-create the
        # split identity this leg exists to end.
        #
        # NOT gated on `_stamp_is_own`: for a carrier-less session that check is TAUTOLOGICAL — it compares
        # the stamp to `_resolve_session_ref()`, which rediscovers that same stamp via selector 2 and so is
        # always True. A guard that can never fire is worse than none (it reads as protection).
        #
        # Honest residual: an intruder with NO live record for this locus is indistinguishable from the
        # worktree's own carrier-less session, and still adopts. That is not a regression — every other
        # governed verb here ALREADY resolves the stamp — and it is precisely what Rule 2.2 ("a per-instance
        # locus by construction") + the T-0362 protocol ("a FOREIGN worktree is NEVER auto-resumed: do NOT
        # cd into it") assume. A session that CARRIES a ref never reaches this leg.
        others = sorted({r["session_id"] for r in _live_runtime_records()
                         if r.get("session_id") != stamp_ref})
        if others:
            _die(
                f"session_ref: this worktree is stamped by session {stamp_ref}, but a LIVE v2 session "
                f"record for this locus names {', '.join(others)} — refusing to adopt a foreign worktree's "
                "identity (SPEC-0137 Rule 5 fail-closed; T-0362 forbids auto-adoption). Carry your own "
                f"{SELF_REF_ENV} to work here, or — only once the holder is confirmed dead — adopt the "
                "worktree explicitly via `bin/yitc-v2 worktree adopt`."
            )
        return stamp_ref, "worktree_stamp"
    return _mint_session_id(), "minted_self_ref"


def _reset_frozen_session_ref() -> None:
    """Test seam (T-0561): clear the in-process frozen-ref snapshot so a single test process can
    exercise multiple worker identities. Production never calls this (one short-lived process per
    CLI invocation)."""
    global _FROZEN_SESSION_REF
    _FROZEN_SESSION_REF = None


# ── SPEC-0137 rediscovery resolver internals (T-10149) ────────────────────────────────────────────
# The interactive (non-worker) resolution is REDISCOVERY over v2-OWNED state, NEVER a provider env carrier
# (Rule 4). A resolving process locates its identity by trying, IN ORDER, the ENUMERATED selector set of
# Rule 2; the record's own-id match IS the identity, the other selectors only NARROW which record. All
# helpers below read ONLY v2-owned state (a v2-named carry env, the T-0362 worktree stamp, the T-10148
# runtime record, the journal anchor) — a grep of this call path finds no PROVIDER env-var NAME.

# Dormant Rule-6 resolver HOOK contract (T-10150 wires the setter): a v2-owned isolated-verify env holding
# the scenario's OWN session ref. When set, resolution HONORS it BEFORE probing any record, so a `land`
# verify test owns its OWN scenario identity and never inherits/rediscovers the launcher's (fu_54c5905adf9f).
# Unset here (dormant) — T-10150 owns `_run_verify_tests` setting it per-subprocess (card acceptance).
ISOLATED_VERIFY_ENV = "YITC_ISOLATED_VERIFY"


def _isolated_verify_scenario_ref() -> "str | None":
    """SPEC-0137 Rule 6 resolver leg (T-10149): the v2-owned isolated-verify scenario ref, or None. When
    set, `_rediscover_session_ref` returns it BEFORE any record probe so a hermetic verify test resolves
    its OWN scenario identity, never the launcher's leaked one. DORMANT until T-10150 sets the env."""
    return os.environ.get(ISOLATED_VERIFY_ENV, "").strip() or None


def _pid_alive(pid: "int | None") -> bool:
    """Signal-0 liveness (SPEC-0137 Rule 2.4) — True iff `pid` names a live process THIS uid may signal.
    A dead pid raises ProcessLookupError → False; EPERM (alive, not ours) counts as ALIVE (the process
    exists). A non-int / None → False (fail-closed: unprovable liveness is not credited)."""
    try:
        os.kill(int(pid), 0)
        return True
    except ProcessLookupError:
        return False
    except PermissionError:
        return True
    except (TypeError, ValueError, OSError):
        return False


def _record_is_live(rec: dict) -> bool:
    """A runtime record is LIVE iff its minting `pid` OR its `locus_key` (the session-LEADER pid) is alive
    (SPEC-0137 Rule 2.4). The leader check is what lets a record survive the interactive READ phase's
    separate short-lived CLI subprocesses (the minting subprocess pid is dead by the next verb, but the
    login-session leader lives); a FULLY dead session (leader gone too) is pruned — the P9 stale-record
    fix. In a single-process test the minting pid IS alive, so same-process records stay live."""
    if _pid_alive(rec.get("pid")):
        return True
    lk = rec.get("locus_key")
    return lk is not None and str(lk).isdigit() and _pid_alive(int(lk))


def _live_runtime_records() -> "list[dict]":
    """LIVE runtime records for the CURRENT locus (SPEC-0137 Rule 2.3/2.4): every valid record whose
    `locus_key` == this process's `_runtime_locus_key()` AND that passes `_record_is_live` (the MANDATORY
    dead-record prune BEFORE any ambiguity is declared). Cross-locus records are excluded — a record from
    a DIFFERENT login session is not a candidate for THIS one."""
    here = _runtime_locus_key()
    return [r for r in _read_runtime_records()
            if str(r.get("locus_key")) == here and _record_is_live(r)]


# T-10936 — the per-process NEGATIVE memo of `_ref_current_epoch_anchored` (which see for the WHY, the
# key, and why only a REFUSAL is cached). Entries are `(ref, <the read signature below>)`; the set lives
# and dies with the process — nothing is written to disk (a persisted identity-backing verdict would go
# stale exactly when identity matters).
_REF_BACKING_UNBACKED: set = set()

# T-12209 (SPEC-0190 rule 10) — the CREDIT twin of the set above, and the seam's ONE read scope.
#
# WHY IT IS THE SCOPE AND NOT A CACHE. A CLI invocation IS the request, so the process IS the scope
# rule 10 asks the WIRING SITE to establish; `_REF_BACKING_UNBACKED` has already been exactly that,
# for the refusal verdict, since T-10936. What made this necessary: `_emit_cli_invoked` asks the
# identity question TWICE in one process — once for the `carried_session_ref_unbacked` check and again
# ~30 lines later to stamp the gate-bearing `--help` receipt — and each ask re-derived the answer
# against a journal that had not moved. Measured on this repo 2026-09-07: `--help` reported folds 4 /
# rows_parsed 44120 over rows 14038 (3.14x) where every other light verb reported 2, i.e. exactly the
# same read set, paid twice. That is rule 10's shape — one seam, two views, each folding the same
# artifact for itself — and its remedy is ONE scope at the site, never a cache per view.
#
# WHY THE NEGATIVE-ONLY RULE COULD BE LIFTED, on its own stated grounds rather than around them.
# `_ref_current_epoch_anchored`'s docstring gives ONE reason a credit must not be remembered: `_decide`
# also keys on `_session_epoch()`, so an epoch advance turns a current-epoch credit into a stale-epoch
# refusal. The epoch is therefore IN THE KEY here, which removes exactly that decay. The only other way
# a credit can change is new/absent evidence, which is a journal WRITE, and a write moves size or
# mtime_ns — already in the key via `_events_read_signature`. So this set can hold a stale credit only
# if the journal changed without changing size or mtime_ns, which is the same assumption the negative
# set has always rested on. Entries are `(ref, signature, epoch)`; process-local, never persisted.
#
# THE `epoch` STORED IS THE ONE READ AT ENTRY, so a `/compact` landing mid-decision keys the entry to
# the epoch the verdict was actually taken under, and a later ask under the new epoch simply misses and
# re-decides live. Both directions then share ONE signature-stability rule at the store site: a verdict
# read off a journal that moved under the whole decision is never remembered, in either direction.
#
# WHY THIS PROSE LIVES HERE AND NOT BESIDE THE CODE IT EXPLAINS. `_ref_current_epoch_anchored`'s body
# is held by an AC3 STRUCTURAL guard (tests/test_session_ref_backing_concurrent_rewrite.py) asserting
# there is no iteration around the decision — a real and worthwhile guard, but tested by SUBSTRING over
# the source region with only the docstring stripped, so ordinary English in an in-region COMMENT trips
# its proxy. It did, three times, during T-12209 (deviation fingerprint
# `structural-source-guard-lexical-substring-proxy-trips-on-comment-prose`). Keeping the explanation
# out here keeps that region prose-light WITHOUT weakening the guard and without writing worse comments
# inside it; the guard's real subject, that region's control flow, is untouched by T-12209.
_REF_BACKING_BACKED: set = set()
# T-13296 — the only event types `_ref_current_epoch_anchored._decide` reads (the anchor reader +
# the seed-receipt reader), declared so its full read keeps those rows of ONE ref and nothing else.
_REF_BACKING_TYPES = ("session_started", "cli_invoked")


def _events_read_signature() -> tuple:
    """The identity+content signature of the journal `_ref_current_epoch_anchored` reads: (path, size,
    mtime_ns), or (path, None, None) when it cannot be stat'ed (absent / unreadable — still a legal,
    distinct key). The path is resolved by the SAME expression that check's `_attempt` reads
    (`EVENTS_APPEND_PATH` under `--read-only`, else the `EVENTS_PATH` default `_iter_events` takes) —
    coherent with SPEC-0078 §3's read/write split, and with the in-process test seam that monkeypatches
    `EVENTS_PATH` alone. Any append or in-place rewrite moves size or mtime_ns, so this is what makes
    the memo an EXACT-INPUT one: a changed journal is a different key, never a stale hit."""
    path = EVENTS_APPEND_PATH if READ_ONLY_ROOT is not None else EVENTS_PATH
    try:
        st = path.stat()
    except OSError:
        return (str(path), None, None)
    return (str(path), st.st_size, st.st_mtime_ns)


def _ref_current_epoch_anchored(ref: str, *, bounded: bool = False) -> bool:
    """CURRENT-EPOCH read-gate backing for a carried ref (SPEC-0137 Rule 2.1) — True iff the journal holds
    a `session_started` anchor for `ref` AND a seed-read receipt for `ref` stamped with the CURRENT context
    epoch. REUSES the read-gate's OWN evidence helpers (`_session_started_lower_bound` + `_seed_receipt_epochs`
    + `_session_epoch`) so a ref the read-gate would credit is exactly a ref the resolver honors (no parallel
    scan — P5). A HISTORICAL / foreign / cross-epoch anchor with no current-epoch receipt does NOT qualify
    (audit-pre finding: a stale anchor is not sufficient backing). These helpers take `ref` EXPLICITLY and
    `_session_epoch` keys on the provider transcript — NEITHER re-enters `_resolve_session_ref` (no recursion).

    TAIL-FIRST + BOUNDED RETRY — routed through the read-gates' OWN driver (T-10396 windowing, T-10409
    retry). This check reads the SAME journal, for the SAME class of receipt, as `_require_seed_read` /
    `_require_help_read` — and that journal is rewritten IN-PLACE by the reconcile (worktree.py
    `write_text`, NOT an atomic temp+rename), so a reader concurrent with a land can catch a TRUNCATED
    file and torn-MISS a durably present receipt. T-10115 hardened the two read-gates against exactly
    that; this reader was the last one still deciding a refusal on a SINGLE read, which surfaced as a
    spurious UNBACKED carry under concurrent-land load (the class suspected behind T-10404's one-off
    land-verify failure on tests/test_t10317_read_tolerant_session_ref.py).

    So the tail-first pass and the retry budget are BOTH inherited by delegating to
    `gates._gate_pass_tail_first` — the single home of that discipline (its docstring carries the
    monotonicity proof: a tail-window credit is provably also a credit under the full read, so only a
    would-be REFUSAL pays the full re-read). `_decide` IS the driver's decision hook, and the same two
    constants bound the budget (`_READ_GATE_RETRY_ATTEMPTS` × `_READ_GATE_RETRY_BACKOFF`) — one retry
    mechanism, not a second one (CHARTER §P5). Semantics on the pass path are unchanged
    (return-on-first-credit, single read); a genuine stale-epoch / unbacked ref still returns False,
    having paid a complete read of the history — the retry recovers a TRANSIENT torn read, it never
    waves through a real absence.

    PER-PROCESS NEGATIVE MEMO (T-10936). The REFUSAL path above is expensive by construction: it pays
    the tail probe AND the whole `_READ_GATE_RETRY_ATTEMPTS` budget of FULL journal walks, with a
    backoff sleep between attempts. Nothing on the caller chain held that answer, so ONE invocation
    re-derived it once per caller — measured 2026-08-09 under cProfile: an un-backed carry made
    `journal query --fleet-verdict` re-walk the 266k-row journal ~35 times (the classifier calls the
    tolerant own-check once per task), 9.3M json.loads, 162s of a 175s run vs 6.5s for the same command
    with a BACKED ref. So a repeat question with a provably identical answer is now answered from
    `_REF_BACKING_UNBACKED` instead of re-read.

    THE KEY IS THE FULL INPUT ENVELOPE, never the ref alone: `(ref, journal path, size, mtime_ns)` of
    the SAME journal `_attempt` reads. Any append or in-place rewrite moves size or mtime_ns, so a ref
    that BECOMES backed mid-process (a `session start` writing its own anchor+receipt; a concurrent
    land finishing its rewrite after a torn read) MISSES the memo and is re-decided live. The signature
    is taken before the decision and RE-TAKEN after it, and the entry is stored only when the two
    match — so a verdict read off a journal that changed mid-decision is never cached. A memo hit
    therefore means exactly: "this ref was decided un-backed against a journal provably unchanged
    across the whole decision".

    BOTH DIRECTIONS ARE MEMOIZED, AND THE TWO KEYS DIFFER BY EXACTLY THE ONE THING THAT DECAYS
    (T-12209). This was NEGATIVE-ONLY until T-12209, on ONE stated ground: a credit is the verdict that
    can decay WITHOUT the journal changing, because `_decide` also keys on `_session_epoch()` (the
    provider transcript's `/compact` count) and an epoch advance turns a current-epoch credit into a
    stale-epoch refusal. That ground is MET rather than argued around — the credit key CARRIES the
    epoch (`_REF_BACKING_BACKED`, entries `(ref, signature, epoch)`), so the one decay path it named is
    now a MISS and the verdict is re-decided live. The only OTHER way either verdict can change is new
    or vanished evidence, which is a journal WRITE, and a write moves size or mtime_ns — already in the
    signature both keys share. A refusal needs no epoch in its key because an epoch advance never
    UN-stales a receipt.
    WHY THE CREDIT SIDE IS WORTH HAVING — the original text weighed this correctly for its time, and
    what changed is the measurement, not the reasoning. A credit does return on the FIRST tail read
    (the hot path the T-10396 window made cheap), while the refusal is the pass that spends the full
    budget — so the refusal was the one worth remembering. But `_emit_cli_invoked` asks this question
    TWICE in one process (the `carried_session_ref_unbacked` check, then the gate-bearing `--help`
    receipt stamp), so that cheap read was paid twice: measured 2026-09-07 at `--help` folds 4 /
    rows_parsed 44120 over rows 14038, against every other light verb's 2. Remembering the credit is
    this seam's ONE request-scoped read scope (SPEC-0190 rule 10 — the process IS the request), never a
    cache bolted onto a view. NEITHER direction can weaken the SPEC-0137 Rule-5 fail-closed posture: a
    miss re-decides live, and `_decide` is untouched.

    Process-local by construction (a module global, dropped when the process exits) — NOTHING is
    persisted, and deliberately so: a session-ref backing verdict written to disk would go stale
    exactly when identity matters. `_carried_ref_backed`'s live-runtime-record short-circuit is
    likewise NOT memoized — it is a single cheap file read, and leaving it live keeps a record written
    mid-process instantly visible.

    CHANGE-KEYED RE-DECIDE (T-11287). The T-10409 budget above is COUNT-based and BLIND: it re-reads a
    fixed number of times whether or not the journal was actually moving, so under real contention
    every attempt in the budget can land inside the same rewrite window. Measured 2026-08-18 at 4
    worker lines / 3 concurrent lands: `land` refused with an UNBACKED verdict for a ref that was alive
    and working in every other verb of the same shell (fingerprint
    `concurrent-land-journal-rewrite-plus-rawgit-unstamped-locus-fails-session-ref-backing`).

    But the evidence needed to tell those two situations apart was already being computed here and then
    thrown away: the read signature is taken BEFORE the decision and RE-TAKEN after it, and was used
    only to SUPPRESS the memo. So a NOT-credited verdict whose two signatures DIFFER — positive proof
    that the file moved under the whole decision — is now re-decided EXACTLY ONCE against the settled
    file, keyed on that observation rather than on a count.

    NOT A SECOND RETRY MECHANISM (CHARTER §P5 — the constraint the T-10409 paragraph above sets). The
    re-decide RE-ENTERS `gates._gate_pass_tail_first`; it introduces no attempts constant, no backoff,
    no sleep and no loop, and the driver's budget is untouched. The two answer different questions at
    different altitudes: the driver asks "was THIS read torn?" (count-bounded, blind), this asks "did
    the file move under the WHOLE decision?" (evidence-keyed, single-shot). It is BOUNDED TO ONE by
    construction — a single `if`, never a poll loop — so a journal that keeps moving costs one extra
    decision, not an unbounded wait.

    It CANNOT weaken the SPEC-0137 Rule 2.1 fail-closed direction, and not by care: `_decide` is
    untouched, so the re-read re-runs the SAME predicate and a genuine absence returns False on BOTH
    passes — there is no path on which absent evidence becomes a credit. Nor can a broken discriminator
    open anything: `_events_read_signature` degrades to `(path, None, None)` on a stat failure, so an
    unreadable journal reads STABLE (no re-decide, refusal stands) and a mid-decision transition costs
    at most one extra pass that still refuses. Pinned by
    tests/test_session_ref_backing_concurrent_rewrite.py (the differential arm mutates the signature
    back to stable and watches the same fixture refuse).

    BOUNDED MODE (T-12671) — `bounded=True` reads AT MOST THE TAIL: exactly one `_attempt(tail=True)`,
    no driver loop, no full-read retry budget, no T-11287 re-decide. It exists for ONE caller — the
    SPEC-0050 §8a TOLERANT branch of `gates._require_seed_read` — where the answer is not load-bearing:
    a tolerant verb turns an UNBACKED verdict into the `selected_source=` telemetry field and the
    BOUND-2 warning and then runs anyway; it never refuses and never writes, so the certainty the full
    budget buys (a refusal must be final) protects nothing there. MEASURED before this mode (cProfile,
    2026-09-17, engine journal ~2.5M rows across segments): `-C <born-consumer> --read-only profile
    --json` spent 44.15s of 44.43s here — tail probe + 3 full segment walks + the re-decide — to
    conclude a verdict the caller then tolerated; against the 60s YITC_PROFILE_SNAPSHOT_TIMEOUT that
    floor left no headroom, and under load (75.0s measured) the SPEC-0145 resolver timed out: X-1464 (a
    healthy <project> deploy refused) and the 2026-09-16 five-branch land freeze on
    tests/test_t12090_self_activation_e2e.py — journal fingerprint
    `t12090-self-activation-e2e-flakes-under-pool-load-blocks-unrelated-lands` (5 captures) — are the
    same defect. Attribution for the numbers above: that fingerprint + X-1464. The strict keyer and every other
    caller keep the default. MEMO DISCIPLINE in this mode: a tail CREDIT is stored (sound by the
    driver's own monotonicity proof — a tail credit is a full-read credit); a tail REFUSAL is NEVER
    stored in `_REF_BACKING_UNBACKED`, because it is not a full-read verdict and a later STRICT caller
    in the same process would otherwise trust it and skip the full reads it owes (fail-closed)."""
    if not ref:
        return False

    sig = _events_read_signature()
    memo_key = (ref, sig)
    if memo_key in _REF_BACKING_UNBACKED:
        return False
    # T-12209 — the CREDIT direction of the same per-process scope; see `_REF_BACKING_BACKED`.
    epoch = _session_epoch()
    if (ref, sig, epoch) in _REF_BACKING_BACKED:
        return True
    _segments: dict = {}   # T-13296 — this decision's per-segment rows; dies with the call (rule 10(a))
    _skip_noted: list = []   # T-13370 — the horizon's skipped segments are reported once per decision
    _segment_paths = events.segment_paths   # bound here: `_attempt` shadows `events` with its rows

    def _decide(events) -> bool:
        lb = _session_started_lower_bound(ref, events=events)
        if lb is None:
            return False
        return _session_epoch() in _seed_receipt_epochs(ref, lb, events=events)

    def _attempt(*, tail: bool):
        """One read attempt in the driver's `(credited, payload, bounded)` contract. `payload` is the
        snapshot the decision was taken on — this check phrases no refusal from it (the resolver owns
        the diagnostic), so it is carried only to satisfy the contract."""
        # T-10859: read the SESSION-IDENTITY journal. This check credits THIS session's own anchor +
        # seed receipt, and those live wherever this session WRITES — so under `--read-only` it must
        # read the reader's own journal, not the `-C` target's (which cannot hold them, making a scan
        # of it meaningless). Same coupling the gate candidates resolve; kept coherent at both sites,
        # since this helper's contract is "a ref the read-gate would credit is a ref the resolver honors".
        #
        # SCOPED TO THE MODE, deliberately: outside read-only this stays on `_iter_events()`'s own
        # EVENTS_PATH default rather than the (then identical) EVENTS_APPEND_PATH global, because the
        # in-process test seam monkeypatches `yitc.EVENTS_PATH` alone — reading the global here instead
        # silently bypassed that redirect and sent ~3 suites at the real journal.
        ev = EVENTS_APPEND_PATH if READ_ONLY_ROOT is not None else None
        # T-13139 — inside a one-pass scope that holds this journal AND captured `ref`'s lines (the
        # debt echo declares every carried ref), decide from those lines: they hold every row
        # `_decide` can match, and the scope's snapshot IS the whole file, so `bounded=False` — the
        # same answer T-12035's memo branch in `_iter_events_tail` gives. Otherwise both reads below
        # are a second physical read of a journal the scope already folded, and the full one
        # materialises it.
        #
        # T-13330 — a keep_all scope (task close's) may have walked only the TASK HORIZON: its rows are
        # then a NARROWED snapshot, exactly the tail attempt's shape — so the tail attempt decides on
        # them and reports `bounded`, and the full attempt asks the SAME scope for the whole history
        # (one recorded extension of its walk, never a second fold). The driver below is unchanged.
        _jp = ev if ev is not None else EVENTS_PATH
        # T-13337 — a keep_all scope answers from the SPEC-0190 summary window (`_scoped_session_window`,
        # the seed and help gates' own source), never the whole history: a refusal walks no archive
        # segment wholly older than the window (AC2).
        shared = _scoped_session_window(_jp, ref, _decide if tail else None, not tail)
        if shared is not None:
            return _decide(shared[0]), shared[0], shared[1]
        scoped = journal_mod.scope_needle_rows(_jp, ref, whole=not tail)
        if scoped is not None:
            return _decide(scoped), scoped, not journal_mod.scope_is_whole(_jp)
        if tail:
            # T-13289: walk THIS ref's rows back only as far as `_decide` needs to credit (its horizon).
            events, bounded = _iter_events_tail(ev, session_ref=ref, settled=_decide)
        elif _held_session_walk(_jp, ref) is not None:
            # T-13370 — the FULL read RESUMES the walk the tail attempt took (`_SessionWalk.refresh`:
            # finish it to the SPEC-0190 summary-window floor, then read only bytes appended since; a
            # moved or torn history starts a fresh walk, T-10115). The same full read the seed and help
            # gates' refusal retries take (fp1:72f442162d197019), so the resolver refuses on the read
            # gate's own horizon — "a ref the read-gate would credit is a ref the resolver honors" —
            # and an unbacked carry no longer re-folds every segment the walk already read (the cron
            # sweep: 48 + 125 folds over 123 segments). The segments the horizon leaves unopened are
            # reported once, as SPEC-0190 rule 4 class 2 skips.
            events, bounded = _iter_events_tail(ev, session_ref=ref, full=True)
            walk = _held_session_walk(_jp, ref)
            if walk is not None and not _skip_noted:
                _skip_noted.append(True)
                try:
                    journal_mod.note_segments_skipped(
                        max(0, len(_segment_paths(_jp)) - len(walk._segs)))
                except OSError:
                    pass
        elif journal_mod.accepts_declaration(_iter_events):
            # T-13296 — the FULL read, DECLARED: only the rows `_decide` can match (this ref's anchors
            # and receipts), each segment folded once per decision unless its bytes moved (a torn read
            # — then, and only then, the budget's re-read happens). Undeclared, this materialised the
            # whole history up to 3 times for every unbacked carry: 10.78 GB per cron sweep, measured.
            events, bounded = list(_iter_events(ev, types=_REF_BACKING_TYPES, segment_cache=_segments,
                                                pred=lambda e: e.get("session_ref") == ref)), False
        else:
            events, bounded = list(_iter_events(ev)), False   # an injected single-argument reader
        return _decide(events), events, bounded

    if bounded:
        # T-12671 — the tail alone (see BOUNDED MODE above). ONE physical read; a non-narrowed tail
        # (short journal) is the full file and still ONE read. The credit memo is shared with the
        # default path because a tail credit is sound; the refusal memo is deliberately NOT written.
        credited, _snapshot, _narrowed = _attempt(tail=True)
        if credited and _events_read_signature() == sig:
            _REF_BACKING_BACKED.add((ref, sig, epoch))
        return credited

    credited, _snapshot = gates._gate_pass_tail_first(_attempt, _sleep=time.sleep, tail_enabled=True)
    after = _events_read_signature()
    if not credited and after != sig:
        # T-11287 — the CHANGE-KEYED re-decide. The signatures straddle the WHOLE decision, so a
        # mismatch is positive evidence that the journal was rewritten UNDER it (only an append or an
        # in-place rewrite moves size/mtime_ns) — i.e. this refusal was computed against a moving file
        # and is not yet trustworthy. Re-decide ONCE against the settled file, rebasing the signature
        # so the memo below keys on the pass that actually survives.
        sig, memo_key = after, (ref, after)
        credited, _snapshot = gates._gate_pass_tail_first(_attempt, _sleep=time.sleep, tail_enabled=True)
        after = _events_read_signature()
    if after == sig:
        # T-12209 — one signature-stability discipline, both directions: a verdict read off a journal
        # that moved under the decision is never remembered. See `_REF_BACKING_BACKED` above.
        if credited:
            _REF_BACKING_BACKED.add((ref, sig, epoch))
        else:
            _REF_BACKING_UNBACKED.add(memo_key)
    return credited


def _held_session_walk(path, ref: str):
    """T-13370 — the `_SessionWalk` the request's preamble scope (`_preamble_read_scope`, installed by
    `main()`) already holds for (journal, ref): the walk a tail attempt took. None outside that scope or
    before any walk. The key is the one `_iter_events_tail` stores under, so a hit is that very walk."""
    scope = getattr(_SESSION_TAIL_TLS, "scope", None)
    if not scope:
        return None
    try:
        held = scope.get((str(Path(path).resolve()), ref))
    except OSError:
        return None
    return held[1] if held is not None else None


def _carried_ref_backed(ref: str, *, bounded: bool = False) -> bool:
    """Is a carried v2-own self-ref BACKED by live v2-owned evidence (SPEC-0137 Rule 2.1 bound)? True iff
    a LIVE runtime record keyed by `ref` exists (the strong, post-mint/record path) OR `ref` is
    current-epoch read-gate anchored (the transitional bridge the option-A amendment permits, and the
    shape existing anchor-seeding tests + the pre-T-10152 interactive mint produce). A provider carrier is
    NEVER consulted. An UNBACKED carry (stale/foreign/typo) is NOT honored → the resolver falls through.
    `bounded` (T-12671) threads the tail-only read into the epoch-anchored check — the tolerant seed-gate
    branch alone passes it; the live runtime-record short-circuit ahead of it is unchanged."""
    rec = _read_runtime_record(_runtime_record_path(ref))
    if rec is not None and _record_is_live(rec):
        return True
    return _ref_current_epoch_anchored(ref, bounded=bounded)


def _try_rediscover_session_ref_with_source(*, allow_locus_stamp: bool = True, bounded_backing: bool = False) -> "tuple[str | None, str, str | None]":
    """NON-DYING interactive rediscovery CORE over v2-OWNED state (SPEC-0137 Rule 2, T-10149) — NO provider
    env carrier is read. Returns (ref, "ok", source) on a resolved id, else (None, reason, None) with reason
    in {"ambiguous","absent"}. The CALLER decides the outcome: the fail-closed governance-KEYING resolver
    (`_resolve_session_ref`) turns a None into the matching Rule-5 `_die`; the best-effort EVENT-ENVELOPE
    resolver (`_resolve_session_ref_for_envelope`) falls back instead. Extracting this core is the auditor-F1
    fix — the envelope path must NOT call a dying resolver and swallow its already-printed diagnostic.
    Selector order: (hook) isolated-verify scenario ref → (1b) BOUNDED v2-own carry → (2) worktree gitdir
    stamp → (3) the sole LIVE runtime record for this locus (dead records already pruned, Rule 2.4).

    T-10318: `source` NAMES the selector that won — the fact this core already decides and, before this
    change, DISCARDED. It is ENVELOPE PROVENANCE (what got recorded), never a resolution carrier CLASS, so
    it is NEVER routed through `_assert_modeled_source_kind` (exactly as `minted_self_ref` /
    `worktree_stamp` already are not, on the `session_started` side). This function DECIDES the selector at
    ONE site; every reporter merely reads it back — no parallel re-derivation. Resolution is UNCHANGED:
    every selector returns the same ref, in the same order, as before (observability only)."""
    # Rule-6 hook (dormant until T-10150): a hermetic verify test's OWN scenario ref wins before any record.
    iv = _isolated_verify_scenario_ref()
    if iv:
        return iv, "ok", "isolated_verify"
    # Selector 1b — the BOUNDED v2-own carried self-ref (provider-neutral). Honored ONLY when BACKED by
    # live v2 evidence; an UNBACKED carry falls through (no cross-credit — the retired X-0158 failure mode).
    carried = os.environ.get(SELF_REF_ENV, "").strip()
    # T-12671: a tolerant caller bounds this read. The kwarg is passed ONLY when set, so the default
    # path keeps the pre-change call shape byte-for-byte (test fakes of `_carried_ref_backed` that
    # take a bare `ref` — tests/test_t10318 — keep working; the strict keyer never reaches the kwarg).
    if carried and (_carried_ref_backed(carried, bounded=True) if bounded_backing
                    else _carried_ref_backed(carried)):
        # Spelled from SELF_REF_ENV, never a literal, so the carrier name has ONE home (P5).
        return carried, "ok", f"env:{SELF_REF_ENV}"
    # Selector 2 — the write-phase worktree stamp (T-0362): a per-instance locus by construction. Absent
    # on the shared main checkout (no stamp there) → fall through. `allow_locus_stamp=False` SKIPS it
    # (T-11911): "by construction" holds only while the process RUNS in that instance, and `-C` breaks
    # exactly that — see `_repo_root_is_caller_locus`.
    if allow_locus_stamp:
        stamp = _read_worktree_stamp(REPO_ROOT)
        if stamp and stamp.get("session_ref"):
            return stamp["session_ref"], "ok", "worktree_stamp"
    # Selector 3 — the sole LIVE runtime record for this locus. Exactly one → that id; MULTIPLE live records
    # + no distinct selector → Rule 5 ambiguity; none → Rule 5 absence.
    ids = sorted({r["session_id"] for r in _live_runtime_records()})
    if len(ids) == 1:
        return ids[0], "ok", "runtime_record"
    if len(ids) > 1:
        return None, "ambiguous", None
    return None, "absent", None


def _try_rediscover_session_ref(*, allow_locus_stamp: bool = True) -> "tuple[str | None, str]":
    """The (ref, reason) VIEW of `_try_rediscover_session_ref_with_source` (T-10318) — the pre-existing
    2-tuple shape its three callers (`_resolve_session_ref`, `_try_resolve_session_ref`,
    `_resolve_session_ref_for_envelope`) consume. A thin projection, NOT a second resolution path: the
    selector is decided once, in the core above."""
    ref, reason, _source = _try_rediscover_session_ref_with_source(allow_locus_stamp=allow_locus_stamp)
    return ref, reason


_REDISCOVERY_SELECTORS_TRIED = (
    "isolated-verify scenario ref, the carried YITC_SESSION_REF, the worktree stamp, the runtime records"
)


def _resolve_session_ref(*, allow_locus_stamp: bool = True) -> str:
    """GOVERNANCE-KEYING session_ref resolution — v2-OWNED, provider-agnostic, FAIL-CLOSED (SPEC-0137
    Rule 2 two-role scope, T-10149). This resolves the identity that KEYS a governance decision: the
    read-gate anchor/seed-receipt match (`_require_reads`), the worktree-stamp own-check (`_stamp_is_own`
    / `_write_worktree_stamp`), journal-sync keying, aspect-audit. There "who am I, provably" MUST be
    bounded — an unbacked/ambiguous identity FAILS CLOSED, never guesses. It is DELIBERATELY NOT the
    event-envelope stamper: `_append_event`'s DEFAULT routes through `_resolve_session_ref_for_envelope`
    (best-effort, never dies) so the fail-closed rewrite does not break the universal emit path.

    STARTUP-FROZEN worker identity (T-0561 part 2, UNCHANGED): when the launcher-assigned `expected`
    contract value is present it IS the frozen session_ref — the bounded v2-own carry, selector-1a —
    MATERIALIZED into _FROZEN_SESSION_REF so later in-process calls return it with no re-read (audit-pre F2).
    Absent `expected` (interactive / non-worker) → the Rule-2 rediscovery core with a Rule-5 fail-closed
    diagnostic — NO provider env var at resolution (Rule 4). This REPLACES the prior provider-carrier chain
    (`_resolve_session_ref_with_source()[0]`) that landed a missed carry under a drifting provider key
    (X-0158). Bootstrap-exemption (Rule 1): `session start` resolves-or-MINTS via
    `_resolve_session_ref_with_source` (untouched) and is the sole verb needing no record."""
    global _FROZEN_SESSION_REF
    if _FROZEN_SESSION_REF is not None:
        return _FROZEN_SESSION_REF
    # Selector 1a — Worker contract PRESENT (T-0561, UNCHANGED): YITC_EXPECTED is the EXCLUSIVE, fail-closed
    # keying authority. A present-but-blank/invalid contract ABORTS rather than falling through — carrier-use
    # for worker keying stays structurally impossible. A pre-abort DIAGNOSTIC emit passes an explicit
    # session_ref to _append_event and never reaches this _die.
    if EXPECTED_SESSION_REF_ENV in os.environ:
        frozen = _expected_session_ref()
        if not frozen:
            _die(
                f"session_ref: {EXPECTED_SESSION_REF_ENV} is set but blank/invalid — refusing to fall "
                "through (fail-closed worker identity contract; T-0561 / consult t0561-freeze-fix-fork). "
                "Re-dispatch with a valid expected ref."
            )
        _FROZEN_SESSION_REF = frozen
        return frozen
    # Interactive / non-worker (contract var ABSENT) → v2-owned rediscovery (SPEC-0137 Rule 2/4/5).
    ref, reason = _try_rediscover_session_ref(allow_locus_stamp=allow_locus_stamp)
    if ref is not None:
        return ref
    # T-11011 (X-0843): on a `-C <consumer>` invocation this identity refusal is the SECOND of two
    # independent consumer-side carriers, so it names BOTH — the operator who just fixed `-C` must not
    # discover carrier 2 only by hitting it. Keyed on the ENUMERATED consumer-target fact
    # (`_is_consumer_build()`, the same common-dir signal used everywhere else — an engine linked
    # worktree is NOT a consumer), never on message text; empty for an engine-local refusal, which stays
    # byte-identical. Computed ONLY on these dying paths.
    _pair = _consumer_carrier_pair_advisory() if _is_consumer_build() else ""
    if reason == "ambiguous":
        _die(
            "session_ref: multiple live v2 session records for this locus and no distinct selector — "
            "refusing to guess (SPEC-0137 Rule 5). Tried selectors: " + _REDISCOVERY_SELECTORS_TRIED
            + ". Supply a selector (carry your session's YITC_SESSION_REF) or open a worktree." + _pair
        )
    # Rule-5 absence splits into two OPERATOR situations that need OPPOSITE advice (T-10244). Read the
    # carry for the MESSAGE only — never as a selector (Rule 2.1 already rejected it above as unbacked).
    carried = os.environ.get(SELF_REF_ENV, "").strip()
    if carried:
        _die(
            f"session_ref undetermined — the carried {SELF_REF_ENV}={carried!r} is UNBACKED: no live v2 "
            "session record in this locus backs it, so it cannot key a governance decision (SPEC-0137 "
            "Rule 2.1 / Rule 5 fail-closed). TWO CAUSES — check the transient one FIRST (T-10409): "
            "(1) TRANSIENT — a concurrent `land` may be mid-rewrite of this journal, and a truncated "
            "read torn-misses a receipt that IS durably present. The backing check already re-read it a "
            "bounded number of times, so this is unlikely — but if a land is running right now, RE-RUN "
            "THIS VERB ONCE before concluding staleness. (2) STALE — the carry really is dead/foreign. "
            "Then find where this ref IS backed (run from the checkout/worktree whose session minted "
            f"it), or drop the carry (`unset {SELF_REF_ENV}`) and start a session there. Either way, "
            "re-running `bin/yitc-v2 session start` will NOT re-back this ref — it MINTS A NEW id and "
            f"deepens the split. Tried: {_REDISCOVERY_SELECTORS_TRIED}. NO provider-carrier fallback "
            "exists (Rule 4)." + _pair
        )
    # T-13120: a `-C <consumer>` refusal LEADS with one plain line + the exact, copyable command for THIS
    # path — a post-install newcomer running `-C <path> init` first has no relative `bin/yitc-v2`. The
    # internal diagnostic follows as detail (T-12935 / T-11011 key on it); engine-local text unchanged.
    lead, mint = "", "Run `bin/yitc-v2 session start` to mint one"
    if _pair:
        lead = ("This project has no active session yet — run this command first, then re-run yours:\n"
                f"  {shlex.quote(str(ENGINE_ROOT) + '/bin/yitc-v2')} -C {shlex.quote(str(REPO_ROOT))} session start\nDetails: ")
        mint = "That `session start` mints one"
    _die(
        lead + "session_ref undetermined — no live v2 session record for this locus and no backed carry "
        f"(SPEC-0137 Rule 5 fail-closed). {mint}, or carry your "
        f"session's {SELF_REF_ENV}. Tried: {_REDISCOVERY_SELECTORS_TRIED}. NO provider-carrier fallback "
        "exists (Rule 4)." + _pair
    )


def _try_resolve_session_ref(*, allow_locus_stamp: bool = True) -> "str | None":
    """NON-DYING twin of the governance-KEYING resolver `_resolve_session_ref` (SPEC-0137, T-10167):
    returns the keyer's ref when resolvable, else None — it NEVER `_die`s. Its ONLY use is a BEST-EFFORT
    gate-receipt CO-STAMP (the `cli_invoked` receipt stamping in `_cli_invoked_resource_summary`): that
    path wants "the same ref the keyer would resolve, or nothing — quietly". Calling `_resolve_session_ref`
    there and swallowing its `SystemExit` swallowed the CONTROL-FLOW but NOT `_die`'s already-printed
    stderr line, leaking a scary `session_ref undetermined ... fail-closed` diagnostic on the NORMAL
    happy path (fresh mint / a non-propagated carry). This is the SPEC-0137 comment-919 principle — "a
    best-effort path must NOT call a dying resolver and swallow its already-printed diagnostic" — applied
    to the gate-receipt co-stamp sites (the envelope path already got it via `_try_rediscover_session_ref`).
    Mirrors the keyer's selector order EXACTLY, minus the death: frozen worker ref → EXPECTED contract
    (valid→ref, blank→None, NOT the keyer's blank-contract ABORT) → the non-dying rediscovery core
    (absent/ambiguous→None). The FAIL-CLOSED keyer stays the SOLE governance gate — a genuine gated verb
    still resolves via `_resolve_session_ref` and still emits the Rule-5 diagnostic on a real no-session."""
    return _try_resolve_session_ref_with_source(allow_locus_stamp=allow_locus_stamp)[0]


def _try_resolve_session_ref_with_source(*, allow_locus_stamp: bool = True, bounded_backing: bool = False) -> "tuple[str | None, str | None]":
    """(ref, source) twin of `_try_resolve_session_ref` (T-10318) — same selectors, same order, same
    never-`_die` contract, plus the NAME of the selector that won. Returns (None, None) when unresolvable.

    Exists so a GATE-BEARING `cli_invoked` receipt (`--help`) can record the selector that actually
    produced the ref stamped on it, instead of collapsing to the `explicit` bucket (audit-pre finding 1).
    The frozen snapshot and the EXPECTED contract are ONE class — `expected_contract` — because the frozen
    value IS the materialized expected (`_resolve_session_ref` sets it only on that leg), so they are not
    two distinct provenances. NOT a governance path: this reads the keyer's ROLE (would the keyer resolve,
    and from where?) for RECORDING only; no caller gates on it."""
    if _FROZEN_SESSION_REF is not None:
        return _FROZEN_SESSION_REF, "expected_contract"
    if EXPECTED_SESSION_REF_ENV in os.environ:
        exp = _expected_session_ref()
        # A blank/invalid contract is None HERE (the keyer, not this twin, owns the ABORT) → no source.
        return (exp, "expected_contract") if exp else (None, None)
    ref, _reason, source = _try_rediscover_session_ref_with_source(
        allow_locus_stamp=allow_locus_stamp, bounded_backing=bounded_backing)
    return ref, source


def _resolve_session_ref_for_envelope() -> str:
    """BEST-EFFORT event-envelope stamp — NEVER fail-closed (SPEC-0137 Rule 2 two-role scope, T-10149).
    This is `_append_event`'s DEFAULT session_ref resolver: an emit is append-only PROVENANCE that must
    NEVER be lost or blocked, so this NEVER `_die`'s. It is also PROVIDER-FREE (auditor F2) — it never
    consults a provider carrier, so a stamped session_ref is at worst a v2-own best-effort value or the
    'unresolved' sentinel, NEVER a provider id (no second provider-coupled surface). A best-effort stamp
    is EXPLICITLY NON-AUTHORITATIVE: no governance consumer keys off a session_ref read back FROM an event
    line — the keying consumers resolve LIVE via `_resolve_session_ref` — so a best-effort stamp can never
    become a parallel identity path. GATE-BEARING emits (the session_started anchor, seed-read / --help
    fetch receipts) do NOT use this default: they pass an EXPLICIT strict/bootstrap ref (auditor F3), so
    the evidence the keyer later matches is written under the authoritative id.

    Precedence: in-process frozen snapshot → worker EXPECTED → the raw v2-own SELF_REF carry (the caller's
    DECLARED identity — even if UNBACKED; a stamp is best-effort provenance, NOT a keying decision, so the
    carry-must-be-backed rule that governs the KEYER does not apply here) → the non-dying rediscovery result
    for a CARRY-LESS process (its worktree stamp / live record) → 'unresolved'. The carry precedence
    DELIBERATELY differs from the keyer: for KEYING an unbacked carry must NOT win (the X-0158 fix), but for
    PROVENANCE an explicitly-carried self-ref IS the honest identity to stamp under (this also restores the
    pre-T-10149 emit behavior — carry-first — so existing emit-under-carry tests are unchanged). Provider
    carriers are NEVER consulted (auditor F2 — no second provider-coupled surface)."""
    return _resolve_session_ref_for_envelope_with_source()[0]


def _resolve_session_ref_for_envelope_with_source() -> "tuple[str, str, str | None]":
    """(ref, source_kind, fallback_reason) twin of `_resolve_session_ref_for_envelope` (T-10318) — the SAME
    best-effort precedence, the same never-`_die` contract, plus the NAME of the selector that stamped the
    ref and, when nothing resolved, WHY.

    `source_kind` ∈ {`expected_contract`, `env:<SELF_REF_ENV>`, `isolated_verify`, `worktree_stamp`,
    `runtime_record`, `unresolved`} — envelope PROVENANCE, never a resolution carrier class, so never
    routed through `_assert_modeled_source_kind` (same treatment `minted_self_ref`/`worktree_stamp` already
    get on `session_started`; the shared spellings let ONE grep span both envelopes).

    `fallback_reason` is non-None ONLY on the `unresolved` sentinel, and splits the two OPPOSITE operator
    situations the sentinel used to collapse into one opaque token: `ambiguous` (multiple live runtime
    records, no distinct selector) vs `absent` (no records, no stamp, no carry). Every RESOLVED leg returns
    None, so a happy-path row carries no key (omit-when-default — T-10317's "the key name IS the flag").

    NOT recorded here: that a WINNING carry was UNBACKED. `_emit_cli_invoked`'s T-10317
    `carried_session_ref_unbacked` key already carries that fact (and the ref verbatim); re-encoding it as a
    `fallback_reason` would give one fact two carriers that can drift apart (P5). A dashboard reads the
    carry-masks-a-broken-stamp case as the COMPOSITION `source_kind == env:<SELF_REF_ENV>` AND
    `carried_session_ref_unbacked` present — derived, not duplicated."""
    global _FROZEN_SESSION_REF
    if _FROZEN_SESSION_REF is not None:
        return _FROZEN_SESSION_REF, "expected_contract", None
    if EXPECTED_SESSION_REF_ENV in os.environ:
        exp = _expected_session_ref()
        if exp:
            return exp, "expected_contract", None
    # An explicitly carried v2-own self-ref is the caller's declared identity — the honest provenance stamp,
    # even if unbacked (the keyer separately REJECTS an unbacked carry; a stamp does not need backing).
    carried = os.environ.get(SELF_REF_ENV, "").strip()
    if carried:
        return carried, f"env:{SELF_REF_ENV}", None
    # No carry → rediscover a carry-less process's OWN identity (worktree stamp / live runtime record);
    # a None (ambiguity/absence) degrades to the sentinel — never fails closed.
    ref, reason, source = _try_rediscover_session_ref_with_source()
    if ref is not None:
        return ref, source, None
    return "unresolved", "unresolved", reason


def _provider_session_ref() -> "str | None":
    """T-10137: the PROVIDER session id used for the D-0030 transcript join + the context epoch —
    resolved SEPARATELY from the read-gate discriminator (`_resolve_session_ref`). It SKIPS the
    self-ref carrier YITC_SESSION_REF (which names no `~/.claude/.../<id>.jsonl` transcript file) and
    the frozen EXPECTED contract; returns the first present PROVIDER carrier in precedence order, or
    None when none is set. NON-dying — every consumer is a best-effort context/epoch sensor that
    fail-safes to 0/None, so a truly provider-less env (a scrubbed worker) is not an error here.

    This is the DECOUPLE at the heart of the fix: post-mint `_resolve_session_ref` returns the minted/
    self ref (a random uuid that names no transcript), so using it to LOCATE the transcript would break
    the epoch + context sensors. The provider carrier — drift-prone as a cross-subprocess DISCRIMINATOR
    — is perfectly stable as a transcript NAME, which is all these consumers need."""
    for var in PROVIDER_CARRIERS:
        val = os.environ.get(var, "").strip()
        if val:
            return val
    return None


# T-10152 (SPEC-0137 Rule 8): the T-10137 `_mint_interactive_self_ref` two-anchor additive-alias helper
# is RETIRED. `session start` now MINTS the identity DIRECTLY (`_session_start_identity` → the single
# session_started anchor + runtime record under the minted id) instead of resolving a provider carrier
# then emitting a SEPARATE tagged alias under a fresh uuid. One identity, one anchor — no read_gate_alias /
# aliases_provider_ref rows, no provider-carrier dependency in the bootstrap.


# T-12649 (X-1465): the governed-reason locator findings for THIS invocation. EMPTY on every clean
# invocation — which is what makes the `_append_event` stamp below cost a truthiness test and nothing
# else on the normal path.
_LOCATOR_FINDINGS: list = []


def _reason_values_of(args: argparse.Namespace) -> dict:
    """The `{field: value}` governed free-text arguments of this invocation (T-12649). PURE.

    Reads the `journal_mod.GOVERNED_REASON_FIELDS` attributes off the parsed namespace, plus the same
    keys inside an `event --data` payload (the one place a governed reason arrives as JSON rather than
    as a flag). A verb carrying none of them yields {} — no work, no file opened.
    """
    out = {}
    for field in journal_mod.GOVERNED_REASON_FIELDS:
        val = getattr(args, field, None)
        if isinstance(val, str) and val:
            out[field] = val
    raw = getattr(args, "data", None)
    if isinstance(raw, str) and raw.strip().startswith("{"):
        try:
            payload = json.loads(raw)
        except (ValueError, TypeError):
            payload = None
        if isinstance(payload, dict):
            for field in journal_mod.GOVERNED_REASON_FIELDS:
                val = payload.get(field)
                if isinstance(val, str) and val:
                    out.setdefault(f"data.{field}", val)
    return out


def _check_reason_locators(args: argparse.Namespace) -> None:
    """WARN when a governed free-text reason cites a journal locator that does not RESOLVE (T-12649).

    SPEC-0204 rule 2's principle — authority is proven by RESOLUTION, never by a non-empty string —
    applied to the FREE-TEXT fields it never reached. Called ONCE per invocation from `main()`, AFTER
    the `-C` rebind (so it reads the right journal) and AFTER `_auto_sync` (so a locator naming a row
    this very session just materialized resolves).

    REPORT-ONLY, and deliberately so: it is a WARN plus a mark on the row, never a refusal. The class
    it addresses is a defect that LANDED unnoticed, and a stderr line in a background worker is gone
    the moment the process exits — so the durable half is the `unresolved_locators` stamp
    `_append_event` writes, which makes the record self-describing and greppable
    (`journal query --grep unresolved_locators`). Wrapped so it can never raise: a governance warning
    must not be able to break a verb.
    """
    _LOCATOR_FINDINGS.clear()
    try:
        values = _reason_values_of(args)
        if not values:
            return
        # T-12923 (X-1572): also resolve against main's journal (SPEC-0168 rule 1) — a worktree cut
        # before the Controller's directive row does not carry it. The git lookup runs only when a
        # value actually carries a locator claim.
        main_path = (_main_events_path()
                     if any(journal_mod.locator_claims(v) for v in values.values()) else None)
        findings = journal_mod.scan_governed_locators(values, EVENTS_PATH,
                                                      main_journal_path=main_path)
        if not findings:
            return
        _LOCATOR_FINDINGS.extend(findings)
        for f in findings:
            why = ("not a well-formed timestamp" if f["why"] == "malformed"
                   else "no journal row at that ts")
            print(f"yitc-v2: WARN — `{f['field']}` cites events.jsonl#ts={f['locator']} "
                  f"which does not resolve ({why}). SPEC-0204 rule 2: authority is proven by "
                  f"RESOLUTION, never by a non-empty string. The row is being stamped "
                  f"`unresolved_locators` so the record says so.", file=sys.stderr)
    except Exception:                    # noqa: BLE001 — a WARN must never break the verb
        _LOCATOR_FINDINGS.clear()


def _append_event(
    event_type: str,
    task_id: str | None,
    data: dict | None,
    *,
    agent: str = "main",
    session_ref: "str | None" = None,
    spawned_by: str | None = None,
    source_ref: str | None = None,
    ts: str | None = None,
    events_path: "Path | None" = None,
    text_cap: bool = False,
) -> dict:
    """Thin host wrapper → events.append_event (the single journal-write path, T-9247).

    RETURNS the primitive's witness unchanged (T-10949) — the resolved path + row locator this
    wrapper's own target resolution produced. Pass-through only: no call site is obliged to read it
    (all ~76 ignore it), and `cmd_event` is the one that PRINTS it (see there for the R3 rationale).

    The write-path BODY (envelope build + provenance + SPEC-0002 byte cap + flock O_APPEND) lives in
    bin/lib/events.py; this wrapper resolves the host-coupled inputs the primitive must NOT read itself
    and delegates — so the 76 call-sites + the test monkeypatch of yitc.EVENTS_PATH are unchanged:
      - target path: the T-0357 YITC_EVENTS_SINK quarantine takes precedence over the explicit
        `events_path=` override (the `worktree new` main-journal bind, T-0109/D-0054) and the current
        EVENTS_PATH (read HERE at call time, so a `-C` rebind / the test monkeypatch is honored).
      - session_ref: the BEST-EFFORT envelope resolver (SPEC-0137 Rule 2 two-role scope, T-10149) — an
        emit is append-only provenance that must never be lost, so the DEFAULT never fails closed (the
        governance-KEYING fail-closed resolver `_resolve_session_ref` is a SEPARATE path). An EXPLICIT
        value is passed straight through, never re-resolved — used by gate-bearing emits (the
        session_started anchor / seed / --help receipts, auditor F3) + pre-abort DIAGNOSTIC emits.
      - ts: the host clock `_utc_now_iso()` (or an adapter-supplied source-entry ts, T-0095).
      - guard: the SPEC-0078 consumer→engine write-boundary check, invoked on the resolved target.
    """
    sink = os.environ.get("YITC_EVENTS_SINK", "").strip()
    # T-10859: under `--read-only` the default append target is EVENTS_APPEND_PATH (the reader's own
    # journal) instead of EVENTS_PATH — that redirect is what keeps the `-C` target untouched.
    # Precedence is UNCHANGED (sink > explicit events_path= > default), and an explicit `events_path=`
    # reaching into a read-only target is still refused by the guard below.
    # SCOPED TO THE MODE: outside it, keep reading EVENTS_PATH at call time. The two globals hold the
    # same value there, but ~40 in-process tests redirect `yitc.EVENTS_PATH` ALONE, so defaulting to
    # the other global would silently send their appends to the real journal.
    default_target = EVENTS_APPEND_PATH if READ_ONLY_ROOT is not None else EVENTS_PATH
    target = Path(sink) if sink else (events_path or default_target)
    # T-13181 (SPEC-0163 §4e): no floor-shaped credential reaches a journal row, whichever writer
    # carries it — redacted HERE, the one host write path, so the next free-text writer is covered the
    # day it is added. FIRST, so every stamp below reads the row as it will be stored. A clean payload
    # comes back as the SAME object (byte-identical); a changed one is a copy, never the caller's dict.
    data = journal.redact_payload(data)
    # T-11363 (SPEC-0025 §land_completed): WHO ran this land. `land_completed` is the row that records
    # a verify BYPASS was used and why (`no_tests` / `rebaselined`; `not_a_spike` too, until T-11940
    # removed that override) — and until now it
    # recorded no actor at all, so the acting person was recoverable only by joining `session_ref`
    # against sibling rows of the same session that happen to carry one. Measured on this repo: of
    # 7419 land_completed rows, the 17 carrying a `no_tests_reason` had a null `source_ref` and no
    # actor key; <project> measured 67 of 67. A record that takes a forensic join nobody thinks to run
    # is not a record, and a gate on identity is impossible where identity is not recorded.
    #
    # WHY HERE, and not at the three emit sites. `bin/lib/worktree.py` owns all three
    # (`_land_integrate`'s ok emit, `_emit_land_abort`, and its T-11241 clearing copy) but is a
    # declared identity-agnostic kernel module that NEVER back-imports the host, so it cannot resolve
    # an OS identity or read the host registry; and threading an `_actor` dep through
    # cmd_land -> _land_integrate -> _emit_land_abort is exactly the widen-in-lockstep hazard that
    # function's own docstring warns turns an abort into an unhandled crash. This wrapper's stated job
    # is resolving the host-coupled inputs the primitive must not read itself, and an actor is one. One
    # home also means the NEXT land_completed emit site is attributed the day it is added.
    #
    # UNCONDITIONAL, on BOTH outcomes — deliberately NOT scoped to bypass-carrying rows. Three grounds:
    # a bypass-only key could only be adopted by performing a bypass (SPEC-0103 forbids weakening a
    # gate to manufacture evidence); the bypass set has grown three times already, so an enumerated
    # condition ships the FOURTH bypass unattributed by default; and the sibling `deviation_captured`
    # stamp (T-10410) is unconditional for the same reason. This is therefore the one land_completed
    # key that is NOT additive/conditional — registered as always-present in SPEC-0025.
    #
    # NOT CALLER-ASSERTABLE (the AC2 line): the value comes from `_server_actor()`, which reads the OS
    # uid and no argv/env, and the rebind OVERWRITES any `actor` a caller pre-seeded into `data` — so
    # the payload channel cannot forge it either (`actor` is additionally a RESERVED `--data` key,
    # T-10410, so `event --data` refuses it loudly upstream). COPY, never mutate: the clearing copy
    # re-appends this same dict under a pinned ts and must stay byte-identical for the land-time dedup
    # to fold the two into one row (the derive is deterministic in-process, so both carry one value).
    if event_type == "land_completed":
        data = {**(data or {}), "actor": _server_actor()}
    # T-12844 (SPEC-0161 `bg_dispatch_halted.block_classification`): EVERY blocked-on-land halt carries
    # its SPEC-0191 classification, stamped HERE because the halt has several writers (the verb, the
    # land repeated-abort backstop, the audit-loop ceiling halt, a hand `event` append) and only the
    # verb asked for one — measured 112/689 halts classified. One home means the next writer is
    # covered the day it is added. COPY, never mutate (a caller may re-append the same dict).
    if event_type == "bg_dispatch_halted":
        _bc = events.derive_block_classification(data)
        if _bc is not None and (data or {}).get("block_classification") != _bc:
            data = {**data, "block_classification": _bc}
    # T-12649: stamp the row in flight when THIS invocation's governed reason carried an unresolvable
    # locator AND the data being written actually carries the offending token. A truthiness test on a
    # list that is empty on every clean invocation — so zero added cost normally, and NO journal read
    # on this path ever. Idempotent (skipped when already present, so `land_completed`'s clearing
    # re-append stays byte-identical). The precedent for deriving a key onto the row in flight is the
    # `land_completed` -> `actor` rebind just above.
    if _LOCATOR_FINDINGS and data and "unresolved_locators" not in data:
        try:
            hit = [f for f in _LOCATOR_FINDINGS
                   if any(f["locator"] in v for v in data.values() if isinstance(v, str))]
            if hit:
                data = {**data, "unresolved_locators": [
                    {"field": f["field"], "locator": f["locator"], "why": f["why"]} for f in hit]}
        except Exception:                # noqa: BLE001 — a mark must never lose an append
            pass
    return events.append_event(
        event_type, task_id, data,
        agent=agent,
        session_ref=session_ref if session_ref is not None else _resolve_session_ref_for_envelope(),
        spawned_by=spawned_by,
        source_ref=source_ref,
        ts=ts or _utc_now_iso(),
        events_path=target,
        guard=_guard_consumer_engine_write,
        text_cap=text_cap,   # T-12732: the SPEC-0002 text cap is opt-in — only the transcript adapter passes it
    )


def _guard_consumer_engine_write(path: Path) -> None:
    """Consumer→engine write-boundary guard (SPEC-0078). REFUSE a corpus write that reaches INTO the
    ENGINE's own corpus (under ENGINE_ROOT, OUTSIDE the session's own REPO_ROOT) from a genuine
    CONSUMER session. An engine-OWN session is NEVER refused.

    Consumer-detection reuses the EXISTING `_is_consumer_build()` (T-0952) — NOT a bare
    `REPO_ROOT != ENGINE_ROOT`: an engine LINKED WORKTREE shares the engine's git common-dir, so it IS
    the engine (a `-C <engine-worktree>` build, a worktree→main `land` write) and must NOT be guarded;
    only a SEPARATE repository (different common-dir) is a consumer. `_is_consumer_build()` short-circuits
    to False (no subprocess) on the common engine-own path (REPO_ROOT == ENGINE_ROOT) and caches the rest.

    The `not under REPO_ROOT` clause is load-bearing: the session's OWN corpus is always writable even if
    REPO_ROOT is nested inside ENGINE_ROOT (a test repo under the engine checkout); only a reach OUTSIDE
    REPO_ROOT but INTO ENGINE_ROOT is the breach. On refusal: exit 1 + a stable stdout token.

    READ-ONLY CLAUSE FIRST (SPEC-0078 §5, T-10859). Under `--read-only` the boundary is INVERTED: the
    `-C` target is the thing being protected, and the invoking identity is the ENGINE (a kernel session
    reading a consumer for evidence), not the consumer this helper's §2 clause assumes. So:
      (i) REFUSE any target resolving under READ_ONLY_ROOT — the promise "writes nothing there" is held
          by the MECHANISM at the one chokepoint SPEC-0078 §1 enumerates as complete, never by which
          verbs someone remembered to gate; and
      (ii) then RETURN, before §2. `_is_consumer_build()` reads REPO_ROOT — which under `-C` IS the
          consumer — so §2 would otherwise refuse the engine writing its OWN journal, the very redirect
          that makes the mode work. This is an inversion of the boundary, not a hole in it: every write
          is still refused on exactly one side, and the refusal token is the existing one (no new
          vocabulary).
    """
    if READ_ONLY_ROOT is not None:
        target = Path(os.path.realpath(str(path)))
        if target == READ_ONLY_ROOT or target.is_relative_to(READ_ONLY_ROOT):
            print(f"WRITE-BOUNDARY: REFUSED {target}")
            sys.exit(1)
        return
    if not _is_consumer_build():
        return  # engine-own session (incl. engine worktrees + land cross-checkout writes) — guard silent
    target = Path(os.path.realpath(str(path)))
    repo = Path(os.path.realpath(str(REPO_ROOT)))
    # T-13192 (SPEC-1003 rule 4): a served process guards BOTH its served checkout and the live kernel
    # checkout (which contains the per-sha dirs); outside a served process the two are one path.
    under_engine = any(target == e or target.is_relative_to(e)
                       for e in {Path(os.path.realpath(str(ENGINE_ROOT))),
                                 Path(os.path.realpath(str(_engine_live_root())))})
    under_repo = target == repo or target.is_relative_to(repo)
    if under_engine and not under_repo:
        print(f"WRITE-BOUNDARY: REFUSED {target}")
        sys.exit(1)


def _warn_dropped_yaml_comments(path: Path, content: str) -> None:
    """REPORT-ONLY: name the full-line YAML comments this rewrite is about to destroy (T-11245).

    `dump_state` is PyYAML, which has no comment model, so every card-rewriting verb (`stage`,
    `task update`, `task analyze`, `task close`, the plan back-link) silently drops any comment the
    card carried — the <project> X-0982 loss, where authored prose vanished on the next worker's
    stage-entry with nothing failing closed anywhere. Detection is the fix (LOUD-DETECT): PRESERVING
    the comments needs a round-trip-safe parser, i.e. a SECOND parser path, which CHARTER §P5 forbids.

    WARNS, never refuses — 109 live cards carry `#`-leading lines, so a refusal would wedge every
    lifecycle verb on them. Scoped to `.yaml`/`.yml` targets that ALREADY EXIST: a YAML comment is a
    YAML-file concept, which keeps `graph/index.json` (also written through this helper) out of scope,
    and a brand-new file has nothing to lose. Any read failure is swallowed — a warning must never
    break a write. The comparison lives in `state.dropped_comment_lines` (which states its own bound:
    full-line comments only; a block-scalar `#` line survives the dump, so it never reports).
    """
    try:
        if path.suffix not in (".yaml", ".yml") or not path.is_file():
            return
        lost = state.dropped_comment_lines(path.read_text(encoding="utf-8"), content)
    except Exception:
        return
    if not lost:
        return
    try:
        rel = path.relative_to(REPO_ROOT)
    except ValueError:
        rel = path
    sys.stderr.write(
        f"WARN: this rewrite DROPS {len(lost)} YAML comment line(s) from {rel} — the serializer has no "
        f"comment model, so they are gone from the file after this write:\n"
        + "".join(f"    {line}\n" for line in lost)
        + "  Comments are NOT a schema field and do not survive a lifecycle re-write. Re-author the "
          "text into the field that carries prose (`scope:` / `acceptance:` / `analysis:` — SPEC-0028) "
          "if it is meant to last. Proceeding with the write (T-11245).\n")


def write_text_atomic(path: Path, content: str) -> None:
    """Atomic write for regular state files (tasks/*.yaml) — per patterns/atomic-state-file-writes.md.

    Unlike events.jsonl (append-only), task YAML is a full-file rewrite target where a
    partial write would corrupt the file for downstream readers (picker, graph build).
    """
    _guard_consumer_engine_write(path)  # SPEC-0078: reject consumer→ENGINE_ROOT corpus writes
    _warn_dropped_yaml_comments(path, content)   # T-11245: the round-trip comment loss, made LOUD
    path.parent.mkdir(parents=True, exist_ok=True)
    # T-10182: mkstemp() hardcodes 0600 and os.replace() PRESERVES the tmp file's mode, so without an
    # explicit chmod every atomic-written state file lands owner-only — invisible to a scoped group-read
    # collaborator (the <project> incident: `-C init` scaffolds unreadable to a design collaborator in
    # group dev). Restore the INTENDED mode: preserve a pre-existing target's mode (a deliberately-private
    # file — e.g. a 0600 — stays private on rewrite), else apply the umask-respecting default for a NEW
    # file. Chmod the tmp fd BEFORE os.replace so atomicity (SPEC-0003) is unchanged.
    try:
        _existing_mode = os.stat(path).st_mode & 0o777
    except FileNotFoundError:
        _existing_mode = None
    fd, tmp = tempfile.mkstemp(dir=str(path.parent), prefix=f".{path.name}.", suffix=".tmp")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            if isinstance(content, str):
                f.write(content)
            else:
                f.writelines(content)   # T-13138 — a STREAMED body (iterable of str chunks), never joined
            f.flush()
            os.fsync(f.fileno())
        if _existing_mode is not None:
            os.chmod(tmp, _existing_mode)
        else:
            _cur = os.umask(0)
            os.umask(_cur)
            os.chmod(tmp, 0o666 & ~_cur)
        os.replace(tmp, path)
    except Exception:
        try:
            os.unlink(tmp)
        except OSError:
            pass
        raise
    # Invalidate the yaml-tree memo for THIS path at the WRITE chokepoint (T-0460): the cache key is
    # (path, mtime_ns, size), and a rewrite that yields the SAME size AND a coarse-equal mtime_ns
    # (e.g. "resolved"→"reopened", both 8 chars) collides with the pre-write key, so the read returns a
    # STALE tree BEFORE the per-read eviction can run (a write-then-read within one op). Evicting here
    # — at the single write chokepoint — makes the next `_read_yaml` always re-parse from disk. Fixes
    # the pre-existing reopen-test flake (yaml-tree-cache-stale-hit-reopen-tests). Defensive: never
    # let cache bookkeeping break a successful write.
    try:
        _p = str(path.resolve())
        _cache = _yaml_tree_cache()
        for _stale in [k for k in _cache if k[0] == _p]:
            del _cache[_stale]
    except Exception:
        pass


# =============================================================================
# Session-log adapter (T-0051, per D-0030 + SPEC-0004)
#
# Materializes chat-class events (owner_directive / instruction_injection /
# slash_command) from the provider session log into events.jsonl with provenance.
# Provider-neutral contract = SPEC-0004; Claude Code is the first concrete binding
# (shapes below are Claude-specific and live only in this code, not the handbook).
# =============================================================================

# The Claude-Code transcript root — the LIVE knob the claude-code descriptor resolves by name
# (`log_root_var:"SESSION_LOG_GLOB_ROOT"`). Kept as a module global (not folded into the descriptor
# literal) so host-isolated tests can redirect the claude transcript tree by rebinding it, and
# `_session_log_path` reads the current value each lookup. The provider-agnostic locator is
# PROVIDER_TRANSCRIPT_DESCRIPTORS + _session_log_path.
SESSION_LOG_GLOB_ROOT = Path.home() / ".claude" / "projects"
SYNC_STATE_DIR = REPO_ROOT / "journal-sync-state"
# Claude Code runtime entry types carrying no governance signal (lossy filter).
CC_NOISE_TYPES = frozenset({
    "mode", "permission-mode", "file-history-snapshot", "last-prompt",
    "ai-title", "queue-operation", "attachment", "system", "assistant",
    "deferred_tools_delta", "skill_listing",
})
MAX_EVENT_BYTES = events.MAX_EVENT_BYTES   # single value home = bin/lib/events.py (T-9247); re-export
                                           # keeps yitc.MAX_EVENT_BYTES readers + the SPEC-0002 anchor
MAX_TEXT_CHARS = textutil.MAX_TEXT_CHARS   # single value home = bin/lib/textutil.py (T-9260); re-export
                                           # keeps yitc.MAX_TEXT_CHARS readers + the SPEC-0002 anchor
# Dedup runs ONLY on the recovery path (first-sync / stale-cursor rescan) and scans
# the FULL events.jsonl history — correct for arbitrarily large replays (audit-post F1:
# the original bounded window could duplicate older rows). Steady-state sync (entries
# after the checkpoint cursor) skips dedup entirely — those entries are necessarily new.


def _current_provider_kind() -> "str | None":
    """T-10153: the transcript-provider KIND of the live session — the value captured as a v2 runtime
    record's forensic `provider_meta` (SPEC-0137 Rule 2.5), read from the first present provider carrier
    in descriptor precedence. None when no provider env is set (a scrubbed / unknown provider). This is
    the SINGLE place provider-KIND is derived from env — a record-writer records THIS; a locator reads
    the RECORDED value back as the `provider_kind` hint below (v2 state, not the live env)."""
    for desc in PROVIDER_TRANSCRIPT_DESCRIPTORS:
        if os.environ.get(desc["env"], "").strip():
            return desc["kind"]
    return None


def _provider_transcript_ref(session_ref: "str | None" = None) -> "str | None":
    """T-12400: the ref that NAMES this session's D-0030 transcript, when the v2 identity does not.

    Since T-10152 an interactive session's identity is a MINTED uuid (`_session_start_identity`), which
    names no `~/.claude/projects/*/<id>.jsonl` — so `_session_log_path(<v2 ref>)` returns None and the
    per-verb implicit `journal sync` was structurally INERT for EVERY interactive Controller, in every
    home (<project> X-1364 / <project> X-1345). Two ordered sources, both already sanctioned for the
    transcript-join role ONLY:
      1. the LIVE provider carrier (`_provider_session_ref` — the D-0030 role, explicitly NOT an
         identity selector per SPEC-0137 Rule 4/8b), then
      2. the `provider_session_id` this session RECORDED at its birth-write, read back from v2 STATE —
         so a verb whose env no longer carries the provider var still joins (the `provider_kind`
         read-back in `_session_log_path` below is the same rule-2.5 shape one field over).
    None when neither resolves. NON-dying and side-effect-free: every consumer is best-effort and
    fail-safes to today's behaviour, so a scrubbed worker / unknown provider is not an error.

    This resolves a TRANSCRIPT NAME and nothing else. It is NEVER consulted by identity resolution —
    `_resolve_session_ref` is untouched, and SPEC-0137 Rule 4 (no provider-carrier identity fallback)
    stands exactly as written."""
    live = _provider_session_ref()
    if live:
        return live
    if session_ref:
        try:
            rec = _read_runtime_record(_runtime_record_path(session_ref))
        except Exception:
            return None
        if rec:
            recorded = (rec.get("provider_session_id") or "").strip()
            if recorded:
                return recorded
    return None


def _session_log_path(session_ref: str, *, provider_kind: "str | None" = None) -> Path | None:
    """Locate the provider transcript for `session_ref` (D-0030 forensic journal-sync join).
    Provider-agnostic (T-10153): try each PROVIDER_TRANSCRIPT_DESCRIPTORS glob and return the first
    match — only the OWNING provider's tree contains a given ref, so a Claude session id resolves under
    ~/.claude/projects/*/<ref>.jsonl and a codex thread id under ~/.codex/sessions/**/rollout-*-<ref>.jsonl
    (session may launch from any cwd — do NOT cwd-encode). None when no descriptor matches (an unknown
    provider = a clean skip, not an error).

    `provider_kind` is the OPTIONAL v2-STATE hint (SPEC-0137 Rule 2.5): a runtime record's recorded
    `provider_meta`. When None, this reads it back from v2 STATE — the runtime record for `session_ref`,
    written at session-start birth — so lookup consumes the RECORDED provider before the live-env
    descriptor scan (auditor part 2). When the recorded provider's descriptor is known, it is tried
    FIRST (then the full scan) — lookup HONORS v2 state without DEPENDING on it (a missing/absent record
    just degrades to the full provider-agnostic scan; a scrubbed worker is not an error)."""
    if not session_ref:
        return None
    if provider_kind is None:
        # v2-STATE read-back (best-effort): the birth-written runtime record's forensic provider_meta.
        try:
            rec = _read_runtime_record(_runtime_record_path(session_ref))
            if rec:
                provider_kind = rec.get("provider_meta")
        except Exception:
            provider_kind = None
    descriptors = PROVIDER_TRANSCRIPT_DESCRIPTORS
    if provider_kind is not None:
        descriptors = ([d for d in descriptors if d["kind"] == provider_kind]
                       + [d for d in descriptors if d["kind"] != provider_kind])
    for desc in descriptors:
        root = globals().get(desc["log_root_var"])   # resolve the LIVE root global each lookup
        if root is None:
            continue
        matches = sorted(root.glob(desc["log_glob"].format(ref=session_ref)))
        if matches:
            return matches[0]
    return None


def _session_config_descriptor() -> str:
    """T-0376: ONE opaque, comparable descriptor of the primary-AI configuration, recorded
    VERBATIM from what the harness reports (plan observability-metrics PART-1, L3).

    Sources, in order: (1) each set SESSION_CONFIG_ENV_KEYS env var as `K=V` verbatim;
    (2) best-effort `model=<verbatim>` from the provider transcript TAIL (the last assistant
    entry's message.model — the model is not in env; bounded read, broad-except: ANY failure
    just omits the part — session start is the protocol entry and never fails on a log quirk).
    ZERO signals → the explicit marker "unknown" (never inferred). Consumers compare the
    descriptor for EQUALITY only — no parsing, no normalization, no semantic fields
    (SPEC-0025 opaque-key contract; benchmark protocol PART 3 reads this snapshot)."""
    # audit-post F0: TRULY verbatim — no strip/normalization of the value; skip only unset/empty keys.
    parts = [f"{k}={os.environ[k]}" for k in SESSION_CONFIG_ENV_KEYS
             if os.environ.get(k, "") != ""]
    try:
        # T-10152 (SPEC-0137 Rule 8b): the TRANSCRIPT is named by the PROVIDER carrier (D-0030), NOT the
        # v2 identity. Resolve it via `_provider_session_ref` — the transcript-role resolver over
        # PROVIDER_CARRIERS — NOT `_lookup_identity_env` (the identity registry, which the collapse reduced
        # to the v2-own self-ref that names no `~/.claude/.../<id>.jsonl` transcript). Best-effort: None
        # when no provider carrier is present (a scrubbed worker) → the model part is simply omitted.
        ref = _provider_session_ref()
        log = _session_log_path(ref) if ref else None
        if log is not None:
            # bounded tail read (last ~64KB) — enough for the latest assistant entries
            with open(log, "rb") as fh:
                fh.seek(0, os.SEEK_END)
                size = fh.tell()
                fh.seek(max(0, size - 65536))
                tail = fh.read().decode("utf-8", errors="replace")
            model = None
            for ln in tail.splitlines():
                if '"model"' not in ln:
                    continue
                try:
                    e = json.loads(ln)
                except ValueError:
                    continue
                m = (e.get("message") or {}).get("model") if isinstance(e.get("message"), dict) else None
                if m:
                    model = str(m)
            if model:
                parts.append(f"model={model}")
    except Exception:
        # best-effort: an unreadable/odd transcript never blocks session start. Narrowed to
        # Exception (audit-post F1) — KeyboardInterrupt/SystemExit propagate, an intentional
        # abort is never masked.
        pass
    return " ".join(parts) if parts else "unknown"


# Pure text/parse helpers — single home = bin/lib/textutil.py (T-9260). Re-export residue keeps
# every yitc._extract_text / yitc._cap_text caller + the SPEC-0004 `_cap_text` graph anchor resolving.
_extract_text = textutil.extract_text
_cap_text = textutil.cap_text


# Governed docs whose READ counts as a «commanded / expected read» (D-0048). The canonical
# handbook (by basename — GOVERNED_DOCS, derived from HANDBOOK_READ_ORDER below) + the doc layer
# (specs / decisions / patterns). A Read of one of these via the Read tool is captured as
# instruction_injection arrival=commanded — the half the journal used to drop as tool-result noise.
# Arbitrary code/task reads are NOT governed (avoid flooding).
GOVERNED_DIRS = ("specs", "decisions", "patterns")


# The graph node-id token shape for a `graph query` point-lookup (SPEC/T/D/E-NNNN or a plan/view
# slug). Anchored full-match on a single argv token — never a substring search inside a larger string
# (T-0434: that is the false-mint defense the audit-pre flagged). The same id-only bound as
# `_emit_cli_invoked`'s node_id key (`graph query`'s `args.id` positional; --type/--projected forms
# carry no positional id, so they yield nothing here too).
_GRAPH_QUERY_NODE_ID_RE = re.compile(r"^(?:SPEC-\d{4,}|T-\d{4,}|D-\d{4,}|E-\d{4,}|[a-z0-9][a-z0-9-]*)$")


# --- dispatch-status reader (T-0391, A1 reader-only) ------------------------------------------
# A PURE READ-ONLY mode of `journal query` (NO per-call emit — a read must not mutate, CHARTER
# §P5/§P1-F2). It encodes the 2026-06-02-debugged dispatch query ONCE, consuming the SETTLED
# contracts: the terminal-marker contract (T-0378 / SPEC-0025 §Terminal-marker — a terminal carries
# a top-level task_id ALWAYS + data.dispatch, in the worktree journal) and per-dispatch correlation
# (T-0379 / SPEC-0025 §Per-dispatch correlation — the envelope session_ref). NOT a D-0053 graph view
# (graph/index.json strips session_ref + data, proven unfit). Liveness is ADVISORY (journal ts +
# live worktree claim) — NO process-tree walk (CHARTER L59/148); detect+surface ONLY, never kill.

# Boundary events that SEED the dispatch task set (any one of these = a dispatch existed). Startup
# is ONE seed, not the sole enumerator, so a task that died PRE-startup still shows (scope §4).
# `bg_dispatch_launched` (T-0559) is a boundary too — the LAUNCH is the start of a dispatch's life,
# so a launched-but-not-yet-picked worker seeds the wave view (the COLLAPSED early-catch window is
# pre-pick). This constant has a SINGLE consumer (the wave-seed loop in cmd_journal_dispatch_status
# below) — it is dispatch-status-private, not a shared boundary set (audit-pre F0 absorption).
# T-12645 — `bg_dispatch_spawned` joins the seed (journal.DISPATCH_LAUNCH_TYPES). This tuple is what
# SEEDS the task set `--fleet-verdict` / `--dispatch-status` classify; a worker whose parent died inside
# the spawn->launch-row window has no `task_picked` and no `bg_dispatch_launched` yet, so without this
# member the id never entered the fleet view at all and the widened reader below it could never run.
DISPATCH_BOUNDARY_TYPES = ("task_picked", "startup_protocol_completed", "bg_dispatch_halted",
                           "bg_dispatch_launched", "bg_dispatch_spawned")
# Terminal markers — a recognized terminal event present in the chain ends a dispatch. TWO are the
# EMITTED dispatch markers (T-0378 / SPEC-0025 §Terminal-marker contract): done = task_closed, halt =
# bg_dispatch_halted. The THIRD (T-0588) is a reader-recognized TASK-STATUS terminal reached WITHOUT a
# dispatch marker: wont-do = task_wont_do — a worker correctly DECLINING a superseded / self-
# unsatisfiable task (`task update --status wont-do`, which carries a top-level task_id). The reader
# treats it as terminal too so a polling controller does not read a FINISHED dispatch as a live worker
# and quiescent reflects terminal (incident: T-0581 read 'working', 2026-06-08). Additive — adds no
# emitted marker and changes nothing an emitter must do.
DISPATCH_TERMINAL_TYPES = ("task_closed", "bg_dispatch_halted", "task_wont_do")
# Detail label per terminal type (surfaced as TERMINAL(<detail>) — _classify_dispatch + the line-label).
DISPATCH_TERMINAL_DETAIL = {"task_closed": "done", "bg_dispatch_halted": "halt", "task_wont_do": "wont-do"}
# Pollution kill (b): owner_directive + instruction_injection are NEVER dispatch lifecycle — excluded
# by anchored envelope `type` (never a text-payload substring). Anchoring on the field, not content.
DISPATCH_EXCLUDED_TYPES = ("owner_directive", "instruction_injection")
# Staleness windows: a non-terminal task whose last event is older than its PHASE window is "stale"
# (working -> silent_stop / hang_suspect split). Advisory only — a coarse recency cut, not a lease/TTL.
# T-9748 — PER-PHASE, replacing the single 30-min global: a worker journal is SPARSE (events only at
# stage boundaries), so under one 30-min window a real hang silent 10-20 min sat `working` (3 run
# incidents: T-9727/T-9737 bootstrap, T-9738 audit-post). NORMAL is tight so those surface; AUDIT
# (Audit-pre/Audit-post) is a generous backstop for the legitimately-minutes-long, journal-SILENT
# external-audit stage — where the T-9747 dispatch-log heartbeat is the liveness substrate that resets
# staleness (see _classify_dispatch). LAND is NOT a phase here: a worker mid-land reads
# closed_pending_land (task_closed + live claim) and returns ABOVE the staleness split, covered by the
# T-9601 land-verify heartbeat. NORMAL > the 10-min near-launch grace below (a booting worker is not
# yet stale). Neither is a kill fuse — the controller's >=2-poll gate + Confirmed-dead GATE decide any
# action (detect+surface).
DISPATCH_STALE_NORMAL_SEC = 15 * 60
DISPATCH_STALE_AUDIT_SEC = 30 * 60
# T-9749 — near-launch BOOTSTRAP grace: a launcher-dispatched worker that has not come up (no
# session_started for its assigned ref) + not claimed is "still booting" WITHIN this window; PAST it
# it is surfaced as launch-stall. Mirrors the §Launch-side liveness >=10-min bootstrap grace
# (patterns/background-session-operation.md §START-CHECK) — a cold worker under fleet load reads the
# full handbook + brief before it claims, so a shorter fuse false-stalls a live-but-slow boot. This
# is the reader's SURFACE threshold only; the controller's >=2-poll gate + Confirmed-dead GATE decide
# any action (detect+surface, never a kill fuse). Advisory, not a lease/TTL.
DISPATCH_NEAR_LAUNCH_GRACE_SEC = 10 * 60
# No-`--task` wave window (F1 absorption): the wave view seeds only boundary events within this
# recent window so OLDER waves do not bleed in (inherited-history kill (a) at the seed layer). A
# caller bounds the wave explicitly with --since/--until; this is the default when neither is given.
DISPATCH_WAVE_WINDOW_SEC = 24 * 60 * 60
# The lifecycle-integrity sweep is a WEEKLY cadence (QUEUE §Re-review), so its no-arg default must
# span a week — the 24h dispatch-wave default would silently miss any bypass older than 1 day
# (T-9367, from a T-9365 audit-post finding). ~8 days = a week + a day of overlap so adjacent weekly
# runs never leave an uncovered seam. A caller still bounds it explicitly with --since/--until.
LIFECYCLE_INTEGRITY_WINDOW_SEC = 8 * 24 * 60 * 60


_parse_iso_ts = textutil.parse_iso_ts   # single home = bin/lib/textutil.py (T-9260)


# --- lifecycle-integrity report (T-9365, post-hoc; X-0044 backstop) ---------------------------
# A PURE READ-ONLY report (no emit, no gate — non-goal #7) that flags a DISPATCHED worker which
# REACHED completion (a land/close terminal) WITHOUT its governed lifecycle chain — the X-0044
# bypass shape: the worker called read-only `task pick` (no claim), never created a worktree,
# committed straight to main, hand-emitted a fake `land_completed`, and ran NO audit. It REUSES
# `_dispatch_status_events` (the one dispatch journal-union reader, Principle 1) — no new store.
# Scoped to DISPATCHED tasks only (those with a `bg_dispatch_launched` boundary), so an interactive
# build is never flagged. land_completed / worktree_created carry the task via data.branch
# (`task/T-XXXX`) / data.leaf, NOT a top-level task_id, so `_event_task_of` maps both forms.
# COMPLETION = a worker claimed WORK SHIPPED: a land OR a close. NOT bare commit_landed (it also
# fires for wont-do bookkeeping + every folded commit), and a `task_wont_do` task is a legitimate
# DECLINE (no work shipped) excluded below — both were false-positive sources in the T-9365 dogfood.
_DISPATCH_COMPLETION_TYPES = ("land_completed", "task_closed")
_DISPATCH_AUDIT_TYPES = ("audit_pre_completed", "audit_post_completed", "external_audit_completed")
# The lifecycle events a governed dispatched build MUST leave before a land/close terminal.
_DISPATCH_REQUIRED_LIFECYCLE = ("worktree_created", "task_picked")


def _kernel_index():
    """T-13012: the ENGINE's committed derived index (`<ENGINE_ROOT>/graph/index.json`) — returned ONLY
    on a -C consumer build (else None, so the engine's own echo never reads it). It is the engine's own
    derived view of the same kernel specs `_kernel_overlay_files` scans: the consumer's own index
    carries no kernel bindings, so the kernel `binding:[seed]` set and the kernel titles live here."""
    if not _is_consumer_build():
        return None
    p = ENGINE_ROOT / GRAPH_DIR / "index.json"
    try:
        return _read_yaml(p) if p.exists() else None
    except Exception:  # noqa: BLE001 — an advisory echo must never crash `session start`
        return None


def _realm_tagged_items(ids, realms, own_specs, kernel_specs) -> list:
    """T-13012: render a consumer echo's kernel ∪ own spec set, one `<SPEC-ID> — <title>` item per id
    (the SPEC-0013 item form), the title taken from THAT id's realm corpus. Realm semantics are the
    gate's (`_stage_bundle_specs(with_realms=True)`): an id the kernel binds is realm "kernel" even when
    the consumer owns the same id (SPEC-0092 — the kernel receipt is the one the gate proves), and
    renders untagged under the line's `--kernel` fetch tail; every OWN-realm item carries its own bare
    fetch form, so a reader never fetches the kernel body for a project-own id or vice versa."""
    items = []
    for sid in ids:
        kernel = realms.get(sid) == "kernel"
        title = (((kernel_specs if kernel else own_specs) or {}).get(sid) or {}).get("title") or ""
        item = f"{sid} — {title.strip()}" if title.strip() else sid
        if not kernel:
            item += f" (project-own: `{graph.spec_query_hint(sid, is_consumer=kernel, cli='')}`)"
        items.append(item)
    return items


def _seed_howto(idx=None, is_consumer=None, kidx=None) -> str:
    """T-0289: the GENERATED seed how-to for STAGE-AGNOSTIC general verbs — derived SOLELY from the specs
    carrying the `seed` residency token (committed `binding_report.seed_specs`, the single canonical
    carrier; P5 — NOT a hand-maintained general-verb list). Regenerating from the carrier reproduces it.
    Lifecycle-scoped content is NOT here — it is delivered on the stage-entry axis (`stage <NAME>`). A
    legitimately-empty set (no spec seed-bound yet) still renders a generated line. Returns 0 effect if
    the index is absent (pre-first-build).

    T-0512: each seed spec renders WITH its title inline (the title IS the navigational pointer — e.g.
    the write-flow pointer to AGENTS §Writes-happen-in-a-worktree), so the seed line surfaces the
    intent→home routing, not a bare id. Title comes from the same derived index (`specs[<id>].title`);
    still generated SOLELY from binding:[seed] (no hand list). `idx` is injectable for testability —
    defaults to reading the committed index.

    T-13012: in a -C consumer session the line renders the kernel ∪ own seed set — the consumer's own
    index carries no kernel `binding:[seed]` specs, so it used to print "(none bound yet)" while the
    kernel seed rules still governed it. Kernel ids come from `_kernel_index()`, realm-tagged by
    `_realm_tagged_items` and fetched `--kernel` (SPEC-0092). The engine's own path is unchanged. `kidx`
    lets the session-start seam hand in the ONE kernel-index read it shares with the Filing echo.

    T-13422 (SPEC-0007 §5a): each item now carries its spec's one-sentence `seed_cue` between the title
    and a PER-ITEM retrieval pointer (`_seed_cue_item`) — cue-and-pointer, the body read on applicability.
    That per-item pointer replaces the old line-level "fetch via" tail; kernel items keep `--kernel`."""
    if idx is None:
        idx = _read_yaml(GRAPH_PATH) if GRAPH_PATH.exists() else None
    if is_consumer is None:
        is_consumer = _is_consumer_build()
    head = ("stage-agnostic general-verb seed (generated from binding:[seed] — each rule's startup cue, "
            "then where its full body lives; read a body when its surface becomes relevant, before the "
            "governed action)")
    if is_consumer:
        kidx = (kidx if kidx is not None else _kernel_index()) or {}
        own = list(((idx or {}).get("binding_report") or {}).get("seed_specs") or [])
        kern = list((kidx.get("binding_report") or {}).get("seed_specs") or [])
        ids = own + [i for i in kern if i not in own]
        if ids:
            realms = {i: ("kernel" if i in kern else "own") for i in ids}
            heads = _realm_tagged_items(ids, realms, (idx or {}).get("specs"), kidx.get("specs"))
            items = []
            for sid, item in zip(ids, heads):
                kernel = realms[sid] == "kernel"
                meta = ((kidx.get("specs") if kernel else (idx or {}).get("specs")) or {}).get(sid) or {}
                items.append(_seed_cue_item(item, meta,
                                            graph.spec_query_hint(sid, is_consumer=kernel, cli="")))
            return (head.replace("binding:[seed]", "binding:[seed], kernel ∪ this project", 1) + ": "
                    + "; ".join(items))
    seed = ((idx or {}).get("binding_report") or {}).get("seed_specs") or []
    if not seed:
        return "stage-agnostic general-verb seed (generated from binding:[seed]): (none bound yet)"
    specs_meta = (idx or {}).get("specs") or {}
    items = []
    for sid in seed:
        meta = specs_meta.get(sid) or {}
        title = (meta.get("title") or "").strip()
        items.append(_seed_cue_item(f"{sid} — {title}" if title else sid, meta,
                                    graph.spec_query_hint(sid, is_consumer=bool(is_consumer), cli="")))
    return head + ": " + "; ".join(items)


def _seed_cue_item(item: str, meta: dict, pointer: str) -> str:
    """T-13422 (SPEC-0007 §5a): one seed item = `<id> — <title>` + its one-sentence `seed_cue` (the trigger
    and first required action) + the retrieval pointer to the full body. A seed spec WITHOUT a cue is never
    silently reduced to its title: it renders a loud MISSING marker (`graph conformance` refuses it)."""
    cue = meta.get("seed_cue")
    cue = cue.strip() if isinstance(cue, str) else ""
    if not cue:
        cue = "seed_cue MISSING (`graph conformance` refuses this — read the body before acting)"
    return f"{item} — {cue} — details before the applicable action: `{pointer}`"


def _filing_reference_howto(idx=None, is_consumer=None, kidx=None) -> str:
    """T-0602 (SPEC-0059 leg-1 Filing carve-out): the GENERATED session-start REFERENCE for the
    Filing-stage authoring doctrine (SPEC-0060). Filing has NO preceding `stage` entry verb, so its
    doctrine cannot be delivered at a `stage <NAME>` entry — it surfaces HERE as an availability
    reference (no gate; the `task file` read-check is the CHECK leg). DERIVED-ONLY from the Filing
    stage bundle (the `stage-entry:Filing` binding → `binding_report.stage_to_specs["Filing"]`, the
    SAME single canonical carrier as `_seed_howto`, P5 — never a hand list). Each spec renders WITH
    its title inline (the navigational pointer). A legitimately-empty set (none bound yet — e.g. while
    SPEC-0060 is non-active) still renders a generated line. `idx` injectable for testability;
    defaults to the committed index. Returns "" only when the index is absent (pre-first-build).

    T-12334 (X-1328): the `fetch via` tail is rendered by the ONE shared SPEC-0092 retrieval-hint
    renderer (`graph.spec_query_hint`, T-11992) — kernel-explicit (`--kernel`) in a `-C` consumer
    session, bare in the engine's own — so this echo and the `worktree new` read-gate hint
    (`_filing_read_gate_hint_lines`) can never disagree on the form. `is_consumer` injectable for
    testability; defaults to `_is_consumer_build()` (the common-dir predicate, never a bare path test).

    T-13012: in a -C consumer session the SET is the one the `task file` read-gate enforces —
    `_stage_bundle_specs('Filing', include_kernel=True, with_realms=True)`, the same call
    `_filing_read_gate_hint_lines` makes — not the consumer's own index, which carries no kernel
    bindings (it printed "(none bound yet)" while the gate refused on exactly those specs). Items are
    realm-tagged by `_realm_tagged_items`; no own index is required (a fresh consumer is gated too).
    `kidx`: the kernel index the session-start seam already read for `_seed_howto` (read once, shared)."""
    if idx is None:
        idx = _read_yaml(GRAPH_PATH) if GRAPH_PATH.exists() else None
    if is_consumer is None:
        is_consumer = _is_consumer_build()
    fetch = f" — fetch via `{graph.spec_query_hint('<SPEC>', is_consumer=bool(is_consumer), cli='')}`"
    label = ("filing-stage authoring doctrine (no entry verb — reference at `task file` time, "
             "SPEC-0059 Filing carve-out): ")
    if is_consumer:
        ids, realms = _stage_bundle_specs("Filing", include_kernel=True, with_realms=True)
        if ids:
            return label + "; ".join(_realm_tagged_items(
                ids, realms, (idx or {}).get("specs"),
                ((kidx if kidx is not None else _kernel_index()) or {}).get("specs"))) + fetch
    if idx is None:
        return ""
    filing = (((idx or {}).get("binding_report") or {}).get("stage_to_specs") or {}).get("Filing") or []
    if not filing:
        return label + "(none bound yet)"
    specs_meta = (idx or {}).get("specs") or {}
    items = []
    for sid in filing:
        title = ((specs_meta.get(sid) or {}).get("title") or "").strip()
        items.append(f"{sid} — {title}" if title else sid)
    return label + "; ".join(items) + fetch


def _filing_read_gate_hint_lines(checkout) -> list:
    """T-11845: the READY-TO-RUN command lines a filer must execute IN a freshly-created
    filing-capable worktree before `task file` / `spec new` — `session start` (the checkout-local
    read-gate anchor) followed by one `graph query <SPEC>` per Filing-stage contract.

    ORDER IS THE CONTRACT, not presentation: `_require_reads` credits only fetch receipts at
    ts >= THIS checkout's own `session_started` lower bound (gates.py), so a fetch run before the
    anchor grants nothing — `session start` therefore comes first.

    DERIVED-ONLY from the SAME single carrier the gate itself reads (`_stage_bundle_specs('Filing',
    include_kernel=_is_consumer_build())`, P5) — the sibling of `_filing_reference_howto`, which
    renders the same bundle as an AVAILABILITY reference. Never a hand list: a spec entering or
    leaving the Filing bundle changes what the gate demands AND what this prints, together.

    CORPUS-AWARE, mirroring the `_require_reads` refusal (T-10564 / X-0416): under a `-C` consumer
    the bare form records its `cli_invoked` receipt on the ENGINE journal while the gate reads the
    consumer's, so the printed form must carry `-C`. It names the CHECKOUT the caller passes — the
    NEW WORKTREE — never REPO_ROOT: a receipt written to the main checkout's journal cannot credit a
    filing inside a worktree (the branch-copy property this card exists to warn about), so the hint
    must not itself commit the mistake it warns against.

    Graceful: an empty/unreadable Filing bundle imposes no obligation → [] (mirrors
    `_filing_reference_howto`'s legitimately-empty path — a hint helper must never crash the verb).

    KERNEL-EXPLICIT under `-C` (T-12334, X-1328). The specs this bundle names are KERNEL contracts,
    but a bare `graph query SPEC-XXXX` resolves consumer-own-FIRST (SPEC-0092): <project> owns its OWN
    SPEC-0060 (video re-keying), so a filer obeying this hint verbatim read the wrong doctrine and paid
    a full re-read (2026-09-08). The always-loaded floor trigger-map already prints `--kernel` for this
    exact reason (T-10766), so the two startup surfaces disagreed on one instruction. Each line is now
    rendered by the ONE shared renderer (`graph.spec_query_hint`, T-11992) — `--kernel` in a consumer
    session, the bare form in the engine's own (byte-identical to before there)."""
    try:
        specs = _stage_bundle_specs("Filing", include_kernel=_is_consumer_build())
    except Exception:  # noqa: BLE001 — advisory hint; a degraded corpus must not break `worktree new`
        return []
    if not specs:
        return []
    is_consumer = _is_consumer_build()
    prefix = (f"{ENGINE_ROOT}/bin/yitc-v2 -C {checkout}" if is_consumer
              else "bin/yitc-v2")
    return ([f"{prefix} session start"]
            + [graph.spec_query_hint(sid, is_consumer=is_consumer, cli=prefix) for sid in specs])


def _worker_identity_self_check(args: argparse.Namespace, resolved_ref: str, source_kind: str) -> None:
    """Worker fail-closed identity self-check at session start (T-0561 part 1).

    GATED on the EXPECTED_SESSION_REF_ENV key being PRESENT in the environment — the ONLY worker
    signal the T-0558 launcher provides (it sets the key UNCONDITIONALLY; there is no separate
    worker-mode flag). Key ABSENT => a normal interactive session (no contract) => return, unaffected.
    Key PRESENT => worker-mode => mechanically compare against `expected`, read ONLY from the explicit
    contract input (no env-resolution fallback — external concept-audit (3)):
      - expected blank/whitespace ("absent/ambiguous" VALUE in worker-mode) => fail-closed ABORT (AC2);
      - the carrier-resolved `resolved_ref` (NOT the frozen accessor — so the check is never
        self-satisfied) != expected => fail-closed ABORT (AC1 — identity collapse / foreign env).
    The ABORT happens BEFORE the session_started emit + any claim/worktree, emitting a
    `worker_identity_refused` event from the pre-claim state (no worktree needed — D-0049 main-checkout
    append; additive event on the open SPEC-0025 enum, precedent read_gate_refused). _die raises, so
    no session_started is emitted and no task is picked. The miswired-no-key worker is prevented by the
    launcher's unconditional set AND backstopped by the read-gate fail-closed session_started anchor
    (SPEC-0050) — a check-skipping worker still cannot commit/close."""
    if EXPECTED_SESSION_REF_ENV not in os.environ:
        return
    expected = os.environ[EXPECTED_SESSION_REF_ENV].strip()
    if not expected:
        _append_event("worker_identity_refused", None,
                      {"type": args.type, "reason": "expected_absent_or_ambiguous",
                       "resolved_session_ref": resolved_ref, "source_kind": source_kind},
                      session_ref=resolved_ref)  # explicit best-effort ref: the fail-closed keying
                      # resolver would _die on the blank contract, so the diagnostic refusal passes the
                      # carrier-resolved ref to still journal (T-0561 / consult t0561-freeze-fix-fork).
        _die("session start (worker): YITC_EXPECTED_SESSION_REF is set but blank/ambiguous — "
             "fail-closed ABORT before any claim/worktree (T-0561 AC2; the launcher-assigned expected "
             "contract input is missing). No task was picked.")
    if resolved_ref != expected:
        _append_event("worker_identity_refused", None,
                      {"type": args.type, "reason": "resolved_expected_mismatch",
                       "resolved_session_ref": resolved_ref, "expected": expected,
                       "source_kind": source_kind},
                      session_ref=expected)  # journal under the launcher-assigned (frozen) identity
                      # for controller correlation (matches AC1) — explicit, not via the keying resolver.
        _die(f"session start (worker): resolved session_ref {resolved_ref!r} != launcher-assigned "
             f"expected {expected!r} — fail-closed ABORT before any claim/worktree (T-0561 AC1; "
             "identity collapse / foreign env). No task was picked.")


def _receipt_only_session_start() -> bool:
    """Is THIS `session start` a RECEIPT-ONLY need (T-12116, WIDENED by T-12207)? DERIVED, never declared.

    True iff this checkout is a **WORKTREE** — that alone. On that answer `cmd_session_start` skips the
    two RE-DELIVERIES (the SPEC-0119 debt echo and the SPEC-0086 cross-coord fold) and prints one line
    saying so; everything else — the anchor, the audience-seed echo, the posture dispatch, and the
    `cli:seed` receipt emit itself — runs unchanged, which is why a worktree run remains a valid stamp
    of its own receipt.

    WHY THE KEY IS THE CHECKOUT, not the session's receipt history (T-12207, owner ask 2026-09-07 «по
    session start в worktree не гонять долг если он там не нужен»). T-12116 keyed this on a fresh
    same-ref same-epoch `seed_read` receipt on the MAIN journal, and its ground was RE-DELIVERY: such a
    session had already received the echo. That ground is real but it covers only part of the case.
    Measured in a `task/` worktree 2026-09-07: a dispatched Worker's `session start --type build` DID
    already skip (its launcher pre-records the main receipt, T-10083 — 2.8 s), but a FIRST-in-checkout
    anchor holding no prior receipt spent 7.8 s deciding the predicate and then 28.5 s folding 18 debt
    lines — inside a worktree, where this echo is not delivered TO anyone who acts on it.

    So the ground recorded here is AUDIENCE + SEAM, not re-delivery: the debt echo is a
    Controller/MAIN-CHECKOUT session-start surface (the same reasoning SPEC-0039 §0 uses to exempt a
    dispatched worker from the MEMORY.md buffer). Nothing that GATES moves — the echo gates nothing at
    all (SPEC-0119 rule 3), and rule 5's on-demand `bin/yitc-v2 debt` re-fold stays the escape, which
    the skip line names. (The LAND-TAIL seam, rule 2b, was itself RETIRED by T-13142 — the echo's two
    seams are main-checkout session start + on-demand `debt`.)

    WHAT THIS DELETES (CHARTER §P1 F3): the session-ref resolution and the `gates.fresh_seed_receipt`
    read with its two `_iter_events` injections — the 7.8 s the predicate itself spent deciding, on top
    of the fold it skips. No flag, no config, no new store. NOTE, stated precisely because the obvious
    guess is wrong: this WAS `gates.fresh_seed_receipt`'s ONLY caller, so that helper (and T-12201's
    tail-first cut inside it) is now UNWIRED. It is deliberately left in place by this card rather than
    deleted with it — retiring it also retires two live test suites and touches `gates.py`, which is an
    adjacent removal owing its own card (§Filing rule), filed as a followup. The SPEC-0050 §8 seed
    read-gate does NOT use this helper; it has its own readers (`_gate_pass_tail_first`).

    THE ONE CONJUNCT, fail-closed toward TODAY'S behaviour (False = the unchanged full run): a MAIN
    checkout journal RESOLVES and DIFFERS from this checkout's. On the main checkout itself the two
    paths are equal, so the predicate is False there BY CONSTRUCTION — which is what keeps the
    main-checkout seam untouched. The dependency on resolving that main checkout is DELIBERATE and is
    kept fail-closed: where the resolution fails, this returns False and the session pays exactly what
    it paid before this change. Degrading an unresolved lookup to "worktree" would invert that
    direction and could suppress the echo on `main` itself (audit-pre F1, declined as framed).

    THE BARE-CLONE ARM (T-13410), reached ONLY when that lookup RETURNED None — never OR'd in unordered,
    never keyed on the T-11445 harness-narrowed locus. The remote-verify box leg is a DETACHED linked
    checkout of a BARE clone (`remote_verify.py#ship_trees` / `#_BOX_LEG_TEMPLATE`): `main` is mirrored
    there but checked out nowhere, so no main-checkout seam exists and every leg paid the debt and cross
    folds whose output it discards. The arm answers True only when the listing at REPO_ROOT SUCCEEDED,
    names NO `branch refs/heads/main`, lists a `bare` entry FIRST, and THIS checkout — REPO_ROOT and the
    directory EVENTS_PATH lives in, as realpaths — is one of its LINKED entries. It is not the declined
    degrade: the listing PROVES no checkout holds main. A failed listing, an unresolved main in a NON-bare
    repo, and a journal redirected off the checkout (an in-process test, the harness's private default)
    still answer False, so `_main_worktree` itself is untouched and answers None there as before.

    Best-effort by contract: ANY exception answers False. This surface may never be the reason a session
    fails to start, and the cost of a wrong False is only that the session pays the folds it pays today.
    """
    try:
        main_events = _journal_locus_main_events(REPO_ROOT)
        if main_events is None:
            entries = _worktree_porcelain_entries(REPO_ROOT)
            if not entries or "bare" not in entries[0]["attrs"]:
                return False
            if any("branch refs/heads/main" in e["attrs"] for e in entries):
                return False
            here = os.path.realpath(REPO_ROOT)
            if os.path.realpath(Path(EVENTS_PATH).parent) != here:
                return False
            return any(os.path.realpath(e["path"]) == here for e in entries[1:])
        if not main_events or Path(main_events) == Path(EVENTS_PATH):
            return False
        return True
    except Exception:
        return False


def _seed_cues_held_this_epoch(ref: "str | None") -> bool:
    """Does THIS context already hold the start block for `ref` (T-13580)? DERIVED, never declared.

    True only on positive proof of BOTH, read before this start writes anything of its own:
      (T) THIS CONVERSATION WAS SHOWN IT — the transcript of the provider session this call runs in
          carries, since its last compaction, the output of a main-checkout `session start` of this
          repository (`session.start_block_in_context`). The transcript is the one carrier that
          binds a delivery to a conversation: a journal receipt binds it to a REF, and a ref can be
          carried into another conversation (a worktree-stamp adoption, a hand-carried id). A start
          whose output went to the null device, the dispatch launcher's pre-recorded worker receipt
          and a start made in another conversation all leave no such record here;
      (J) THIS REF STARTED ON MAIN IN THIS EPOCH — the newest seed receipt of `ref` in the MAIN
          checkout's journal is stamped with an epoch not older than the current one (an absent
          stamp is epoch 0, the seed gate's own reading, SPEC-0050 section 8).
    A `/compact` fails both: the transcript proof is reset at the boundary and the receipt is from
    the earlier epoch — so the sanctioned post-compact re-run prints the full block.
    False in every other state, any exception included — the caller then prints the whole block,
    exactly as before this card. It grants nothing: no receipt, credit or gate reads it.

    reuses: for (J), `gates._gate_snapshot`'s session-scoped tail walk of ONE journal (the read
    `_stage_bundle_held_shas` makes for the same question about a stage contract) — it stops at the
    first seed receipt of this ref; for (T), the transcript `session_epoch` already reads line by
    line on every gated verb, with the same substring pre-filter. (T) runs first, so a session with
    no such record (every dispatched Worker) never walks the journal."""
    try:
        prov = (_provider_session_ref() or "").strip()
        main_events = _journal_locus_main_events(REPO_ROOT)
        if not ref or not prov or not main_events:
            return False
        if not session.start_block_in_context(prov, Path(main_events).parent,
                                              _session_log_path=_session_log_path):
            return False

        def _seed_rows(rows) -> list:
            return [e for e in rows if e.get("type") == "cli_invoked" and e.get("session_ref") == ref
                    and (e.get("data") or {}).get("node_id") == gates.SEED_READ_NODE_ID]

        rows, _bounded = gates._gate_snapshot(
            Path(main_events), tail=True, _iter_events=_iter_events,
            _iter_events_tail=_iter_events_tail, session_ref=ref,
            settled=lambda snap: bool(_seed_rows(snap)))
        seeds = _seed_rows(rows)
        if not seeds:
            return False
        ep = (max(seeds, key=lambda e: e.get("ts") or "").get("data") or {}).get("epoch")
        return (ep if isinstance(ep, int) and not isinstance(ep, bool) else 0) >= _session_epoch()
    except Exception:   # noqa: BLE001 — an echo trim never breaks a start; full block instead
        return False


def cmd_session_start(args: argparse.Namespace) -> None:
    # T-13303 (AC5): the verb's OWN wall-clock start — its seed receipt below is emitted IN-verb, so
    # `main`'s post-run `duration_ms` never reaches it; measured from here, as `main` measures a body.
    _t0 = time.monotonic()
    # T-12208 (SPEC-0190 rule 10) — THE ONE REQUEST-SCOPED ReadScope FOR THE WHOLE SESSION-START
    # REQUEST, installed HERE, at the seam's WIRING SITE: the residue that COMPOSES every view this
    # verb prints. The three managers are the SAME ones `_debt_echo_lines` installs at its own
    # (narrower) residue — no new mechanism, and emphatically NOT a per-view cache, which rule 10
    # names as the proposal to skip the rule.
    #
    # WHAT IT COLLAPSES: the resume-or-await dispatch reads the LIVE worktree journals and their
    # archive segments from TWO callers that sit OUTSIDE `_debt_echo_lines`' scope (the
    # fleet-verdict leg and the dispatch lambda), so the memo that already collapses exactly this
    # was installed one level too deep. This scope collapses those cross-view repeats.
    #
    # HOW MUCH, and WHAT IS LEFT — measured by the regression on its own fixture
    # (tests/test_t12208_session_start_read_scope.py, `_fixture` n_worktrees=3, 2026-09-08), which
    # is where these numbers are re-derived rather than inherited: the whole request folds 60 files
    # over 4 paths (56 repeats) with this scope REMOVED, and 19 over 4 (15 repeats) with it
    # installed. So the scope removes 41 of 56 repeats and LEAVES 15.
    #
    # IT DOES NOT REACH ONE-FOLD-PER-ARTIFACT, and this comment does not claim it does (T-12282 —
    # the earlier «315 folds over 315 paths / one fold per artifact» reading here was contradicted
    # by the shipped measurement and is retired). The remainder is INSIDE a single
    # `_dispatch_status_events` call: `_shared_prefix_start` compares every live-worktree leg
    # against MAIN, so main's journal is opened once per (leg x composed reader) and nothing
    # memoizes that probe. It is owned by T-12269 (owner directive 2026-09-08T01:54:23Z put it out
    # of scope for the card that installed this scope), and the regression BOUNDS it — whole-request
    # repeats <= 2x the per-call union residual — rather than asserting it away.
    #
    # THE SCOPE MUST ENCLOSE ARGUMENT EVALUATION, not just the callee: the debt echo, the cross
    # fold and the controller dispatch all run as OPERANDS of the `session.cmd_session_start` call
    # below (the T-12116 comment there says so explicitly — the folds are paid at argument time).
    #
    # THE INNER `with` IN `_debt_echo_lines` IS NOW A RE-ENTRANT NO-OP (all three managers gained
    # that arm in this change), so the on-demand `debt` re-fold — which enters that residue with NO
    # outer scope — stays byte-identical to before.
    #
    # The body is INDENTED under this `with` rather than delegated to a `_cmd_session_start_scoped`
    # (the T-12144 shape used at `cmd_journal_query` / `cmd_graph_conformance`): four suites pin the
    # debt injection line by the source text of a function LITERALLY named `cmd_session_start`
    # (test_t9754 #test_c1 plus t11125 / t11181 / t11353), and `git diff -w` shows this change as
    # the one line it is.
    #
    # T-13108 — `rows_memo` IS NOW UNCONDITIONAL; the paragraph below is the T-12208 reasoning it
    # replaces, kept because its measurement is still true and its PREMISE is not. It held that a
    # receipt-only start folds nothing else whole, so declaring the journal would only turn the
    # dispatch leg's bounded tail into full folds. T-12380 then added `_auditor_hint_lines` ->
    # `audit.auditor_status`, which folds the WHOLE journal (`_iter_events`) on EVERY start, and the
    # auto-sync's T-12495 hand-down memo is only ADOPTED by a scope that declares the journal. So an
    # undeclared receipt-only start paid TWO whole folds: measured on a <project> task worktree
    # 2026-09-28, 140 folds over 70 segments, and on the consumer fixture in
    # tests/test_t12208_session_start_read_scope.py. Declared, the sync's fold is adopted and every
    # later reader — the auditor count, the followup fold, the dispatch leg — is served from it.
    #
    # (T-12208, superseded premise) WHY `rows_memo` WAS THE ONE CONDITIONAL MEMBER — it is the only one of the three that changes a
    # reader's PATH CHOICE, not merely where its answer comes from. `_dispatch_status_events`
    # consults `rows_memo_holds(p)` and, for a HELD journal, abandons its bounded tail seek and
    # folds the whole segment set (journal.py — the `start == 0 and rows_memo_holds(p)` branch),
    # which is exactly right when something else in the request folds it anyway. On a FULL start the
    # debt echo does. On a RECEIPT-ONLY start (T-12116 — a worktree entry by a session already
    # holding a fresh receipt) the debt echo is NOT CALLED AT ALL, so declaring the journal there
    # would convert the dispatch leg's 2 bounded folds into 99 full ones — the seam would pay MORE
    # reads for adopting rule 10. MEASURED, not reasoned: 2 -> 99 on this checkout, 2026-09-07.
    # The other two declare no path and can only ever SERVE a call their scope's reader would have
    # made, so they are unconditional.
    _receipt_only = _receipt_only_session_start()
    with contextlib.ExitStack() as _read_scope:
        # T-13265: name each malformed task card / plan this start skips, once per path.
        _start_skip_scope(True)
        _read_scope.callback(_start_skip_scope, False)
        _read_scope.enter_context(_dispatch_events_memo())
        _read_scope.enter_context(followup_mod.fold_memo())
        # T-13303: `live_settled` — nothing in this request appends to the live segment and reads it
        # back (the debt echo and every view run before `session_started` is emitted), so the
        # strict-text readers (the SPEC-0098 floor probe) take the live segment from this one fold too.
        _live_memo = _read_scope.enter_context(journal_mod.rows_memo([EVENTS_PATH]))
        if _live_memo is not None:      # a test that nulls the memo hands back None
            _live_memo.live_settled = True
            # T-13461: what this request's walks leave in the memo is the live segment plus the
            # SPEC-0190 summary window, compressed — never decoded lines + parsed rows of every
            # segment a walk touched (5.2 GB on the kernel), and nothing older than that window.
            _live_memo.pack_since = events.summary_window_floor() or "9999-12-31"
        # Thin residue → session.cmd_session_start (T-9336). Injects host collaborators/globals read at
        # call time (so a -C REPO_ROOT rebind + any monkeypatch.setattr(yitc, …) — incl. the dispatch
        # helper residues a test patches + drives THROUGH cmd_session_start — stay honored). argparse
        # set_defaults(func=cmd_session_start) stays on THIS residue.
        # T-12116: DERIVE whether this run is receipt-only (a worktree entry by a session that already
        # holds a fresh seed_read receipt on main). Computed ONCE, BEFORE the argument list below, because
        # the two folds this skips are paid at ARGUMENT-EVALUATION time — guarding the CALLS is what buys
        # the time, not a branch inside the callee. Measured on this repo 2026-09-05: `_debt_echo_lines()`
        # alone is ~52 s of a ~57 s in-worktree run; the cross fold is ~0.4 s.
        # (`_receipt_only` is derived ABOVE, before the scope — the scope's own membership needs it.)
        # T-12961 (SPEC-0125 Rule 2c): the project identity computed ONCE — it is both recorded on
        # `session_started` and printed in the visible start line, so the two cannot differ.
        _peer_aliases = _cross_peer_aliases() if not _receipt_only else None
        _project = cross.canonical_peer((_main_worktree(REPO_ROOT) or REPO_ROOT).name, _peer_aliases)
        # T-13012: ONE engine-index read per -C session start, shared by the seed + Filing echoes
        # (None on the engine's own session — `_kernel_index` returns None there).
        _kidx = _kernel_index() if not _receipt_only else None
        # T-13580: on a receipt-only run, ask ONCE — at identity resolution, before this start writes
        # its anchor or its runtime record — whether this context already holds the start block, and
        # hand the answer in as a VALUE (the `_cross_linked_ids` shape: no new bare-name Call in the
        # AST-scanned body). Empty on every other start, so nothing is read there.
        _seed_held_refs: set = set()

        def _identity_noting_seed_held(arg_value=None):
            ref, kind = _session_start_identity_noted(arg_value)
            if _receipt_only and _seed_cues_held_this_epoch(ref):
                _seed_held_refs.add(ref)
            return ref, kind

        _resolved_ref, _resolved_source_kind = session.cmd_session_start(
            args, _resolve_or_mint_identity=_identity_noting_seed_held,
            _seed_held_refs=_seed_held_refs,
            _worker_identity_self_check=_worker_identity_self_check, _append_event=_append_event,
            _session_config_descriptor=_session_config_descriptor, _is_consumer_build=_is_consumer_build,
            _seed_howto=lambda: _seed_howto(kidx=_kidx),
            _filing_reference_howto=lambda: _filing_reference_howto(kidx=_kidx),
            _main_worktree=_main_worktree,
            _session_build_dispatch=_session_build_dispatch,
            _session_controller_dispatch=_session_controller_dispatch,
            _controller_acting_holder=_controller_acting_holder, REPO_ROOT=REPO_ROOT,
            ENGINE_ROOT=ENGINE_ROOT, RELEASE_VIEW_DIR=RELEASE_VIEW_DIR,
            HANDBOOK_READ_ORDER=HANDBOOK_READ_ORDER, CROSS_LOG_PATH=_SELF.CROSS_LOG_PATH,
            # T-9400: compute the linked-ids SET here in the (un-AST-scanned) residue and inject the VALUE,
            # so cmd_session_start references it without a new bare-name Call — keeping the D-0052 F5 startup
            # allowlist green without a two-phase land vs the SPEC-0077 pinned verifier.
            # T-12116: skipped (not merely unused) on a receipt-only run — see `_receipt_only_session_start`.
            # Same operand order as the debt fold below, for the same pinned-seam reason.
            _cross_linked_ids=_cross_linked_ids() if not _receipt_only else None,
            _cross_peer_aliases=_peer_aliases, _project_name=_project,
            _receipt_only=_receipt_only,
            # T-12984: is the kernel a registered peer on THIS host? (empty set on a missing/unreadable
            # registry -> False -> the consumer reflex echo says LOCAL, never AUTO-ROUTES).
            _kernel_is_local_peer=(KERNEL_NAME in _cross_known_registry_peers()) if not _receipt_only else None,
            # T-9469: inject the yaml reader so the consumer-echo can count the consumer's active specs
            # (_read_yaml is already in the D-0052 F5 startup AST-allowlist — no new bare-name call).
            _read_yaml=_read_yaml,
            # T-9754 (SPEC-0119): the proactive-debt echo. COMPUTE the lines here in the (un-AST-scanned)
            # residue and inject the VALUE — so cmd_session_start references it without a new bare-name Call,
            # keeping the D-0052 F5 startup allowlist green without a two-phase land (the _cross_linked_ids
            # precedent). Best-effort ([] on any failure) so startup is never broken by the surface.
            # T-12116: the ~52 s fold — NOT CALLED at all on a receipt-only run (the session already
            # received this echo at its main-checkout start; re-fold on demand with `bin/yitc-v2 debt`).
            # KEEP THIS OPERAND ORDER. Several sibling suites pin this seam by the literal source text
            # `_debt_echo_lines=_debt_echo_lines()` (tests/test_t9754_proactive_debt_echo.py
            # #test_c1_session_start_call_site_wired and the census/creep guards that mirror it), asserting
            # the seam injects the COMPUTED VALUE of the ONE shared helper rather than a callable or a
            # re-implementation — which this still does. Writing it the other way round
            # (`[] if _receipt_only else …`) breaks that substring and fails 6 suites that this change has
            # no business touching. The conditional is lazy either way, so the skip is real in this order.
            # T-12305 (SPEC-0119 rule 40): the injected value is COMPACTED to the one-row-per-class
            # table before it is printed. The owner could not read the paragraph render («читать
            # нельзя», 2026-09-09) — measured 19,014 bytes over 20 lines on this repo. The long text
            # is NOT lost and NOT rewritten: `bin/yitc-v2 debt` bare still renders it in full (rule 5,
            # the post-`/compact` re-fold) and `debt --explain <class>` reprints one class verbatim.
            # The pinned literal `_debt_echo_lines=_debt_echo_lines()` above SURVIVES this wrapping
            # (it is the keyword argument), so the four suites that assert this seam injects the
            # COMPUTED VALUE of the ONE shared helper stay green — and they still describe the truth:
            # the helper's return value is what is injected, now via a pure presentation fold.
            _debt_echo_lines=_debt_echo_compact(_debt_echo_lines=_debt_echo_lines()) if not _receipt_only else [],
            # T-10153: inject the runtime-record writer + the live provider-KIND reader (references, not
            # Calls — D-0052 F5 startup-allowlist-safe, the _session_start_identity precedent) so session-start births
            # a runtime record carrying the FORENSIC provider_meta (SPEC-0137 Rule 2.5). NARROW forensic
            # transcript-locator capture only — it does NOT touch the resolver (_resolve_session_ref); the
            # record is inert until T-10149's rediscovery consumes it, and _session_log_path reads the
            # provider_meta back to locate a codex/claude transcript from v2 state, not the live env.
            _write_runtime_record=_write_runtime_record, _provider_kind=_current_provider_kind,
            # T-12400: the provider's own session id (the D-0030 transcript NAME) — same reference-not-call
            # injection, same forensic rule-2.5 role as _provider_kind above; never an identity selector.
            _provider_session_id=_provider_session_ref,
            # T-13010: the journal `_append_event` actually wrote under --read-only (same expression it
            # uses to pick its default target), so the confirmation line names THAT, not the -C target.
            _read_only_journal=EVENTS_APPEND_PATH if READ_ONLY_ROOT is not None else None)
        # T-10172 (SPEC-0143 Rule 3): the report-only per-concern DRIFT surface at the consumer -C
        # session-start seam — consumer-gated, suppressed-when-clean, derived (no consumer-repo mutation),
        # emits concern_drift_surfaced AFTER the session_started anchor above. Best-effort (never breaks start).
        _surface_concern_drift()
        # T-12000: DELIVER this checkout's current stage bundle — AFTER the `session_started` anchor
        # `session.cmd_session_start` just wrote, at the SAME post-anchor residue seam as the
        # concern-drift surface above (so `cmd_session_start` gains no injected dep and the D-0052 F5
        # startup AST-allowlist is untouched — the `_surface_concern_drift` precedent). The ordering IS
        # the correctness property: receipts written here satisfy `ts >= _session_started_lower_bound`
        # by construction, which is exactly what a CLAIM-time delivery could not do (T-11988).
        _deliver_current_stage_bundle_at_session_start()
        # T-10776 (SPEC-0171): the consumer frontend-error ECHO — report-only, suppressed-when-clean,
        # printed at this same post-anchor residue seam as the concern-drift surface above (so
        # cmd_session_start gains no injected dep and the D-0052 F5 startup AST-allowlist / SPEC-0077
        # pinned-verify contract is untouched — the `_surface_concern_drift` precedent). Best-effort:
        # the leaf returns [] on ANY failure, so this never breaks start. The post-`/compact` re-fold is
        # `bin/yitc-v2 [-C <repo>] frontend-errors` (AGENTS §After-`/compact`), co-designed with it.
        for _fe_ln in _frontend_error_echo_lines():
            print(session.mark(_fe_ln, session.REPORT_ONLY))   # T-13435: every echo line states its class
        # T-12380 (SPEC-0201 rule 3 / SPEC-0202 rule 4): the external-auditor HINT — ONE report-only line
        # while no external provider resolves for the routine tier, silent otherwise — printed at this
        # SAME post-anchor residue seam (engine self-start AND -C: one residue, the consumer's journal
        # for the count, the engine-rebound AUDIT_CONFIG_PATH for the config). Session-start ONLY (owner
        # decision 2026-09-06 «только на старте»); the post-`/compact` re-fold is `bin/yitc-v2 audit
        # status` (AGENTS §After-`/compact`), co-designed with it. Best-effort: [] on any failure.
        for _ah_ln in _auditor_hint_lines():
            print(session.mark(_ah_ln, session.REPORT_ONLY))
        # T-13251 (SPEC-1004 §4): the open session hand-offs — interactive Controller ONLY (never a
        # `--type build` / launcher-dispatched worker, SPEC-1004 §5), engine and -C alike, at this same
        # post-anchor residue seam. Owner-cued show-and-wait (T-13503: no runnable command on it),
        # suppressed-when-empty, read-only; best-effort so it never breaks start. The post-`/compact`
        # re-fold is `session handoff list`.
        # T-13580: an owner-cued line this context already holds — not repeated on a same-epoch repeat.
        if (getattr(args, "type", None) != "build" and EXPECTED_SESSION_REF_ENV not in os.environ
                and _resolved_ref not in _seed_held_refs):
            try:
                _ho_lines = session.handoff_start_echo_lines(
                    REPO_ROOT, split_frontmatter_text=split_frontmatter_text,
                    now=_dt.datetime.now(_dt.timezone.utc))
            except Exception:   # noqa: BLE001 — report-only; never breaks session start
                _ho_lines = []
            for _ho_i, _ho_ln in enumerate(_ho_lines):   # the head is owner-cued; rows are its continuation
                print(session.mark(_ho_ln, session.OWNER_CUED) if _ho_i == 0 else _ho_ln)
        # T-10268 (SPEC-0147 §5): station A's OWN seam. The digest names the stations this person still
        # owes and the seam each is due at — suppressed entirely when no pointer is held (zero footprint),
        # and skipped for a dispatched Worker, which does not read the buffer at all (SPEC-0039 §0 / T-9757).
        if getattr(args, "type", None) != "build":
            _onboarding_digest()
        _print_context_seam_tail()   # SPEC-0115 §7 seam tail (T-9707) — printed once at this clean seam
        # T-13258: the engine version THIS session runs (a release updated under a live session leaves it
        # on the old code). Report-only, engine and -C alike; post-/compact re-fold: `release check`.
        try:
            print(session.mark(release_mod.engine_version_line(), session.REPORT_ONLY))
        except Exception:  # noqa: BLE001 — a report-only line never fails the start
            pass
        # T-13435: the LAST agent-facing line — startup's end and the one step left (the session-tied
        # `--help` scan), printed immediately BEFORE the person-facing line, which stays the final one.
        print(session.startup_done_line(getattr(args, "type", None) == "build",
                                        f"YITC_SESSION_REF={_resolved_ref} {_cli_invocation_form()} --help"))
        print(session.visible_start_line(_project))   # SPEC-0125 Rule 2c (T-12961) — the person's start line
        # T-10081 (SPEC-0042 §seed floor): emit the seed_read fetch-receipt AFTER session_started + the
        # audience-seed delivery above — the pass-granting evidence of the BROAD anti-Forgetting read-gate
        # (`_require_seed_read`, checked at the main() dispatch chokepoint for every governed/mutating verb).
        # A cli_invoked row carrying data.node_id == gates.SEED_READ_NODE_ID (the emit analog of the --help
        # fetch-receipt; the node_id is set inside _emit_cli_invoked for verb_label "session start"). The
        # receipt necessarily post-dates the session_started anchor just emitted, so it lands in-window
        # (SPEC-0050 §2). Best-effort — the seed is already delivered, so a journal hiccup must not fail
        # `session start` (mirrors the --help emit's swallow).
        # T-10246: stamp it under the ref `cmd_session_start` just resolved — the SAME id `session_started` was
        # emitted under. Passing it, rather than letting `_emit_cli_invoked` re-derive one, is what keeps the
        # two gate-bearing emits on ONE authoritative id (SPEC-0137 Rule 2). Re-derivation is what split them.
        # T-10318: pass its `source_kind` too, so the receipt records the selector that actually produced the
        # id — the same authoritative class `session_started` carries, never a re-derivation or an `explicit`
        # collapse-bucket (audit-pre finding 1).
        try:
            _emit_cli_invoked("session start", sys.argv[1:], 0, 0, 0, session_ref=_resolved_ref,
                              source_kind=_resolved_source_kind,
                              duration_ms=int((time.monotonic() - _t0) * 1000))
        except Exception:
            pass


def cmd_session_pick(args: argparse.Namespace) -> int:
    # Thin residue → session.cmd_session_pick (T-12960, SPEC-0086 rule 6f). Injects the registry path,
    # the ONE registry reader and the runner at call time (so $YITC_REGISTRY + monkeypatches stay honored).
    import subprocess as _sp
    rc = session.cmd_session_pick(
        args, registry_path=REGISTRY_PATH, engine_root=ENGINE_ROOT, kernel_name=KERNEL_NAME,
        _v2_projects=nightly_mod._v2_projects, cli=_ENTRY_FILE, _run=_sp.run, _input=input,
        _isatty=sys.stdin.isatty)
    if rc:
        sys.exit(rc)
    return rc


def cmd_session_handoff(args: argparse.Namespace) -> None:
    # Thin residue → session.cmd_session_handoff (SPEC-1004 §4 / T-13250). Collaborators are read at call
    # time so a -C REPO_ROOT/EVENTS_PATH rebind + test monkeypatches stay honored. The worker context is
    # the launcher-assigned contract var (the same signal the strict keyer's selector 1a keys on).
    def _live_watchers(author_ref):
        # T-13539 — the hand-off author's live watchers, through the dedup seam's own reader, window
        # and liveness test (one definition of a live watcher). Watcher rows live on MAIN's journal.
        return dispatch._live_watchers_over(
            [], session_ref=author_ref, main_wt=_main_worktree(REPO_ROOT) or REPO_ROOT,
            _dispatch_status_events=_dispatch_status_events, _pid_alive=dispatch._default_pid_alive)

    return session.cmd_session_handoff(
        args, REPO_ROOT=REPO_ROOT, _die=_die, _resolve_session_ref=_resolve_session_ref,
        _append_event=_append_event, split_frontmatter_text=split_frontmatter_text, redact_secrets=journal_mod.redact_secrets,
        alloc=_alloc_under_lock, state_dump=state.dump,
        worker_context=EXPECTED_SESSION_REF_ENV in os.environ, _live_watchers=_live_watchers)


def cmd_session_context(args: argparse.Namespace) -> None:
    # Thin residue → session.cmd_session_context (SPEC-0115 / T-9704). Injects the host collaborators
    # read at call time (so a -C REPO_ROOT rebind + any monkeypatch.setattr(yitc, …) stay honored).
    return session.cmd_session_context(
        args, _provider_session_ref=_provider_session_ref, _session_log_path=_session_log_path,
        _kernel_content_file=_kernel_content_file, _read_yaml=_read_yaml, ENGINE_ROOT=ENGINE_ROOT)


def _context_seam_tail_line():
    """The context-sensor seam tail (SPEC-0115 §7 / T-9707) — the one-line `context N% — …` string for
    the CURRENT session, computed by the SINGLE compute home session.context_tail_for_current_session
    (P5 — never re-parsed here). BEST-EFFORT: any failure (no transcript, parse hiccup) returns None so
    the seam verb — especially `land` — is NEVER broken by the informational sensor. Returns str|None.

    T-10495: ENGINE_ROOT is injected so the pricing config still resolves at the LAND tail — `-C <worktree>
    land` points REPO_ROOT at a worktree that land has REMOVED by the time this prints, and ENGINE_ROOT is
    the import-time root `-C` never rebinds."""
    try:
        return session.context_tail_for_current_session(
            _provider_session_ref=_provider_session_ref, _session_log_path=_session_log_path,
            _kernel_content_file=_kernel_content_file, _read_yaml=_read_yaml, ENGINE_ROOT=ENGINE_ROOT)
    except Exception:
        return None


def _print_context_seam_tail() -> None:
    """Print the context-sensor seam tail ONCE at a clean workflow seam (SPEC-0115 §7). No-op when the
    sensor yields nothing (best-effort). The leaf compute home calls no seam verb → no recursion."""
    line = _context_seam_tail_line()
    if line:
        print(session.mark(line, session.REPORT_ONLY))   # T-13435: report-only at every seam it closes


def _open_followup_counts() -> dict:
    """SPEC-0119 / T-9754, three-way since T-10309: the OPEN-followup counts — folds the journal
    (SPEC-0095, `followup._fold`) and partitions the still-`open` records into `{actionable,
    armed_fired, armed_waiting}` (the disposition-awaiting debt, split from the armed waiters). Reuses
    the ONE fold + the ONE partition + the EFFECTIVE followup events path (read-path==write-path); no
    second parse, so this can never disagree with `followup list`.

    The fire check needs the set of TERMINAL task ids — supplied by the EXISTING terminality scan
    (the done|wont-do predicate `views` already consumes for the retention drain), read-only. No new
    resolver, no new store: an armed followup whose `awaits` task has since closed is derived, at
    read time, as `armed_fired`. T-11604 — the SAME scan now also hands over each terminal card's
    `closed_at` (`_terminal_task_closures`), which the stale-provenance marker needs for its ordering
    check. Same walk, same read, one extra field off the card; `terminal_ids` is unchanged, so the
    fire key is untouched."""
    # T-11453 — `journal_mod.fold_lines` arrives by INJECTION, never by import: followup.py is
    # leaf-up / stdlib-only (SPEC-0080 §P-A1), so the request-scoped memo has to reach it the way
    # every other host collaborator does. Inside `_debt_echo_lines`' scope this fold is served from
    # the SAME single parse the other ~14 debt readers share; outside one it is a plain read, so
    # `followup list` / `promote` are byte-identical.
    closures = _terminal_task_closures()
    return followup_mod.open_followup_counts(_followup_events_path(), frozenset(closures),
                                             closed_at_by_id=closures,
                                             _segment_lines=journal_mod.segment_fold_lines,
                                             # T-12202 — the ALREADY-PARSED lane of the SAME read,
                                             # beside the line reader, so the fold stops paying a
                                             # SECOND full parse of the corpus the scope already
                                             # holds. THE ONLY injection site, and the bound is the
                                             # scope: this function has ONE caller, inside
                                             # `_debt_echo_lines`' `rows_memo` `with`, where taking
                                             # both lanes is one read + a memo hit. At a site
                                             # reachable OUTSIDE that scope it would be a second
                                             # physical read (see `debt.p8_carrier_followups`), and
                                             # it is not needed there: this call runs BEFORE the
                                             # render, so the entry every later fold is served from
                                             # is the one computed here. Same leaf-up injection
                                             # discipline (SPEC-0080 §P-A1): followup.py imports no
                                             # host module.
                                             _segment_rows=journal_mod.segment_rows,
                                             # T-11964 — the X-NNNN half of the fire set. The
                                             # event-class half rides the fold this call already does.
                                             terminal_cross_ids=_terminal_cross_ids())


def _born_permissive_concerns_for_echo() -> list:
    """T-11969: the born-permissive concern roster AS A REPORT-ONLY SURFACE READS IT — the shipped
    `init.born_permissive_concerns` reader, with an UNREADABLE registry answered as "nothing to
    report" instead of as a seam-killing exit.

    THE WRAPPER EXISTS FOR A CONTAINMENT GAP, not for taste. `init._load_concern_registry` FAILS CLOSED
    on a missing / unparseable registry by design — it is the roster the `graph conformance` REFUSAL
    iterates, and a silent empty roster there would fail the whole sweep OPEN. But it fails closed by
    raising SystemExit, which is a BaseException: the residue's own `except Exception` does NOT catch
    it, so without this wrapper an unmaterialised `graph/concern-registry.json` would take down EVERY
    debt line at EVERY seam — session-start and the `debt` verb alike. Measured, not
    theorised: it reddened 8 test files whose sandboxes build a repo copy without the derived registry.

    FAILING TOWARD SILENCE IS THE RIGHT DIRECTION *HERE*, and only here (`lessons/a-signal-about-a-
    reader-fails-safe-the-opposite-way-to-a-gate.md`). A GUARD fails closed; a REPORT-ONLY signal fails
    toward saying nothing. The fail-closed reading of a broken registry is not weakened by this: it
    still fires at its own home, the `graph conformance` RED refusal, which is the surface that owns
    that question. This wrapper narrows nothing there and adds no second answer to it."""
    try:
        return init_mod.born_permissive_concerns()
    except (Exception, SystemExit):   # noqa: BLE001 — see the containment paragraph above
        return []


def _project_growth_reading(now=None):
    """T-11969 (SPEC-0189 §Parameters + rule 3): THIS repo's growth reading — the shared fold
    `views.project_growth` over this repo's OWN journal rows, across the window read from SPEC-0189.
    Returns the labelled reading, or None when it cannot be taken.

    IT READS ONLY THIS REPO'S JOURNAL. AGENTS §Scope-boundary keeps another project's repo read-only
    and explicitly NOT monitored or probed, so the reading a session takes is its own — which is also
    why the fold takes its events as an input rather than resolving paths itself.

    IT COSTS NOTHING EXTRA AT THE SEAM: `_iter_events` is the same reader its ~15 debt-echo siblings
    use, and this call sits inside the residue's `rows_memo` scope, so the journal is already parsed
    once between all of them (T-11453). No second parse path (CHARTER §P1).

    FAIL-CLOSED TO None, never to a number: `growth_window_days` returns None when SPEC-0189's token
    cannot be read, and a guessed window would be exactly the local literal that parameter exists to
    forbid. A None reading still renders — the proposal is emitted either way and the clause names the
    absence (rule 3: growth never decides whether a proposal is made).

    `now` defaults to the wall clock and is a PARAMETER for the same reason
    `growth_window_days(specs_dir=…)` takes one: a fixture corpus is dated history, so the census
    driver that exercises THIS function (rather than a re-implementation of it) needs to ask it for a
    window the fixture's rows actually fall in. Production callers pass nothing."""
    window = views.growth_window_days()
    if window is None:
        return None
    return views.project_growth(REPO_ROOT.name, _iter_events(types=views.PROJECT_GROWTH_READ_TYPES),
                                window_days=window, now=now)


#: T-12085 (audit-post finding, 2026-09-05) — the OMITTED-ARGUMENT sentinel for the debt seam's
#: carrier thread. `None` cannot carry it: `None` is also what a carrier-less read may answer, so a
#: caller that legitimately says "this repo HAS no carrier" was indistinguishable from one that
#: never passed the argument — and the seam re-opened `yitc-ops.yaml` on every such call. With the
#: sentinel, "not supplied" is a value nothing else can produce, and ABSENT is an ordinary `{}`.
_CARRIER_UNSET = object()


def _profile_resolution(carrier=_CARRIER_UNSET) -> dict:
    """T-12080 (SPEC-0198 rule 3): THIS repo's growth profile — the ONE host binding of the resolver.

    The whole contribution here is BINDING, never deriving: which checkout (`REPO_ROOT`, so the
    `-C`-rebound root wins) and whose journal rows (`_iter_events()`, this repo's own). Every value
    comes from `profile.resolve_profile`, which SPEC-0198 rule 3 makes the only derivation site.

    IT EXISTS AS ONE NAMED HELPER RATHER THAN TWO INLINE EXPRESSIONS because it has two callers —
    the `profile` verb and the debt-echo collaborator — and two spellings of the same binding is
    exactly the drift CHARTER §P5 is about. It is also what keeps the journal-reader census
    (`dev-utilities/census-journal-readers.py`) enumerating ONE site for this feature instead of two.

    IT READS ONLY THIS REPO'S JOURNAL — AGENTS §Scope-boundary keeps another project's repo
    unmonitored, the same bound `_project_growth_reading` above states. At the debt residue this call
    sits inside the request-scoped `journal_mod.rows_memo` scope, so it costs no second parse.

    `carrier` is the ALREADY-PARSED ops carrier when the CALLER holds one (the debt seam does — it
    reads it FIRST and threads it here). Omitted, the resolver opens the file itself, which is what
    a lone `profile` verb wants. Threading it is what makes the seam's one-carrier-read property
    TRUE at the seam rather than only at the two helpers below it: before this, `resolve_profile`
    re-opened `yitc-ops.yaml` on its own no matter what the seam had already parsed."""
    ops = None if carrier is _CARRIER_UNSET else carrier
    # T-12452: a LIST, not the `_iter_events()` generator — the resolver walks `events` twice (the
    # liveness scan in `_derive`, then rule 7's `_prior_snapshot`), and a generator exhausted by the
    # first walk silently starved the latch of every recorded snapshot.
    # T-13139 — declared: the resolver reads the live-signal rows and the snapshot rows, nothing else.
    return profile_mod.resolve_profile(
        REPO_ROOT, events=list(_iter_events(types=profile_mod._LIVE_EVENT_TYPES
                                            + profile_mod.PROFILE_SNAPSHOT_EVENT_TYPES)), ops=ops)


def _gap_task_resolvable(tid: str) -> bool:
    """T-12085: does a task card for `tid` EXIST in this repo's corpus?

    The host half of `debt.gap_task_linked`'s "requires a RESOLVABLE T-id" — binding `TASKS_DIR`,
    deciding nothing. It lives here rather than in the fold for the reason every corpus lookup does:
    `lib.debt` is handed its inputs and does not resolve repo paths, and `TASKS_DIR` is a module
    global the hermetic-corpus helper REBINDS, so a path derived any other way would read the real
    corpus straight through that redirect.

    THE GRAMMAR IS CHECKED HERE, BEFORE ANY PATH LOOKUP (audit-post finding, 2026-09-05). The id is
    INTERPOLATED into a glob, so an unvalidated value is a glob INJECTION: a carrier declaring
    `task: "T-*"` matched an unrelated card, the reference read as resolvable, and the followup was
    armed on somebody else's task. Validating inside `debt.gap_task_linked` alone was not enough —
    that is the other caller; THIS path reached the glob first. Fail-closed: anything that is not
    exactly `T-<digits>` is unresolvable and never touches the corpus."""
    if not debt_mod._GAP_TASK_ID_RE.match(str(tid or "").strip()):
        return False
    try:
        return any(TASKS_DIR.glob(f"{tid}-*.yaml")) or (TASKS_DIR / f"{tid}.yaml").exists()
    except Exception:                              # noqa: BLE001 — an unreadable corpus is not a proof
        return False


def _gap_ops_carrier():
    """THIS repo's parsed `yitc-ops.yaml` — read ONCE per debt seam and threaded into the profile
    resolution, the gap fold and the writer beside them (audit-post findings, 2026-09-05).

    It exists as one named helper for the same reason `_profile_resolution` does: two spellings of
    one binding is the drift CHARTER §P5 is about, and here the second spelling was also a second
    parse of the same file at every session start and every `debt` re-fold.

    IT NEVER ANSWERS `None`, and that is the fix rather than an incidental tidy. `None` conflated
    "this repo HAS no carrier" with "the argument was not supplied", so a carrier-LESS repo — the
    engine kernel itself — re-opened the file at every consumer, which is precisely the repeated
    read the one-carrier-read rule is about. The answers are now the three the reader actually
    needs, and they are `profile._load_ops`' OWN answers because this delegates to it rather than
    re-deriving them: `{}` = read successfully, declares nothing (ABSENT or empty);
    `profile._OPS_UNREADABLE` = the file is there and could not be read, so every carrier-borne
    signal is UNKNOWN not absent; otherwise the parsed mapping. Reaching for a sibling module's
    private reader is the `task._ops_declares` precedent (it calls `worktree._load_ops_carrier_text`
    for the same reason): ONE parser, not a second spelling of it."""
    try:
        return profile_mod._load_ops(REPO_ROOT)
    except Exception:                              # noqa: BLE001 — a broken read is not a proof
        return profile_mod._OPS_UNREADABLE


def _gap_register_view(resolution=None, carrier=_CARRIER_UNSET) -> dict:
    """T-12085 (SPEC-0119 rule 39 / SPEC-0198 rules 5+7): THIS repo's brownfield gap register.

    Binding only — the checkout's ops carrier, this repo's already-parsed journal rows, and the
    already-resolved profile. `resolution` is passed IN by the debt residue so the profile is
    resolved ONCE per seam and shared with the T-12080 line; a caller that omits it resolves its
    own. No cache lives here: inside the residue this call sits in the request-scoped
    `journal_mod.rows_memo` scope, which is the SPEC-0190 rule 10 answer (the seam owes ONE
    ReadScope at its wiring site, never a per-view cache).

    `carrier` OMITTED (the sentinel) means "I hold none, read it" — NOT "this repo has none". A
    caller that has already read the carrier passes it, INCLUDING the `{}` an absent one answers,
    and nothing here opens the file again. The resolution is derived from the SAME carrier, so the
    line and the register can never speak for two versions of `yitc-ops.yaml`."""
    _carrier = _gap_ops_carrier() if carrier is _CARRIER_UNSET else carrier
    return debt_mod.profile_gap_register(
        resolution=resolution if resolution is not None else _profile_resolution(carrier=_carrier),
        ops_path=REPO_ROOT / "yitc-ops.yaml",
        ops=_carrier,
        rows=_gap_filed_rows_repo_wide(_iter_events(types=debt_mod.GAP_FILED_READ_TYPES)),   # T-13139 typed own read + T-13042 siblings
        resolvable=_gap_task_resolvable)


_GAP_SIBLING_ROW_TYPES = ("followup_added", "followup_promoted", "followup_dropped")


def _gap_filed_rows_repo_wide(own_rows):
    """T-13042 (SPEC-0119 rule 39 'deduped FOREVER by the key'): the rows the gap register learns
    what is FILED from — `own_rows` (this checkout's segment set), then the followup rows of every OTHER worktree's
    journal of the same repo (the main checkout is one of them), segment-aware through the SAME
    `journal.segment_lines` fold — SKIPPING every archive segment `journal._archive_segments_identical_to_main`
    verifies identical to this checkout's own (the T-12494/T-13108 skip): re-folding those per sibling
    doubled the request's folds (T-13108's consumer read-scope bound), while a segment only the sibling
    has (rotated before landing) is still read. This checkout's own journal is never re-folded here.

    Measured cause: <project> filed the same two gap keys twice, 09-11 and 09-13, because the first
    filing sat in an unlanded sibling worktree's journal the second seam never read.

    A GENERATOR ON PURPOSE: `profile_gap_register` consumes `rows` only after its carrier-absent early
    return, so a carrier-less repo (the kernel: 20+ worktrees of an 85MB journal) opens no sibling.
    De-duplicated by the write side's own identity (`_event_dedup_key`, SPEC-0168 rule 3) — a landed
    copy of an `added` row replayed after its `promoted` would otherwise re-open the item. An absent
    sibling journal is ordinary; an UNREADABLE one is named on stderr and skipped (fail-open, never
    silent — the `_profile_gap_autofile` arm)."""
    seen = set()

    def _fresh(row):
        key = _event_dedup_key(json.dumps(row, ensure_ascii=False))
        if key in seen:
            return False
        seen.add(key)
        return True

    for row in own_rows:
        if _fresh(row):
            yield row
    r = _run_git_cap(["worktree", "list", "--porcelain"], REPO_ROOT)
    if r.returncode != 0:
        return
    for line in r.stdout.splitlines():
        if not line.startswith("worktree "):
            continue
        path = Path(line[len("worktree "):].strip()) / "events.jsonl"
        try:
            if not path.exists() or (EVENTS_PATH.exists() and path.samefile(EVENTS_PATH)):
                continue
            if not os.access(path, os.R_OK):
                raise PermissionError("not readable")
            skip = journal_mod._archive_segments_identical_to_main(path, EVENTS_PATH)
            rows = list(journal_mod._parsed_lines(journal_mod.segment_lines(path, skip=skip)))
        except OSError as exc:
            sys.stderr.write(f"WARN: the SPEC-0119 rule-39 gap register could not read the sibling "
                             f"journal {path} ({exc}) — a gap filed there is invisible to this "
                             f"seam's dedupe.\n")
            continue
        for row in rows:
            if isinstance(row, dict) and row.get("type") in _GAP_SIBLING_ROW_TYPES and _fresh(row):
                yield row


def _profile_gap_autofile(register, carrier=_CARRIER_UNSET) -> int:
    """T-12085 — THE WRITER: file ONE followup per unmet gap item, capped per run. Returns how many.

    FILING ONLY, and the fence is the point (SPEC-0198 rule 5 / CHARTER §6). A crossing MAY file a
    followup; it may NOT dispatch a worker, run an audit, open a PR, deploy, or mutate code. This
    function appends `followup_added` rows and does nothing else — there is no branch here that
    could reach any of those, which is what makes SPEC-0198's VP4 (the fence proven BY ABSENCE)
    checkable rather than merely promised.

    NOT A NEW STORE AND NOT A NEW CAPTURE PATH: it calls `followup.cmd_followup_add`'s OWN body — the
    same code `followup add` runs — so the id allocation, the `followup_added` event and the 2-state
    followup FSM stay in their one home. That is the T-11980 close-time-carrier shape, reused
    verbatim rather than re-implemented.

    ONCE PER ITEM, FOREVER — carried by the EXISTING `fingerprint` field (T-10779), stamped with
    `debt.gap_dedupe_key`. The fold has already excluded every key the journal has seen, so a
    re-run of any seam files nothing. The CAP is a separate, weaker bound on ONE RUN: a project with
    more gaps than the cap files the rest at the next seam rather than all at once.

    ARMED ONLY WHEN SOMETHING CAN ACTUALLY FIRE IT (SPEC-0095 §Armed / T-11863). A gap whose carrier
    section names a RESOLVABLE task id is born armed on that id; everything else is filed ACTIONABLE,
    because an armed item with nothing able to fire it is the unfireable-waiter state that door
    already refuses — strictly worse than a visible actionable row.

    FAIL-OPEN, BUT NEVER SILENT (the T-11980 arm, and the same audit finding behind it): a capture
    that cannot be written must not break a seam that was only ever reporting — but a swallowed
    exception makes "nothing was owed" and "the writer is BROKEN" look identical. The except arm
    names the failure on stderr and returns what it managed."""
    filed = 0
    try:
        # T-12085 (audit-post findings, 2026-09-05) — the carrier is read ONCE PER SEAM, by the
        # residue, and PASSED IN; the section each item needs is handed to the resolver, which opens
        # no file of its own. Two earlier shapes are both closed here: re-reading per ITEM, and
        # re-reading once more in the writer after the fold had already parsed it. A caller that
        # passes nothing still gets a correct answer, it just pays its own read.
        _carrier = _gap_ops_carrier() if carrier is _CARRIER_UNSET else carrier
        for item in (register or {}).get("unfiled", [])[:debt_mod.GAP_AUTOFILE_CAP]:
            awaits = _gap_carrier_task_ref(item, carrier=_carrier)
            trigger = (f"the carrier task {awaits} closes" if awaits else None)
            buf = io.StringIO()
            with contextlib.redirect_stdout(buf):   # the verb's own next-step lines are not the seam's
                followup_mod.cmd_followup_add(
                    argparse.Namespace(text=debt_mod.gap_autofile_text(item), relates_to=None,
                                       trigger=trigger, awaits=awaits,
                                       fingerprint=item.get("key"), from_stdin=False),
                    append_event=_append_event, die=_die)
            filed += 1
    except Exception as exc:                       # noqa: BLE001 — see FAIL-OPEN BUT NEVER SILENT
        sys.stderr.write(
            f"WARN: the SPEC-0119 rule-39 gap register filed {filed} item(s) and then FAILED — "
            f"{type(exc).__name__}: {exc}. The echo above is unaffected (this is fail-open by "
            f"design), but the remaining gaps are held by NOTHING until the next seam. File them by "
            f"hand with `yitc-v2 followup add --text 'GAP: ...' --fingerprint <key>`, then capture "
            f"the failure as a deviation.\n")
    return filed


def _profile_snapshot_record(resolution) -> bool:
    """T-12452 (SPEC-0198 rule 7): record the resolved profile as `profile_snapshot_recorded`.

    IDEMPOTENT PER SNAPSHOT HASH: writes only when the newest recorded snapshot for this repo (the
    same `profile._prior_snapshot` fold the latch reads) carries a different hash, so an unchanged
    profile re-folded at every seam appends nothing. Because the resolution it records is already
    latched, a latched dimension stays in the next snapshot — which is what keeps the latch holding.

    A RECORD, NOT AN ACT (rule 5): no dispatch, audit, deploy or code touch. FAIL-OPEN, NEVER
    SILENT — the `_profile_gap_autofile` arm: a failure names itself on stderr and the seam goes on.
    Returns True when a row was written."""
    try:
        if not (resolution or {}).get("resolved"):
            return False
        new_hash = str(resolution.get("snapshot_hash") or "")
        dims = {d: (v or {}).get("value") for d, v in (resolution.get("dimensions") or {}).items()}
        if not new_hash or not dims:
            return False
        # The prior identity rides the resolution (`resolve_profile` already folded it for the
        # latch), so this writer opens no journal reader of its own.
        if resolution.get("prior_snapshot_hash") == new_hash:
            return False
        _append_event("profile_snapshot_recorded", None,
                      {"snapshot_hash": new_hash, "dimensions": dims,
                       "emitter": "cli._debt_echo_lines"})
        return True
    except Exception as exc:                       # noqa: BLE001 — see FAIL-OPEN, NEVER SILENT
        sys.stderr.write(
            f"WARN: the SPEC-0198 rule-7 profile snapshot was not recorded — {type(exc).__name__}: "
            f"{exc}. The echo above is unaffected; the latch holds nothing new until the next seam.\n")
        return False


def _gap_carrier_task_ref(item, *, carrier) -> "str | None":
    """The RESOLVABLE task id an unmet gap item's carrier section already names, or None.

    This is the whole "armed when a nameable artifact fires it, else actionable" fork, and it is
    deliberately narrow: the ONLY thing that counts as nameable is a `T-NNNN` the project itself
    wrote into that section's `task:` key (`debt.GAP_CARRIER_TASK_KEY`) AND which resolves to a real
    card. It is read STRUCTURALLY, from that one key — never mined out of the section's free prose,
    which would resurrect the route-on-prose defect T-10335 records. The fold treats a lone `task:`
    pointer as NOT an answer, which is what leaves such an item in the register for this fork to
    reach.

    `carrier` is the ALREADY-PARSED ops mapping, read once by the caller — this function opens no
    file of its own, so a run over N items costs ONE carrier read rather than N."""
    try:
        section = (carrier or {}).get((item or {}).get("carrier"))
        ref = str((section or {}).get(debt_mod.GAP_CARRIER_TASK_KEY) or "").strip() \
            if isinstance(section, dict) else ""
        if ref and _gap_task_resolvable(ref):
            return ref
    except Exception:                              # noqa: BLE001 — no ref is a legal answer
        return None
    return None


def _debt_followup_floor() -> int:
    """SPEC-0119 / T-9789 (X-0157): the open-followups echo FLOOR — a small followup backlog BELOW this
    floor is treated as clean (suppressed), so it does not spam the session-start / `debt`
    echo. Configurable via env `YITC_DEBT_FOLLOWUP_FLOOR` (default 5; blank/malformed → default). A
    non-positive value disables the floor (the leaf treats <=0 as effective floor 1 — any count > 0
    fires). Only the open-followups view is floored (see `views._render_debt_echo` — not-adopted is
    already status-gated, overdue-rechecks are date-triggered; both stay unfloored)."""
    raw = os.environ.get("YITC_DEBT_FOLLOWUP_FLOOR", "").strip()
    if not raw:
        return 5
    try:
        return int(raw)
    except ValueError:
        return 5


def _debt_security_finding_floor_days() -> int:
    """SPEC-0119 rule 11 / T-10440 (X-0306 half 1): the AGE floor, in days, for the open sub-critical
    security-findings echo — a finding open for LESS than this is not yet surfaced. Configurable via env
    `YITC_DEBT_SECURITY_FINDING_FLOOR_DAYS` (default 30; blank/malformed → default). A non-positive value
    disables the floor (any open sub-critical finding fires). Modeled on `_debt_followup_floor`, but note
    the floor is an AGE floor, not that view's COUNT floor: one warning open for a year is real debt, so
    the count is never hidden here — only youth suppresses (SPEC-0119 rule 3)."""
    raw = os.environ.get("YITC_DEBT_SECURITY_FINDING_FLOOR_DAYS", "").strip()
    if not raw:
        return 30
    try:
        return int(raw)
    except ValueError:
        return 30


def _debt_dispatch_monitor_floor_minutes() -> int:
    """SPEC-0119 rule 12 / T-10471 (X-0336): the AGE floor, in minutes, for the unmonitored-dispatch
    echo — an in-flight dispatch younger than this is not yet surfaced. Configurable via env
    `YITC_DEBT_DISPATCH_MONITOR_FLOOR_MINUTES` (default 90; blank/malformed → default). A non-positive
    value disables the floor (any in-flight dispatch with no journaled monitoring read fires).

    WHY 90. The floor must exceed the longest sanctioned watch cycle, because the watcher journals its
    read receipt at EXIT — so a watch that is currently ARMED is invisible to the fold until it finishes
    (WATCH_MAX_RUNTIME_SECS = 1800s = 30 min; the §Watcher recipe shows a `--watch-timeout 3600` = 60
    min). At 90 minutes a controller who keeps re-arming the blessed watcher can never be false-nagged,
    and only a genuinely abandoned wave surfaces. Modeled on `_debt_security_finding_floor_days`: an AGE
    floor, not that view's COUNT floor — the count is never hidden, only youth suppresses (rule 3)."""
    raw = os.environ.get("YITC_DEBT_DISPATCH_MONITOR_FLOOR_MINUTES", "").strip()
    if not raw:
        return 90
    try:
        return int(raw)
    except ValueError:
        return 90


def _debt_test_class_stale_floor_days() -> int:
    """SPEC-0152 rule 24 / T-10513 (X-0375): the staleness AGE floor, in days, for the unexecuted-test-class
    echo — a declared class whose latest recorded successful execution is younger than this is not yet
    surfaced as `stale` (a NEVER-run class always surfaces, unconditionally). Configurable via env
    `YITC_DEBT_TEST_CLASS_STALE_FLOOR_DAYS` (default 30; blank/malformed → default). A non-positive value
    disables the staleness arm (only never-run fires). Modeled on `_debt_security_finding_floor_days` — an
    AGE floor, not a COUNT floor: one class unrun for a year is real debt, so the count is never hidden."""
    raw = os.environ.get("YITC_DEBT_TEST_CLASS_STALE_FLOOR_DAYS", "").strip()
    if not raw:
        return 30
    try:
        return int(raw)
    except ValueError:
        return 30


def _worker_session_ref():
    """This session's own DISPATCHED-worker ref, or None in an interactive/controller session.

    `dispatch` assigns each worker a distinct ref and exports it as `YITC_EXPECTED_SESSION_REF` (the
    T-0558 launch-time env scrub + assign). Its presence is therefore the honest "am I a dispatched
    worker?" signal — the same carrier `land` keys its verify-heartbeat off (T-9601)."""
    ref = os.environ.get("YITC_EXPECTED_SESSION_REF", "").strip()
    return ref or None


def _carried_session_refs() -> tuple:
    """T-13139 — the session refs this process CARRIES (the v2 self-ref carrier, then the dispatched
    worker's expected ref), non-empty and in that order: the refs a debt-echo view may ask
    `_ref_current_epoch_anchored` about, which the echo's one-pass scope therefore captures."""
    refs = (os.environ.get(SELF_REF_ENV, "").strip(), os.environ.get(EXPECTED_SESSION_REF_ENV, "").strip())
    return tuple(r for r in refs if r)


def _unmonitored_dispatch_view() -> dict:
    """SPEC-0119 rule 12 (T-10471): the unmonitored-dispatch fold, bound to the host's EXISTING readers.

    Injects the SAME two §6-safe readers the blessed watcher ticks on — `journal query --fleet-verdict`
    (the in-flight fleet) and `journal query --dispatch-status --task` (the per-task class) — run
    IN-PROCESS through `_watch_read_json_lines`, so there is exactly ONE dispatch-classifier path in the
    system (SPEC-0133 rule 5 admits no second) and a `-C` rebind or a test monkeypatch on those host
    names stays honored. Both readers are PURE: this view reads, and journals nothing.

    The EVENTS come from `_dispatch_status_events` — the same UNIONED dispatch journal reader those
    classifiers use (local checkout + MAIN + every live worktree, deduped). That union is load-bearing:
    `dispatch` appends `bg_dispatch_launched` to MAIN's journal, so reading the local `events.jsonl`
    alone would find NO launches from inside a worktree and the view would be silently dead there. It is
    bounded by the SAME wave window the fleet rows are derived under (no new constant — CHARTER §P1), so
    a launch aged out of that window is not surfaced, exactly as its worker is absent from the rows.

    Cost is proportional to the in-flight fleet and is ZERO when it is empty (the fold short-circuits on
    an empty row set before it reads any events) — the common clean case at a debt seam."""
    _since = (_dt.datetime.now(_dt.timezone.utc)
              - _dt.timedelta(seconds=DISPATCH_WAVE_WINDOW_SEC)).strftime("%Y-%m-%dT%H:%M:%SZ")
    # T-11438 — ONE journal read for the whole fold. Every reader below bottoms out in the SAME
    # windowed `_dispatch_status_events(task_id=None, since=now-DISPATCH_WAVE_WINDOW_SEC)`: the fleet
    # verdict once, the event lambda once, and the per-task classifier ONCE PER CANDIDATE (through
    # `--dispatch-status --task` → `_dispatch_events_tail_first_multi`). Measured 15 reads / 143.1s for 13
    # candidates on the engine journal (2026-08-22) — a full fold recomputed per dispatch, and the
    # fold that aborted the task/T-11430 land twice that day. The memo serves them all from the first
    # read and is EXACT by derivation, not by approximation (the argument is homed on
    # `journal.DispatchEventsMemo`); nothing about WHICH rows this view reports moves. Scoped to this
    # view alone: no other caller of the host reader is inside it.
    with _dispatch_events_memo():
        return debt_mod.unmonitored_dispatches(
            _watch_read_json_lines(cmd_journal_fleet_verdict,
                                   argparse.Namespace(json=True, since=None, until=None)),
            lambda task: next(iter(_watch_read_json_lines(
                cmd_journal_dispatch_status,
                argparse.Namespace(json=True, task=task, since=None, until=None))), None),
            lambda: _dispatch_status_events(since=_since),
            _debt_dispatch_monitor_floor_minutes(),
            self_session_ref=_worker_session_ref())


def _unresolved_halt_view() -> dict:
    """SPEC-0119 rule 18 (T-10858): the unresolved-worker-halt fold — dispatch/worker TERMINAL-ATTENTION
    debt, bound to the host's EXISTING journal reader and the ONE resolution predicate.

    Injects `journal._halt_resolution` (SPEC-0133 rule 2d / T-10771 — the same fail-closed predicate
    `--fleet-verdict` and the re-dispatch brief share) plus `journal._dispatch_task_of` (the same
    attribution that predicate matches on), so there is exactly ONE notion of "resolved" and ONE of
    "which task is this" in the system (SPEC-0133 rule 5 admits no second classifier path). Both are
    PURE: this view reads, and journals nothing.

    THE READER IS BOUNDED BY TYPE, NEVER BY AGE — and that is the entire point of the card. Its sibling
    `_unmonitored_dispatch_view` passes a wave-window `since`, so a launch that ages out is not surfaced;
    doing the same here would re-create the exact bug this rule removes (a halt going silent as it gets
    older, when it needs attention most). So NO `since` is passed. An unbounded read of the whole union
    is far too heavy for a session-start echo (measured 3.47s / 252936 events per journal on the engine
    journal, 2026-08-09), so the cost bound moves to the axis that costs no signal:
    `include_types=HALT_ATTRIBUTION_INPUT_TYPES` — the types `_halt_resolution` can match, PLUS the
    `bg_dispatch_launched` join row the T-11351 attribution needs, homed beside the predicate itself
    (the resolution set alone measured 0.56s / 18742 events; the launch rows add ~2.3k to that). Still the SAME unioned reader (local
    checkout + MAIN + every live worktree), which is load-bearing: `dispatch` appends to MAIN's journal,
    so a fold reading only the local `events.jsonl` would be silently dead inside a worktree.

    NOT controller-seam-gated, a DELIBERATE divergence from rule 12 (which contributes nothing in a
    dispatched-worker session). Rule 12's gate exists because its remedy — arming a fleet watcher — is
    the CONTROLLER's and a worker cannot perform it. Here the subject is not a live fleet a worker would
    be nagged about but a STOPPED worker still owed a decision, and the originating incident is precisely
    that no surface reported one at all. Every session that reads a debt seam should see it.

    THE CARD CROSS-CHECK IS THE EXISTING ONE (T-10873). `_main_task_strand_state` — the same reader
    `--fleet-verdict` already injects to read a paused card for its `pause_detail` (T-10712 / X-0557) —
    is passed as `_card_state` so the fold can drop a halt whose card has already reached a TERMINAL
    status (`done` / `wont-do`): such a card awaits no decision, and this row's subject is a decision
    still owed. EXTENDING that reader is the point; a SECOND card reader would be the failure, not the
    fix (CHARTER §P1 F1). That cross-check covers a disposition PRE-DATING the halt, which the shared
    predicate cannot see looking forward (a halt emitted AFTER its task closed and landed) — what a
    faithful UNRESOLVED MEANS there belongs to each reader
    (`lessons/fail-closed-belongs-to-the-reader-not-the-parser`). The complementary AFTER-the-halt
    disposition is NOT a reader concern and is not one here: T-12068 taught it to the predicate as arm
    (iv), deliberately, because `--fleet-verdict` and this line were reading the same parked pre-claim
    refusal two different ways (CHARTER P7) and only a shared arm can make them agree. This view's
    injection is unchanged by that: the widened `HALT_ATTRIBUTION_INPUT_TYPES` below is derived from the
    resolution set, so the reader already carries the disposition rows.
    It reads the MAIN checkout of the ACTIVE repo, so under `-C <consumer>` a consumer's fold reads that
    consumer's own cards. Measured on the engine journal (2026-08-10): 60 rows → 5."""
    return debt_mod.unresolved_worker_halts(
        lambda: _dispatch_status_events(include_types=journal_mod.HALT_ATTRIBUTION_INPUT_TYPES),
        journal_mod._halt_resolution,
        journal_mod._dispatch_task_of,
        _card_state=_main_task_strand_state,
        # T-10902 — the ABSENT-CARD provenance reader, bound to the MAIN checkout (where the cards and
        # the git history live; a worktree checkout carries the same history, but MAIN is where the
        # card set is authoritative). It answers ONLY from a deleting COMMIT or from test-fixture
        # provenance, so a card missing for no recorded reason still reports — absence never clears.
        _absent_card_provenance=lambda task_id: debt_mod.absent_card_provenance(
            task_id, repo_root=_main_worktree(REPO_ROOT) or REPO_ROOT),
        # T-11351 — the ATTRIBUTION pair. `_halt_dispatcher_session` performs the dispatch→halt join the
        # journal has always carried but this fold never made: the halt's own `session_ref` is the
        # WORKER's, and the `bg_dispatch_launched` that assigned it (`data.expected`) names the
        # CONTROLLER that launched it. `self_session_ref` is the NON-DYING resolver, deliberately:
        # `_resolve_session_ref` is the fail-closed governance KEYER and prints a diagnostic before it
        # dies, which a report-only debt echo must never do — an unresolvable session here simply
        # attributes nothing. Neither collaborator can drop, reorder or filter a row; both only add.
        _halt_dispatcher=journal_mod._halt_dispatcher_session,
        self_session_ref=_try_resolve_session_ref())


def _debt_dead_land_floor_minutes() -> int:
    """SPEC-0119 rule 23 / T-11254: the AGE floor, in minutes, for the dead-land echo — a candidate
    younger than this is not yet surfaced. Configurable via env `YITC_DEBT_DEAD_LAND_FLOOR_MINUTES`
    (default 90; blank/malformed → default). A non-positive value disables the floor.

    WHY A FLOOR AT ALL, and why this view is NOT unfloored. Between land step-1's bookkeeping commit
    and its terminal row, a HEALTHY IN-FLIGHT land is byte-for-byte indistinguishable from a dead one
    — same marker tip, same absent row. This was caught by the card's OWN AC2 live probe: the first
    run named 1 branch, a run minutes later named 5, of which FOUR were sibling lanes still verifying.

    WHY 90 — measured, not decreed. Over the 4365 `land_completed` rows in this journal carrying
    timings, the longest healthy land (verify + admission wait) ran 38.7 min, p95 8.0 min; 90 exceeds
    that observed maximum by 2.3x, so a merely SLOW land — a long verify, a SPEC-0132 admission wait,
    a retry — can never read as dead, while the originating incident (20 HOURS silent) surfaces with
    an enormous margin. The value and the shape are DELIBERATELY the sibling's
    (`_debt_dispatch_monitor_floor_minutes`, rule 12), reused rather than newly decreed: an AGE floor,
    never a COUNT floor — the count is never hidden, only youth suppresses (rule 3)."""
    raw = os.environ.get("YITC_DEBT_DEAD_LAND_FLOOR_MINUTES", "").strip()
    if not raw:
        return 90
    try:
        return int(raw)
    except ValueError:
        return 90


def _debt_uncarried_p8_window_hours() -> int:
    """SPEC-0119 rule 31 / T-11563: the reading HORIZON, in hours, for the uncarried-P8-WARN echo —
    a closure older than this is history rather than debt. Configurable via env
    `YITC_DEBT_UNCARRIED_P8_WINDOW_HOURS` (default 168 = 7 days; blank/malformed -> default). A
    non-positive value DISABLES the view.

    A HORIZON, NEVER A COUNT FLOOR — the rule-26 knob shape (`_debt_abort_breadth_window_hours`),
    reused rather than newly decreed. It is what keeps a closure from a month ago being re-announced
    forever, and it hides nothing INSIDE the window: every uncarried row in the horizon is counted.

    WHY A HORIZON IS NEEDED AT ALL, measured on this repo rather than assumed: the journal carries
    452 historical `adoption_evidence_seen: false` rows across the whole corpus. Unbounded, the line
    would print a number no session can act on — the exact noise that buries the echo it rides
    (SPEC-0149's trial-run disproof). At 168h the same fold reads 29, at 72h 14, at 24h 5.

    WHY 168 — the sibling's own horizon (the rule-27 aborted-land-cost window is 7 days), so a reader
    holding one debt line's horizon in mind holds this one's too. It also spans a weekend, which a
    72h window does not: a Friday closure would otherwise fall out of the horizon before the next
    working session ever read the line."""
    raw = os.environ.get("YITC_DEBT_UNCARRIED_P8_WINDOW_HOURS", "").strip()
    if not raw:
        return 168
    try:
        return int(raw)
    except ValueError:
        return 168


def _uncarried_p8_view() -> dict:
    """SPEC-0119 rule 31 (T-11563): the UNCARRIED-P8-WARN fold — `class: infra` closures whose
    CHARTER §P8 adoption WARN fired (`task_closed.adoption_evidence_seen: false`) and which NOTHING
    is holding. The thin host residue: it binds this repo's journal, this repo's task cards and the
    horizon knob, and decides nothing — every rule lives in the pure fold.

    BOTH READS ARE THIS REPO'S OWN. The journal goes through the ONE shared parsed fold, so the
    T-11453 request-scoped memo collapses it with its ~15 siblings at the debt residue and this view
    costs no extra parse; the card reads are bounded to the candidates that SURVIVE carrier
    subtraction, which is a handful, not the corpus.

    A repo whose infra closures all carry their adoption evidence folds to 0 -> suppressed."""
    return debt_mod.uncarried_p8_warns(
        EVENTS_PATH, root=REPO_ROOT, window_hours=_debt_uncarried_p8_window_hours(),
        _is_consumer_build=_is_consumer_build)   # T-12796 — judge a ref under the arm `task close` uses


def _dead_land_view() -> dict:
    """SPEC-0119 rule 23 (T-11254 / <project> X-0976): the DEAD-LAND fold — a `land` that committed its
    step-1 bookkeeping and then died before emitting any terminal row. The thin host residue: it binds
    the two readers the pure fold cannot resolve itself, and decides nothing.

    THE GIT READ IS ONE CALL, not one-per-branch — `for-each-ref` carries the tip subject and date, so
    the whole frontier costs a single subprocess at a session seam:
      `git for-each-ref --no-merged main --format=<short>\t<committerdate:iso-strict>\t<subject> refs/heads/`
    Bound to the MAIN checkout, like the rule-18 view's card reader: a worktree checkout carries the
    same refs, but main is where the branch frontier is authoritative. A repo with no `main` (a fresh
    consumer, a detached bootstrap) yields NOTHING rather than an error — `for-each-ref` exits nonzero
    and the reader returns [], which the fold reads as a clean zero.

    THE JOURNAL READ IS THE UNIONED ONE, and that is a correctness condition rather than a wiring
    choice (audit-pre finding 1). `land` runs from main and appends `land_completed` to MAIN's journal,
    but a row can also sit in a branch's own journal or a live worktree's; a local-only read would then
    report a land that DID report — a false dead-land, the exact noise class the fold's condition 2
    exists to prevent. So this binds `_dispatch_status_events`, the SAME unioned reader
    (local checkout + MAIN + every live worktree) the rule-18 sibling uses, narrowed BY TYPE and never
    by AGE: a dead land must not age out of its own detection, and the type bound is what keeps the
    read cheap enough for a session seam without costing signal. NO second journal reader is written
    (P5) — one that drifted would be free to disagree with the one every sibling already trusts.

    `_worktree_path_for_branch` supplies REMEDY CONTEXT ONLY and is passed keyword-only, so it can
    never occupy a predicate slot. The fold guards it per branch: a dead land whose worktree was
    already removed still reports."""
    _main = _main_worktree(REPO_ROOT) or REPO_ROOT

    def _branch_tips() -> list:
        # Tab-separated so a subject containing spaces (every land marker does) survives the split.
        r = _run_git_cap(["for-each-ref", "--no-merged", "main",
                          "--format=%(refname:short)\t%(committerdate:iso-strict)\t%(contents:subject)",
                          "refs/heads/"], _main)
        if r.returncode != 0:
            return []
        tips = []
        for ln in r.stdout.splitlines():
            parts = ln.split("\t")
            if len(parts) < 3:
                continue
            branch, committed_at, subject = parts[0], parts[1], "\t".join(parts[2:])
            # The tip SHA is fetched only for a branch that already passed the cheap subject test, so
            # the frontier scan stays one call even on a repo carrying many stale branches.
            tips.append({"branch": branch, "committed_at": committed_at, "subject": subject,
                         "sha": None})
        for tip in tips:
            if debt_mod._dead_land_tip_is_land_marker(tip.get("subject"), tip.get("branch")):
                sha = _run_git_cap(["rev-parse", "--short", tip["branch"]], _main)
                tip["sha"] = sha.stdout.strip() if sha.returncode == 0 else None
        return tips

    return debt_mod.dead_lands(
        _branch_tips,
        lambda: _dispatch_status_events(include_types=(debt_mod.DEAD_LAND_TERMINAL_EVENT,)),
        _debt_dead_land_floor_minutes(),
        _worktree_of=_worktree_path_for_branch,
        # T-11682 — the batch's own record of what killed a dead HEAD. The SAME unioned reader, for
        # the same reason its sibling above is unioned: a member verdict reaches MAIN's journal from
        # the dissolve/release arms, but a row can also sit in a branch's own journal or a live
        # worktree's, and a local-only read would silently lose the cause of exactly the deaths this
        # view exists for. NO second journal reader is written (CHARTER §P5).
        #
        # THIS BINDING IS A THUNK AND THE FOLD CALLS IT LAZILY — only when a dead land actually
        # exists. That is load-bearing, not incidental: `land_member_verdict` is a type no sibling
        # view reads, so the T-11453 request-scoped memo cannot serve it from an existing base and it
        # costs a REAL scan of the ~3 GB union. The sibling above is a strict SUBSET of the rule-18
        # halt-set base and is therefore memo-served for free — this one is not, so it must not be
        # paid at every seam to explain a set that is almost always empty. The fold owns that gate.
        _member_rows=lambda: _dispatch_status_events(
            include_types=(debt_mod.DEAD_LAND_MEMBER_EVENT,)))


def _debt_ahead_branch_floor_hours() -> int:
    """SPEC-0119 rule 24 (T-11303): the AHEAD-BRANCH age floor in hours, `YITC_DEBT_AHEAD_BRANCH_FLOOR_HOURS`
    (default 24). EVERY healthy in-flight build has a branch ahead of main — that is what a worktree IS —
    so youth is precisely what must never fire, and the floor is what separates a live lane from an
    abandoned one. WHY 24: measured on this repo's live frontier at design time, two genuinely live lanes
    sat at 15.7h and 17.5h against the one genuinely abandoned branch at 25.8h, and the originating
    <project> incident (X-1001) measured 28-40h — so the floor sits below every reported instance and above
    every live one. The value and the shape are DELIBERATELY the siblings' (`_debt_dead_land_floor_minutes`,
    rule 23; `_debt_dispatch_monitor_floor_minutes`, rule 12), reused rather than newly decreed: an AGE
    floor, never a COUNT floor — the count is never hidden, only youth suppresses (rule 3). A bad value
    degrades to the default, never to an error."""
    raw = os.environ.get("YITC_DEBT_AHEAD_BRANCH_FLOOR_HOURS", "").strip()
    if not raw:
        return 24
    try:
        return int(raw)
    except ValueError:
        return 24


def _debt_abort_breadth_window_hours() -> int:
    """SPEC-0119 rule 26 (T-11380): the READING HORIZON in hours, `YITC_DEBT_ABORT_BREADTH_WINDOW_HOURS`
    (default 24). Not a floor and not a governance scalar — the rule-14 `window_days` analog: how far back
    a cross-branch repeat is still worth naming. 24h is the measured shape of the incident (four branches
    inside one hour) with room for a slower repeat. A bad value degrades to the default, never to an error.

    THE OUTER HORIZON ONLY — this knob is NOT what clears a fixed cause, and the claim that it was is
    RETRACTED here (T-12052). This docstring used to end "and it is what keeps a cause that was FIXED
    yesterday from being re-announced today". It does not: measured 2026-09-04 ~04:00Z, the rule-26 line
    named `verify-failed#af84843f8263` on three branches that had all landed the previous day, well
    inside this window, and the owner read it as spam. What clears a fixed cause is the RESOLUTION
    predicate in the fold itself (`debt._abort_breadth_resolution`) — a branch drops off the cause once
    it lands. This window's honest remaining job is the branch that NEVER lands: abandoned or parked, it
    can only age out, and this is how far back it stays worth naming."""
    raw = os.environ.get("YITC_DEBT_ABORT_BREADTH_WINDOW_HOURS", "").strip()
    if not raw:
        return 24
    try:
        return int(raw)
    except ValueError:
        return 24


# SPEC-0190 rule 10 (T-13288): the engine's ONE read-contract exemption carrier, repo-relative.
ENGINE_READS_EXEMPTIONS = "tests/read-contract-exemptions.yaml"


def _reads_exemptions() -> list:
    """This repo's OWN declared `reads.exemptions[]` entries (SPEC-0190 rule 10 / SPEC-0160 rule 25).

    The thin HOST read for the rule-37 debt fold, here rather than in the leaf for the reason every
    other carrier read is here: `REPO_ROOT` and the ops-contract filename live on this side, and the
    fold must stay a pure function of its inputs so a test can hand it an exemption set directly.

    The SHAPE is validated fail-closed at its one home (`init.py#_hook_reads_exemptions`, which
    refuses a half-registered entry by NAME); this read does not re-validate it, so there is exactly
    one place the four-field rule is spelled. What this returns is the raw list; the fold applies
    only the two fields it USES (`seam` / `ratio_bound`) and ignores an entry it cannot use.

    FAIL-CLOSED to `[]` on every unhappy path — absent carrier, unreadable carrier, malformed
    section. An exemption that cannot be read must never widen a bound: the fail-open direction would
    let a corrupted carrier silently exempt every seam, which is strictly worse than reporting a seam
    whose accepted risk is on record elsewhere. ABSENCE is the state every project starts in and
    reads as "this project exempts no seam" (the born-fully-commented carrier).

    T-13467 — THE ENGINE'S ONE CARRIER. The engine carries no `yitc-ops.yaml` (SPEC-0077), so
    SPEC-0190 rule 10 names `tests/read-contract-exemptions.yaml` as its one home — same
    `reads: exemptions:` shape, validated by the same shape hook (the tripwire runs it over that
    file). On the engine (the canonical `_is_consumer_build` test, so a linked worktree counts) this
    reads THAT file; a consumer reads its own `yitc-ops.yaml` and never a `tests/` file. Before this
    the engine read returned [] and the debt lens reported seams whose accepted risk was on record."""
    try:
        ops_path = REPO_ROOT / ("yitc-ops.yaml" if _is_consumer_build() else ENGINE_READS_EXEMPTIONS)
        if not ops_path.is_file():
            return []
        ops = _read_yaml(ops_path)
        sec = ops.get("reads") if isinstance(ops, dict) else None
        entries = sec.get("exemptions") if isinstance(sec, dict) else None
        return entries if isinstance(entries, list) else []
    except Exception:                      # noqa: BLE001 — a report-only input, never fatal
        return []


def _debt_prequeue_refusal_window_days() -> int:
    """SPEC-0119 rule 33 (T-11841): the REPORTING window, in DAYS, for the pre-queue known-broken
    refusal line — `YITC_DEBT_PREQUEUE_REFUSAL_WINDOW_DAYS` (default
    `debt.PREQUEUE_REFUSAL_WINDOW_DAYS`; blank/malformed -> default, never an error).

    THE KNOB SHAPE IS REUSED, NOT NEWLY DECREED — `_debt_abort_breadth_window_hours` (rule 26) and
    `_debt_uncarried_p8_window_hours` (rule 31) are the analogs, and rule 33 was the only windowed
    line in this family with no reader-facing knob at all. Same three arms, same degrade-to-default
    posture, same host-residue placement: the fold in `debt.py` reads the environment NOWHERE and
    keeps taking `window_days` as a plain argument, so the pure layer stays pure.

    DAYS, NOT HOURS, and that is the one place it departs from the analogs. This fold's parameter IS
    `window_days`, its answer carries `window_days`, and the rendered line reads "in the last Nd";
    converting to hours would ripple through the signature, the answer dict and the view string for
    no reader gain. The SHAPE is the thing being reused, not the unit.

    THE DEFAULT IS READ FROM THE FOLD'S OWN CONSTANT, never re-typed here — the number this rule
    reports on has exactly one home, so a knob resolver can never drift from the fold it feeds."""
    raw = os.environ.get("YITC_DEBT_PREQUEUE_REFUSAL_WINDOW_DAYS", "").strip()
    default = int(debt_mod.PREQUEUE_REFUSAL_WINDOW_DAYS)
    if not raw:
        return default
    try:
        return int(raw)
    except ValueError:
        return default


def _debt_abort_breadth_min_branches() -> int:
    """SPEC-0119 rule 26 (T-11380): how many DISTINCT branches one cause must refuse before the line
    prints, `YITC_DEBT_ABORT_BREADTH_MIN_BRANCHES` (default 2). NOT a count-floor in the rule-3 sense —
    nothing is being hidden below it: one branch repeating on one cause is a DIFFERENT surface's business
    entirely (the T-0655 repeated-abort backstop), and this fold counts DISTINCT branches, so such a branch
    contributes exactly 1 no matter how often it retries. 2 is therefore the earliest moment the
    cross-branch fact EXISTS at all, and each later moment costs another full verify (430-560s measured).

    WHAT 2 COSTS, measured on this repo's live journal at 2026-08-21T06:00Z (a freeze night, i.e. the
    unfavourable case): 6 causes at >=2 branches, 1 at >=3. So the default is the SENSITIVE end, and the
    honest statement is that it reports every duplicated diagnosis rather than only the dominant one. It
    is still ONE line carrying a count, capped at 2 named causes, and it CANNOT fire on a burst of
    different causes — but a reader who finds 2 too eager on their repo raises this knob rather than
    filtering the line, which is the whole reason it is a knob. A bad value degrades to the default,
    never to an error.

    FLOORED AT 2, not merely parsed (audit-post finding): a value of 1 (or 0, or negative) would make a
    SINGLE-branch cause print, which is not this view's signal at all — it is the T-0655 repeated-abort
    backstop's, duplicated onto a surface whose whole claim is that it reads ACROSS branches. So a
    below-2 value is INVALID and degrades to the default exactly as an unparseable one does; the knob
    can only ever make the line LESS eager, never turn it into a second backstop."""
    raw = os.environ.get("YITC_DEBT_ABORT_BREADTH_MIN_BRANCHES", "").strip()
    if not raw:
        return 2
    try:
        parsed = int(raw)
    except ValueError:
        return 2
    return parsed if parsed >= 2 else 2


def _debt_branch_burn_min_attempts() -> int:
    """SPEC-0119 rule 34 (T-11821): how many UNLANDED land attempts ONE branch must burn before the
    line prints — `YITC_DEBT_BRANCH_BURN_MIN_ATTEMPTS`, default 4.

    NOT rule 26's 2, and the difference is the whole design. Rule 26's floor is the EARLIEST moment
    its fact exists, because every further miss costs ANOTHER branch a full verify. Here the
    opposite pressure governs: retrying IS the normal shape of a converging build, and the external
    adjudication (GREEN, 2026-08-28) rejected a cause-agnostic gate precisely so legitimate
    iteration is not read as stuckness — `task/T-11810` aborted five times and then LANDED on its
    sixth attempt. So this floor must sit ABOVE the ordinary iteration band.

    WHY 4, measured on this repo's own journal over 2026-08-21..28 — which is the FREEZE week, i.e.
    the unfavourable case. Still-unlanded refusals per branch in a trailing 24h: 106 branches never
    exceed 1, then 50 reach 2 or more, 28 reach 3 or more, 18 reach 4 or more. The three-attempt
    convergence band dominates, 4 is the first value clear of it, and 4 is one BELOW the smaller of
    the two shapes that PROVED the gap (T-11810 at five aborts, T-11733 at seven) — so the line
    arrives while the burn is still worth interrupting rather than after it has completed. What that
    costs on the same worst week: a line in ~78% of sampled hours naming a median of 3 branches (at
    most 8). A reader who finds it too eager on their repo raises this knob rather than filtering
    the line, which is the whole reason it is a knob.

    FLOORED AT 2, not merely parsed: a value of 1 (or 0, or negative) would make a SINGLE unlanded
    attempt print, which is not a repeat at all and is the ordinary outcome of any failing verify.
    A below-2 value is therefore INVALID and degrades to the default exactly as an unparseable one
    does, so the knob can only ever make the line LESS eager. A bad value degrades to the default,
    never to an error, matching every sibling knob here.

    There is deliberately NO window knob of its own — the window is rule 26's
    (`YITC_DEBT_ABORT_BREADTH_WINDOW_HOURS`), since the two folds are transposes of one reading met
    by the same reader at the same seam."""
    raw = os.environ.get("YITC_DEBT_BRANCH_BURN_MIN_ATTEMPTS", "").strip()
    if not raw:
        return 4
    try:
        parsed = int(raw)
    except ValueError:
        return 4
    return parsed if parsed >= 2 else 4

def _debt_measurement_margin() -> float:
    """SPEC-0119 rule 28 (T-11396): how CLOSE a recorded measurement may come to its own floor before
    the line prints — `YITC_DEBT_MEASUREMENT_MARGIN`, default 0.10 (so the line fires from 0.90 down,
    against SPEC-0161's 0.80 floor).

    A NOTICE WIDTH, never a bar. It cannot make a measurement pass or fail anything: the floor itself
    is `debt.SPEC0161_COVERAGE_FLOOR` and lives in the fold, unchanged by this knob and unchanged by
    this task. 0.10 is the width at which the incident would have been caught early rather than
    tightly: the 2026-08-21 refusal came in at 79%, and the run before it sat in the 80s, so a 10-point
    notice band names the drift while it is still an ordinary edit.

    A NON-POSITIVE value disables only the APPROACH arm — a measurement already AT or BENEATH its floor
    still prints, because at that point a land is already being refused and silence would be the one
    genuinely harmful reading. So the knob can make the line less eager, never blind. A bad value
    degrades to the default, never to an error, matching every sibling knob here."""
    raw = os.environ.get("YITC_DEBT_MEASUREMENT_MARGIN", "").strip()
    if not raw:
        return 0.10
    try:
        return float(raw)
    except ValueError:
        return 0.10


def _recorded_measurement_view() -> dict:
    """SPEC-0119 rule 28 (T-11396): the RECORDED-MEASUREMENT DRIFT fold — SPEC-0161's recorded
    payload-key candidate set approaching (or already beneath) its own floor.

    The thin host residue: it binds the three inputs the pure fold cannot resolve itself (this repo's
    spec corpus, its `bin/` blob, its journal) plus the notice-width knob, and decides nothing. All
    policy — what governs, what counts as named, and when the reading is close enough to interrupt —
    lives in the fold (`lessons/scope-the-trigger-not-the-view`).

    Bound to REPO_ROOT, so a `-C <consumer>` session measures that consumer's own corpus and its own
    code. A repo whose corpus this rule does not describe finds nothing governing, folds to count 0,
    and stays silent.

    THE RECORD IS THE ONE THING THAT IS NOT THIS REPO'S (T-12618). SPEC-0161 is a KERNEL spec, so a
    `-C` consumer has no `SPEC-0161-*.yaml` of its own; without a record the oracle's `named` test is
    always false and EVERY governing pair reads unnamed — coverage 0.0, a permanent false line, and a
    named remedy SPEC-0078 refuses under `-C` (<project> X-1418). `_spec0161_engine_record_specs` is
    the ONE predicate for "does this root own the record or borrow it?" — the same call the land arm
    `spec0161_branch_unnamed` already makes, reused here rather than spelling `ENGINE_ROOT / "specs"`
    inline, so the two readers cannot drift apart. It returns None for a kernel-shaped root, which
    makes the ENGINE's own reading byte-identical to before BY CONSTRUCTION, and keeps the SPEC-0092
    id-collision case right (a consumer owning its own SPEC-0161 keeps its own text). Only the
    RECORD is borrowed; the corpus stays this repo's, deliberately."""
    return debt_mod.recorded_measurement_drift(
        EVENTS_PATH,
        specs_dir=REPO_ROOT / "specs",
        code_dir=REPO_ROOT / "bin",
        margin=_debt_measurement_margin(),
        engine_specs_dir=debt_mod._spec0161_engine_record_specs(REPO_ROOT))


def _abort_cause_breadth_view() -> dict:
    """SPEC-0119 rule 26 (T-11380): the LAND-ABORT CAUSE-BREADTH fold — one cause refusing several
    DIFFERENT branches. The thin host residue: it binds the journal, the two knobs, and the EXISTING
    cause identity, and decides nothing itself.

    THE IDENTITY IS THE ONE THE BACKSTOP USES — `_land_abort_cause_identity`, reached through this host's
    own `_land_abort_key` residue's dependency (the same `_normalize_abort_cause` injection), so the fold
    and the T-0655 backstop can never disagree about what "the same cause" means. No second identity is
    minted anywhere in this task (CHARTER P5)."""
    return debt_mod.land_abort_cause_breadth(
        EVENTS_PATH,
        _cause_identity=lambda d: worktree_mod._land_abort_cause_identity(
            d, _normalize_abort_cause=_normalize_abort_cause),
        window_hours=_debt_abort_breadth_window_hours(),
        min_branches=_debt_abort_breadth_min_branches())


def _land_head_read_scope():
    """T-13138 (X-1687) — `cmd_land`'s head ReadScope (T-12392, SPEC-0190 rule 10): ONE streaming pass
    over the journal that keeps only the two row types its readers take — the T-0655 backstop's own
    branch's `land_completed` rows and the rule-26 cause-breadth fold's `_ABORT_BREADTH_EVENTS` — as
    compressed lines, parsed as they are served. It replaces `rows_memo([EVENTS_PATH])`, which gave the
    head its one fold per segment by retaining every segment's lines AND parsed rows (~3.9 GB of the
    land's peak on the kernel checkout). A head read the declaration misses is still answered, and
    RECORDED on the scope's `fallbacks`.

    T-13365 — it is the land's WORKTREE-PRE-MERGE scope now (SPEC-0190 rule 10: one pass per journal
    state): it also declares what the P0 preflights and `_land_integrate`'s pre-queue currency read take
    from this journal — the audit-currency types and the SPEC-0161 type-keys reducer — and it is opened
    before those preflights and handed into `_land_integrate`, which closes it before its attempt loop
    (`worktree._LandReadScopes`). `index=True` serves every archived segment whose summary covers this
    declaration (T-13356); `catch_up=True` keeps it fresh across the land's own appends and turns it
    stale on a rewrite, so it never answers for a journal state it did not read (T-13332)."""
    return journal_mod.scan_scope(
        EVENTS_PATH, keep={t: None for t in (*debt_mod._ABORT_BREADTH_EVENTS,
                                             *worktree_mod._land_read_types())},
        reducers={"spec0161_type_keys": debt_mod.debt_spec0161.TypeKeysReducer},
        needles=worktree_mod._land_session_needles(), index=True, catch_up=True)


def _abort_cause_breadth_head_lines() -> list:
    """T-12392 — the LAND-HEAD lines of the SPEC-0119 rule-26 cause-breadth fold, for `cmd_land`.

    THE SAME residue the debt echo already uses (`_abort_cause_breadth_view`), rendered by the SAME
    module-level renderer the debt echo calls (`views.abort_cause_breadth_cause_line`, hoisted for
    exactly this reason) — ONE fold, ONE identity, ONE journal read path, no second view and no new
    knob (CHARTER §P5). What is new is only the SEAM: the causes are named BEFORE the land pays its
    SPEC-0132 admission wait and its verify, instead of at session start alone.

    Read INSIDE `cmd_land`'s head ReadScope (injected beside this one), so it is served from the
    parse the T-0655 backstop's own journal read already paid for. Report-only and
    suppressed-when-clean: `[]` when no cause is unresolved across branches."""
    return views.abort_cause_breadth_land_head_lines(_abort_cause_breadth_view())


def _branch_attempt_burn_view() -> dict:
    """SPEC-0119 rule 34 (T-11821): the STUCK-BRANCH UNLANDED-ATTEMPT fold — ONE branch burning
    repeated land attempts whatever the cause each time, the exact TRANSPOSE of the rule-26 view
    just above. The thin host residue: it binds the journal and the two scalars, and decides nothing
    itself (`lessons/scope-the-trigger-not-the-view`).

    IT BINDS NO CAUSE IDENTITY, and that absence is load-bearing rather than an omission. Rule 26's
    residue injects `_land_abort_cause_identity` because its whole subject is one cause; this
    projection is cause-AGNOSTIC by construction, so injecting an identity here would give the
    corpus a second opinion about what "the same cause" means (CHARTER P5). The branches this line
    exists for are precisely the ones for which no refined key can be computed at all.

    THE WINDOW IS RULE 26'S, REUSED AND NOT RE-DECLARED — `_debt_abort_breadth_window_hours()`, so
    one knob moves both transposes and a reader meeting them at the same seam holds one horizon."""
    return debt_mod.branch_unlanded_attempt_burn(
        EVENTS_PATH,
        window_hours=_debt_abort_breadth_window_hours(),
        min_attempts=_debt_branch_burn_min_attempts())

def _ahead_branch_view() -> dict:
    """SPEC-0119 rule 24 (T-11303 / <project> X-1001, corrected by X-1003): the AHEAD-WORK-BRANCH fold —
    `task/*` / `work/*` branches carrying commits main does not have. The thin host residue: it binds the
    ONE reader the pure fold cannot resolve itself, and decides nothing.

    THE GIT READ IS ONE CALL for the WHOLE frontier, never one per branch — which is the whole reason this
    view is cheap enough for a session seam, and the correction the card's own analysis made to it (the
    card assumed a per-branch `rev-list --count main..<branch>`). Two facts make one call enough: a branch
    is `--no-merged main` iff `rev-list --count main..<branch>` > 0, so `for-each-ref` ALREADY yields
    exactly the ahead-of-main set; and `%(ahead-behind:main)` carries the count itself. So the frontier,
    its counts, its tip dates and its tip subjects arrive together:
      `git for-each-ref --no-merged main --format=<short>\t<ahead-behind:main>\t<committerdate:iso-strict>\t<subject> refs/heads/`
    Bound to the MAIN checkout, like its rule-23 sibling's reader: a worktree checkout carries the same
    refs, but main is where the branch frontier is authoritative. A repo with no `main` (a fresh consumer,
    a detached bootstrap) yields NOTHING rather than an error — `for-each-ref` exits nonzero and the reader
    returns [], which the fold reads as a clean zero.

    `%(ahead-behind:)` needs git >= 2.41. On an older git the field comes back EMPTY, the parse yields no
    int, and the fold's `ahead` predicate DROPS the branch — so the view degrades to SILENT rather than to
    a wrong count, which is the right direction for a report-only surface.

    NO POLICY LIVES HERE (`lessons/scope-the-trigger-not-the-view`). The read is deliberately fleet-wide;
    the three bounds that decide what INTERRUPTS — the task/work namespace, the age floor, and rule-23
    ownership — are the TRIGGER and they live in the fold."""
    _main = _main_worktree(REPO_ROOT) or REPO_ROOT

    def _frontier() -> list:
        # Tab-separated so a subject containing spaces (most do) survives the split.
        r = _run_git_cap(["for-each-ref", "--no-merged", "main",
                          "--format=%(refname:short)\t%(ahead-behind:main)\t"
                          "%(committerdate:iso-strict)\t%(contents:subject)",
                          "refs/heads/"], _main)
        if r.returncode != 0:
            return []
        rows = []
        for ln in r.stdout.splitlines():
            parts = ln.split("\t")
            if len(parts) < 4:
                continue
            branch, ab, committed_at, subject = parts[0], parts[1], parts[2], "\t".join(parts[3:])
            # "<ahead> <behind>" — only the ahead leg is this view's subject. An empty/unparseable field
            # (a git older than 2.41) leaves `ahead` None, which the fold DROPS: silent, never wrong.
            ahead = None
            head = ab.strip().split(" ")[0] if ab.strip() else ""
            if head.lstrip("-").isdigit():
                ahead = int(head)
            rows.append({"branch": branch, "ahead": ahead, "committed_at": committed_at,
                         "subject": subject})
        return rows

    return debt_mod.ahead_work_branches(_frontier, _debt_ahead_branch_floor_hours())


def _debt_behind_branch_floor_commits() -> int:
    """SPEC-0119 rule 32 (T-11579): the BEHIND-BRANCH COUNT floor,
    `YITC_DEBT_BEHIND_BRANCH_FLOOR_COMMITS` (default 200).

    A COUNT floor, NOT an age floor — the deliberate departure from every sibling floor in this
    module, and the card's own decree. Elapsed time carries no information here: a repo committing
    hundreds of times a day makes a copy cut this morning hundreds of commits behind by noon, while a
    quiet day barely moves it, so the same hours mean opposite things in two repos and on two days in
    one repo. Distance from main is what hurts, so distance is what is floored.

    WHY 200: measured separation on this repo's live frontier 2026-08-25 — the six genuinely live
    lanes at 29 / 33 / 33 / 33 / 42 / 68 commits behind against the three genuinely stale desk copies
    at 995 / 3946 / 4268, with nothing whatever between 68 and 995 — and it sits below the originating
    <project> incident's own 234 (T-0435 / X-1105), so it would have fired there. The count is never
    hidden by it, only nearness suppresses (rule 3), and a non-positive value disables the bound. A
    bad value degrades to the default, never to an error."""
    raw = os.environ.get("YITC_DEBT_BEHIND_BRANCH_FLOOR_COMMITS", "").strip()
    if not raw:
        return 200
    try:
        return int(raw)
    except ValueError:
        return 200


def _behind_branch_view() -> dict:
    """SPEC-0119 rule 32 (T-11579 / <project> X-1105): the BEHIND-WORK-BRANCH fold — LIVE `task/*` /
    `work/*` worktrees whose branch main has run far ahead of. The thin host residue: it binds the
    two reads the pure fold cannot resolve itself, and decides nothing.

    TWO WHOLE-FRONTIER READS, never one per branch — which is what keeps this cheap enough for a
    session seam. (1) `git for-each-ref refs/heads/` carrying `%(ahead-behind:main)`, whose SECOND
    leg is this view's subject; (2) ONE `git worktree list --porcelain` parse for the set of branches
    that actually have a tree checked out.

    THE MISSING `--no-merged` IS THE LOAD-BEARING DIFFERENCE from the rule-24 reader, and it is not
    an oversight to be tidied away. `--no-merged main` yields exactly the branches that are AHEAD of
    main, so it can never yield a branch that is 0-ahead and far behind — which is precisely the
    worst case this rule exists to report. One lives on this repo right now
    (`work/batch-culprit-attribution`, 0 ahead / 3625 behind, measured 2026-08-25): fully merged, so
    invisible to rule 24 by construction AND unreachable by its reader. The behind leg therefore
    needs the FULL frontier. Bound to the MAIN checkout like both siblings — a worktree carries the
    same refs, but main is where the branch frontier is authoritative.

    `%(ahead-behind:)` needs git >= 2.41. On an older git the field comes back EMPTY, the parse
    yields no int, and the fold's `behind` predicate DROPS the branch — the view degrades to SILENT
    rather than to a wrong count. A repo with no `main` (a fresh consumer, a detached bootstrap)
    yields NOTHING rather than an error: `for-each-ref` exits nonzero and the reader returns [],
    which the fold reads as a clean zero. The worktree read fails the same way, to an EMPTY live set
    — which silences the view rather than reporting every branch as live, the direction that cannot
    accuse (`lessons/a-signal-about-a-reader-fails-safe-the-opposite-way-to-a-gate`).

    NO POLICY LIVES HERE (`lessons/scope-the-trigger-not-the-view`). The read is deliberately
    frontier-wide; the four bounds that decide what INTERRUPTS — the task/work namespace, the
    readable-count belt, the live-worktree subject and the commit floor — are the TRIGGER and they
    live in the fold."""
    _main = _main_worktree(REPO_ROOT) or REPO_ROOT

    def _frontier() -> list:
        live = set()
        w = _run_git_cap(["worktree", "list", "--porcelain"], _main)
        if w.returncode == 0:
            for ln in w.stdout.splitlines():
                if ln.startswith("branch refs/heads/"):
                    live.add(ln[len("branch refs/heads/"):].strip())
        # Tab-separated so a subject containing spaces (most do) survives the split.
        r = _run_git_cap(["for-each-ref",
                          "--format=%(refname:short)\t%(ahead-behind:main)\t"
                          "%(committerdate:iso-strict)",
                          "refs/heads/"], _main)
        if r.returncode != 0:
            return []
        rows = []
        for ln in r.stdout.splitlines():
            parts = ln.split("\t")
            if len(parts) < 3:
                continue
            branch, ab, committed_at = parts[0], parts[1], parts[2]
            # "<ahead> <behind>" — only the BEHIND leg is this view's subject. An empty/unparseable
            # field (a git older than 2.41) leaves `behind` None, which the fold DROPS.
            behind = None
            legs = ab.strip().split(" ") if ab.strip() else []
            if len(legs) >= 2 and legs[1].lstrip("-").isdigit():
                behind = int(legs[1])
            rows.append({"branch": branch, "behind": behind, "committed_at": committed_at,
                         "has_worktree": branch in live})
        return rows

    return debt_mod.behind_work_branches(_frontier, _debt_behind_branch_floor_commits())


def _concurrent_session_view() -> dict:
    """SPEC-0119 rule 25 (T-11353 / <project> X-1025): the CONCURRENT-SESSION-HOLDS fold — live
    worktrees in THIS repo stamped by a session OTHER than this one. The thin host residue: it binds
    the three reads the pure fold cannot resolve itself, and decides nothing.

    THE WORKTREE READ IS ONE CALL, not one-per-branch — the same single `git worktree list
    --porcelain` parse `_live_land_frontier` uses, so the whole frontier costs one subprocess at a
    session seam. Per row it then reads the T-0362 stamp file (a small local read in the worktree's
    private git admin dir, no subprocess of its own beyond the git-dir resolution `_worktree_stamp_path`
    already does) and takes ONE advisory liveness probe per DISTINCT stamp, never per worktree.

    THE OWN-REF IS THE READ-TOLERANT KEYER (`_try_resolve_session_ref`, T-10317), never the dying
    `_resolve_session_ref`: an unbacked or ambiguous identity must not `_die` inside a report-only
    echo. It yields None there, and the FOLD then goes silent rather than reporting every holder —
    an identity we cannot resolve proves nothing foreign.

    LIVENESS IS PASSED IN AS ADVISORY AND STAYS SEPARATE FROM PRESENCE
    (`lessons/a-presence-count-is-not-a-liveness-probe`): `alive` is three-valued, and the fold keeps
    it beside the presence count instead of ORing the two into one boolean — the conflation behind
    T-0351. The probe is READ-ONLY, never kills, and the view acts on nothing it finds.

    THE PROBE IS TOLD WHAT IT CAN SEE (T-13470). `_session_proc_alive` matches the `--session-id`
    argv, which only a dispatched worker carries; an interactive controller never does, so the bare
    probe answer read «NOT seen» for a live controller by construction. This residue therefore hands
    `debt.holder_liveness` TWO facts and lets it decide: the probe's answer, and whether a
    `bg_dispatch_launched` row declares that argv for this exact ref (`session_id_argv: true`). The
    second set is filled by the SAME pass over the launch rows the fleet derivation already makes —
    no second journal read. A ref no such row names reads undetermined, never not-seen; an
    unreadable journal leaves the set empty, which is the same humble answer.

    Fail-OPEN {} on any git or identity error (advisory read-side, never an integration gate — the
    posture `_live_land_frontier` / `_ahead_branch_view` already carry)."""
    def _rows() -> list:
        r = _run_git_cap(["worktree", "list", "--porcelain"], REPO_ROOT)
        if r.returncode != 0:
            return []
        main_wt = _main_worktree(REPO_ROOT)
        pairs, cur_path = [], None
        for line in r.stdout.splitlines():
            if line.startswith("worktree "):
                cur_path = line[len("worktree "):].strip()
            elif line.startswith("branch ") and cur_path:
                br = line[len("branch "):].strip()
                if br.startswith("refs/heads/"):
                    br = br[len("refs/heads/"):]
                # The MAIN checkout is not a hold — it is where everyone reads from.
                if br.startswith(("task/", "work/")):
                    pairs.append((Path(cur_path), br))
                cur_path = None
        rows, alive_by_ref = [], {}
        for path, br in pairs:
            if main_wt is not None and path == main_wt:
                continue
            stamp = _read_worktree_stamp(path) or {}
            ref = stamp.get("session_ref")
            # ONE liveness probe per DISTINCT stamp — a /proc scan per worktree would pay the same
            # answer N times, and the probe is about the SESSION, not about the directory.
            if ref and ref not in alive_by_ref:
                try:
                    alive_by_ref[ref] = debt_mod.holder_liveness(
                        journal_mod._session_proc_alive(ref), ref in carriers)
                except Exception:
                    alive_by_ref[ref] = None
            rows.append({"branch": br, "path": str(path), "session_ref": ref,
                         "started_at": stamp.get("started_at"),
                         "alive": alive_by_ref.get(ref) if ref else None})
        return rows

    # THE FLEET DERIVATION IS GUARDED ON ITS OWN, and that separation is load-bearing (audit-post
    # RED, 2026-08-26): sharing the outer guard would let an unreadable journal return `{}` and
    # SUPPRESS THE WHOLE LINE — hiding the genuine foreign holders it exists to surface, on a
    # failure of the merely-additive attribution leg. Degrading attribution costs a fleet that reads
    # as foreign (visible, the safe direction); degrading the view costs the signal itself.
    # `carriers` is created BEFORE the guarded call and filled by it, so a derivation that raises
    # leaves it empty: every not-found holder then reads undetermined (T-13470), never not-seen.
    carriers: set = set()
    try:
        fleet = _own_dispatched_fleet_refs(
            _try_resolve_session_ref(), argv_carriers=carriers)
    except Exception:                      # noqa: BLE001 — no attribution, never a suppressed view
        fleet = set()
    try:
        return debt_mod.concurrent_session_holds(
            _rows, _try_resolve_session_ref(), own_fleet_refs=fleet)
    except Exception:
        return {}


def _own_dispatched_fleet_refs(reader, events_path=None, argv_carriers=None) -> set:
    """The session refs the READING controller itself dispatched — `data.expected` on every
    `bg_dispatch_launched` whose ENVELOPE `session_ref` is that reader's (T-11606). Feeds
    `debt.concurrent_session_holds`' own-fleet attribution (SPEC-0119 rule 25).

    NO NEW STATE AND NO NEW READ PATH: the launch record already carries both halves of the
    attribution — who launched (the envelope) and which ref that worker will stamp with (`expected`)
    — so own-versus-foreign is a fold over the journal the debt echo already parses. It rides the
    SAME memoised `_iter_events` the ~15 sibling debt folds share inside `_debt_echo_lines`'
    `rows_memo` scope, so it costs no extra parse at the seam.

    MODULE-LEVEL AND INJECTABLE rather than nested in its caller, so the SPEC-0190 census records it
    as a journal-consumer site of its own and the segment-identity suites can DRIVE it directly.
    `events_path` is `_iter_events`' OWN optional-path argument, passed straight through — and the
    call below is spelled LITERALLY for the same reason: the census enumerates by AST, so a reader
    reached through an indirect callable (`read = _iter or _iter_events`) is INVISIBLE to it. A
    journal consumer the census cannot see is precisely the state that census exists to prevent, so
    the injection must never cost the call site its name.

    THE ATTRIBUTION IS THE ONE THING IN THIS VIEW THAT CAN SUPPRESS A ROW, so it is derived, never
    assumed: an unresolvable reader identity yields the EMPTY set (attribute nothing), which leaves
    every holder foreign and visible — the direction a mistake must fail in (the fold's own fail-safe
    paragraph). The own/foreign DECISION itself stays in the fold; this only supplies the refs.

    `argv_carriers` (T-13470) — an OPTIONAL set this same pass FILLS with every worker ref whose
    launch record declares the `--session-id` argv (`data.session_id_argv is True`), whoever
    launched it. It is rule 25's liveness leg: the argv probe can only ever find such a process, so
    «not seen» is a claim only for these refs (`debt.holder_liveness`). An out-set rather than a
    second reader ON PURPOSE: the same rows answer both questions, and a second read site would be
    a second journal consumer for the SPEC-0190 census to carry. None ⇒ nothing is collected and the
    return value is exactly what it was. It SUPPRESSES nothing — it only decides which of two
    advisory wordings a holder gets — so it is taken from ANY launcher's row, unlike the fleet.
    """
    if not isinstance(reader, str) or not reader.strip():
        return set()
    refs = set()
    # T-13139 — declared: the launch rows only (the debt seam's one-pass scope serves them).
    for event in _iter_events(events_path, types=(debt_mod.DISPATCH_LAUNCH_EVENT,)):
        if not isinstance(event, dict) or event.get("type") != debt_mod.DISPATCH_LAUNCH_EVENT:
            continue
        data = event.get("data")
        expected = data.get("expected") if isinstance(data, dict) else None
        expected = expected.strip() if isinstance(expected, str) and expected.strip() else None
        if argv_carriers is not None and expected and data.get("session_id_argv") is True:
            argv_carriers.add(expected)    # T-13470 — any launcher: the argv is a fact about the worker
        if event.get("session_ref") != reader.strip():
            continue                       # someone else's launch attributes nothing to me
        if expected:
            refs.add(expected)
    return refs


def _plan_census_view() -> dict:
    """SPEC-0119 rule 21 (T-11181): the NON-TERMINAL plan census fold over `plans/*.md` frontmatter —
    how many plans sit in each non-terminal stage of the plan FSM. Named (rather than inlined at the
    injection site) because T-11212 made it the ONE collaborator whose SEAM SET differs from its
    siblings': the caller decides whether to inject it, so which seams carry it is readable here.

    T-12081 — it now also binds the two SIBLING corpora the slice-staleness tail reads: `TASKS_DIR`
    (the `decomposed_from` cut cards) and `EVENTS_PATH` (the `plan_stage_entered` age rows). Both are
    passed EXPLICITLY rather than left to the fold's `plans_dir.parent` default, because these module
    globals are the seams a test REBINDS (`tests/_hermetic.py#make_corpus_hermetic`): a path derived
    from the repo root would read the real ~100MB journal straight through that redirect, which is
    the non-hermeticity that helper exists to close. Host binding only — the fold decides everything."""
    return debt_mod.nonterminal_plan_census(REPO_ROOT / "plans",
                                            tasks_dir=TASKS_DIR, events_path=EVENTS_PATH)


def _load_sensitive_uncarded_view() -> dict:
    """SPEC-0119 rule 41 (T-12359): the declared load-sensitive files that NO non-terminal card is
    holding. The host's whole contribution is binding THIS repo's two directories and deciding
    nothing — the `_unpickable_ready_view` shape one function down, reused.

    THE CARRIER IS READ THROUGH THE RUNNER'S OWN PARSER (`verify_runner._load_sensitive_set`), never
    a second one: that parser is what DECIDES which files actually get serialized, so a view built on
    a private re-parse could report a set the runner does not use. One parser, one answer.

    ONE SCAN OF `tasks/`, NOT TWO (T-12662): the fold's `ids_out` channel hands back every card id it
    already walked past, which is what the ratification exit's existence check needs — so this seam
    opens the corpus once and derives both answers from that single walk."""
    _ids: set = set()
    _carded = debt_mod.load_sensitive_carded(TASKS_DIR, ids_out=_ids)
    return debt_mod.load_sensitive_uncarded(
        worktree_mod.verify_runner._load_sensitive_set(REPO_ROOT / "tests"), _carded, _ids)


def _unpickable_ready_view() -> dict:
    """SPEC-0119 rule 36 (T-11868): the READY cards whose `requires:` names a `wont-do` target — the
    permanently-unpickable set. Named beside its `plans/` sibling because the host's whole contribution
    is the same one: binding THIS repo's `tasks/` directory, deciding nothing."""
    return debt_mod.unpickable_ready_cards(TASKS_DIR)


def _debt_echo_inject(kw, name):
    """T-12710 (C11c) — supply a moved `_debt_echo_*` body's host collaborators at CALL time (the
    inject-residue seam, `_cross_inject`'s C11c sibling). The leaf's `INJECTS[name]` is the generated
    keyword-only inject roster of that mover; each is read from THIS module's globals when the residue
    runs — the same dict `monkeypatch.setattr(yitc, ...)` and a `-C` rebind mutate — so a patched name
    is honoured; an explicit keyword from the caller wins."""
    _bind_debt_bookkeeping_authority()
    g = globals()
    for _k in debt_mod.INJECTS[name]:
        kw.setdefault(_k, g[_k])


def _bind_debt_bookkeeping_authority() -> None:
    """T-12847 — hand `lib.debt` the bookkeeping authority its SURFACE-2 overlap limb consults
    (`debt._authored_overlap`), which it may not import from here: debt is a leaf of this module.
    The getter reads THIS module's globals at CALL time, so a rebound `_BOOKKEEPING_ALLOWLIST`, a
    `monkeypatch.setattr(yitc, ...)` and a `-C` rebind are all honoured. Bound from
    `_debt_echo_inject`, the seam every debt-echo residue — the only production path to that
    detector — runs before the leaf body."""
    g = globals()
    debt_mod.bind_bookkeeping_authority(
        lambda: (g["_BOOKKEEPING_ALLOWLIST"], g["_zero_ship_diff_bookkeeping"]))


def _debt_echo_lines(_plan_census=_plan_census_view, _concurrent=_concurrent_session_view) -> list:
    """T-12710 (C11c) host residue — the body now lives in `bin/lib/debt.py#_debt_echo_lines`. NOT
    `functools.wraps`-ed: `debt_mod` is a deferred `_LazyLib` (T-11540) and a decorator would touch
    `debt_mod.<sym>` at cli import time, loading lib.debt eagerly — the residue resolves it at CALL time."""
    kw = {}
    _debt_echo_inject(kw, "_debt_echo_lines")
    return debt_mod._debt_echo_lines(_plan_census, _concurrent, **kw)


def _debt_echo_compact(*a, **kw):
    """T-12710 (C11c) host residue — the body now lives in `bin/lib/debt.py#_debt_echo_compact`. NOT
    `functools.wraps`-ed: `debt_mod` is a deferred `_LazyLib` (T-11540) and a decorator would touch
    `debt_mod.<sym>` at cli import time, loading lib.debt eagerly — the residue resolves it at CALL time."""
    _debt_echo_inject(kw, "_debt_echo_compact")
    return debt_mod._debt_echo_compact(*a, **kw)


def _frontend_error_echo_lines() -> list:
    """SPEC-0171 (T-10776): the CONSUMER frontend-error echo lines — report-only,
    SUPPRESSED-WHEN-CLEAN. Thin host residue: resolves the engine-qualified `-C` CLI hint (so the
    line's re-fold pointer is a command the reader can paste verbatim) and hands the leaf its
    collaborators. NOT wired into `_debt_echo_lines`: the settled re-fold verb for THIS echo is
    `frontend-errors`, not `debt` (plan `frontend-error-telemetry-conveyor-as-a-kernel-exte`), so it
    must not inherit a second re-fold name by riding that echo's seams."""
    return session.frontend_error_echo_lines(
        REPO_ROOT, _read_yaml, frontend_errors_mod,
        as_of=_dt.datetime.now(_dt.timezone.utc), cli_hint=_frontend_errors_cli_hint(),
        events_path=_followup_events_path(),   # T-10777: the ack fold reads the EFFECTIVE journal
        # T-10803: the cadence-liveness fold reads the CARRIER's journal instead — a different
        # resolver on purpose (the nightly records engine-side; see `_carrier_events_path`).
        carrier_events_path=_carrier_events_path())


def _auditor_hint_scope():
    """T-13461 — the session-start hint's ONE indexed scope (SPEC-0190 rule 4 class 3; the
    `cmd_audit_status` / `_onboarding_history_rows` idiom): it declares the one type the hint counts
    over the whole history, so an archived segment whose T-13356 summary covers it is served, never
    opened. Lazy — nothing is walked unless the hint reads. Before it, the cron-shaped start (no
    external auditor) opened every archive on each run: 135 folds, 35 with it."""
    return journal_mod.scan_scope(EVENTS_PATH, keep={audit.AUDITOR_SELF_PROVIDER_TYPE: None}, index=True)


def _auditor_hint_lines() -> list:
    """T-12380 (SPEC-0201 rule 3): the session-start external-auditor hint lines — report-only,
    SUPPRESSED when an external provider resolves for the routine tier. Thin host residue: hands the
    ONE fold (`audit.auditor_status`) the host-coupled AUDIT_CONFIG_PATH (engine-rebound under -C) +
    this checkout's journal reader, and the engine-qualified CLI form so the pointer is pasteable.
    Best-effort ([] on any failure) — the `_frontend_error_echo_lines` precedent: an informational
    surface never breaks `session start`."""
    try:
        # T-13303: `hint_only` — the hint reads no journal while an external auditor resolves, and
        # otherwise only the DECLARED `audit_self_provider_used` rows. T-13461: that whole-history
        # count is answered through the index (`_auditor_hint_scope`), as `audit status` answers it.
        with _auditor_hint_scope():
            st = audit.auditor_status(
                config_path=AUDIT_CONFIG_PATH, hint_only=True,
                iter_events=functools.partial(_iter_events, types=(audit.AUDITOR_SELF_PROVIDER_TYPE,)))
        # T-13013: kernel-authored text into a -C consumer realm-qualifies its bare kernel spec ids.
        return [_consumer_render(ln) for ln in audit.auditor_hint_lines(st, cli_form=_cli_invocation_form())]
    except Exception:
        return []


def _cli_invocation_form() -> str:
    """The runnable `bin/yitc-v2` invocation form for THIS checkout — engine-qualified with `-C` in a
    consumer session (which has no local `bin/yitc-v2`), bare in the engine's own checkout.

    T-11027: `_is_consumer_build()`, not a bare path inequality — an engine linked worktree IS the
    engine (T-0952), so it gets the bare form its own checkout does. Extracted by T-11409: the same
    one-liner was already written twice (`_frontend_errors_cli_hint` / `_onboarding_cli`, both of
    which now delegate here) and the read-gate refusal needed a third — one home instead (P1 F1/F3)."""
    return f"{ENGINE_ROOT}/bin/yitc-v2 -C {REPO_ROOT}" if _is_consumer_build() else "bin/yitc-v2"


def _is_consumer_root(root) -> bool:
    """`_is_consumer_build` for an EXPLICIT root (T-13176): the same common-dir comparison, so help text
    rendered BEFORE main's `-C` rebind can ask it of the raw-argv pre-parsed target."""
    root = Path(root)
    if root == ENGINE_ROOT:
        return False
    repo_common, engine_common = _git_common_dir(root), _git_common_dir(ENGINE_ROOT)
    return not (repo_common is not None and repo_common == engine_common)


def _consumer_render(text: str, root=None, *, qualify_specs: bool = True) -> str:
    """T-13176 host wrapper over `graph.consumer_render`: kernel-authored hint/help/refusal text with
    every command in the engine-absolute `-C <repo>` form and every path resolvable in the consumer.
    `root` defaults to the (possibly rebound) REPO_ROOT, read at CALL time. Any failure → `text`
    unchanged: a render must never break the verb (or the refusal) it decorates."""
    try:
        root = REPO_ROOT if root is None else Path(root)
        is_consumer = _is_consumer_build() if root == REPO_ROOT else _is_consumer_root(root)
        return graph.consumer_render(text, is_consumer=is_consumer,
                                     cli_form=f"{ENGINE_ROOT}/bin/yitc-v2 -C {root}",
                                     engine_root=ENGINE_ROOT, repo_root=root,
                                     qualify_specs=qualify_specs)
    except Exception:   # noqa: BLE001 — advisory rendering only
        return text


def _die_rendered(msg: str, code: int = 1, abort_class: "str | None" = None,
                  abort_detail: "dict | None" = None) -> None:
    """`_die` for the READ/SEED/STAGE gate refusals (T-13176): the remediation commands and paths they
    print resolve under `-C`. Spec ids stay as written — those gates qualify KERNEL ids themselves
    (T-13013), and a refusal may name the consumer's own. `_die` itself stays the untouched raw
    chokepoint (the land abort reasons + the T-12630 refused-set pin read it). Same exit contract as
    `_die` (SystemExit carrying the RAW `yitc_reason`); it adds no refusal text of its own — every
    message it prints is authored (and route-checked) at the gate's own literal `_die` site."""
    print(f"yitc-v2: {_consumer_render(msg, qualify_specs=False)}", file=sys.stderr)
    e = SystemExit(code)
    e.yitc_reason = msg
    if abort_class is not None:
        e.yitc_abort_class = abort_class
    if abort_detail is not None:
        e.yitc_abort_detail = abort_detail
    raise e


def _pre_parse_c_root(raw_argv: list) -> "Path | None":
    """The `-C/--directory` target resolved off RAW argv, BEFORE `build_parser()` (T-13176) — so help
    that argparse prints+exits during parse_args (before the rebind) can name the consumer. Silent None
    on any failure: `_resolve_c_flag` still validates (and dies) later on the real path."""
    val = None
    for i, a in enumerate(raw_argv):
        if a in ("-C", "--directory") and i + 1 < len(raw_argv):
            val = raw_argv[i + 1]
        elif a.startswith("--directory="):
            val = a.split("=", 1)[1]
        elif a.startswith("-C") and len(a) > 2:
            val = a[2:]
        if val is not None:
            break
    try:
        p = Path(val).expanduser() if val else None
        if p is None or not p.is_absolute() or not p.is_dir():
            return None
        r = subprocess.run(["git", "-C", str(p), "rev-parse", "--show-toplevel"],
                           capture_output=True, text=True, timeout=10)
        return Path(r.stdout.strip()) if r.returncode == 0 and r.stdout.strip() else None
    except Exception:   # noqa: BLE001
        return None


def _wrap_help_for_root(parser, root) -> None:
    """Wrap `format_help`/`format_usage` of `parser` and EVERY sub-parser at every depth so any help
    argparse prints renders for the pre-parsed `-C` root (T-13176). The root is passed EXPLICITLY."""
    seen = set()

    def _walk(p):
        if id(p) in seen:
            return
        seen.add(id(p))
        for name in ("format_help", "format_usage"):
            orig = getattr(p, name)
            setattr(p, name, lambda _o=orig: _consumer_render(_o(), root=root))
        for act in p._actions:
            if isinstance(act, argparse._SubParsersAction):
                for sub in act.choices.values():
                    _walk(sub)
    _walk(parser)


def _frontend_errors_cli_hint() -> str:
    """The invocation THIS reader would re-run (the `_surface_concern_drift` idiom)."""
    return _cli_invocation_form()


def _surface_concern_drift() -> None:
    """SPEC-0143 Rule 3 (T-10172): the report-only per-concern DRIFT surface at the consumer `-C`
    session-start seam (the SPEC-0118 MCP-reconcile session-start echo precedent). CONSUMER-gated;
    computes drift over THIS repo's ops carrier (adopted concern-version vs the KERNEL registry version),
    prints one report-only line per drifting concern, SUPPRESSED-WHEN-CLEAN (the SPEC-0119 debt-echo
    posture), and emits ONE `concern_drift_surfaced`. DERIVED — it mutates NOTHING in the consumer repo
    (the §6 fence); the emit rides the consumer's OWN session journal (its own observability, exactly
    like the session_started anchor — NOT a kernel push). BEST-EFFORT: any failure is swallowed so
    session-start is never broken by this informational surface (the `_debt_echo_lines` precedent).
    Computed in this (un-AST-scanned) host residue, so it adds NO injected dep to session.cmd_session_start
    (the D-0052 F5 startup AST-allowlist / SPEC-0077 pinned injected-deps == holds — the debt-echo
    precedent)."""
    try:
        if not _is_consumer_build():
            return   # drift is a consumer concept; the engine's own repo has no ops carrier anyway
        cd = init_mod.concern_drift(REPO_ROOT / "yitc-ops.yaml")
    except Exception:
        return
    if cd.get("count", 0) <= 0:
        return   # SUPPRESSED-WHEN-CLEAN (every concern level, or no-carrier/unreadable)
    if READ_ONLY_ROOT is not None:
        # T-13010: a read-only reader must not be handed `init --adopt-concern` WRITE cues for a target
        # it promised not to write — one count line instead, and no emit (it would land in the reader).
        print(session.mark(f"concern-drift: {cd.get('count')} concern(s) drifted — adopt cues withheld (read-only)",
                           session.REPORT_ONLY))
        return
    _eng_cli = f"{ENGINE_ROOT}/bin/yitc-v2 -C {REPO_ROOT}"
    for dr in cd.get("drifts", []):
        adopted = dr.get("adopted") or "none"
        print(f"concern-drift: {dr.get('concern')} adopted={adopted} current={dr.get('current')} "
              f"({dr.get('reason')}) — the kernel concern moved; review then record your decision via "
              f"`{_eng_cli} init --adopt-concern {dr.get('concern')}:<adopt|waive|na>:<owner>`. "
              f"Report-only (SPEC-0143 — the kernel never mutates your repo). " + session.REPORT_ONLY)
    try:
        _append_event("concern_drift_surfaced", None, {
            "seam": "session-start", "project": REPO_ROOT.name, "path": str(REPO_ROOT),
            "count": cd.get("count"), "drifts": cd.get("drifts")})
    except Exception:
        pass


def _print_task_resume(t: dict, label: str = "build", holder=None) -> None:
    # Thin residue → session._print_task_resume (T-9336, pure — no host deps). T-9698: `label`
    # frames the resume line per posture (controller|build) — the interactive Controller resumes
    # own work too (resume triggers off worktree/own-stamp STATE, not the type label).
    # T-13526: `holder` (a confirmed live foreign holder's ref) prints the held line instead.
    return session._print_task_resume(t, label, holder)


def _paused_awaits_resolver():
    """The HOST half of T-12407's awaited-artifact echo: `(ref) -> (arrived, at)`, for
    `session._waiting_on_owner_lines`.

    IT ASSEMBLES NOTHING NEW. Arrival is decided by the two readers that already decide it for the
    followup `armed -> fired` lens and for `views._deferred_probe_due` (T-12076): `arrived_ids` — the
    exact-membership union of terminal task ids + terminal coordination ids + observed event classes
    (T-11964) — and `event_after_arrived` for the `@after=` anchored shape (T-12057). A ref this
    resolver can decide is exactly a ref `awaits_kind` admits at the `task pause` write door, because
    that door classifies through the same splitter. No new terminality decision is made here (P5).

    LAZY, AND THE LAZINESS IS THE POINT. The three corpora are folded on the FIRST call and cached in
    the closure, so a session with no `paused_awaits` card pays NOTHING — this runs at the
    session-start seam, where the T-12030 read-narrowing exists precisely because work done per
    startup is work done thousands of times.

    BEST-EFFORT PER SOURCE, each in its own `try`, copied deliberately from `_overdue_recheck_view`'s
    injection shape. Every failure degrades to «has not arrived», which keeps the card WAITING —
    visible and disposable — rather than asserting an arrival that may not have happened (the
    T-10335 false-fire direction, and the direction `_terminal_cross_ids` already fails in).

    `at` is the arrival TIMESTAMP where a reader genuinely carries one: `_terminal_task_closures`
    maps each terminal task id to its `closed_at`. A coordination item's fold carries a status and no
    terminal ts, and an event class's arrival is not a per-ref moment — both return None, and the
    renderer prints no timestamp rather than a fabricated one."""
    cache: dict = {}

    def _load(events: bool) -> dict:
        # T-13303 (SPEC-0190 rule 4) — the JOURNAL corpus is folded only for an EVENT-class ref
        # (`events.jsonl#type=…`, the one grammar whose arrival it decides): a task- or cross-id ref
        # is decided by the two card/log corpora alone, so it no longer pays a whole-journal fold.
        # The event-class fold is a WHOLE-HISTORY membership question with no index (routed T-13288).
        if not cache:
            try:
                cache["closures"] = _terminal_task_closures()
            except Exception:
                cache["closures"] = {}
            try:
                cache["terminal_cross"] = _terminal_cross_ids()
            except Exception:
                cache["terminal_cross"] = frozenset()
            cache["fired"] = followup_mod.arrived_ids(frozenset(cache["closures"]), cache["terminal_cross"], ())
            cache["latest"] = {}
        if events and not cache.get("events"):
            cache["events"] = True
            closures, cross_ids = cache["closures"], cache["terminal_cross"]
            seen: set = set()
            latest: dict = {}
            try:
                # The SAME fold key every other followup reader uses — the effective events path plus
                # the SEGMENT-AWARE physical reader (SPEC-0190 rule 4; an un-injected reader would
                # silently see the live segment alone). The out-parameters are the only thing wanted.
                followup_mod._fold(_followup_events_path(),
                                   _segment_lines=journal_mod.segment_fold_lines,
                                   seen_event_types=seen, latest_event_ts=latest)
            except Exception:
                pass
            cache["fired"] = followup_mod.arrived_ids(frozenset(closures), cross_ids, tuple(seen))
            cache["latest"] = latest
        return cache

    def _arrived(ref):
        if not isinstance(ref, str) or not ref.strip():
            return False, None
        ref = ref.strip()
        c = _load(ref.startswith(followup_mod.AWAITS_EVENT_PREFIX))
        if ref in c["fired"]:
            return True, c["closures"].get(ref)     # a ts only for the reader that carries one
        try:
            if followup_mod.event_after_arrived(ref, c["latest"]):
                return True, None
        except Exception:
            pass
        return False, None

    return _arrived


#: T-13526 — THIS start's own session ref, for the duration of `cmd_session_start` (None outside
#: one). `session start` is the WRITER of that ref's anchor, so "is this worktree stamp mine?" is an
#: equality against it — the T-13371 rule: no identity re-read, hence no journal read, at start.
_START_OWN_REF: "str | None" = None


def _session_start_identity_noted(arg_value: "str | None" = None) -> "tuple[str, str]":
    """`_session_start_identity`, with the resolved-or-minted ref noted for this start's held-card
    lookup (T-13526). Same return, same refusals; `_start_skip_scope(False)` clears the note."""
    global _START_OWN_REF
    ref, kind = _session_start_identity(arg_value)
    _START_OWN_REF = ref
    return ref, kind


class _LiveHolderLookup:
    """T-13526 — `.get(task id)` → the session ref of a LIVE FOREIGN session holding that task's
    worktree, else None. Built ONCE per `session start` and shared by the waiting rows and the
    single-card resume, so a card asked about twice is probed once (the memo).

    REUSE, NOT A SECOND PREDICATE (CHARTER §P1 F1): the hold is `task._refuse_live_foreign_hold` (a
    worktree checked out on `task/<id>` whose stamp is not ours — T-12762) and the liveness is
    `_session_proc_alive` (the SPEC-0133 argv probe, read at CALL time through `_SELF` so a test
    monkeypatch or a `-C` rebind is honoured). It is deliberately NOT the `--dispatch-status` journal
    fold: that costs 0.5-4 s and this runs at every start (owner no-startup-burn directive
    events.jsonl#ts=2026-10-04T06:31:46Z). A probe here is one `git worktree list`, one stamp file
    and one /proc scan (~30 ms), and it runs ONLY for a card whose start line it could change.

    FAIL-CLOSED TOWARD TODAY'S TEXT. A hold is answered only on positive proof at every step: no
    worktree, an own stamp, an unstamped or ref-less worktree, a dead or unreadable process table,
    and any exception all answer None — the caller then prints exactly what it printed before. "Own"
    is equality with this start's ref; outside a start no ref is known, so nothing is own."""

    def __init__(self, own_ref: "str | None" = None):
        self._own_ref = own_ref
        self._memo: dict = {}

    def get(self, tid, default=None):
        if not tid:
            return default
        if tid not in self._memo:
            self._memo[tid] = self._probe(tid)
        return self._memo[tid] or default

    def _probe(self, tid) -> "str | None":
        own = self._own_ref
        try:
            hold = task_mod._refuse_live_foreign_hold(
                tid, _worktree_path_for_branch=_worktree_path_for_branch,
                _read_worktree_stamp=_read_worktree_stamp,
                _stamp_is_own=lambda stamp: bool(stamp) and bool(own)
                and stamp.get("session_ref") == own)
            if hold is None:
                return None
            ref = ((hold[1] or {}).get("session_ref") or "").strip()
            if not ref or not _SELF._session_proc_alive(ref):
                return None
            return ref
        except Exception:
            return None


def _live_holder_lookup() -> "_LiveHolderLookup":
    """The per-start live-holder lookup (T-13526), keyed on THIS start's own ref."""
    return _LiveHolderLookup(_START_OWN_REF)


def _waiting_on_owner_lines(held=None) -> list:
    # Thin residue → session._waiting_on_owner_lines (T-9336). Injects the tasks dir + yaml reader,
    # and (T-12407) the awaited-artifact arrival predicate — passed as a VALUE, so no AST-scanned
    # startup body gains a bare-name Call and the D-0052 F5 allowlist is untouched.
    # T-13526: `held` — the per-start live-holder lookup, handed in by `_session_build_dispatch` so
    # the waiting rows and the single-card resume share ONE memo. A direct caller that passes none
    # gets a fresh one: the answer is the same, only the sharing is lost.
    if held is None:
        held = _live_holder_lookup()
    _skips = [] if _START_SKIP_SEEN is not None else None
    lines = session._waiting_on_owner_lines(TASKS_DIR=TASKS_DIR, _read_yaml=_read_yaml,
                                            _awaits_arrived=_paused_awaits_resolver(), skipped=_skips,
                                            held=held)
    _report_start_skips(_skips)
    return lines


def _controller_acting_holder(own_ref: "str | None" = None) -> "str | None":
    # Thin residue → session._controller_acting_holder (T-12306). Injects the host globals + the
    # SAME `_SELF._session_proc_alive` `worktree recover-land` uses for its confirmed-dead axis,
    # read at CALL time so a `-C` rebind or a test monkeypatch is honoured (never a second predicate).
    # T-13371 — `own_ref`: `session start` passes the ref it just resolved-or-minted. It is the WRITER of
    # that ref's anchor (SPEC-0137 rule 1 bootstrap exemption, T-10149/T-10246), so "is this stamp mine?"
    # is that equality — no rediscovery. The strict `_stamp_is_own` re-derived the identity through
    # `_ref_current_epoch_anchored`, which for a carried ref with no anchor yet (every fresh start in a
    # task worktree) read the WHOLE journal, untyped, into the start's rows_memo: 123 of 123 segments,
    # 5.37 GB peak on the kernel (the T-13357 census row). Without `own_ref` the strict check is unchanged.
    is_own = _stamp_is_own if own_ref is None else (
        lambda stamp: bool(stamp) and stamp.get("session_ref") == own_ref)
    return session._controller_acting_holder(
        REPO_ROOT=REPO_ROOT, TASKS_DIR=TASKS_DIR, _read_yaml=_read_yaml, _run_git_cap=_run_git_cap,
        _read_worktree_stamp=_read_worktree_stamp, _stamp_is_own=is_own,
        _session_proc_alive=_SELF._session_proc_alive)


def _session_build_dispatch(label: str = "build", show_posture: bool = False,
                            acting_holder=None, checkout_only: bool = False) -> None:
    # Thin residue → session._session_build_dispatch (T-9336). Injects host collaborators/globals
    # (incl. the _waiting_on_owner_lines / _print_task_resume residues) read at call time.
    # T-9698: `label`/`show_posture` frame the SAME resume-or-await for the worker (build) vs the
    # interactive Controller (which also prints a lean posture line on the await paths).
    # T-13265: during a `session start`, collect the malformed cards this walk skips and name them.
    # T-13526: ONE live-holder lookup per start, shared (as a VALUE — no new bare-name Call in the
    # AST-scanned body) by the waiting rows and the single-card resume.
    _skips = [] if _START_SKIP_SEEN is not None else None
    _held = _live_holder_lookup()
    try:
        return session._session_build_dispatch(
            skipped=_skips, held=_held,
            TASKS_DIR=TASKS_DIR, _read_yaml=_read_yaml,
            _waiting_on_owner_lines=functools.partial(_waiting_on_owner_lines, _held),
            _run_git_cap=_run_git_cap,
            REPO_ROOT=REPO_ROOT, _read_worktree_stamp=_read_worktree_stamp, _stamp_is_own=_stamp_is_own,
            # `_main_worktree` here resolves a journal LOCUS (session.py uses it for nothing else — it
            # builds the `journals` list `_foreign_hold_report` reads), so it takes the locus-aware form:
            # a hermetic child has no main journal to consult (T-11445).
            _print_task_resume=_print_task_resume, _main_worktree=_journal_locus_main_worktree,
            EVENTS_PATH=EVENTS_PATH, _foreign_hold_report=_foreign_hold_report,
            label=label, show_posture=show_posture, acting_holder=acting_holder,
            checkout_only=checkout_only)   # T-13580: a same-epoch repeat reports this checkout only
    finally:
        _report_start_skips(_skips)


def _session_controller_dispatch(acting_holder=None, checkout_only: bool = False) -> None:
    # Thin residue → the SAME session._session_build_dispatch resume-or-await, framed for the
    # interactive Controller (T-9698 — Build|Review interactive type retired; the read-leaning
    # posture folds into the lean controller posture line printed on the await paths). Replaces
    # the retired _session_review_dispatch.
    # T-12306: `acting_holder` (the confirmed-dead foreign holder's ref, or None) is threaded from
    # the ONE `cmd_session_start` computation so the echo and the journal key cannot disagree.
    return _session_build_dispatch(label="controller", show_posture=True, acting_holder=acting_holder,
                                   checkout_only=checkout_only)



def _auto_sync(args: argparse.Namespace) -> None:
    """Auto-sync hook (D-0049): materialize the session log into events.jsonl BEFORE every verb,
    so the journal stays continuously fresh (post-analysis + read-compliance). DEFAULT-ON; the
    ONLY exclusions are `journal sync` (it IS the sync — recursion) and `land` (does its own
    events reconcile), both marked `no_autosync=True`. Read-only verbs sync too — the resulting
    allowlist dirt on the main checkout is folded by `land` (T-0099 / D-0051), no longer blocking
    it (closes D-0049 step_0). A sync failure propagates fail-closed for MUTATING/governance verbs;
    a read/query verb (the `cli_invoked_verb` marker) fail-OPENS on an OSError (unwritable journal) —
    the read mutates nothing, so it must not die for an I/O failure (handled in main(), T-0304). The
    SPEC-0010 invariants hold either way: the sync still RUNS for reads; only its FAILURE is non-fatal."""
    if getattr(args, "no_autosync", False) or _zero_write_view(args):   # T-12929: SPEC-0010 amendment
        return
    if READ_ONLY_ROOT is not None:
        return   # T-10859: the sync WRITES (journal-sync-state/ + event appends) into the read-only target
    _journal_sync()


def _pre_claim_refuse_hint(tid: str) -> None:
    """Cheap adoption belt (T-10385) for the pre-claim premise-false miss (2/2 on 2026-07-10 —
    T-10367/T-10368 captured a deviation then exited WITHOUT `task refuse`, so fleet-verdict read
    launch-stall instead of needs-decision). When a DISPATCHED worker (YITC_EXPECTED_SESSION_REF
    set by the launcher) emits `deviation_captured` about a --task it has NOT yet claimed — task
    still `ready`, and we are NOT in a writing worktree — print an advisory pointer to the covering
    verb `task refuse`. DEFENSIVE + PRINT-ONLY: any failure here MUST NOT break the capture (the
    deviation_captured event already landed); this never dies and never mutates. The rule home is
    the preamble point 5 / AGENTS §Deviation-capture corollary / T-10291 — this is only a cue."""
    try:
        if not os.environ.get("YITC_EXPECTED_SESSION_REF"):
            return                      # not a launcher-dispatched worker — no pre-claim context
        if _in_writing_worktree():
            return                      # already claimed (writing worktree) — the refuse case is PRE-claim
        path = _find_task_yaml(tid)
        if path is None:
            return
        rec = _read_yaml(path)
        if not isinstance(rec, dict) or rec.get("status") != "ready":
            return                      # only a still-ready (unclaimed) card is refusable pre-claim
        print(f"  hint (T-10385): if this deviation means {tid} cannot be claimed (premise false / "
              f"out-of-scope / unmet precondition), the GOVERNED pre-claim exit is "
              f"`bin/yitc-v2 task refuse {tid} --reason <why>` — NOT a silent exit. It records "
              f"refused(pre-claim) so fleet-verdict reads needs-decision, not launch-stall (T-10291).")
    except Exception:
        return                          # belt is advisory — never let it break the capture


# T-10600 (X-0447): the event types whose registration through THIS verb is AUTHORITY-class — the
# record IS the authority a later worker cites (SPEC-0121 refusal ground 1), so it must carry a
# locator that RESOLVES from the event alone. Kept as an exact-match tuple, not a prefix/heuristic:
# every other event type keeps `_append_event`'s legitimately-open source_ref default.
SOURCE_REF_REQUIRED_TYPES = ("owner_directive",)


def _resolve_owner_directive_source_ref(explicit: "str | None" = None) -> str:
    """T-10600 (X-0447): resolve the D-0030 owner-transcript locator for an AUTHORITY-class
    registration, or _die LOUDLY. Never returns None and never returns an unverified locator —
    a silent `source_ref: null` is exactly the incident this closes.

    WHY THE FAIL-CLOSED LIVES HERE, not in `_append_event`/the adapter: fail-closed is a property of a
    USE SITE, not of a shared primitive (lessons/fail-closed-belongs-to-the-reader-not-the-parser.md).
    For most event types an absent source_ref is legitimate, so the primitive's open default is correct
    and stays untouched; a hand-registered owner_directive is provenance-bearing BY DEFINITION, so THIS
    caller — the one that knows that — owns the missing-value judgement.

    Locator resolution honors D-0030's identity-vs-transcript-role split (SPEC-0137): the transcript is
    named by the PROVIDER carrier (`_provider_session_ref`), NEVER by the envelope's v2 identity
    (`_resolve_session_ref_for_envelope`), which is a minted self-ref naming no transcript file. Getting
    this backwards IS the X-0447 defect: the incident event recorded identity 796eda8c where a
    transcript locator belonged, so the authority turn was findable only by an out-of-band hunt.
    """
    # `is not None`, NOT truthiness: an EXPLICITLY supplied `--source-ref ""` is a caller asserting a
    # locator, not declining to — so it must fail the validation below rather than silently fall through
    # to derivation. Only an OMITTED flag (None) derives.
    if explicit is not None:
        loc = explicit.strip()
        # A locator is `<transcript-path>` or `<transcript-path>#<anchor>` (the adapter's materialized
        # form, e.g. `...jsonl#uuid:<uuid>`, pins the exact owner turn). Verify the PATH part only —
        # the anchor addresses a row INSIDE the file and is not a filesystem object.
        path_part = loc.split("#", 1)[0]
        if not path_part or not Path(path_part).is_file():
            _die(f"--source-ref locator does not resolve to a file on disk: {path_part!r}\n"
                 f"  an owner_directive is AUTHORITY-class — its locator MUST be openable by a later\n"
                 f"  reader, or the record cannot be verified from itself (X-0447 / SPEC-0121).\n"
                 f"  pass a real transcript path, optionally anchored: <transcript>#uuid:<entry-uuid>")
        return loc

    ref = _provider_session_ref()
    if not ref:
        _die("cannot resolve the owner-transcript locator for an owner_directive: no provider session\n"
             "  carrier is set in this environment, so there is no transcript to name.\n"
             "  refusing rather than appending a silent `source_ref: null` (X-0447).\n"
             "  pass the locator explicitly: --source-ref <transcript-path>[#uuid:<entry-uuid>]")
    log = _session_log_path(ref)
    if log is None:
        _die(f"cannot resolve the owner-transcript locator for an owner_directive: no transcript on\n"
             f"  disk for provider session {ref!r} (searched every known provider tree).\n"
             f"  refusing rather than appending a silent `source_ref: null` — an unverifiable\n"
             f"  authority record is exactly the X-0447 incident (SPEC-0121 refusal ground 1).\n"
             f"  pass the locator explicitly: --source-ref <transcript-path>[#uuid:<entry-uuid>]")
    return str(log)


def _validated_explicit_source_ref(raw: str) -> str:
    """T-11741 (X-1174): validate an EXPLICITLY supplied `--source-ref` for a NON-authority event
    type, or `_die` naming the reason. Returns the locator to persist; never returns None and never
    returns a value the citation grammar cannot address.

    WHY THIS EXISTS. `--source-ref` was read at exactly ONE place — the `owner_directive` branch below
    — so for every OTHER event type the value was parsed by argparse and then DROPPED: the verb exited
    0, printed only its `#ts=` witness, and the row persisted `source_ref: null`. The cost is a closed
    loop, and it is why "silently ignored" was not survivable here: `task close --settle-probe
    --settle-evidence events.jsonl#source_ref=<ref>` is a citation form the settle grammar
    DOCUMENTS and ACCEPTS (`_LIVE_PROBE_SETTLED_REF_RE`, `bin/lib/task.py`), and it then refused with
    "resolves to NO event in the journal" because the ref was never stored — so a settlement could not
    be given a UNIQUE locator when several evidence rows shared a second (<project>: 22 dropped refs,
    9 refused settles).

    PERSIST, NOT REFUSE-THE-FLAG — the fork the card left open. Refusing every non-authority
    `--source-ref` would have been honest about the drop, but it would leave the settle grammar
    documenting a locator form NO caller can produce, which is a standing artifact contradiction
    (CHARTER §Principle 7). Persisting closes the loop instead.

    SAME USE-SITE RATIONALE as `_resolve_owner_directive_source_ref` above, and the same reason it is
    NOT in `_append_event`: the missing-value judgement belongs to the caller that knows what the
    value means (lessons/fail-closed-belongs-to-the-reader-not-the-parser.md). The primitive's open
    default is correct and stays untouched — the parser/adapter calls it directly with locators it
    already trusts.

    WHAT IS REFUSED, and why these two and nothing more. A value that persists but can never be CITED
    would just relocate the silent failure one step downstream, so the accept-or-refuse line is drawn
    at "can the settle grammar address it?":
      - empty / whitespace-only — the caller ASSERTED a locator and supplied none. (`is not None` at
        the call site, not truthiness: an explicit `--source-ref ""` must fail HERE rather than fall
        through to a null, the same discrimination T-10600 made for the authority branch.)
      - contains whitespace ANYWHERE, judged on the RAW argument — `events.jsonl#source_ref=<ref>`
        matches `\\S+`, so such a value is unaddressable by the very citation form this change exists
        to make work.

    WHY THE WHITESPACE TEST READS THE RAW ARGUMENT AND THE ACCEPTED VALUE IS NEVER TRIMMED
    (audit-post T-11741, RED, fixed in scope). An earlier cut stripped first and judged the result,
    so `--source-ref " ref "` exited 0 and stored `"ref"` — which is neither persisting the caller's
    value NOR refusing it, but a THIRD outcome: silently altering the asserted locator. That is the
    same shape as the defect this whole change closes, one step over: the caller's ref and the stored
    ref differ, and nothing said so. This verb has exactly two admissible outcomes on an explicit
    value, so a surrounding-whitespace ref is REFUSED like any other uncitable one and an accepted
    value is stored BYTE-FOR-BYTE as given. (`.strip()` survives only to decide the EMPTY case, whose
    message tells the caller to omit the flag — it never reaches the returned value.)
    Nothing else is judged: `source_ref` is an OPAQUE locator by contract (SPEC-0002), so this refuses
    what the grammar provably cannot read and takes no view on what a locator should otherwise look
    like. In particular a NON-authority ref is NOT filesystem-checked — that check belongs to the
    authority branch, where the locator is a transcript path by definition; here it may legitimately
    name a row in another project's journal, a coordination item, or any opaque source.
    """
    if not raw.strip():
        _die("--source-ref was given but is empty — refusing rather than appending a silent\n"
             "  `source_ref: null` (T-11741 / X-1174). Passing the flag ASSERTS a locator; to emit\n"
             "  no locator, OMIT the flag entirely.")
    # RAW, not stripped: see the docstring — trimming and storing the result would be a third
    # outcome (neither persisted nor refused), which is the defect class this verb must not have.
    if any(c.isspace() for c in raw):
        _die(f"--source-ref contains whitespace and so cannot be CITED: {raw!r}\n"
             f"  the citation form `events.jsonl#source_ref=<ref>` matches a whitespace-free ref, so\n"
             f"  this value would persist and STILL fail to resolve when a probe settlement cites\n"
             f"  it — the silent failure this gate exists to close. It is REFUSED rather than\n"
             f"  trimmed: silently storing a locator different from the one you passed is the same\n"
             f"  defect one step over.\n"
             f"  pass a whitespace-free locator (T-11741 / X-1174).")
    return raw


@functools.wraps(events.cmd_event)
def cmd_event(*a, **kw):
    """T-12704 (C11a) host residue — the body now lives in `bin/lib/events.py#cmd_event`.
    Every inject is read HERE from this module's live globals at call time, so `-C` rebinds and
    `monkeypatch.setattr(yitc, ...)` stay honoured."""
    g = globals()
    for _k in events.CMD_EVENT_INJECTS:
        kw.setdefault(_k, g[_k])
    return events.cmd_event(*a, **kw)


def _reservation_dir(directory: Path):
    """Cross-worktree ID reservation root (T-0073 / D-0037). Returns the dir holding the
    shared lock + monotonic counter, or None when not in a git repo (single-checkout → caller
    falls back to a per-directory lock + scan).

    Shared-across-worktrees = the git common-dir (`.git/` of the main checkout; every linked
    worktree resolves to the SAME one). A per-worktree lock/scan is NOT cross-worktree-safe:
    each worktree has its own checkout, so its lock file differs and its glob can't see a
    sibling worktree's unmerged `<prefix>-NNNN`. Tests override via ID_RESERVATION_DIR
    (in-process) or YITC_ID_RESERVATION_DIR (the SUBPROCESS sibling — the reservation analog of
    the YITC_EVENTS_SINK journal write-sink, T-0357; T-9197). Production sets neither.
    """
    env_resv = os.environ.get("YITC_ID_RESERVATION_DIR", "").strip()
    if env_resv:
        return Path(env_resv)
    if ID_RESERVATION_DIR is not None:
        return Path(ID_RESERVATION_DIR)
    import subprocess
    try:
        out = subprocess.run(["git", "-C", str(directory), "rev-parse", "--git-common-dir"],
                             capture_output=True, text=True, check=False)
    except (FileNotFoundError, OSError):
        return None
    if out.returncode != 0 or not out.stdout.strip():
        return None
    common = Path(out.stdout.strip())
    if not common.is_absolute():            # rev-parse returns it relative to the -C dir
        common = (directory / common).resolve()
    return common / "yitc-v2-id-reservations"


# The ONE flock-target open — now homed in `bin/lib/lockfile.py` so `bin/lib/*` can reach it too
# (T-10336). The private def that used to live here was unreachable from the lib modules — the
# dependency runs the other way — which is exactly how four more `open(p, "w")` sites re-introduced
# the X-0226 bug. Bound to its historical private name so the `_id_alloc_lock` / `_with_repo_lock`
# critical sections below are untouched.
_open_flock_target = lockfile.open_flock_target


def _bump_id_reservation(resv_path: Path, nxt: int) -> None:
    """Write the monotonic reservation counter under the caller's flock. A NAMED seam (T-10888)
    rather than an inline `write_text`: this one line is what makes two concurrent allocations
    DIFFER before either has written its artifact, so it is also the single symbol a differential
    probe no-ops to reproduce the pre-allocator collision."""
    _guard_consumer_engine_write(resv_path)  # SPEC-0078: reject consumer→ENGINE_ROOT reservation writes
    resv_path.write_text(f"{nxt}\n", encoding="utf-8")


@contextlib.contextmanager
def _alloc_under_lock(ref: Path, key: str, scan_max, fmt, *, fallback_lock: "Path | None" = None,
                      require_reservation: bool = False, explicit: "int | None" = None,
                      band: "tuple[int, int] | None" = None):
    """THE allocator core (T-10888, lifted verbatim out of `_id_alloc_lock`) — yield the next
    sequential token while holding an exclusive flock, `next = max(scan_max(), reservation) + 1`.

    Everything that makes allocation SAFE lives here and is shared: the lock + the monotonic
    reservation counter both live in the git common-dir (`_reservation_dir`), so every linked
    worktree serializes on ONE lock and sees what a sibling reserved before merge, and the
    reservation is bumped under the lock BEFORE the yield (a failed write leaves a GAP, never a
    collision — tokens must be unique + increasing, not gap-free). What varies per caller is only
    `scan_max()` (the durable floor read off whatever the caller's artifacts are) and `fmt(n)` (the
    token spelling) — two callbacks, not two allocators.

    `require_reservation`: when True, a missing reservation root is a REFUSAL rather than the
    scan-only fallback. Correct for any caller that does NOT write its artifact inside the
    with-block: without the durable reservation, two concurrent callers scan the same floor and
    receive the SAME token — the very bug. `_id_alloc_lock`'s callers DO write inside the block, so
    they keep the historical single-checkout fallback (`fallback_lock`).

    `explicit` (T-12397): allocate THIS number instead of `floor + 1`. Admitted ONLY strictly ABOVE
    the floor `max(scan_max(), reservation)` — so an id already taken by an artifact (which raises
    `scan_max()`) or already handed to a sibling worktree (which raises the reservation) is
    REFUSED, and the refusal happens BEFORE the reservation bump, so a rejected explicit id burns
    nothing. Monotonicity is preserved (the reservation is bumped TO the explicit value), so the
    next plain allocation continues after it. This does not relax what the allocator exists for —
    tokens stay unique + increasing; the caller may only choose a BIGGER gap, never reuse.

    `band=(lo, hi)` (T-12839): the caller's ALLOCATION ZONE. A sequential token is lifted to at least
    `lo` (so a corpus whose history sits below the zone starts at `lo`), and a token that would pass
    `hi` is REFUSED with `<key>-id-zone-exhausted` — before the reservation bump, so nothing is burned.
    WHICH zone applies is the caller's policy, never this core's; `band=None` is byte-identical to
    before, so every other caller is untouched.
    """
    resv_dir = _reservation_dir(ref)
    if resv_dir is not None:
        resv_dir.mkdir(parents=True, exist_ok=True)
        lock_path = resv_dir / f"{key}.lock"
        resv_path = resv_dir / f"{key}.max"
    elif require_reservation:
        _die(f"allocator '{key}': no cross-worktree reservation root (not a git repo?) — refusing.\n"
             f"  Without the durable reservation two concurrent callers scan the same floor and get\n"
             f"  the SAME token, which is the collision this allocator exists to prevent.")
    else:
        lock_path = fallback_lock
        resv_path = None
    lock_fd = _open_flock_target(lock_path)
    try:
        fcntl.flock(lock_fd, fcntl.LOCK_EX)
        resv_max = 0
        if resv_path is not None and resv_path.exists():
            try:
                resv_max = int(resv_path.read_text(encoding="utf-8").strip() or "0")
            except ValueError:
                resv_max = 0
        floor = max(scan_max(), resv_max)
        if explicit is None:
            nxt = floor + 1
            if band is not None:
                lo, hi = band
                nxt = max(nxt, lo)
                if nxt > hi:
                    # Fail-closed BEFORE the bump, exactly like the explicit refusal below (T-12839).
                    _die(f"{key}-id-zone-exhausted: the next id {nxt:04d} is above this repo's zone "
                         f"ceiling {hi:04d} (zone {lo:04d}-{hi:04d}, current floor {floor:04d}). "
                         f"No id was burned and nothing was written.")
        elif explicit <= floor:
            # Fail-closed BEFORE the bump: no id burned, no artifact written (T-12397).
            _die(f"allocator '{key}': explicit id {explicit:04d} is not above the current floor "
                 f"{floor:04d} — it is already taken (an artifact carries it) or already reserved "
                 f"by a sibling worktree. Ids must stay unique + increasing; pick a higher one, or "
                 f"omit --id to take the next ({floor + 1:04d}).")
        else:
            nxt = explicit
        if resv_path is not None:
            _bump_id_reservation(resv_path, nxt)
        yield fmt(nxt)
    finally:
        os.close(lock_fd)  # releases the flock — after the caller's write completes


@contextlib.contextmanager
def _id_alloc_lock(directory: Path, prefix: str, width: int = 4, explicit: "int | None" = None,
                   band: "tuple[int, int] | None" = None):
    """Yield the next sequential `<prefix>-NNNN` id while holding an exclusive flock — the
    single shared ID allocator (T-0009 + T-0063 + T-0073). TOCTOU-safe: the caller writes the
    file INSIDE the with-block so concurrent invocations cannot claim the same id (pattern:
    patterns/atomic-state-file-writes.md §Combine with flock).

    Cross-worktree-safe (T-0073 / D-0037): the lock AND a monotonic reservation counter live in
    the git common-dir (shared by every worktree), so two worktrees serialize on ONE lock and
    each sees IDs the other reserved even before merge. `next = max(file_scan_max, reservation)
    + 1`; the reservation is bumped under the lock BEFORE the yield (a failed write leaves a
    gap, never a collision — IDs must be unique + increasing, not gap-free). The file-scan max
    is the durable floor, so the reservation self-heals if the common-dir state is deleted.
    Outside a git repo (`_reservation_dir` → None) it falls back to the original per-directory
    lock + scan (single-checkout behaviour unchanged).

    That lock+reservation body now lives in `_alloc_under_lock` (T-10888), which this function
    parameterises with the directory-glob scan + the `<prefix>-NNNN` spelling. The semantics above
    are unchanged; the core simply has a second caller (`_ledger_label_alloc_lock`) that differs
    only in how it reads its floor and spells its token.

    Counting rule (T-0063 audit-pre F3): match the leading `<prefix>-<width digits>` token
    followed by а delimiter (`-` либо `.`). Sibling artifacts like `D-0011-audit-pre.yaml`
    carry the SAME number as their parent decision, so they never shift max(); `_template.yaml`
    has no prefix-number token. No YAML parse — filename token only, so no parse-noise breakage.
    """
    directory.mkdir(parents=True, exist_ok=True)
    id_re = re.compile(rf"^{re.escape(prefix)}-(\d{{{width}}})(?=[-.])")

    def _scan_max():
        return max((int(m.group(1)) for p in directory.glob(f"{prefix}-*.yaml")
                    if (m := id_re.match(p.name))), default=0)

    with _alloc_under_lock(directory, prefix.lower(), _scan_max,
                           lambda n: f"{prefix}-{n:0{width}d}",
                           fallback_lock=directory / f".{prefix.lower()}-alloc.lock",
                           explicit=explicit, band=band) as tok:
        yield tok


# T-10888 — the rule↔test ledger's ROW LABELS, allocated on the SAME core as task/spec ids.
# A row opens `**<LABEL>.**` under a `## <Letter>. <title>` heading, and labels are unique WITHIN a
# section (SPEC-0165 §8). Nothing used to allocate them: each author scanned the section on the main
# they branched from and took max+1, so two in-flight cards always picked the SAME number and the
# collision surfaced only at merge (T-10869 hit it twice in one land window). The keyed merge
# resolver (T-10845) cannot fix this class — a same-label pair is precisely its fail-closed case.
_LEDGER_ROW_LABEL_RE = re.compile(r"^\s*(?:[-*]\s+)?\*\*([A-Za-z][A-Za-z0-9-]*)\.\*\*")
_LEDGER_SECTION_RE = re.compile(r"^## ([A-Za-z])\. ")


def _ledger_section_max(text: str, section: str) -> int:
    """Highest row NUMBER in the ledger's `## <section>.` section, 0 if the section holds none.

    A label counts when it is `<section><digits>` with an optional alpha suffix — `H5` and `A11d`
    both count (as 5 and 11); off-shape spellings that merely start with the letter (`A-FE38`,
    `Jx1`) are SKIPPED rather than mis-parsed, so they neither inflate the floor nor crash it. They
    are hand-assigned names, not points on this counter."""
    num_re = re.compile(rf"^{re.escape(section)}(\d+)[A-Za-z]*$")
    in_section = False
    top = 0
    for line in text.splitlines():
        head = _LEDGER_SECTION_RE.match(line)
        if head:
            in_section = head.group(1) == section
            continue
        if not in_section:
            continue
        row = _LEDGER_ROW_LABEL_RE.match(line)
        if row and (m := num_re.match(row.group(1))):
            top = max(top, int(m.group(1)))
    return top


def _ledger_sections(text: str) -> list:
    """Every section letter the ledger actually defines, in document order."""
    out = []
    for line in text.splitlines():
        head = _LEDGER_SECTION_RE.match(line)
        if head and head.group(1) not in out:
            out.append(head.group(1))
    return out


@contextlib.contextmanager
def _ledger_label_alloc_lock(ledger_path: Path, section: str):
    """Yield the next `<section><N>` ledger row label, allocated under the shared flock core.

    `require_reservation=True`, unlike the id allocator: a ledger row is authored by hand AFTER the
    label is handed out, so there is no write inside the with-block to make the scan TOCTOU-safe —
    the durable reservation is the only thing carrying uniqueness across that gap. An allocated
    label that never becomes a row leaves a gap in the section's numbering, which is the accepted
    semantics of every caller of this core (unique + increasing, not gap-free)."""
    text = ledger_path.read_text(encoding="utf-8")
    with _alloc_under_lock(ledger_path.parent, f"ledger-{ledger_path.stem}-{section}".lower(),
                           lambda: _ledger_section_max(text, section),
                           lambda n: f"{section}{n}", require_reservation=True) as label:
        yield label


def cmd_spec_ledger_label(args: argparse.Namespace) -> None:
    """Allocate the next free row label in a rule↔test ledger section (T-10888)."""
    ledger = REPO_ROOT / args.ledger
    if not ledger.exists():
        _die(f"spec ledger-label: no such ledger: {args.ledger}")
    section = args.section.strip()
    known = _ledger_sections(ledger.read_text(encoding="utf-8"))
    if section not in known:
        _die(f"spec ledger-label: unknown section '{section}' in {args.ledger} — "
             f"sections are: {', '.join(known) or '(none)'}")
    with _ledger_label_alloc_lock(ledger, section) as label:
        print(label)


@contextlib.contextmanager
def _with_repo_lock(ref: Path):
    """Exclusive cross-session repo lock (T-0138 / D-0083 §3d) — serializes the SHORT critical
    sections that must not interleave between concurrent worktree sessions: the `land` ff-merge to
    main, and `worktree new`'s claimability-check + branch-create. SAME fcntl.flock idiom as
    `_id_alloc_lock` (no new mechanism) — one lock file in the git COMMON dir (shared by every
    linked worktree, never tree-tracked). Advisory + process-local — fine, since every writer is
    bin/yitc-v2. Single lock, always released on context exit, never nested → deadlock-free.

    `ref` is any path inside the repo; the common-dir is resolved from it. Outside a git repo
    (`_reservation_dir` → None, the single-checkout fallback) there is no cross-worktree contention,
    so the lock is a no-op pass-through."""
    resv = _reservation_dir(ref)
    if resv is None:
        yield
        return
    resv.mkdir(parents=True, exist_ok=True)
    fd = _open_flock_target(resv / "repo.lock")
    try:
        fcntl.flock(fd, fcntl.LOCK_EX)
        yield
    finally:
        os.close(fd)  # releases the flock


# Single home = bin/lib/textutil.py (T-9260). _slug is pure → re-export; _as_list fail-exits, so the
# host wrapper injects _die (read at call time → any monkeypatch on yitc._die stays honored).
_slug = textutil.slug


def _as_list(name: str, val) -> list:
    return textutil.as_list(name, val, _die)


# The substantive post-claim lifecycle stages in order (Filing skipped — by claim time the task is
# already filed/claimed). Analysis is listed so the one sequence also shows its FETCH contracts +
# finalize verb; the claim ITSELF is Analysis-entry (T-9741).
_SEQUENCE_STAGES = ("Analysis", "Plan", "Audit-pre", "Execution", "Tests", "Commit", "Audit-post", "Closure")


def _stage_sequence_skeleton(tid: str = "T-XXXX", corpus: "dict | None" = None) -> str:
    """The CANONICAL per-stage command sequence, surfaced ONCE at the claim moment (T-9741) so a fresh
    executor learns the whole ENTER → WORK → FINALIZE shape UP FRONT instead of discovering it via the
    >=3 cascading stage-correspondence / read-gate refusals (the gates are CORRECT — only their delivery
    was late; this is a delivery/discoverability fix, not a new gate). Report-not-block teaching text
    (CHARTER non-goal #7). DERIVED, never a second hand-list (P5): the DELIVERS column is each stage's
    read-gate contracts (`_stage_bundle_specs` — the SAME carrier `_require_reads` enforces) and the
    FINALIZE column is STAGE_WORK_VERBS (the inherent stage affordance). A hand-written field ALONE
    never satisfies a finalize verb (T-9472/X-0079).

    T-13510: ENTER itself delivers each contract in full AND writes the receipt the read-gate credits
    (T-11550), so the skeleton no longer prescribes a `graph query` per contract before working — that
    step re-read ~55-335 kB the session had just been handed. The ids are still listed per stage (what
    ENTER delivers); the fetch command is named ONCE, as the re-read after a `/compact`.

    T-13550: the rows ask about every stage, so the corpus is read ONCE here (or by the caller, who
    passes its own read as `corpus`) and handed to each stage's lookup — it was one read per stage."""
    rows = []
    if corpus is None:
        corpus = _stage_bundle_corpus(include_kernel=True)
    for st in _SEQUENCE_STAGES:
        specs = _stage_bundle_specs(st, include_kernel=True, corpus=corpus)   # exact per-stage read-gate contracts (P5 carrier)
        delivers = ", ".join(specs) if specs else "(no contract bound — work-verb only)"
        verbs = [v for v in STAGE_WORK_VERBS.get(st, []) if "worktree new" not in v]   # drop the claim self-ref row
        # T-11982: interpolate the id AT the `--task` token, not only when the row ENDS with it — a
        # work-verb row may now carry a flag + prose after `--task` (the Audit-pre/post preview step).
        # Byte-identical for a trailing `--task` (replace == append), so no existing row's render moves.
        finals = [(f"yitc-v2 {v.replace('--task', f'--task {tid}', 1)}" if "--task" in v
                   else f"yitc-v2 {v}") for v in verbs]
        finalize = " / ".join(finals) or "(no work-verb)"
        rows.append(f"    {st:<10} ENTER:    yitc-v2 stage {st} --task {tid}\n"
                    f"    {'':<10} DELIVERS: {delivers}\n"
                    f"    {'':<10} WORK:     do the {st} work (read the delivered contract(s), then act), then —\n"
                    f"    {'':<10} FINALIZE: {finalize}")
    return (
        f"→ Per-stage command sequence (T-9741) — EVERY substantive stage repeats the SAME 3 steps, IN "
        f"ORDER. This is the WHOLE path from claim to `land` for {tid}, surfaced ONCE so no per-stage "
        "refusal is needed to discover it:\n"
        "  1. ENTER     yitc-v2 stage <NAME> --task <tid>  (records current_stage, DELIVERS each of that "
        "stage's contracts in full and CREDITS the read-gate for them — no separate fetch is owed; a "
        "contract this context epoch already holds is named as a one-line pointer instead of repeated)\n"
        "  2. WORK      do the stage's work (analyze / plan / edit code / run tests ...)\n"
        "  3. FINALIZE  the stage's work-verb — a hand-written field ALONE does not satisfy it (T-9472)\n"
        "  RE-READ      yitc-v2 graph query <SPEC>         (only after a /compact evicted a contract, or "
        "to re-open one named by a pointer — never a step before working)\n"
        "  Stages in order (exact commands):\n"
        + "\n".join(rows) + "\n"
        f"  then integrate: yitc-v2 land --task {tid}")


def _analysis_procedure_reminder(tid=None) -> str:
    """The ordered Stage-1 (Analysis) procedure SURFACED at the claim moment (`worktree new --task` —
    the claim IS Analysis-entry, so it delivers the Analysis stage bundle; T-0279, axis migrated to
    stage-entry by T-0289). Report-not-block surfacing: the rule
    half is fixed teaching text (the ORDERED checklist), the pointer half is DERIVED from the binding
    map (the Analysis stage_to_specs view — single canonical carrier, P5). Each step REFERENCES its detail
    home (CHARTER §1 / T-0133 / SPEC-0005 / SPEC-0012) — it does NOT duplicate the discipline (DRY;
    those stay the homes). Report-not-block: surfaces the procedure, never gates (CHARTER non-goal #7).

    T-9741: ALSO appends the per-stage command-sequence skeleton (`_stage_sequence_skeleton`) — the SAME
    claim-moment delivery, extended so the whole ENTER→FETCH→WORK→FINALIZE path is surfaced ONCE (`tid`
    substituted when known, else the `T-XXXX` placeholder for the no-arg callers)."""
    corpus = _stage_bundle_corpus(include_kernel=True)   # T-13550: ONE corpus read for this echo — the Analysis pointer and the skeleton below
    analysis_specs = _stage_bundle_specs("Analysis", include_kernel=True, corpus=corpus)   # T-0865: DELIVERY surfacing → expose kernel Analysis specs on a -C consumer
    ptr = ((f"→ Analysis stage-entry delivers: {', '.join(analysis_specs)} "
            "(in full, by your worktree `session start` — no fetch owed; re-read one after a /compact "
            "with `yitc-v2 graph query <SPEC>`)") if analysis_specs
           else "→ Analysis stage-entry: no spec bound (the claim IS Analysis-entry)")
    return _consumer_render(   # T-13176: every command/path in the claim-time hint resolves under -C
        "→ Stage-1 (Analysis) procedure (Analysis stage-entry) — work these IN ORDER before any edit:\n"
        "  1. Prior-art grep (CHARTER §Principle 1 filter 1): does a similar mechanism / file / decision "
        "already exist? Extend it, don't create parallel.\n"
        "  2. Cite-the-proof (T-0133): when you assert a symbol / flag / analog / decision exists (or "
        "not), cite the grep/path that PROVES it — sweep `decisions/` too, not only code. «I think it "
        "exists» is not prior-art.\n"
        "  3. Establishes/changes a standing rule? → it is a candidate `proposed` spec (SPEC-0005); name "
        "it now, STAGE it in Plan.\n"
        "  4. Needs decomposition? ONE provable claim per accept-unit (SPEC-0012) — if this proves >1 "
        "claim, SPLIT (order via `requires:`); a deferral MUST be a tracked task, never prose.\n"
        "  5. Spec-coverage reverse-lookup (SPEC-0031): for EACH file/symbol you expect to touch, run "
        "`yitc-v2 graph query <file>` → read the governing active spec(s) → declare in the plan one line "
        "per direction: (1) governed → `spec update: yes <which>` OR `no, because <reason>`; (2) no "
        "governing spec → justified spec-less (SPEC-0005 admission test) OR name the candidate `proposed` "
        "spec (joins step 3).\n"
        "  6. Read the cited specs / decisions / prior tasks.\n"
        "  7. Scope unclear? File a clarification to a Review session — don't proceed on a guess.\n"
        + ptr
        + "\n" + _stage_sequence_skeleton(tid or "T-XXXX", corpus=corpus))   # T-9741: surface the whole per-stage sequence once


def _scenario_spec_view(spec_ids, index=None, *, stale_only=False):
    """ONE read-only scenario↔spec view (SPEC-0076 §6c, T-1050) shared by the Analysis impact-WARN
    and the staleness-WARN — in TWO selection modes, because the two WARNs ask different questions
    and keying both on the task's cites was the T-11420 defect (X-1077):

      - `stale_only=False` (default, the IMPACT lens) — given the SPEC ids a task touches, return the
        scenarios that `cites` any of them. Unchanged: this is the right key for "you are about to
        edit a spec these user-paths pass through".
      - `stale_only=True` (the STALENESS lens) — `spec_ids` is IGNORED; walk EVERY scenario's own
        SPEC-shaped cites and keep only those whose cited spec is NOT `active`. This is the property
        SPEC-0076 §7(2) actually calls staleness ("cites a superseded/retired spec") and §Verification
        asks the view to surface ("a scenario whose cited spec CHANGED STATUS") — a fact about the
        SCENARIO, independent of what any task cites.

    Status resolution in the staleness mode MIRRORS `graph._scenario_cites_all_active` (SPEC-0076 §3),
    the predicate already behind the node's `cites_all_active`, rather than authoring a second notion
    of "stale" (CHARTER §P1 filter 2): spec cites are identified by id-SHAPE; the OWN corpus wins on
    PRESENCE and `_kernel_spec_statuses()` is the cross-realm fallback (SPEC-0092 §Internal — a
    consumer spec that exists but is `proposed` must not fall through to a kernel spec of the same id);
    an id absent from BOTH corpora fails closed to non-active and IS reported. Fail-closed here costs a
    reader one line to check, where fail-open is the silence this task exists to remove. (`covers` is scenario→CODE, a
    different address space; a code-anchor impact view is its own future concern per SPEC-0076 §4
    scope-guard, so the spec-impact view rides `cites`, the scenario→spec link.) Each row:
    {scenario, actor, spec, spec_status}. Read-only + fail-soft: returns [] (never raises) if the
    graph index is unavailable — a WARN view must NEVER break a lifecycle stage (rule 6c: surface,
    never gate). `index` is overridable for unit tests; default loads graph/index.json (engine-index
    fallback on a -C consumer, mirroring cmd_graph_query)."""
    wanted = {s for s in (spec_ids or []) if isinstance(s, str) and _SPEC_ID_RE.fullmatch(s)}
    if not wanted and not stale_only:
        return []
    if index is None:
        try:
            if GRAPH_PATH.exists():
                index = _read_yaml(GRAPH_PATH) or {}
            elif _is_consumer_build() and _engine_index():
                index = _engine_index()
            else:
                return []
        except Exception:
            return []
    specs = index.get("specs") or {}
    scenarios = index.get("scenarios") or {}
    kernel = {}
    if stale_only:
        try:
            kernel = _kernel_spec_statuses() or {}
        except Exception:
            kernel = {}          # fail-soft, as everywhere in this view: a WARN never breaks a stage

    def _status_of(sp):
        if sp in specs:                                   # own-wins on PRESENCE (SPEC-0092 §Internal)
            return (specs.get(sp) or {}).get("status", "") or ""
        return kernel.get(sp, "") or ""                   # cross-realm fallback (T-10933)

    rows = []
    for sid in sorted(scenarios):
        node = scenarios.get(sid) or {}
        cites = [c for c in (node.get("cites") or []) if isinstance(c, str) and _SPEC_ID_RE.fullmatch(c)]
        selected = sorted(set(cites)) if stale_only else sorted({c for c in cites if c in wanted})
        for sp in selected:
            status = _status_of(sp)
            if stale_only and status == "active":
                continue
            rows.append({"scenario": sid, "actor": node.get("actor", ""),
                         "spec": sp, "spec_status": status})
    return rows


def _task_cited_spec_ids(task) -> list:
    """The SPEC ids a task touches = its `cites:` SPEC-XXXX entries (the spec the task changes).
    The scenario impact/staleness views key off this (SPEC-0076 §6c, T-1050)."""
    return [c for c in _as_list("cites", task.get("cites"))
            if isinstance(c, str) and _SPEC_ID_RE.fullmatch(c)]


def _print_scenario_impact_warn(task) -> None:
    """Analysis impact-WARN (SPEC-0076 §6c / T-1050): name the scenarios that pass through (cite)
    the specs this task touches, so the author re-verifies those user-paths BEFORE editing.
    Read-only, never blocks, never nonzero (rule 6c)."""
    rows = _scenario_spec_view(_task_cited_spec_ids(task))
    if not rows:
        return
    scns = sorted({r["scenario"] for r in rows})
    print(f"⚠ scenario impact (read-only, never blocks — SPEC-0076 §6c): {len(scns)} scenario(s) "
          f"cite a spec this task touches — re-verify the user-path(s):")
    for r in rows:
        print(f"  - {r['scenario']} (actor: {r['actor'] or '?'}) cites {r['spec']}")


def _impact_warn_with_surface(task) -> None:
    """Analysis entry: the spec→scenario impact-WARN above, then (T-12789) the code→scenario
    uncovered-surface line over the SAME forecast audit-pre reads (`_forecast_touched_files`)."""
    _print_scenario_impact_warn(task)
    try:
        _print_uncovered_surface_warn(_forecast_touched_files(task), label="Analysis, forecast")
    except Exception:
        pass


def _print_uncovered_surface_warn(paths, label="Analysis, forecast") -> None:
    """T-12789 (SPEC-0076 §6c code→scenario direction / SPEC-0093 rule 29): name each DECLARED user
    surface (`ui.surfaces:`) this task's paths touch that no scenario `covers`. Report-only, never
    blocks, never nonzero; silent without a declaration. The derivation's one home is
    `debt_mod.uncovered_surface_files` (the debt row reads the same). Called at Analysis ONLY: the
    Closure call was retired (T-13496 — it printed in 33+ real closes and no scenario followed)."""
    try:
        prefixes = debt_mod.user_surface_prefixes(profile_mod._load_ops(REPO_ROOT))
        if not prefixes:
            return
        index = _read_yaml(GRAPH_PATH) if GRAPH_PATH.exists() else {}
        hits = debt_mod.uncovered_surface_files(paths, prefixes, index or {})
    except Exception:
        return
    for pre, files in sorted(hits.items()):
        shown = ", ".join(files[:5]) + (" …" if len(files) > 5 else "")
        print(f"⚠ uncovered user surface ({label}, read-only, never blocks — SPEC-0076 §6c): diff "
              f"touches {pre} no scenario covers ({shown}) → author one (`bin/yitc-v2 scenario new`) "
              f"or state why not")


def _cross_territory_paths(*a, **kw):
    """T-12708 (C11b) host residue — the body now lives in `bin/lib/cross.py#_cross_territory_paths`. NOT
    `functools.wraps`-ed: `cross` is a deferred `_LazyLib` (T-11540) and a decorator would touch
    `cross.<sym>` at cli import time, loading lib.cross eagerly — the residue resolves it at CALL time."""
    _cross_inject(kw, "_cross_territory_paths")
    return cross._cross_territory_paths(*a, **kw)


def _print_cross_territory_routing_hint(paths) -> None:
    """Report-only cross-territory routing hint (SPEC-0032 / SPEC-0084, T-1272). When a task's forecast
    paths (`expected_touch`) resolve OUTSIDE own territory, the work looks like ANOTHER project's — so
    surface the territory-safe route ONCE: do NOT `task file` it into THIS queue; file a coordination item
    on the kernel-owned SHARED coordination log via `yitc-v2 cross request --to <project>` (the live AUTHOR
    verb). SPEC-0084 is the governing routing contract (this is a navigational POINTER to it — SPEC-0005
    rule 8 — not a restatement; the old per-repo CROSS-TASKS.md / SPEC-0079 surface was retired at the
    T-9293 cutover). Report-not-block, never gates (CHARTER non-goal #7) — the sibling of `_print_scenario_impact_warn`."""
    foreign = _cross_territory_paths(paths)
    if not foreign:
        return
    shown = ", ".join(foreign[:5]) + (" …" if len(foreign) > 5 else "")
    print(f"⚠ cross-territory (read-only, never blocks — SPEC-0084 / AGENTS §Filing rule): {len(foreign)} "
          f"forecast path(s) resolve OUTSIDE this repo's territory ({shown}) — this looks like another "
          "project's work. Do NOT `task file` it into THIS queue; route it via "
          f"`yitc-v2 cross request --to <project>` (the shared coordination log). See "
          f"`{graph.spec_query_hint('SPEC-0084', is_consumer=_is_consumer_build(), cli='yitc-v2')}`.")


def _live_spike_worktree_branches(repo) -> list:
    """Branches matching `work/spike-*` among this project's LIVE worktrees, via `git worktree list
    --porcelain` (T-10696 / X-0548). INTERIM trigger — worktree PRESENCE is the whole signal, NO new
    FSM/store (mirrors `_main_worktree`'s porcelain parse; CHARTER §Principle 1 view-over-new-entity).
    Fail-soft: [] on any git failure — a surfacing helper must never break a stage.

    T-10781: the naming convention is read from the ONE carrier `worktree_mod.SPIKE_BRANCH_PREFIX`, which
    the land refusal (`cmd_land`, SPEC-0172 rule 5) reads too — so this report-only HINT and that GATE can
    never drift to different notions of what a spike branch is."""
    r = _run_git_cap(["worktree", "list", "--porcelain"], repo)
    if r.returncode != 0:
        return []
    out = []
    for line in r.stdout.splitlines():
        if line.startswith("branch refs/heads/"):
            br = line[len("branch refs/heads/"):].strip()
            if br.startswith(worktree_mod.SPIKE_BRANCH_PREFIX):
                out.append(br)
    return out


