def _promote_owner_due_suffix(owner: str, due: str, *, sep: str, label_sep: str = ": ",
                              open_: str = " ", close: str = "", solo: str = "") -> str:
    """Render the owner/due suffix for `error promote` output, ONE-SIDED-SAFE (T-0497): each of
    owner/due is emitted ONLY when supplied, so `--owner X` alone renders `owner X` with no blank
    `due` (and vice-versa). Empty both → the `solo` fallback. Format is parameterized so the two call
    sites keep their existing styles (description `owner: X; due: Y.` vs outcome ` (owner X, due Y)`)."""
    parts = []
    if owner:
        parts.append(f"owner{label_sep}{owner}")
    if due:
        parts.append(f"due{label_sep}{due}")
    if not parts:
        return solo
    return f"{open_}{sep.join(parts)}{close}"


def _file_fix_task(error_id: str, error_title: str, fingerprint: str, owner: str = "", due: str = "",
                   expected_touch: list | None = None) -> str:
    """File a fix task spawned from a promoted error. owner+due are OPTIONAL for solo (T-0460, D-0086
    §PROMOTE — QUEUE has no owner/due fields, so they are recorded in the E-file resolution block only
    WHEN supplied + echoed in the description; absent for a solo ownerless promote). Reuses the shared
    allocator + atomic write + task_filed event.

    `expected_touch` (T-10251) is the touch-surface forecast the caller derived from the case file
    (`error.derive_expected_touch`). Written ONLY when non-empty — the T-0404 additive-optional shape
    (absent key = no forecast; every reader already defaults it absent). Default None keeps every other
    caller byte-identical."""
    import yaml
    title = f"Fix {error_id}: {error_title}"
    with _id_alloc_lock(TASKS_DIR, "T") as tid:
        path = TASKS_DIR / f"{tid}-{_slug(title)}.yaml"
        if path.exists():
            _die(f"collision (post-lock): {path.name} already exists")
        # FINGERPRINT-CARRY (T-0459, D-0086 §9 LINK RULE): cite the E-id AND the source fingerprint,
        # so the §9 LINK RULE (cites: = the single derivation source) routes-by-fingerprint to THIS
        # fix-task — i.e. `_fingerprint_cites_index[fingerprint]` now resolves to this task id. Without
        # the fp in cites:, only the E-id linked back and a recurrence under the fingerprint could not
        # find the promoted fix (the dedup carrier was incomplete). Order-stable, deduped, fp non-empty only.
        cites = [error_id]
        if (fingerprint or "").strip() and fingerprint.strip() not in cites:
            cites.append(fingerprint.strip())
        task = {
            "id": tid, "title": title, "class": "fix", "priority": "medium",
            "status": "ready", "created_at": _utc_now_iso(), "created_by": "ai-agent",
            "scope": [f"Fix the deviation captured in {error_id}: {error_title}"],
            "acceptance": [f"AC1: {error_id} resolved (probe: fingerprint "
                           f"{fingerprint or 'n/a'} no longer recurs OR a regression test covers it)"],
            "cites": cites, "requires": [],
            "description": (f"Spawned from {error_id} via `error promote`."
                            + _promote_owner_due_suffix(owner, due, sep="; ", label_sep=": ",
                                                        open_=" ", close=".",
                                                        solo=" solo: no owner/due.")),
            "analysis": None,            # T-0600 (R6) — Analysis decision-record carrier (see cmd_task_file).
            "implementation_plan": None,
        }
        if expected_touch:
            task["expected_touch"] = list(expected_touch)
        content = _dump_state_yaml(task)
        write_text_atomic(path, content)
        _append_event("task_filed", tid, {
            "path": str(path.relative_to(REPO_ROOT)), "class": "fix",
            "priority": "medium", "status": "ready", "spawned_from": error_id})
    return tid


