def _declared_resolves_cross(rec) -> list:
    """The `resolves_cross` ids DECLARED by one record (a task YAML mapping, or a plan's frontmatter
    mapping) — the ONE coercion both carriers of `_cross_linked_ids` share, so the task leg and the
    plan leg cannot drift into disagreeing about what a declaration looks like (CHARTER §P5).

    Tolerates the single-string spelling (`resolves_cross: X-0001`) the task filing path also accepts,
    and drops empties. PURE: no I/O, no emit; a non-mapping yields []."""
    if not isinstance(rec, dict):
        return []
    rc = rec.get("resolves_cross") or []
    if isinstance(rc, str):
        rc = [rc]
    if not isinstance(rc, (list, tuple)):
        return []
    return [x for x in rc if x]


def _cross_linked_ids(*a, **kw):
    """T-12708 (C11b) host residue — the body now lives in `bin/lib/cross.py#_cross_linked_ids`. NOT
    `functools.wraps`-ed: `cross` is a deferred `_LazyLib` (T-11540) and a decorator would touch
    `cross.<sym>` at cli import time, loading lib.cross eagerly — the residue resolves it at CALL time."""
    _cross_inject(kw, "_cross_linked_ids")
    if _START_SKIP_SEEN is None or "skipped" in kw:
        return cross._cross_linked_ids(*a, **kw)
    _skips: list = []
    try:
        return cross._cross_linked_ids(*a, skipped=_skips, **kw)
    finally:
        _report_start_skips(_skips)


#: T-13265 — the per-`session start` dedupe set of artifact paths already named by a
#: `session start: skipped malformed …` line. None OUTSIDE a start (the residues then record nothing
#: and print nothing); a set for the duration of `cmd_session_start`, so a card that the cross fold AND
#: both open-work walkers each drop is named ONCE. Report-only echo — it journals nothing.
_START_SKIP_SEEN: "set | None" = None


def _report_start_skips(skips) -> None:
    """Print each recorded malformed-artifact drop once per path per start (T-13265)."""
    if not skips or _START_SKIP_SEEN is None:
        return
    for rec in skips:
        p = Path(rec["path"])
        try:
            rel = p.resolve().relative_to(Path(REPO_ROOT).resolve()).as_posix()
        except (ValueError, OSError):
            rel = str(p)
        if rel in _START_SKIP_SEEN:
            continue
        _START_SKIP_SEEN.add(rel)
        reason = " ".join(str(rec.get("reason") or "").split())
        print(session.mark(f"session start: skipped malformed {rec.get('kind')} {rel}: {reason}",
                           session.REPORT_ONLY))


def _start_skip_scope(active: bool) -> None:
    global _START_SKIP_SEEN, _START_OWN_REF
    _START_SKIP_SEEN = set() if active else None
    _START_OWN_REF = None      # T-13526: the start's own-ref note lives exactly as long as the scope


