ASPECTS = {
    "doc-conformance": ["read all MUSTs?", "supplied at the right time?", "steps done in order?",
                        "contradictions?", "all required data loaded?"],
    "doc-health": ["superfluous / duplicated / too-complex?", "repeated-but-useless?",
                   "a missing MUST?", "simplify / generalize / delete candidates?"],
    "cli-vs-manual": ["what was done by hand & why?", "which repeatable hand-actions -> CLI verbs?",
                      "which existing CLI to change / remove?"],
    "resource": ["token/time waste?", "redundant re-reads?", "duplicate tool calls?",
                 "context-window utilization?", "runaway loops?"],
    "ai-failure-class": ["which of the 20 CHARTER classes were relevant / observed?",
                         "gap (a) import/path existence + intended-target match",
                         "gap (b) suppressed-exception / permissive-default / secret scan",
                         "gap (c) reasoning<->action mismatch + post-/compact re-read",
                         "gap (d) resource/token waste signals"],
    "meta": ["TRIGGER-ONLY (governance change / repeated divergence / owner request): "
             "is the audit procedure itself correct?"],
}


