def _git_resolve_sha(ref: str) -> str | None:
    """Verify ref exists в repo; return resolved SHA либо None."""
    import subprocess
    try:
        result = subprocess.run(
            ["git", "-C", str(REPO_ROOT), "rev-parse", "--verify", ref],
            capture_output=True, text=True, check=False,
        )
        if result.returncode != 0:
            return None
        return result.stdout.strip() or None
    except (FileNotFoundError, OSError):
        return None


def _work_batch_next_hint(artifact_rel: "str | None" = None) -> "str | None":
    """T-10117 (SPEC-0060 / D-0033) — the work/<slug> batch commit-then-land next-hint.

    A verb that writes a DIRTY artifact into a `work/<slug>` batch (task file, audit post/adhoc)
    leaves the tree uncommitted, and `land` then ABORTs on uncommitted-non-journal-changes — the
    author twice (2026-07-04) forgot the `work commit` → `land` step. This derives the ONE cue line
    naming that path. OUTPUT-ONLY: pure derivation, no event / flag / store, no side-effect.

    Gating REUSES the existing `_require_work_batch_worktree` derivation: read the current branch via
    `git symbolic-ref --short HEAD` and return the hint ONLY when it starts with `work/`. Returns None
    (no hint) for non-git / detached / unborn HEAD, `main`, or a `task/T-XXXX` worktree — the normal
    9-stage flow whose artifacts land via the closure FOLD, not `work commit`, so the cue never
    misfires there. `artifact_rel` (repo-relative) fills the `--from` slot; a None/blank falls back to
    the generic `<artifact>` placeholder."""
    sref = _run_git_cap(["symbolic-ref", "--quiet", "--short", "HEAD"], REPO_ROOT)
    branch = (sref.stdout or "").strip()
    if sref.returncode != 0 or not branch.startswith("work/"):
        return None
    frm = (artifact_rel or "").strip() or "<artifact>"
    return (f"next: `bin/yitc-v2 work commit --from {frm} -m ...`, "
            f"then `bin/yitc-v2 land --branch {branch}`")


def _task_yaml_in(tasks_dir: Path, tid: str) -> Path | None:
    """Locate <tasks_dir>/T-NNNN-*.yaml by ID — single match expected per D-0008 ID allocation. The ONE
    matching rule; both the session-corpus finder and the kernel-corpus finder below delegate to it."""
    matches = list(tasks_dir.glob(f"{tid}-*.yaml"))
    if len(matches) == 1:
        return matches[0]
    return None  # 0 либо >1 — caller treats as missing


def _find_task_yaml(tid: str) -> Path | None:
    """Locate tasks/T-NNNN-*.yaml by ID in THIS session's corpus (REPO_ROOT — a consumer's own under `-C`)."""
    return _task_yaml_in(TASKS_DIR, tid)


def _find_kernel_task_yaml(tid: str) -> Path | None:
    """Locate the task YAML in the KERNEL corpus (ENGINE_ROOT/tasks — never rebound by `-C`). The second
    realm of the SPEC-0094 §4 live_probe keying: a consumer deploy governed by a KERNEL task card has no
    consumer-side card to key its per-change probe on (X-0343). Read-only — a consumer→engine READ is legal
    (SPEC-0078 guards WRITES). In an engine-self session this is the same corpus as `_find_task_yaml`."""
    return _task_yaml_in(_engine_live_root() / "tasks", tid)   # T-13192: live cards, never a served snapshot


def _decision_file_claims_id(path: Path, did: str) -> bool:
    """A CANONICAL decision file declares `id: <did>` at top level. Audit-verdict siblings
    (`D-NNNN-audit-<stage>.yaml` AND non-canonically-named records like `D-NNNN-approach-audit.yaml`)
    carry `task:`/`stage:`/`verdict:` and NO top-level `id:` — so they are NOT claimants of the
    decision id (T-0323). Content-based, so it is robust to the audit filename VARIANT (`-audit-ad-hoc`,
    `-approach-audit`) AND to a decision SLUG that itself contains '-audit-' (e.g. D-0055). An
    unreadable/malformed candidate is treated as not-a-claim (tolerant, never raises)."""
    import yaml
    try:
        data = state.load_str(path.read_text(encoding="utf-8"))
    except (OSError, yaml.YAMLError):
        return False
    return isinstance(data, dict) and data.get("id") == did


def _find_decision_yaml(did: str) -> Path | None:
    """Locate decisions/D-NNNN-<slug>.yaml by ID (per D-0055 decision-audit target).

    EXCLUDES audit-record files (the `D-NNNN-audit-<stage>.yaml` trail AND non-canonically-named
    audit records) by CONTENT, not filename: a real claimant declares top-level `id: <did>` (T-0323).
    The prior filename regex only excluded `-audit-(pre|post)` and so false-resolved a decision with an
    `-audit-ad-hoc` / `-approach-audit` sibling to None (>1 match) — the structural pre-pass false-WARN.
    Single match expected per D-0008 ID allocation."""
    matches = [p for p in DECISIONS_DIR.glob(f"{did}-*.yaml") if _decision_file_claims_id(p, did)]
    if len(matches) == 1:
        return matches[0]
    return None  # 0 либо >1 — caller treats as missing




def _recorded_commit_landed(tid: str, *, commit: "str | None" = None) -> dict | None:
    """Artifacts-as-gate (D-0082): the DATA payload of the task's MOST RECENT `task commit`, read from
    the durable `commit_landed` event that `task commit` emits (the record — no separate task-YAML write
    that would dirty the tree post-commit and break the task-commit→land invariant). None if none yet.
    T-10737 widened the read from the bare sha to the whole payload because the Commit-stage cue re-read
    also needs the `absorption` marker the SAME event already carries (a view over existing data — no
    new store/field, CHARTER §P1 F2); `_recorded_commit_sha` below is the unchanged sha-only wrapper.
    KIND-BLIND on purpose — the last `commit_landed` wins whatever its `kind`: the RAW D-0082 value the
    `--repin-ship` / `--preshipped-deliverable` legs keep reading (T-12362). The custody-aware sibling
    is `_custody_commit_landed` below (T-12727). `commit=` (T-12727) narrows the SAME scan to the rows
    naming that commit (the chain's own `data.commit` string, compared exactly) — last such row wins —
    so a caller holding a custody sha can read its payload through this one reader rather than a
    second fold of the journal; the default path is byte-identical.

    T-13330 — a DECLARED, TASK-SCOPED read (SPEC-0190 rule 4): commit_landed rows of this task, from
    the task horizon a ReadScope registered for it (`journal.task_floor` — None outside one, i.e. the
    whole history in one walk, exactly as before)."""
    if not EVENTS_PATH.exists():
        return None
    rec = None
    for e in journal_mod.iter_rows(EVENTS_PATH, types=("commit_landed",),
                                   since=journal_mod.task_floor(EVENTS_PATH, tid),
                                   pred=lambda e: e.get("task_id") == tid):
        d = e.get("data") or {}
        if d.get("commit") and (commit is None or str(d.get("commit")) == commit):
            rec = d   # keep scanning — last commit_landed wins (task commit is callable xN)
    return rec


def _recorded_commit_sha(tid: str) -> str | None:
    """The SHA of the task's most recent `task commit` (D-0082) — the sha-only view over
    `_recorded_commit_landed` above. Signature + semantics unchanged (T-10737 refactor)."""
    rec = _recorded_commit_landed(tid)
    return rec.get("commit") if rec else None


# ── T-10567 (X-0422) — the SHIP-vs-BOOKKEEPING custody view over the EXISTING journal ─────────────
# The `commit_landed` discriminator already on disk: the SHIP commit (`cmd_task_commit`) emits NO
# `kind`; the terminal/halt self-commits emit one — park (T-9622) / pause (T-9320) / wont-do (T-0614).
# So "which commit_landed shifted custody off the ship" is DERIVABLE, needing no new store/field/event
# (CHARTER §P1 F2 — a view over existing data, not a new entity).
_BOOKKEEPING_COMMIT_KINDS = frozenset({"park", "pause", "wont-do"})
# NARROW BY CONSTRUCTION — exactly the three self-commit kinds T-10567's card names. The close-tail
# kinds (`closure` / `closes_fp_link` / `pv_late_link`) are emitted by `task close` AFTER the audit-post
# check has already passed, so they can never wedge a closure and are deliberately NOT admitted; an
# unknown/other kind is likewise not admitted (fail-closed — an unrecognized kind must never widen the
# carve-out). Adding a kind here EXTENDS the re-pin's reach and needs its own card + audit.


def _task_commit_landed_chain(tid: str) -> "list[tuple[str, str | None]]":
    """T-10567 — the ORDERED [(sha, kind|None)] of every `commit_landed` for THIS task_id, in journal
    order. `kind is None` marks a SHIP commit (`cmd_task_commit` emits no `kind`); a string marks a
    bookkeeping self-commit. Read-only, tolerant of malformed lines (the `_recorded_commit_sha` shape).
    The ORDER is load-bearing: custody questions are about WHICH record displaced which (an unordered
    set let an OLDER ship of a multi-ship mode-a task be re-pinned to — audit-pre p1 HIGH finding)."""
    chain: "list[tuple[str, str | None]]" = []
    if not EVENTS_PATH.exists():
        return chain
    # T-13330 — declared, task-scoped (see `_recorded_commit_landed` above).
    for e in journal_mod.iter_rows(EVENTS_PATH, types=("commit_landed",),
                                   since=journal_mod.task_floor(EVENTS_PATH, tid),
                                   pred=lambda e: e.get("task_id") == tid):
        data = e.get("data") or {}
        c = data.get("commit")
        if not c:
            continue
        k = data.get("kind")
        chain.append((str(c), str(k) if k else None))
    return chain


def _recorded_commit_kind(tid: str) -> "str | None":
    """T-10567 — the `data.kind` of the task's MOST RECENT `commit_landed` (the D-0082 recorded commit).
    `None` = a SHIP commit (`cmd_task_commit` emits no kind) or nothing recorded; a string names the
    bookkeeping self-commit that currently HOLDS custody (park / pause / wont-do / a close-tail kind).
    The `_recorded_commit_sha` companion — same last-wins semantics, the kind rather than the sha."""
    chain = _task_commit_landed_chain(tid)
    return chain[-1][1] if chain else None


def _custody_commit_landed(tid: str) -> dict | None:
    """T-12727 — the `commit_landed` payload of the task's CUSTODY commit: `_recorded_commit_landed`
    read through the SAME ship-vs-bookkeeping custody view the audit-post subject resolver takes
    (`audit.audit_custody_commit`, T-10567 / T-12362 — the resolver `audit post`'s ordinary leg, `task
    close` (T-12564) and the folded-hazard read (T-12719) all wire identically), so a park / pause /
    wont-do self-commit PROVEN record-only on an UNLANDED ship is transparent here exactly as it is
    there. THE ONE DEFECT this closes (T-12708, 2026-09-18, deviation events.jsonl#ts=2026-09-18T05:57:37Z):
    the card-repair admission's conjunct (a) read the KIND-BLIND last row — a `task pause
    --reason audit-ceiling` self-commit written after the `--fix-red --card-repair` commit — and refused
    the very subject the resolver had just settled on, so the two doors on one route disagreed (the
    X-1251 class) and `audit post --on-decisions` had no admissible subject.

    ONE PHYSICAL READ, THE NAMED MEMO (SPEC-0190 rule 10; audit-pre pass-1 of T-12727 measured the
    three-scan shape). The three questions this view asks — the raw last row, the ordered chain the
    resolver walks, the payload of the row it settles on — are all reads of the SAME journal by the
    EXISTING readers (`_recorded_commit_landed` ×2, `_task_commit_landed_chain`), so they are asked
    inside one `journal_mod.rows_memo([EVENTS_PATH])` scope: the first `segment_lines` fold serves
    the rest from the request-scoped memo. That is the rule-10 remedy by name, not a cache: no new
    journal reader enters the tree (the SPEC-0190 reader census is untouched — a fresh fold function
    would have re-opened it), and inside an outer scope that already holds the journal (`audit
    decide`'s) the inner `with` yields the outer memo and installs nothing (T-12208). The resolver's
    git predicates (`_bookkeeping_commit_authored_paths` per skipped kinded row, one
    `merge-base --is-ancestor`) are its own and unchanged.

    FAIL-CLOSED TO THE RAW ROW: nothing recorded → None; the resolver narrows nothing (its own
    contract — an authored last row, a kinded row that sweeps authored content, a LANDED ship, an
    unanswerable predicate) → the raw last row, byte-identical to `_recorded_commit_landed`; a custody
    sha with no row naming it (impossible by construction — it came from this chain) → the raw row.
    So every shape the raw reader refused today is refused identically; ONLY the proven-transparent
    displacement reads the row the resolver reads."""
    with journal_mod.rows_memo([EVENTS_PATH]):
        raw = _recorded_commit_landed(tid)
        if not raw:
            return None
        recorded = str(raw.get("commit") or "")
        custody = audit.audit_custody_commit(
            _task_commit_landed_chain(tid), recorded, bookkeeping_kinds=_BOOKKEEPING_COMMIT_KINDS,
            authored_paths=lambda sha: _bookkeeping_commit_authored_paths(sha, tid),
            ship_landed=lambda sha: audit._git_ship_landed(sha, repo_root=REPO_ROOT))
        if not custody or str(custody) == recorded:
            return raw
        return _recorded_commit_landed(tid, commit=str(custody)) or raw


def _custody_commit_sha(tid: str) -> "str | None":
    """T-12727 — the sha of the task's CUSTODY commit: the `commit` projection of `_custody_commit_landed`
    (the `_recorded_commit_landed` / `_recorded_commit_sha` pair idiom, T-10737). What the folded-hazard
    read (`_folded_audit_post_hazard`) wires as `_audited_custody_sha` — one wiring of the resolver,
    shared with the card-repair admission, in place of that wrapper's former inner copy."""
    rec = _custody_commit_landed(tid)
    return rec.get("commit") if rec else None


def _displaced_ship_custody(tid: str, *, demote_record_only: bool = False
                            ) -> "tuple[str | None, list[tuple[str, str | None]]]":
    """T-10567 — split the `commit_landed` chain at the LAST ship (absent-kind) record: returns
    `(displaced_ship_sha, [the records AFTER it])`. The displaced ship is the ONE admissible re-pin
    target — a task's custody may be re-pinned only to the ship its own bookkeeping displaced, never
    to a ship of the operator's choosing (that choice IS the custody game). `(None, ...)` when the task
    never shipped.

    `demote_record_only` (T-11512, OPT-IN, default OFF) — ask the DIFF question where the default asks
    the KIND question. A plain `task commit` emits a `commit_landed` with NO `kind`, so the default
    split reads that record as a SHIP even when its own diff carries nothing but lifecycle
    bookkeeping. That is the T-11503 shape: the displacing record becomes the derived target,
    `trailing` comes back EMPTY, and `_ship_custody_repin_check` leg (a) then refuses before the kind
    test is ever reached — a displaced card with no governed exit at all. Under this flag a
    kind-ABSENT record is DEMOTED from ship to displacing-record when its own diff is PROVABLY
    record-only (`_bookkeeping_commit_authored_paths(...) == []`), walking back to the real ship.

    THREE CONSTRUCTIONS keep it as fenced as the flag it serves (the T-11509 hard fence):
      · POSITIVE PROOF ONLY — an unprovable diff (`None`) STOPS the walk, so a diff git cannot compute
        is read as a ship (the stricter side), never demoted;
      · it never reaches a KINDED record — the closed `_BOOKKEEPING_COMMIT_KINDS` question is
        unchanged for anything carrying a kind, admitted or not;
      · the walk EXHAUSTING is not licence to pick anything — see the T-11528 branch below, which is
        the ONLY thing that may answer "no product ship" there.

    T-11528 (X-1074, <project> T-0422) — WHAT THE EXHAUSTED WALK ANSWERS. T-11512 made the walk abort
    WHOLESALE on exhaustion, handing back the DEFAULT split, to keep the T-11403 mode-B shapes
    byte-unchanged. On the reported chain that abort IS the defect: every kind-absent record is
    record-only (4 of them, then two `kind=pause` rows), so the walk exhausts and the DEFAULT split
    hands back a record-only commit AS THE PRODUCT SHIP — `_ship_custody_repin_check` then reads a
    displaced ship that exists, selects MODE A, and leg (b) refuses every sha but that record. The
    card's real ship landed pre-card in a `work/<slug>` batch and could never be named.
    So the exhausted walk now asks the question the chain can actually answer, using the SAME
    `_chain_is_record_only` predicate the mode selector already applies (P1 F1 — one definition of
    "this chain carries no authored content", not a second one): when NO kind-absent record carries
    authored content AND the chain as a WHOLE is record-only, this card records NO PRODUCT SHIP —
    return `(None, chain)`, exactly as a chain with no kind-absent record at all already returns.
    `displaced_full` then falsifies, MODE B is selected, and the pre-card ship is admissible on its
    own governed-landing evidence.

    THIS NARROWS WHAT MAY BE CALLED A SHIP; IT REMOVES NO REFUSAL. The anti-custody-game fence
    ("never re-pin custody off a genuine ship") is UNTOUCHED — three bounds, all by construction:
      · it fires ONLY on a wholly record-only chain. ANY authored content anywhere on it — on a
        kind-absent OR a kinded record — leaves `_chain_is_record_only` False and this branch inert,
        so every mode-A shape is byte-identical, T-10567's two pinned fences (a re-emitted later ship;
        an unadmitted `closure` kind holding custody) included;
      · `_chain_is_record_only` is FAIL-CLOSED on an unprovable diff (answers False), so a diff git
        cannot compute keeps today's stricter behaviour — the same direction as the None-stops-the-walk
        arm above;
      · a chain carrying no authored record has no genuine ship to be re-pinned OFF, which is the very
        property the fence protects. What MODE B then demands of the named sha is its own set of
        fences: governed-landing evidence, ancestor-of-`main`, and leg (c) scanning the FULL chain.
    The T-11403 mode-B shapes stay byte-unchanged in VERDICT: they already select MODE B, and there
    `trailing` is unread (`scan_records = trailing if mode_a else chain`) while `displaced_full` is
    read only by the selector and the MODE-A messages.
    Default OFF, so every other caller (the pinned unit probes) is byte-identical;
    `_require_preshipped_deliverable` opts IN since T-13209 (it must name the authored ship). Never raises."""
    chain = _task_commit_landed_chain(tid)
    last_ship_idx = None
    for i, (_sha, kind) in enumerate(chain):
        if kind is None:
            last_ship_idx = i
    if last_ship_idx is None:
        return (None, chain)
    if demote_record_only:
        i = last_ship_idx
        while i is not None and i >= 0:
            sha, kind = chain[i]
            if kind is not None:                       # a kinded record is never a ship candidate
                i -= 1
                continue
            # T-11732 — the chain TIP decides content survival: a path this record added and a
            # LATER record on the same chain removed puts nothing into the tree an audit runs
            # against, so it cannot be what makes this record the product ship.
            extra = _bookkeeping_commit_authored_paths(sha, tid, ships_into=chain[-1][0])
            if extra is None:                          # unprovable → stop, keep the default split
                break
            if extra:                                  # authored content → the genuine ship
                return (sha, chain[i + 1:])
            i -= 1                                     # provably record-only → demote, keep walking
        else:
            # T-11528 — the walk EXHAUSTED: no kind-absent record on this chain carries authored
            # content. If the chain as a WHOLE is record-only, it records no product ship at all, so
            # say so rather than handing back a record-only commit as the ship (the X-1074 defect).
            # Guarded by `_chain_is_record_only` — the mode selector's own predicate — so any authored
            # content anywhere keeps today's return, and an unprovable diff answers False (fail-closed).
            if _chain_is_record_only(chain, tid):
                return (None, chain)
    return (chain[last_ship_idx][0], chain[last_ship_idx + 1:])


_GOVERNED_LAND_MIN_SHA = 7   # the journal records short shas; below this a prefix match is degenerate


def _governed_land_evidence(sha_full: "str | None", tid: "str | None" = None) -> "str | None":
    """T-11386 (X-1044) — "was this commit landed by a GOVERNED verb?", answered from the EXISTING
    journal WITHOUT requiring the record to be tied to any card.

    THE ONE ROOT this exists for. Every custody mechanism in the lifecycle-verb guard family
    (`lessons/lifecycle-verb-guard-coverage.md`) derives a task's ship from a CARD-TIED `commit_landed`
    (`_displaced_ship_custody` / `_recorded_commit_sha`). A ship that landed in a fast-pass
    `work/<slug>` batch BEFORE its card existed emits `land_completed` — BRANCH-carried, carrying no
    task_id — and never a card-tied `commit_landed`. Such a ship is therefore structurally INVISIBLE to
    both, which is the single root under BOTH symptoms the card names: the `--repin-ship` dead end
    (`_require_ship_custody_repin`) and its `--preshipped-deliverable` sibling.

    Returns a short human label of the FIRST governed landing record naming `sha_full`
    (`land_completed{status: ok}` on ANY branch, or a `commit_landed` under ANY carrier), else None.
    Read-only over the journal already on disk — no new event, store, field or flag (CHARTER §P1 F2:
    a view over existing data, not a new entity). The journal records SHORT shas, so the comparison is
    prefix-wise in either direction, floored at `_GOVERNED_LAND_MIN_SHA` so a truncated/degenerate
    value can never match broadly. Tolerant of malformed lines (the `_task_commit_landed_chain`
    shape); never raises.

    THIS IS EVIDENCE, NOT AUTHORITY. It proves a governed verb landed this commit; it says NOTHING
    about which task owns it. Every caller pairs it with the ancestor-of-`main` fence — that PAIRING,
    never this helper alone, is what stops a custody re-pin from naming an arbitrary sha."""
    import re
    full = str(sha_full or "").strip()
    if len(full) < _GOVERNED_LAND_MIN_SHA or not EVENTS_PATH.exists():
        return None
    # T-12506 — with `tid`, the SAME pass also gathers the landed-branch-ancestor leg's inputs
    # (`_landed_branch_ship_tie`), consulted only when no record NAMES the sha. Without `tid`: unchanged.
    branch = f"task/{tid}" if tid else None
    tips: "list[str]" = []
    tie = None
    try:
        lines = list(journal_mod.segment_lines(EVENTS_PATH))  # T-11444: segment-aware fold (SPEC-0190 r4)
    except OSError:
        return None                     # a journal we cannot read is simply NO evidence (fail-closed)
    for line in lines:
        line = line.strip()
        if not line:
            continue
        try:
            e = json.loads(line)
        except (json.JSONDecodeError, ValueError):
            continue
        if not isinstance(e, dict):
            continue                   # a non-object line (`42`, `[]`) is no record — never raise on it
        etype = e.get("type")
        data = e.get("data") if isinstance(e.get("data"), dict) else {}
        label = None
        if etype == "land_completed":
            if (data.get("status") or "") != "ok":
                continue               # an ABORTed land integrated nothing — never evidence
            rec = str(data.get("sha") or "")
            label = f"`land_completed{{status: ok}}` on branch {data.get('branch') or '?'}"
            if branch and data.get("branch") == branch and len(rec) >= _GOVERNED_LAND_MIN_SHA:
                tips.append(rec)       # T-12506 leg (a) candidates — gathered in this SAME pass
        elif etype == "commit_landed":
            rec = str(data.get("commit") or "")
            label = f"`commit_landed` under {e.get('task_id') or 'an untied carrier'}"
        if branch and tie is None and etype in _REPIN_TIE_FIELDS and e.get("task_id") == tid:
            text = str(data.get(_REPIN_TIE_FIELDS[etype]) or "").lower()   # T-12506 leg (c)
            if any(full.lower().startswith(tok) for tok in re.findall(r"\b[0-9a-f]{7,40}\b", text)):
                tie = f"{etype}.{_REPIN_TIE_FIELDS[etype]}"
        if label is None or len(rec) < _GOVERNED_LAND_MIN_SHA:
            continue
        if full == rec or full.startswith(rec) or rec.startswith(full):
            return label
    return _landed_branch_ship_tie(tid, full, tips, tie) if branch else None


# T-12506 — the card-tied rows (type → text field) that may NAME a raw ship (leg (c) below).
_REPIN_TIE_FIELDS = {"tests_passed": "evidence", "bg_dispatch_halted": "reason", "commit_landed": "subject"}
_REPIN_LANDED_BRANCH_LABEL = "ancestor of `land_completed{status: ok}` on "


def _landed_branch_ship_tie(tid: str, full: str, tips: "list[str]", tie: "str | None") -> "str | None":
    """T-12506 (SPEC-0015 §Internal, the `--repin-ship` MODE B evidence leg) — "did this RAW ship land
    INSIDE this card's own governed landing, and does the journal tie it to the card?"

    A ship a worker authored as a raw git commit (no `commit_landed`) that later landed inside its
    `task/<id>` branch is NAMED by no governed record: `land_completed.sha` is the branch TIP (a
    bookkeeping commit — T-11405 refuses it), so it had no admissible re-pin target at all (T-12453,
    deviation events.jsonl#ts=2026-09-13T09:31:53Z). PURE over what `_governed_land_evidence` already
    gathered in its one journal pass (no second journal read). Returns a label naming the three bound
    legs ONLY when ALL hold, else None (fail-closed):
      (a) the ship is an ANCESTOR of a `land_completed{status: ok}.sha` whose branch is `task/<tid>`
          (`tips`; any git failure is "not proven");
      (b) it carries AUTHORED content — the SAME `_bookkeeping_commit_authored_paths` predicate, read
          positively (an empty or unprovable diff refuses; no relaxation);
      (c) a row tied to `tid` names it (`tie` — `tests_passed.evidence`, `bg_dispatch_halted.reason` or
          `commit_landed.subject` carrying a hex token >= `_GOVERNED_LAND_MIN_SHA` that prefixes it).
    Nothing rests on the operator's word."""
    import subprocess
    if tie is None or not tips:
        return None

    def _is_ancestor(t: str) -> bool:
        try:
            return subprocess.run(
                ["git", "-C", str(REPO_ROOT), "merge-base", "--is-ancestor", full, t],
                capture_output=True, text=True, check=False).returncode == 0
        except (OSError, ValueError, subprocess.SubprocessError):
            return False               # the check could not RUN — not proven, refuse (never raise)

    tip = next((t for t in tips if _is_ancestor(t)), None)
    if tip is None or not _bookkeeping_commit_authored_paths(full, tid):
        return None
    return f"{_REPIN_LANDED_BRANCH_LABEL}task/{tid}@{tip[:7]}; authored content; tied by {tid} {tie}"




def _require_audit_post_for_commit(yaml, tid: str, full_sha: str) -> str:
    """Thin injecting residue (T-9332) — body home: bin/lib/gates.py; host resolves the globals/callables
    at call time so a test's monkeypatch of any host symbol is honored (the audit.py `_fn` precedent)."""
    return gates._require_audit_post_for_commit(
        yaml, tid, full_sha, _audit_yaml_path=_audit_yaml_path, _die=_die,
        _git_resolve_sha=_git_resolve_sha, AUDIT_VERDICT_CANONICAL=AUDIT_VERDICT_CANONICAL,
        AUDIT_VERDICT_CLOSURE_OK=AUDIT_VERDICT_CLOSURE_OK)






P8_EVIDENCE_TYPES = ("consumer_read_evidence", "live_trigger_evidence")






# T-0383 — removal-class hint + state-check probe carrier for the infra-P8 adoption WARN.
# A removal/DROP infra task's adoption IS the VERIFIED ABSENCE (a grep state-check), not a
# consumer-read/live-trigger ADDITION event — so its natural probe key names removal/state-check
# vocabulary, none of which `adopt|live|consumer` matches → the E-0005 WARN fired spuriously
# (T-0224 DROP, run-9). WORD-BOUNDARY anchored so non-removal lookalikes (`dropdown`, `drop-in`)
# never match (audit-pre F0). NO new flag / event / store — extends the single P8 predicate (anti-cx F1).
# The removal-verb `drop` collides with hyphenated UI nouns (`drop-shadow`, `drop-in`, `dropdown`,
# `drop-zone`) — a `\b` boundary still matches before the hyphen. So `drop` is accepted ONLY as a
# STANDALONE word: `drop(?![-\w])` rejects any `drop-*` / `dropX` compound (audit-post F0 — whole class,
# not a hand-listed few) while keeping "Drop the marker" / "DROP task". The inflected `dropped|dropping|
# drops` are unambiguous removal verbs and stay. Other cues are normal `\b`-anchored words.
# State-check / verified-absence vocabulary a removal probe key naturally uses (the carrier that
# proves the absence). Gated BEHIND the removal hint below, so an ADDITION task's state-check-named
# probe alone does NOT satisfy P8 — no regression to the addition-class WARN (acceptance, audit-pre F0).






# AC-probe evidence-class (T-0290). An AC probe may name a JOURNAL EVENT as its proof
# (CHARTER §Principle 3 — "event emit / state check / measurable effect"), but events.jsonl is
# INTENTIONALLY excluded from the audit-post diff (T-0219), so any event-based AC is invisible to
# the auditor unless the packet surfaces it. T-0236 surfaced the two P8 adoption types only — so an
# AC whose probe targets a different event type (e.g. `spec_edited`, T-0282 AC3) could NEVER appear
# and was false-RED'd (E-0008 chain). This class GENERALISES the surface beyond P8: two subject-
# classes, each with its own tie-to-task rule (NOT a one-type special-case).
#   - TASK-subject (the P8 types): the event carries the ADOPTING TASK id in task_id → tied by
#     task_id == the audited task's id (the T-0236 behavior, preserved).
#   - SPEC-subject (`spec_edited`): the event carries the EDITED SPEC id in the task_id slot
#     (bin/yitc-v2 spec edit emits `_append_event("spec_edited", <spec-id>, ...)` with the edited
#     spec's repo-relative path in `data.path`) → tied by EITHER of two signals (T-0551):
#       (a) the edited spec id is in the task's `cites:` (the original T-0290 tie — a task edits a
#           spec it cites; T-0282 cites SPEC-0015 and emitted spec_edited(SPEC-0015)); OR
#       (b) the event's `data.path` is a spec file the audited task's SHIPPED DIFF touched (the
#           `touched_paths` tie). RECURRING incident (T-0549/T-0550): a task EDITS a spec it does
#           NOT cite (T-0549 folded D-0048 into SPEC-0004; T-0550 repointed SPEC-0025/0038) — the
#           cites-only tie omitted its spec_edited event from the packet → false-RED on the
#           "spec_edited emitted for SPEC-XXXX" AC (fingerprint
#           audit-post-adoption-section-omits-spec-edited-events-keyed-by-spec-id). The diff already
#           names the edited spec file, so this tie keys the proof by the spec the task actually
#           touched. Reuses the existing diff (`_diff_touched_files`) + journal read — no new store.
# DISTINCT from the P8 adoption GATE: membership here only makes an event auditor-VISIBLE — it does
# NOT satisfy the infra-class Principle-8 adoption WARN (that stays P8_EVIDENCE_TYPES via
# `_p8_evidence_event_exists`, UNCHANGED — coherence, Principle 7). Append-only as new event-based
# AC patterns appear (mirrors the append-only event-type catalog, SPEC-0025).
# T-10381 (fu_e8dfe6b9939d) — `spec_reverified` is a SECOND spec-subject AC-probe evidence-type, and
# the same unrenderable-evidence false-RED as every deferred class above: a card whose acceptance is
# `probe(event): a spec_reverified for SPEC-X` re-blesses that spec's content-signature via
# `spec reverify` / `task close --reverify` (bin/lib/spec.py / bin/lib/task.py), each emitting
# `spec_reverified` with the RE-VERIFIED SPEC id in the task_id slot AND `data.path` = the spec yaml —
# STRUCTURALLY IDENTICAL to `spec_edited`. events.jsonl is excluded from the diff (T-0219), so without
# membership the auditor reads a genuinely-present reverify as absent and false-REDs the AC (the exact
# gap fu_e8dfe6b9939d reported). Spec-subject: it ties through the SAME spec-subject branch as
# spec_edited — cites-tie (spec id in `cites:`) OR the T-0551 diff-touched-path tie — so no branch
# logic changes. DISTINCT from the P8 adoption GATE: like every class above, membership here only
# makes an event auditor-VISIBLE — it does NOT satisfy the infra-class P8 WARN (`_p8_evidence_event_exists`
# stays P8_EVIDENCE_TYPES, UNCHANGED — coherence, Principle 7), so a reverify can never buy adoption.
_SPEC_SUBJECT_EVIDENCE_TYPES = ("spec_edited", "spec_reverified")
# T-9626 (X-0117/X-0119/X-0120) — the 3 HOST-CONFIG apply evidences (SPEC-0111 §5, the apply seam's
# host_apply.EVIDENCE_EVENTS) are a THIRD AC-probe evidence-class. They are TASK-subject: the apply
# seam emits each with the AUDITED TASK id in the task_id slot (bin/lib/host_apply.py:612-618), so
