#: The three sandbox lifecycle event types (stack up · cage verified on RUNNING containers · data proof ran).
SANDBOX_LIFECYCLE_EVENT_TYPES = ("spike_stack_up", "spike_cage_checked", "spike_data_proved")
#: The four REQUIRED payload keys; `evidence_ref` is the load-bearing one (a name alone renames the gap).
SANDBOX_LIFECYCLE_PAYLOAD_KEYS = ("ok", "producer", "compose_project", "evidence_ref")


def validate_sandbox_lifecycle_payload(event_type, data) -> list:
    """The sorted problems of a sandbox lifecycle payload: `missing:<key>` for an absent required key,
    `bad:ok` unless `ok` is exactly a bool, `bad:<key>` unless the other keys are non-empty strings.
    An OPEN row — no `unknown:` arm, so an instrument may carry extra detail. A non-dict payload is
    missing every key. Returns `[]` for a clean payload and for any other event type. Pure, no raise."""
    if event_type not in SANDBOX_LIFECYCLE_EVENT_TYPES:
        return []
    if not isinstance(data, dict):
        return sorted(f"missing:{k}" for k in SANDBOX_LIFECYCLE_PAYLOAD_KEYS)
    problems = []
    for k in SANDBOX_LIFECYCLE_PAYLOAD_KEYS:
        if k not in data:
            problems.append(f"missing:{k}")
        elif k == "ok":
            if not isinstance(data[k], bool):
                problems.append("bad:ok")
        elif not (isinstance(data[k], str) and data[k].strip()):
            problems.append(f"bad:{k}")
    return sorted(problems)


