def _plan_corpus_signature(slug: str, plan_body: str, lines=None) -> str:
    """Freshness signature for the plan-finalization gate (T-0193; audit-pre F0 absorbed): binds the
    audit to BOTH the plan body AND its spec corpus — EITHER changing invalidates the audit-post.
    sha256(plan content_hash + sorted '<sid>:<status>' corpus). Mirrors `plan check`'s content_hash."""
    corpus = ";".join(f"{sid}:{st}" for sid, st in _plan_specs(slug))
    basis = f"{_plan_content_hash(plan_body)}|{corpus}"
    # T-13126: fold the SAME target-scenario lines the corpus renders (T-13019); no target -> basis unchanged.
    targets = _plan_target_scenario_lines(slug) if lines is None else lines
    if targets:
        basis += "|" + "\n".join(targets)
    return hashlib.sha256(basis.encode("utf-8")).hexdigest()


