def _latest_event_for(task_id: str, event_type, collect: "list | None" = None) -> dict | None:
    """Return the LAST events.jsonl entry matching task_id + type (physical-last, the most
    recent append), or None. Used by task audit-post to surface the Stage-6 `tests_passed`
    evidence to the auditor (T-0123). Read-only; tolerant of malformed lines.
    `event_type` is one type name, or (T-13538) a tuple of them; `collect`, when given, receives
    EVERY matching row in journal order — the same single fold, so a caller that needs all the rows
    (`_task_events_for`) adds no second journal reader."""
    if not EVENTS_PATH.exists():
        return None
    types = (event_type,) if isinstance(event_type, str) else tuple(event_type or ())
    found = None
    # T-11444: segment-aware fold (SPEC-0190 r4); T-13332: served from the audit seam's task rows.
    for obj in _task_rows_or_journal(task_id, journal_mod.segment_lines(EVENTS_PATH)):
        if obj.get("task_id") == task_id and obj.get("type") in types:
            found = obj
            if collect is not None:
                collect.append(obj)
    return found


def _task_events_for(task_id: str, event_types) -> list:
    """T-13538 — every events.jsonl entry tied to `task_id` whose type is one of `event_types`, in
    JOURNAL ORDER (oldest append first): the multi-row view of `_latest_event_for`'s own fold, so the
    audit-post packet can render every task-tied `tests_passed` row since the claim instead of only
    the last one. No reader of its own — same walk, same scope service, same tolerances."""
    rows: list = []
    _latest_event_for(task_id, tuple(event_types or ()), collect=rows)
    return rows


def _task_rows_or_journal(tid, lines):
    """T-13332 — the rows a TASK-keyed journal reader filters, in journal order: the audit seam's
    one-pass rows naming `tid` (from the task horizon on; text-mode admission, `journal.scope_task_rows`)
    when a scope declared that task — else the reader's OWN fold `lines` (its `segment_lines` generator,
    never started when served), parsed exactly as before: strip, skip blank, `json.loads`, skip what
    does not parse. That fallback yields every parsed value — a non-dict still meets the reader's `.get`."""
    rows = journal_mod.scope_task_rows(EVENTS_PATH, tid)
    if rows is not None:
        yield from rows
        return
    for line in lines:
        line = line.strip()
        if not line:
            continue
        try:
            e = json.loads(line)
        except ValueError:
            continue
        yield e


# T-0141: the auditor REVIEWS, it does not act. An agentic auditor on a docs/handbook-edit plan
# tried to APPLY the edit, hit its read-only sandbox, and ABORTed instead of reviewing (T-0139
# incident 2026-05-31). This universal clause (rides every audit prompt) scopes that out — the
# generalization of the audit-post tests-specific D-0043 clause. Provider-neutral (P4b).

# E-0008 fix-1 (T-0258): deliver the mode-a vs mode-b absorption discipline AT AUDIT TIME, in EVERY
# audit prompt (pre + post). Without it, the session pushes PASSABLE findings through mode-a (re-audit)
# and falsely hits the 2-pass ceiling on sound work. Canonical home: LIFECYCLE §Stage 4 + SPEC-0016.


def _forecast_touched_files(task: dict) -> list:
    return audit._forecast_touched_files(task, _anchor_file=_anchor_file, REPO_ROOT=REPO_ROOT)


def _diff_touched_files(diff_text: str) -> list:
    """T-0444 audit-POST: every file named by a unified diff. Parse the FULL `diff --git a/<p1> b/<p2>`
    header — it is present for EVERY shape (rename/copy/delete/new-file/pure-mode-change/binary), so
    taking BOTH paths covers the cases a `+++ b/` scan alone would miss (YELLOW-pre [1]); `+++ b/` /
    `--- a/` stay as a secondary fallback for a malformed header. Pure f(diff); sorted/deduped;
    `/dev/null` dropped (add/delete sentinel)."""
    if not diff_text:
        return []
    out: set = set()
    for ln in diff_text.splitlines():
        if ln.startswith("diff --git "):
            m = re.match(r"diff --git a/(.+?) b/(.+)$", ln)
            if m:
                out.add(m.group(1).strip())
                out.add(m.group(2).strip())
        elif ln.startswith("+++ b/"):
            out.add(ln[6:].strip())
        elif ln.startswith("--- a/"):
            out.add(ln[6:].strip())
    out.discard("/dev/null")
    return sorted(p for p in out if p and p != "dev/null")


_EXPECTED_TOUCH_SPEC_RE = re.compile(r"(?:^|/)specs/(SPEC-\d+)[-.]")


def _plan_activation_ordering_note(task: dict, specs: dict) -> str:
    """T-12918 (X-1564): the recorded activation ordering, rendered for a PREDECESSOR card.

    A plan whose LAST card activates its governing spec leaves every earlier card shipping code the
    still-active corpus contradicts; the auditor read that interim as a spec-coherence defect and each
    such card paid a ceiling (<project> T-0091). The ordering is already RECORDED — a `proposed`
    spec's `activation_owner_task` A, A's transitive `requires:` reaching this card, the spec's
    `supersedes:` target, and the spec files A's own `expected_touch` declares it edits — so this is a
    pure view over it, the predecessor-side sibling of the T-10707 ACTIVATING marker (which covers A
    itself; A is therefore skipped here). The lag set deliberately EXCLUDES A's generic `cites:` — a
    spec A only cites for guidance is not reconciled by A, so a contradiction with it still REDs.
    Each owner card is loaded and walked ONCE, however many proposed specs it activates. Returns ""
    when no activation owner's chain reaches this card."""
    tid = str(task.get("id") or "")
    if not tid:
        return ""
    by_owner: dict = {}
    for sid, node in sorted(specs.items()):
        node = node or {}
        owner = str(node.get("activation_owner_task") or "")
        if node.get("status") == "proposed" and owner.startswith("T-") and owner != tid:
            by_owner.setdefault(owner, []).append(sid)
    blocks = []
    for owner, proposed in sorted(by_owner.items()):
        opath = _find_task_yaml(owner)
        ocard = (_read_yaml(opath) or {}) if opath else {}
        if not ocard or ocard.get("status") == "done":
            continue
        # Breadth-first over `requires:` so the rendered path is a shortest recorded chain.
        parent: dict = {owner: None}
        queue = [owner]
        cards = {owner: ocard}
        while queue and tid not in parent:
            cur = queue.pop(0)
            card = cards.get(cur)
            if card is None:
                cpath = _find_task_yaml(cur)
                card = cards[cur] = (_read_yaml(cpath) or {}) if cpath else {}
            for req in card.get("requires") or []:
                req = str(req)
                if req.startswith("T-") and req not in parent:
                    parent[req] = cur
                    queue.append(req)
        if tid not in parent:
            continue
        chain, cur = [], tid
        while cur is not None:
            chain.append(cur)
            cur = parent[cur]
        chain.reverse()
        lag = [f"{s} (proposed — activates at {owner}'s closure)" for s in proposed]
        seen = set(proposed)
        for s in proposed:
            sup = str((specs.get(s) or {}).get("supersedes") or "")
            if sup and sup not in seen and (specs.get(sup) or {}).get("status") == "active":
                seen.add(sup)
                lag.append(f"{sup} (active — superseded by {s} at that activation)")
        for entry in ocard.get("expected_touch") or []:
            m = _EXPECTED_TOUCH_SPEC_RE.search(str(entry))
            sid = m.group(1) if m else ""
            if sid and sid not in seen and (specs.get(sid) or {}).get("status") == "active":
                seen.add(sid)
                lag.append(f"{sid} (active — edited in {owner}'s shipment per its expected_touch)")
        blocks.append(
            f"- {owner} — {ocard.get('title') or '(untitled)'}\n"
            f"  recorded ordering: {' → '.join(chain)} (each `requires:` the next)\n"
            f"  lagging corpus it reconciles: {'; '.join(lag)}")
    if not blocks:
        return ""
    return ("\n#### Plan activation ordering (recorded — derived, report-not-block, T-12918)\n\n"
            "THIS card is a PREDECESSOR of a recorded activation: the card(s) below activate a "
            "`proposed` spec and their `requires:` chain reaches this card, so the corpus "
            "reconciliation rides THEM, not this card (GRAPH §Spec lifecycle — the activation owner's "
            "`task close` is the SOLE writer of proposed → active).\n\n"
            + "\n".join(blocks) + "\n\n"
            "Judge the interim against that ordering. A spec-coherence finding whose ONLY cause is that "
            "a spec in a LAGGING CORPUS above still describes the pre-plan world is the recorded "
            "ordering, NOT a defect of this card — record it as a note citing the activation card, "
            "never as a RED/YELLOW finding. Everything else is judged as usual and still REDs: a "
            "contradiction with any active spec NOT listed above, the code failing the proposed spec it "
            "is built toward, or any defect in the code itself.\n")


def _spec_coverage_section(task: dict, stage: str, diff: "str | None", stale_sink=None) -> str:
    """T-0444: the derived `### Spec coverage of touched files` block appended to a TASK audit prompt.
    Pure f(graph, plan/diff); REPORT-NOT-BLOCK (GRAPH §"NOT a validation layer" — the auditor judges,
    the section never gates). Touched files = `_forecast_touched_files` (pre) | `_diff_touched_files`
    (post). Per file: the governing ACTIVE specs (graph `code_to_specs`, status-filtered) OR a
    `(no governing spec)` marker; PLUS the symbol-level drift flags from `_changed_anchor_spec_drift`
    (touched-scoped, active-only — it DERIVES drift from each active spec's `implements:` anchor blob
    AS OF the spec's last-touch commit vs the current tree, no change-map needed). This is what lets
    the external auditor answer the two coverage questions: (1) code touched with NO spec — justified
    spec-less or a doc gap? (2) a touched `implements:` anchor whose spec is NOT updated — drift?

    `stale_sink` (T-11977, SPEC-0036 §Packet preview): an optional list this function appends
    `(file, SPEC-ID)` pairs to for every possibly-stale anchor it ALREADY found — the same
    `_changed_anchor_spec_drift` walk, handed back instead of walked twice, so the `--preview`
    readiness block reports stale anchors without re-parsing the section rendered here. Purely
    additive: the returned string is byte-unchanged whether or not a sink is supplied."""
    if stage not in ("pre", "post"):
        return ""
    touched = _forecast_touched_files(task) if stage == "pre" else _diff_touched_files(diff or "")
    header = ("### Spec coverage of touched files\n\n"
              "(derived f(graph, " + ("plan-forecast" if stage == "pre" else "shipped diff") + ") — "
              "REPORT-NOT-BLOCK; the graph is not a validator. Use this to answer the two coverage "
              "questions in the overlay above.)\n")
    if not GRAPH_PATH.exists() and touched:
        return header + "\n(graph index absent — run `yitc-v2 graph build`; coverage unavailable this run)\n"
    index = (_read_yaml(GRAPH_PATH) or {}) if GRAPH_PATH.exists() else {}
    c2s = index.get("code_to_specs", {}) or {}
    specs = index.get("specs", {}) or {}
    # T-12918: the recorded plan-activation ordering for a PREDECESSOR card — rendered on every path
    # that has the index, touched files or not. Report-only: a note error never breaks the section.
    try:
        ordering = _plan_activation_ordering_note(task, specs)
    except Exception:      # noqa: BLE001 — observation only
        ordering = ""
    if not touched:
        # ALWAYS render for a task pre/post (audit-post YELLOW [0]): the section rides EVERY task
        # prompt + carries the two questions even when no touched file is forecast/parsed — never omit.
        return header + ("\n(no touched files "
                         + ("forecast from the plan" if stage == "pre" else "parsed from the diff")
                         + " — coverage N/A this run; the two coverage questions above still apply to "
                         "any code you identify in the plan/diff.)\n") + ordering
    drift: dict = {}
    debt: dict = {}
    _origin_cache: dict = {}
    for d in _changed_anchor_spec_drift(touched, {}):
        _dfile = _anchor_file(d.get("anchor", ""))
        # T-13229 — attribute each stale anchor in this SAME walk. Proven non-card staleness is the
        # corpus's standing debt (`graph build`'s possibly-stale report), never this card's finding,
        # and never a readiness `stale anchors:` row the worker is told to fix.
        origin, why = _anchor_drift_origin(str(d.get("spec") or ""), str(d.get("anchor") or ""),
                                           _origin_cache)
        if origin == ANCHOR_ORIGIN_NON_CARD:
            debt.setdefault(_dfile, []).append(f"{d.get('spec')} @ {d.get('anchor')} ({why})")
            continue
        drift.setdefault(_dfile, []).append(
            (f"{d.get('spec')} @ {d.get('anchor')}: {d.get('warn')}", f"{origin} — {why}"))
        if stale_sink is not None:
            # Report-only capture — a sink must never break the section it rides on.
            try:
                stale_sink.append((_dfile, str(d.get("spec") or "")))
            except Exception:      # noqa: BLE001 — observation only
                pass
    tid = str(task.get("id") or "")
    lines = [header]
    any_activating = False
    for f in touched:
        linked = c2s.get(f, [])
        govs = sorted(s for s in linked if (specs.get(s) or {}).get("status") == "active")
        # T-10707 (X-0556): a spec THIS task activates is still `proposed` at audit time — the
        # proposed→active write is this task's own `task close` (GRAPH §Spec lifecycle). Rendering
        # it as `(no governing spec)` made every activation-owner task read as code-with-no-spec
        # and false-RED at the auditor. Named EXPLICITLY (activation_owner_task == this task id —
        # SPEC-0005 §5), so another task's proposed spec is still not rendered.
        activating = sorted(s for s in linked
                            if tid and (specs.get(s) or {}).get("status") == "proposed"
                            and (specs.get(s) or {}).get("activation_owner_task") == tid)
        any_activating = any_activating or bool(activating)
        entries = govs + [f"{s} (proposed — ACTIVATING at THIS task's closure)" for s in activating]
        lines.append(f"- `{f}` — governed by: {', '.join(entries)}" if entries
                     else f"- `{f}` — (no governing spec)")
        for dl, org in drift.get(f, []):
            lines.append(f"    ⚠ possibly-stale: {dl} — was that spec updated in THIS change? if not, "
                         f"justify (deliberate / unrelated symbol) or update the spec")
            lines.append(f"      origin: {org}")
        for dl in debt.get(f, []):
            lines.append(f"    · stale-signature DEBT, not this card's: {dl} — standing corpus debt "
                         f"(`graph build` possibly-stale report); NOT a finding against this card")
    if debt:
        lines.append("\n(a stale-signature DEBT line is PROVEN non-card (T-13229): no commit of this card "
                     "and no uncommitted edit changed that anchor's code region or its stored signature, "
                     "no merge synthesized either, and both are byte-identical to main's at the "
                     "merge-base, where the anchor is already stale. This settles signature-staleness "
                     "ATTRIBUTION ONLY: the card's own delta is still judged against every governing "
                     "spec's CURRENT meaning at HEAD and on the resolved tree — a main-side change of a "
                     "spec's meaning that this card's code no longer satisfies is still a finding.)")
    if any_activating:
        lines.append("\n(a spec marked ACTIVATING is `proposed` NOW by design: `proposed → active` is "
                     "written by THIS task's own `task close` at Stage 9 (GRAPH §Spec lifecycle) — the "
                     "code is governed, the activation simply follows the ship. Read that as the NORMAL "
                     "ordering, NOT as a doc gap or a missing spec.)")
    lines.append("")
    return "\n".join(lines) + ordering


# T-9315 (friction F-014 / X-0023): the governing scenario contract surfaced into a TASK audit prompt
# ONLY when a scenario file is in the touched set. SPEC-0076 is the scenario DOCTRINE — the governing
# contract; the prompt cites + EMBEDS its body (single-SoT — the auditor judges against the real spec,
# never a restated rule). The recurring false-positive this closes: a routine -C audit flagged a
# `(ungoverned)` step non-conformant against a kernel §5 rule the prompt never surfaced.
SCENARIO_CONTRACT_SPEC = "SPEC-0076"


def _scenario_contract_section(task: dict, stage: str, diff: "str | None") -> str:
    """T-9315: when the planned (pre) / shipped (post) diff touches `scenarios/`, embed the GOVERNING
    scenario contract (SPEC-0076 — the scenario doctrine) so the external auditor judges the scenario
    against the REAL rules (zero-normative; the step-annotation obligation is PER-AUTHORED-item, NOT a
    coverage/completeness mandate; a `(ungoverned)` step is a SANCTIONED marker, never a defect) instead
    of inventing a coverage rule (the F-014 / X-0023 false-positive). The contract file resolves with the
    T-0860/T-9313 ENGINE-content fallback (`_find_spec_path(..., engine_fallback=True)`), so a -C consumer
    whose own corpus lacks the kernel spec still gets it from the engine install path. Task pre/post only
    (decision/plan/adhoc/consult unaffected); REPORT-ONLY (never a gate); omitted when no scenario file is
    touched. Mirrors `_spec_coverage_section`'s touched-files derivation."""
    if stage not in ("pre", "post"):
        return ""
    touched = _forecast_touched_files(task) if stage == "pre" else _diff_touched_files(diff or "")
    if not any(_norm_repo_path(p).startswith("scenarios/") for p in touched):
        return ""
    path = _find_spec_path(SCENARIO_CONTRACT_SPEC, engine_fallback=True)
    if path is None or not path.exists():
        return ""
    body = (_read_yaml(path) or {}).get("body") or ""
    if not body.strip():
        return ""
    return (
        f"### Scenario doctrine — GOVERNING CONTRACT ({SCENARIO_CONTRACT_SPEC})\n\n"
        "This change touches `scenarios/`. A scenario is a ZERO-NORMATIVE, descriptive composition of\n"
        "specs into a user-path; it governs NOTHING and is held to the contract below, NOT to a\n"
        "coverage/completeness standard. Judge the scenario AGAINST THIS CONTRACT — do not invent rules:\n"
        "  - The step-annotation obligation is PER-AUTHORED-item, NOT a coverage mandate (§5): the\n"
        "    ABSENCE of a step or an error-branch is NEVER itself a defect or a review-fail.\n"
        "  - A step marked `(ungoverned)` is a SANCTIONED marker for a deliberately ungoverned step\n"
        "    (a recognized non-goal) — it is CONFORMANT, never a finding.\n"
        "  - The real defect to catch is the OPPOSITE: scenario-resident NORMATIVE language (a\n"
        "    `must/always/never` that is an enforceable rule belongs in a spec/FSM/test, §2), not a\n"
        "    missing or ungoverned annotation.\n\n"
        f"The governing contract (verbatim {SCENARIO_CONTRACT_SPEC} body):\n\n```\n{body.rstrip()}\n```\n"
    )


def _build_audit_prompt(task: dict, stage: str, diff: str | None, extra: str | None,
                        target_kind: str = "task", focus: str = None,
                        event_emit_only: bool = False, serve_deploy: bool = False,
                        reaudit_after_close: bool = False, external_action: bool = False,
                        host_config: bool = False, land_emitted_event: bool = False,
                        preshipped_deliverable: bool = False, preshipped_commit: "str | None" = None,
                        foreign_subject: "dict | None" = None,   # T-12737 — the declared foreign subject
                        settlement_sweep: bool = False, settlement_commits: "list | None" = None,
                        post_ship_observation: "dict | None" = None,
                        activation_gated_radius: "dict | None" = None,
                        prior_record: "dict | None" = None, prior_passes: int = 0,
                        on_decisions: "dict | None" = None,
                        churn_tie: "dict | None" = None,
                        evidence_sink=None,
                        readiness_sink=None, readiness_journal_silent: bool = False,
                        prototype_diff: "str | None" = None,
                        prototype_identity: "dict | None" = None,
                        cross_section_sink=None,
                        optin_excluded_sink=None,
                        zero_ship_diff: bool = False, evidence_locator: "str | None" = None) -> str:
    """Thin host wrapper -> audit.build_audit_prompt (T-9248). Preserves the historical signature so
    cmd_audit* call-sites are unchanged; injects the 7 host-coupled prompt-section helpers (the engine
    reads no host global). The yitc.<symbol> test contracts (each helper individually replaceable on the
    host module) are honored because the host names are resolved here at call time. `prior_record`
    (T-9681): the prior saved audit record for this target+stage, threaded through so the engine renders
    the MONOTONIC per-pass re-audit section on pass N>=2 (None on pass 1 / non-absorption-loop kinds).
    `evidence_sink` (T-10741, SPEC-0168 rule 5): passed straight through — the TASK audit-post branch
    fills it with the evidence rows the packet COUNTED, so `cmd_audit` can record that set durably.
    `readiness_sink` / `readiness_journal_silent` (T-11977, SPEC-0036 §Packet preview): passed
    straight through — the `--preview` path supplies them so the engine renders the report-only
    packet-readiness block from the parts that one assembly pass already computed."""
    return audit.build_audit_prompt(
        task, stage, diff, extra, target_kind=target_kind, focus=focus,
        event_emit_only=event_emit_only, serve_deploy=serve_deploy,
        reaudit_after_close=reaudit_after_close, external_action=external_action,
        host_config=host_config, land_emitted_event=land_emitted_event,
        preshipped_deliverable=preshipped_deliverable, preshipped_commit=preshipped_commit,
        foreign_subject=foreign_subject,   # T-12737 (X-1487): the card-declared foreign subject overlay
        settlement_sweep=settlement_sweep, settlement_commits=settlement_commits,
        post_ship_observation=post_ship_observation,
        activation_gated_radius=activation_gated_radius,
        prior_record=prior_record,
        prior_passes=prior_passes,   # T-12288 (SPEC-0204 rule 8): the pass-1-vs-later round fork
        on_decisions=on_decisions,   # T-12289 (SPEC-0204 rule 3): the decided-residual projection
        churn_tie=churn_tie,   # T-12718: the churn-only merge tie (H, M) — Stage-6 ordering note
        zero_ship_diff=zero_ship_diff, evidence_locator=evidence_locator,   # T-12730: re-lens overlay
        evidence_sink=evidence_sink,
        cross_section_sink=cross_section_sink,   # T-12590: the held rule-4 render, never counted
        optin_excluded_sink=optin_excluded_sink,   # T-13508: the opt-in-excluded TYPES, for `audit post`'s own line
        readiness_sink=readiness_sink,
        readiness_journal_silent=readiness_journal_silent,
        prototype_diff=prototype_diff, prototype_identity=prototype_identity,   # T-12571 (SPEC-0205 r5/6)
        repo_root=REPO_ROOT,   # T-11778: the checkout the collector-shape facts are read from
        yaml_dump_block=yaml_dump_block,
        latest_event_for=_latest_event_for,
        task_events_for=_task_events_for,   # T-13538: every task-tied Stage-6 row since the claim
        diff_touched_files=_diff_touched_files,
        norm_repo_path=_norm_repo_path,
        ac_probe_evidence_events_for=_ac_probe_evidence_events_for,
        cross_evidence_section_for=_cross_evidence_section_for,
        p8_carrier_section_for=_p8_carrier_section_for,
        spec_coverage_section=_spec_coverage_section,
        scenario_contract_section=_scenario_contract_section,
        activation_section=_activates_at_close_section,   # T-12977
        build_referenced_files_section=_build_referenced_files_section)


def _build_referenced_files_section(task: dict) -> str:
    """T-0035: assemble ## Referenced files section для audit-pre prompt.

    Walks _extract_referenced_paths output, reads excerpt per-file under total cap,
    formats as code fences с per-file header. Returns "" если no refs (omit section).
    """
    paths = _extract_referenced_paths(task)
    if not paths:
        return ""
    blocks: list[str] = ["## Referenced files\n"]
    # T-11140: the shared budget runs on BOTH axes. A line-only total budget is defeated by long
    # lines (MEASURED: 2.4MB spent 80 of 3000 "remaining" lines), so a single fat artifact could put
    # megabytes into the prompt while every later path still looked affordable.
    remaining, remaining_b = AUDIT_MAX_REF_LINES_TOTAL, AUDIT_MAX_REF_BYTES_TOTAL
    for path in paths:
        rel = path.relative_to(REPO_ROOT)
        if remaining <= 0 or remaining_b <= 0:
            # NAMED, never silent — an omitted path must stay visibly present (anti-false-absent).
            blocks.append(f"### {rel}\n\n(omitted — total cap reached; the file IS present)\n")
            continue
        excerpt, used, used_b = _read_referenced_excerpt(path, remaining, remaining_b, label=str(rel))
        if not excerpt:
            continue
        blocks.append(f"### {rel}\n\n```\n{excerpt}\n```\n")
        remaining -= used
        remaining_b -= used_b
    return "\n".join(blocks)


def yaml_dump_block(items: list) -> str:
    """Format а list as а bulleted block для prompt readability."""
    if not items:
        return "(empty)"
    return "\n".join(f"- {item}" for item in items)


# Re-export -> audit.codex_subscription_preflight (T-9248): pure env/auth.json check, no host coupling.
_lazy_alias("_codex_subscription_preflight", "audit", "codex_subscription_preflight")


def _invoke_codex(prompt: str, model: "str | None", read_corpus: bool = False,
                  effort: "str | None" = None,
                  read_only: bool = False,
                  consult_class: "str | None" = None,
                  full: bool = False) -> tuple[int, str, str]:
    """Thin host wrapper -> audit.invoke_codex (T-9248). Injects the current REPO_ROOT (honors a -C
    rebind / test override at call time) + the host _codex_subscription_preflight name (so a test that
    replaces it is honored). AUDIT_PROVIDERS["codex"] is THIS wrapper -> the identity contract holds.

    `effort` (T-9550): codex has no native --effort flag, so reasoning effort is set via the CODEX_HOME
    config key `model_reasoning_effort` (default medium) — invoke_codex passes it as the per-invocation
    `-c model_reasoning_effort="<effort>"` override when set (parity with _invoke_claude's --effort).
    When None, NO override is added — codex stays its config-default, byte-identical to before (AC2).

    `read_only` (T-9572): forwards the bare `-s read-only` least-privilege sandbox for the adhoc/judge
    role (see invoke_codex). Default False leaves every lifecycle caller byte-identical.

    `codex_bin` + `codex_home` (T-9653): resolved from bin/audit-config.yaml and injected so the
    governed auditor runs on the OFFICIAL unconfined codex under the subscription-auth CODEX_HOME. The
    config defaults (bare "codex" / None) leave the launch byte-identical to before this task.

    `consult_class` (T-11149): forwards the consult class that selects the default wall-clock budget
    (see audit._audit_timeout_seconds). Default None = the routine budget = byte-identical.

    `full` (T-12350): the audit TIER, threaded from the call site so the per-tier machine binding
    (`auditor.<tier>.binary` / `.home`) is read for the tier that is actually auditing — never a
    tier-less guess. `model=None` = the adapter's own default (the admitted same-provider fallback)."""
    return audit.invoke_codex(prompt, model, read_corpus,
                              repo_root=REPO_ROOT, preflight=_SELF._codex_subscription_preflight,
                              effort=effort, read_only=read_only, consult_class=consult_class,
                              codex_bin=_resolve_codex_binary(full), codex_home=_resolve_codex_home(full),
                              cli_floor_check=_SELF._auditor_cli_floor_refusal)


# Re-export -> audit.claude_subscription_preflight (T-9531): pure env-vector check, no host coupling.
_lazy_alias("_claude_subscription_preflight", "audit", "claude_subscription_preflight")


def _invoke_claude(prompt: str, model: "str | None", read_corpus: bool = False,
                   effort: "str | None" = None,
                   read_only: bool = False,
                   consult_class: "str | None" = None,
                   full: bool = False) -> tuple[int, str, str]:
    """Thin host wrapper -> audit.invoke_claude (T-9531). Injects REPO_ROOT + the host
    _claude_subscription_preflight name (so a test that replaces it is honored), and forwards the
    OPTIONAL per-invocation `effort` (-> claude `--effort <lvl>`). The provider-dispatch sibling of
    _invoke_codex; AUDIT_PROVIDERS["claude"] is THIS wrapper -> the identity contract holds.

    `read_only` (T-9572): accepted for adapter-contract parity; a no-op for claude (prompt-only mode
    already holds no write capability — see invoke_claude).

    `consult_class` (T-11149): forwards the consult class that selects the default wall-clock budget
    (see audit._audit_timeout_seconds). Default None = the routine budget = byte-identical.

    `full` (T-12350): accepted for adapter-contract parity — this adapter needs no binary/home
    binding (bare `claude` on PATH), so the tier selects nothing here. `model=None` = claude's own
    default model (the admitted same-provider fallback)."""
    return audit.invoke_claude(prompt, model, read_corpus,
                               repo_root=REPO_ROOT, preflight=_SELF._claude_subscription_preflight,
                               effort=effort, read_only=read_only, consult_class=consult_class)


# Provider dispatch registry (T-0047). Each adapter implements the contract
# (prompt: str, model: str, read_corpus: bool = False, effort: str|None = None)
#   -> (returncode: int, stdout: str, stderr: str).
# `read_corpus` (T-0713) + `effort` (T-9531) + `read_only` (T-9572) + `consult_class` (T-11149) are
# part of the adapter contract: a registered adapter MUST accept all four (read_corpus default False =
# prompt-only; effort default None = no effort flag; read_only default False = provider sandbox
# default; consult_class default None = the routine wall-clock budget). `full` (T-12350) is the
# OPTIONAL fifth: the audit tier, forwarded by _invoke_auditor only to an adapter whose signature
# accepts it (both shipped adapters do; a pre-T-12350 double is dispatched byte-identically).
# A future provider = add one function + one entry, no cmd_audit rewrite. CHARTER §P4b — provider
# names live here, not in handbook.
AUDIT_PROVIDERS = {
    "codex": _invoke_codex,
    "claude": _invoke_claude,
}


def _invoke_auditor(provider: str, prompt: str, model: "str | None",
                    read_corpus: bool = False, effort: "str | None" = None,
                    read_only: bool = False,
                    consult_class: "str | None" = None,
                    full: bool = False) -> tuple[int, str, str]:
    """Dispatch to the configured provider adapter (T-0047 provider-dispatch layer).

    read_corpus (T-0713) + effort (T-9531) + read_only (T-9572) + consult_class (T-11149) forward to
    the adapter per the AUDIT_PROVIDERS contract — defaults (False / None / False / None) leave every
    existing caller (cmd_audit, the plan-gate audits) byte-identical. `consult_class` is what makes
    the wall-clock budget per-class: the INSPECTION call sites (cmd_audit_adhoc, cmd_audit_consult)
    pass it, the ROUTINE ones do not.

    `full` (T-12350, audit-pre pass-1 finding 2): the audit TIER, threaded end to end so the adapter
    reads the per-tier machine binding for the tier that is auditing. Forwarded only to an adapter
    whose signature accepts it — a registered double that predates the kw keeps its byte-identical
    call. The independence STAMP is NOT written here: this chokepoint has no target/stage/record
    context — it is written by the ONE saved-verdict writer helper `audit.stamp_auditor_verdict`
    (SPEC-0201 rule 2)."""
    adapter = AUDIT_PROVIDERS.get(provider)
    if adapter is None:
        # T-12952 (SPEC-1000): a `<...>` placeholder is the release strip's substitution (v2.0.4 shipped
        # `provider: <external-auditor>`), never a name a person types — evidence the SHIPPED config is
        # corrupt, so only that shape advertises the escape; a plain unknown name is a local typo.
        _escape = ("\n" + textutil.kernel_defect_escape_hint()) \
            if re.fullmatch(r"<[^<>]+>", str(provider or "").strip()) else ""
        _die(f"unknown audit provider {provider!r} — known: {sorted(AUDIT_PROVIDERS)} "
             f"(set bin/audit-config.yaml `provider:` per tier){_escape}")
    extra = {}
    try:
        import inspect
        if "full" in inspect.signature(adapter).parameters:
            extra["full"] = full
    except (TypeError, ValueError):
        pass
    if full and consult_class is None:
        # T-13162 — a full-tier gate run (plan check, plan gates, `audit --full`) arms the full-tier
        # wall, not the routine 300s; an explicit class (INSPECTION) is left as the call site set it.
        consult_class = audit.AUDIT_FULL_CONSULT_CLASS
    return adapter(prompt, model, read_corpus=read_corpus, effort=effort, read_only=read_only,
                   consult_class=consult_class, **extra)


