def _pattern_frontmatter(path: Path, errors: list | None = None) -> dict:
    """Extract YAML frontmatter from a markdown file (between the leading ---/--- pair).

    Per T-0021 audit-pre F2 absorbed: same `errors` tracking as _read_yaml for malformed
    patterns/*.md frontmatter — otherwise drops silently. The parse routes through the single
    state layer (state.load_str, T-9207)."""
    text = path.read_text(encoding="utf-8")
    if not text.startswith("---"):
        return {}
    end = text.find("\n---", 3)
    if end == -1:
        return {}
    import yaml
    try:
        return state.load_str(text[3:end]) or {}  # T-9207: parse via the single state layer
    except yaml.YAMLError as e:
        if errors is not None:
            errors.append({"path": str(path.relative_to(REPO_ROOT)), "error": str(e)[:300]})
        return {}


