def _routing_surface_vocab_static() -> set:
    """The routing-surface vocabulary (floor-trigger NAMES + their surface keys) derived from the canonical
    FLOOR_TRIGGERS carrier. The vocab is just NAMES — fixed by FLOOR_TRIGGERS regardless of which specs are
    currently bound — so it needs no spec load. REUSES `_routing_surface_vocab` over a names-only map
    (CHARTER §P1 F1: one carrier, no hand-maintained copy)."""
    names_only = {trig: {surf: [] for surf in surfaces} for trig, surfaces in FLOOR_TRIGGERS}
    return _routing_surface_vocab(names_only)


def _hint_carries_routing_payload(text: str, vocab: set = None) -> bool:
    """SPEC-0033 structural predicate: True iff `text` is a what/when ROUTING instruction rather than a
    plain post-action note. A routing payload = a routing SURFACE (a `stage-entry:<STAGE>` token OR a
    floor-trigger vocab token) co-present on a line with ≥1 SPEC id — the canonical binding-map syntax that
    names which spec to read at which surface/stage (exactly the assertion shape the T-0300 handbook-
    routing-duplication check flags). A bare operational nudge ('cd back to main', 'run audit post next')
    names no surface×spec pairing → False (a clean hint). REUSES the existing routing-assertion extractor
    `_handbook_routing_assertions` — NOT a parallel scanner (CHARTER §P1 F1).

    BOUNDED BY DESIGN (audit-pre F0, recorded): the structural carrier of "routing" is the binding-token
    syntax. A verb's SANCTIONED forward pointer (`_governing_rule_pointer`) says 'enter stage Closure …
    SPEC-0015' using the HUMAN 'stage <NAME>' phrasing, NOT the 'stage-entry:<STAGE>' binding token, so it
    is NOT a routing payload here — consistent with T-0296 sanctioning it as a post-hint. Widening to chase
    human-stage-name wording would flag that sanctioned pointer (a Principle-7 contradiction) and is the
    completeness over-reach CHARTER non-goal #7 / GRAPH not-a-validation-layer / D-0036 decline."""
    if vocab is None:
        vocab = _routing_surface_vocab_static()
    return bool(_handbook_routing_assertions(text or "", vocab))




def _governing_rule_pointer(surface: str) -> str:
    """Element #2 (Part I-A, T-0232) — the before-X forward-pointer printed by the verb that PRECEDES
    a gated verb (the commit-rules pointer on `task test`; the closure-rules pointer on `audit post`).
    DERIVED-ONLY from the committed `verb_to_specs` binding inversion — the single canonical carrier is
    the per-spec `binding:` field (SPEC-0013); there is NO hand-maintained pointer copy (plan-check
    finding 1 / P5). It is a REMINDER, never the guarantee: the always-loaded floor trigger-map
    (graph/floor-trigger-map.md) is the load-bearing delivery (plan §Ordering). When no active spec is
    bound to the surface yet (e.g. work-first specs still `proposed` — `_build_binding_views` is
    active-only by contract), it falls back gracefully — the pointer LINE is still present, names the
    surface, and points at the floor map."""
    idx = _read_yaml(GRAPH_PATH) if GRAPH_PATH.exists() else {}
    floor = "graph/floor-trigger-map.md"
    if surface in SURFACE_TO_STAGE:                  # T-0289: relocated to the stage-entry delivery axis —
        stage = SURFACE_TO_STAGE[surface]            # point at `stage <STAGE>` (the new delivery), not a
        report = (idx.get("binding_report") or {}) if isinstance(idx, dict) else {}   # stale "before-verb floor".
        sids = (report.get("stage_to_specs") or {}).get(stage) or []
        run = f"`yitc-v2 stage {stage} --task <T-XXXX>`"
        if sids:
            return (f"→ before `{surface}`: enter stage {stage} ({run}) — it delivers the governing "
                    f"rule(s) {', '.join(sids)} (`yitc-v2 graph query <SPEC>`)")
        return (f"→ before `{surface}`: enter stage {stage} ({run}) — the stage-entry delivers its bundle "
                f"(no active spec bound to stage-entry:{stage} yet — reminder, not a guarantee)")
    v2s = (idx.get("verb_to_specs") or {}) if isinstance(idx, dict) else {}
    sids = v2s.get(surface) or []
    if sids:
        return (f"→ before `{surface}`: read the governing rule(s) {', '.join(sids)} "
                f"(`yitc-v2 graph query <SPEC>`; always-loaded map: {floor})")
    return (f"→ before `{surface}`: read the {surface}-rules — see the always-loaded floor trigger-map "
            f"({floor}); no active `retrieved` spec bound yet (reminder, not a guarantee)")


def _render_floor_trigger_map(floor_trigger_map: dict, specs: dict, kernel_provided: bool=False) -> str:
    return graph._render_floor_trigger_map(floor_trigger_map, specs, kernel_provided, FLOOR_TRIGGERS=FLOOR_TRIGGERS, KERNEL_NAME=KERNEL_NAME, FLOOR_TRIGGER_GOVERNED_VERB=FLOOR_TRIGGER_GOVERNED_VERB)


def _print_binding_report(report: dict, prefix: str = "") -> None:
    """Print the bidirectional binding-completeness report to stderr — report-not-block (T-0230,
    Part I-A element #4). `prefix` annotates the auto-rebuild path. No-op when everything is clean."""
    unmapped = report.get("unmapped_gating_verbs") or []
    dangling = report.get("dangling_specs") or []
    unknown = report.get("unknown_tokens") or []
    malformed = report.get("malformed_binding") or []
    seed_cue_missing = report.get("seed_cue_missing") or []   # T-13422 — `graph conformance` refuses on it
    if not (unmapped or dangling or unknown or malformed or seed_cue_missing):
        return
    print(f"\nyitc-v2: {prefix}binding completeness report (report-only — not a build failure):",
          file=sys.stderr)
    if unmapped:
        print(f"  - unmapped gating verb(s) (no active `retrieved` spec bound): {', '.join(unmapped)}",
              file=sys.stderr)
    if dangling:
        print("  - dangling spec(s) (active spec with NO binding token — UNCLASSIFIED; declare a verb "
              "surface or a residency token: floor / query-only / code-enforced): "
              f"{', '.join(dangling)}", file=sys.stderr)
    for u in unknown:
        print(f"  - unknown binding token in {u['spec']}: {u['token']!r} "
              f"(allowed: {', '.join(sorted(BINDING_TOKENS))})", file=sys.stderr)
    for m in malformed:
        print(f"  - malformed binding in {m['spec']}: expected a YAML list, got {m['got']} "
              "(treated as unbound)", file=sys.stderr)
    if seed_cue_missing:
        print("  - binding:[seed] spec(s) with NO seed_cue (SPEC-0007 §5a; `graph conformance` refuses "
              f"this): {', '.join(seed_cue_missing)}", file=sys.stderr)


def _git_common_dir(directory) -> "Path | None":
    """Resolve the git COMMON-dir of `directory` (the main checkout's shared `.git`, identical for
    every linked worktree), or None when `directory` is not inside a git checkout. Lets us tell a
    linked WORKTREE of a repo apart from a SEPARATE repo (T-0952). Mirrors the `_id_reservation_dir`
    rev-parse prior-art (one technique, two readers)."""
    import subprocess
    try:
        out = subprocess.run(["git", "-C", str(directory), "rev-parse", "--git-common-dir"],
                             capture_output=True, text=True, check=False)
    except (FileNotFoundError, OSError):
        return None
    if out.returncode != 0 or not out.stdout.strip():
        return None
    common = Path(out.stdout.strip())
    if not common.is_absolute():            # rev-parse returns it relative to the -C dir
        common = Path(directory) / common
    return common.resolve()


_consumer_build_cache: dict = {}


def _consumer_carrier_pair_advisory() -> str:
    """The SINGLE home of the consumer-side CARRIER-PAIR advisory (T-11011, resolves X-0843).

    A consumer-side `bin/yitc-v2` call from an interactive session carries TWO mandatory carriers that
    live OUTSIDE the verb and fail INDEPENDENTLY, in different layers, with different messages:
      (1) the `-C <consumer>` corpus target — else `_guard_bare_invocation_foreign_corpus` refuses;
      (2) the `YITC_SESSION_REF` env prefix — else `_resolve_session_ref` refuses (SPEC-0137 Rule 5).
    Getting one right gives NO signal about the other, so a session that fixes carrier 1 walks straight
    into carrier 2's refusal — measured on two consecutive attempts at the SAME command in one session,
    and expensive on a minutes-long `land` where each malformed attempt costs a full round-trip. Both
    guards are CORRECT (loud, non-mutating) and neither is weakened here: only their TEXT grows, so the
    refusal that fires teaches the whole invocation instead of one half of it.

    Appended to a REFUSAL ONLY, never to a success path — an advisory that always printed would be
    noise, and noise gets skimmed (the erosion this exists to prevent; the differential acceptance arm).
    The identity call-site additionally gates on the ENUMERATED fact `_is_consumer_build()` (a `-C`
    consumer target is in play — the common-dir test, so an engine linked worktree is NOT one, T-0952 /
    T-11027; the call-site has always used it, this sentence used to name the retired path inequality),
    never on message text, so an engine-local identity refusal is byte-unchanged."""
    return "\n".join([
        "",
        "BOTH consumer-side carriers travel together — they fail INDEPENDENTLY, so getting one right",
        "proves nothing about the other (T-11011 / X-0843):",
        "  1. -C <consumer-repo>            the corpus target (else the foreign-corpus guard refuses)",
        f"  2. {SELF_REF_ENV}=<your ref>   the session-identity carry (else the identity gate refuses)",
        f"Fully-carried form:  {SELF_REF_ENV}=$REF {ENGINE_ROOT}/bin/yitc-v2 -C <consumer-repo> <verb>",
        f"(`{SELF_REF_ENV}` is printed by `session start`; env does NOT cross the harness's per-call",
        "subprocesses, so it is re-supplied on EVERY call.)",
    ])


# T-13485 — the foreign corpus root the X-0093 guard DETECTED and ADMITTED on this invocation (one of
# the explicit-target release verbs run bare from inside a consumer checkout); None on every other
# call. Set by the guard alone, read by `_release_first_install_emit` alone.
_BARE_FOREIGN_CORPUS_ROOT: "Path | None" = None


def _explicit_target_release_verb(args: argparse.Namespace) -> bool:
    """The release verbs whose EVERY target is an argument — `release verify <dest>`,
    `release install <dest> --into <path>`, `release update <dest> --into <path>` — keyed on the
    FUNCTION OBJECT (the seed-gate clause (d) / `report_only_pin` construction), so the X-0093
    admission below is verb-scoped by identity and cannot widen without editing this line.

    DELIBERATELY NARROWER than `_adopter_release_verb`: that set also holds `cmd_release_check`, which
    takes NO argument — its subject is REPO_ROOT, the `-C <project>` target. Run bare from a consumer
    checkout it would report on the ENGINE and read as an answer about the project, which is the
    "silently acts on a different repo than the one you are in" half of X-0093. So it stays refused,
    and the refusal prints the `-C <root>` form it needs."""
    return getattr(args, "func", None) in (cmd_release_verify, cmd_release_install, cmd_release_update)


def _guard_bare_invocation_foreign_corpus(admit_explicit_target: bool = False) -> None:
    """REFUSE a BARE invocation (no `-C` flag AND no YITC_REPO_ROOT) made from INSIDE a FOREIGN yitc
    corpus — a consumer checkout/worktree. Without `-C`, REPO_ROOT resolves to the ENGINE install
    location (Path(__file__).parent.parent), so a bare `yitc-v2 <verb>` run from a consumer worktree
    silently acts on the ENGINE corpus + writes the KERNEL's events.jsonl (X-0093 — a recurrence of
    the 2026-06-23 `consumer-session-verb-missing-C-silently-acts-on-engine-repo` deviation; ~22
    stray kernel-journal lines during <project> T-0082).

    Robust foreign-detection reuses the git COMMON-DIR comparison (the SAME marker as
    `_is_consumer_build` / SPEC-0078), NOT a bare "cwd owns an events.jsonl" (the audit-pre finding:
    that key is too weak): an engine LINKED WORKTREE shares the engine common-dir and is NOT foreign
    (no false refusal); only a SEPARATE repository (different common-dir) is foreign. Fires ONLY when
    BOTH explicit targets are absent. No-op (byte-identical) when an explicit target is set
    (YITC_REPO_ROOT / `-C`, the latter handled by the caller), cwd is not in git, cwd is the engine
    or an engine worktree, or cwd is a foreign NON-yitc git repo (not ours to guard). The fix the
    refusal names is to target the corpus explicitly with `-C`. Sibling of the SPEC-0078
    consumer→engine write guard (REFUSE design — auto-bind was rejected: it would contradict the
    documented no-cwd-auto-detect rule and could silently act on a different repo than invoked).

    THE ONE ADMISSION (T-13485): `admit_explicit_target` — passed True by `main()`
    for `_explicit_target_release_verb` only. Those verbs never read REPO_ROOT (every target is an
    argument), and the published upgrade recipe is run from the project being upgraded, so refusing
    them contradicted the verbs' own "from any checkout" contract. DETECTION IS UNCHANGED and the
    admission is taken ONLY after a foreign yitc corpus was positively detected: the guard then
    RECORDS the detected root in `_BARE_FOREIGN_CORPUS_ROOT` instead of refusing, and that record is
    what makes `_release_first_install_emit` drop its engine-journal fallback on the same call. So
    the half of X-0093 that is a WRITE into the kernel journal stays impossible by construction —
    the waiver and the drop are one branch."""
    if os.environ.get("YITC_REPO_ROOT"):
        return  # explicit env target — honored (test-override / deliberate engine retarget)
    # ORDERING (T-12297, closing T-0677 / E-0010 manifestation D). This guard runs from `main()`,
    # UPSTREAM of `cmd_land`'s re-root at REPO_ROOT — so it is the FIRST thing to dereference the
    # process cwd. A land that inherited a SINCE-REMOVED cwd (the caller shell was standing in a
    # worktree a PRIOR land deleted) therefore died right here, with FileNotFoundError out of
    # os.getcwd(), putting the string "getcwd" into the land's OWN output — exactly the noise the
    # cwd-safety invariant forbids. An UNREADABLE cwd is not a foreign corpus: there is no cwd to be
    # INSIDE of, and REPO_ROOT has already resolved from the script path (`__file__`), so fall
    # through to the re-rooted path instead of raising. WHAT this guard refuses on a foreign corpus
    # is unchanged — only the unreadable-cwd case is added, and the cwd is read ONCE here so no
    # later line can re-raise it.
    try:
        cwd = Path.cwd()
    except FileNotFoundError:
        return  # the process cwd was removed — nothing foreign to detect (T-12297)
    cwd_common = _git_common_dir(cwd)
    if cwd_common is None:
        return  # cwd is not inside a git checkout — nothing foreign to detect
    if cwd_common == _git_common_dir(ENGINE_ROOT):
        return  # the engine itself, or an engine LINKED WORKTREE (same common-dir) — byte-identical
    # cwd is a SEPARATE repository. Refuse ONLY if it is a yitc corpus — keyed on the yitc-SPECIFIC
    # journal `events.jsonl` at the repo root (born by `init` in every consumer; the audit-post finding:
    # a bare `specs/` dir is too GENERIC — many non-yitc repos carry one — so it is NOT a corpus marker).
    import subprocess
    try:
        top = subprocess.run(["git", "-C", str(cwd), "rev-parse", "--show-toplevel"],
                             capture_output=True, text=True, check=False)
        root = Path(top.stdout.strip()) if top.returncode == 0 and top.stdout.strip() else cwd
    except (FileNotFoundError, OSError):
        root = cwd
    if (root / "events.jsonl").exists():
        if admit_explicit_target:
            # T-13485: admitted, and RECORDED — the emit helper reads this to drop the engine journal.
            global _BARE_FOREIGN_CORPUS_ROOT
            _BARE_FOREIGN_CORPUS_ROOT = root
            return
        # T-11011: this arm is a CONSUMER context by construction (cwd is a foreign yitc corpus), so the
        # carrier-pair advisory always applies here — it names carrier 2 the operator has not hit YET.
        _die(f"bare yitc-v2 run from a FOREIGN yitc corpus ({root}) — without -C it resolves to the "
             f"KERNEL repo ({ENGINE_ROOT}) and would pollute its journal (X-0093). Target the corpus "
             f"explicitly: `{ENGINE_ROOT}/bin/yitc-v2 -C {root} <verb>` (or cd into the engine)."
             + _consumer_carrier_pair_advisory())


def _is_consumer_build() -> bool:
    """True iff this graph build targets a CONSUMER checkout rather than the engine's own corpus
    (T-0849, friction F-001). A consumer build is one where REPO_ROOT (possibly rebound by the
    `-C <path>` global flag) points at a DIFFERENT REPOSITORY than ENGINE_ROOT (the engine's own root,
    captured at import — honoring the YITC_REPO_ROOT test-override, so the engine-clone test sandbox
    is NOT a consumer). On a consumer build the kernel-derived structural layers (verb_to_specs /
    floor_trigger_map / binding_report — derived from the engine constants BINDING_VERB_SURFACES /
    FLOOR_TRIGGERS, non-zero even on an EMPTY consumer) are attributed as kernel-provided so they are
    not mistaken for project-derived. Engine self-build (REPO_ROOT == ENGINE_ROOT) → False → unchanged.

    T-0952: a `-C <path>` flag pointing at one of the engine's OWN linked WORKTREES rebinds REPO_ROOT
    to the worktree while ENGINE_ROOT stays the main checkout, so a bare `REPO_ROOT != ENGINE_ROOT`
    mis-flags an engine worktree as a consumer — stamping the engine's OWN derived floor trigger-map
    with the kernel banner, which then LANDS to main (graph/floor-trigger-map.md is bookkeeping-folded)
    and RED-fails every subsequent `graph conformance` (floor-map-drift) → false land-ABORT. A linked
    worktree of the engine IS the engine: same git common-dir == same repo. Compare common-dirs (not
    bare paths) so an engine worktree is never a consumer. A GENUINE consumer is a separate repository
    (different common-dir → True); a non-git sandbox (rev-parse fails → None) falls back to the path
    inequality (still a consumer), unchanged from before."""
    if REPO_ROOT == ENGINE_ROOT:
        return False
    key = (str(REPO_ROOT), str(ENGINE_ROOT))
    if key in _consumer_build_cache:
        return _consumer_build_cache[key]
    repo_common, engine_common = _git_common_dir(REPO_ROOT), _git_common_dir(ENGINE_ROOT)
    same_repo = repo_common is not None and repo_common == engine_common
    result = not same_repo
    _consumer_build_cache[key] = result
    return result


# The kernel-derived STRUCTURAL layers whose shape comes from the engine constants, not the consumer's
# own specs (T-0849). Named ONCE here so the index marker, the floor-map note, and the probe agree.
KERNEL_DERIVED_LAYERS = ("verb_to_specs", "floor_trigger_map", "binding_report")


# ── Engine CONTENT resolution for a -C consumer (T-0860, friction F-010/F-011/F-012) ───────────────
# A -C consumer rebinds REPO_ROOT (+ SPECS_DIR / PATTERNS_DIR / templates) to the consumer, which
# pre-extraction LACKS the kernel's methodology CONTENT (specs for `graph query`, patterns, scaffolding
# templates, the SPEC-0036 gate-template). These READ-ONLY resolvers fall back to ENGINE_ROOT (the
# engine's own root, captured at import — never rebound) when the consumer lacks a file. PER-FILE /
# PER-ID, NOT an all-or-nothing dir swap (audit-pre F1): a consumer-OWNED file wins by path while a
# MISSING kernel file still resolves from the engine, so a mixed consumer+kernel corpus works. They
# make the read-gate's SUBJECTS FETCHABLE for a consumer (`graph query <kernel-spec> -C` now resolves
# + emits the pass-granting cli_invoked); the read-gate DOC-SET itself is deliberately NOT engine-
# merged — it stays the checkout's OWN binding views, so a consumer's gate fires once it owns the
# spec (post-extraction), and the engine's own `-C`-driven flows + the whole test suite are
# behaviour-unchanged (the no-regression bound — a doc-set merge would make every `-C` checkout's
# commit/close read-gate fire). WRITE / activation paths also do NOT use these (they stay engine-
# blind — a consumer worktree must never resolve-then-overwrite an engine file; territory isolation).
# Engine self-build (REPO_ROOT == ENGINE_ROOT) is byte-unchanged: every fallback branch is guarded by
# _is_consumer_build() and is unreachable there.
#
# T-9313 (friction F-018) — THE -C ENGINE-PATH CONTRACT FOR ENGINE-OWNED CONFIG UNDER bin/. This is the
# documentation home of the rule "engine-OWNED config/data resolves at the ENGINE install path under -C".
# The engine's own config files under bin/ are owner-editable DATA the engine reads, NOT consumer
# content — so they route through THIS resolver (own-wins-else-engine). The 3 such configs:
#   bin/audit-config.yaml        — external-auditor model/provider bindings (audit verb; _resolve_audit_*)
#   bin/effort-routing-config.yaml — effort-tier -> (model, effort) for dispatch (the cited F-018, which
#                                    HARD fail-closed at the consumer path: no bin/ -> SPEC-0072 refusal)
#   bin/pricing-config.yaml      — per-model token rates for the token-rollup view (_view_token_rollup)
# They are bound through this resolver at the -C rebind + at the pricing read-site, so each resolves at
# ENGINE_ROOT/bin under -C. A consumer MAY still vendor its own override (own-wins). All OTHER engine
# content already routes through the sibling kernel-content resolvers; these 3 configs were the last
# REPO_ROOT-literal stragglers (audited exhaustively in T-9313).
def _kernel_content_file(rel: str) -> Path:
    """Resolve a single kernel CONTENT file (a scaffolding template) for the current checkout, with an
    ENGINE_ROOT fallback for a -C consumer that lacks it. Project-own WINS: REPO_ROOT/<rel> when it
    exists; else, on a consumer build, ENGINE_ROOT/<rel> when THAT exists; else REPO_ROOT/<rel> (the
    non-existent own path — the caller reports the miss)."""
    own = REPO_ROOT / rel
    if own.exists():
        return own
    if _is_consumer_build():
        eng = ENGINE_ROOT / rel
        if eng.exists():
            return eng
    return own


def _kernel_spec_ids() -> frozenset:
    """T-10106 (X-0209): the set of KERNEL SPEC ids for the current checkout, used by the T-9629 spec→spec
    `cites:` dangling sweep to resolve a legit consumer→kernel cite (SPEC-0073 §1 / SPEC-0074 §4) before
    flagging it dangling. On a -C CONSUMER build, enumerate ENGINE_ROOT/specs/SPEC-*.yaml and parse the
    bare SPEC-NNNN id from the filename prefix (mirrors _kernel_content_file / _kernel_pattern_path
    ENGINE_ROOT resolution). On an ENGINE self-build there is no realm split (the kernel corpus IS the
    consumer corpus already in `specs`), so return empty — the sweep is then a pure no-op change."""
    if not _is_consumer_build():
        return frozenset()
    ids = set()
    for p in state.scan_specs(ENGINE_ROOT / "specs"):
        m = re.match(r"(SPEC-\d{4,})", p.name)
        if m:
            ids.add(m.group(1))
    return frozenset(ids)


def _kernel_spec_statuses() -> dict:
    """T-10933: {SPEC-id: status} for the KERNEL spec corpus — the STATUS-bearing sibling of
    `_kernel_spec_ids`, used by `_compute_scenario_status` to resolve a consumer scenario's cite of a
    kernel spec (SPEC-0076 §3 status derivation) the way T-10106/T-10817 already resolve EXISTENCE.

    WHY a status map and not the id set: `cites_unresolved` only asks "does this id exist", so ids
    suffice there — the filename is enough and no YAML is opened. Status derivation asks WHICH status,
    and a kernel spec may be `proposed` / `superseded` / `retired`. Treating kernel PRESENCE as
    `active` would compute `live` for a scenario resting on a retired rule — wrong in the opposite
    direction from the under-reporting this fixes. (The tempting shortcut "the release export slice is
    active-only, so anything a consumer pins is active" does NOT hold for this source: like its
    sibling, this reads the RAW ENGINE_ROOT/specs dev corpus, not `_release_view_spec_ids()`'s
    active∩kernel slice.)

    ONE id source of truth (CHARTER §P5): the id set comes from `_kernel_spec_ids()` rather than a
    second glob-and-parse — so the two helpers can never disagree about WHICH ids are kernel, and a
    test that rebinds `yitc._kernel_spec_ids` (as test_t1100_broken_cite / test_t9629 do) is honored
    here too. Empty on an ENGINE self-build because that sibling is empty there — a pure no-op outside
    `-C`, exactly like it. Reads the corpus in ONE directory pass keyed by id prefix, not a glob per
    id. A known-kernel id whose YAML is unreadable or carries no `status:` maps to "" — which fails
    closed to non-active at the reader, never to `active`."""
    ids = _kernel_spec_ids()
    if not ids:
        return {}
    out = {sid: "" for sid in ids}
    for p in state.scan_specs(ENGINE_ROOT / "specs"):
        m = re.match(r"(SPEC-\d{4,})", p.name)
        if m and m.group(1) in out:
            out[m.group(1)] = str((_read_yaml(p) or {}).get("status") or "")
    return out


def _kernel_handbook_file(rel: str) -> Path:
    """Resolve a METHODOLOGY-HANDBOOK SEED file (the CHARTER/AGENTS/LIFECYCLE/QUEUE/GRAPH handbook + the
    floor trigger-map) for the current checkout. UNLIKE _kernel_content_file (own-wins-else-engine — correct
    for scaffolding TEMPLATES a consumer may legitimately vendor), the methodology handbook is KERNEL-OWNED
    and a consumer never authors it — so for a -C consumer it resolves from ENGINE_ROOT **unconditionally**
    (engine-ALWAYS), never shadowed by a same-named PROJECT file. The collision this guards is real: a
    consumer's own `CHARTER.md` is its PRODUCT charter, a DIFFERENT document; own-wins would shadow the
    methodology CHARTER (the 8 principles + the voicing anchors) with it (T-0996 / friction F-002).

    For a -C consumer the seed resolves from the CLEAN RELEASE-VIEW (`ENGINE_ROOT/release-view/<rel>`),
    NOT the raw `ENGINE_ROOT/<rel>` handbook (T-1014, SPEC-0074 §7 / F-002 part 2): the raw engine
    handbook carries V2-dev provenance (`from: T-`, D-/T- citations, host paths) a consumer must not
    read; the release-view is the identity-agnostic methodology contract (`_build_release_view`). No
    REPO_ROOT fallback in consumer mode — and NO raw-handbook fallback either: a missing release-view
    file FAILS CLOSED (the caller reports the miss against the release-view path) rather than silently
    resolving to either the consumer's product file or the dev-entangled raw engine handbook.
    Engine self-build (REPO_ROOT == ENGINE_ROOT) returns REPO_ROOT/rel — byte-identical to before."""
    if _is_consumer_build():
        # T-13492: `rel` is the SOURCE name; the view publishes a mapped part under its release-view name.
        return ENGINE_ROOT / RELEASE_VIEW_DIR / graph.release_view_name(rel)
    return REPO_ROOT / rel


def _kernel_pattern_path(name: str) -> 'Path | None':
    return graph._kernel_pattern_path(name, ENGINE_ROOT=ENGINE_ROOT, REPO_ROOT=REPO_ROOT, _is_consumer_build=_is_consumer_build)


_ENGINE_INDEX_CACHE: "dict | None" = None


def _engine_index() -> dict:
    """The ENGINE's own graph/index.json (ENGINE_ROOT/graph/index.json), loaded once and memoized — the
    fallback source for a -C consumer point-lookup of a kernel spec the consumer index lacks. Returns {}
    when absent/unreadable (the caller then reports not-found). Memo is process-local; the engine index
    is immutable for a CLI invocation's lifetime."""
    global _ENGINE_INDEX_CACHE
    if _ENGINE_INDEX_CACHE is None:
        path = ENGINE_ROOT / "graph" / "index.json"
        _ENGINE_INDEX_CACHE = (_read_yaml(path) or {}) if path.exists() else {}
    return _ENGINE_INDEX_CACHE


def _kernel_overlay_files(subdir: str, pattern: str) -> list:
    """The DIRECTORY-granularity sibling of _kernel_content_file (T-0865): the ENGINE_ROOT/<subdir>
    files matching glob <pattern>, returned ONLY on a -C consumer build (else []). It is the read-only
    SOURCE for the kernel-overlay DELIVERY readers — `graph query --type view` (_list_views) and the
    `stage <NAME>` bundle (_stage_bundle_specs / _stage_bundle_patterns) — which merge these UNDER their
    own files so that kernel specs/views are DISCOVERABLE on a blank consumer, not just point-resolvable.
    The CALLER owns the own-WINS dedup by its identity key (spec id / pattern name / view name) — this
    helper only supplies the engine candidates. DELIVERY-only: the read-gate DOC-SET (_require_reads via
    _stage_bundle_specs default) does NOT pass these through, so a consumer's commit/close gate still
    fires only on OWNED specs (the T-0860/T-0864 no-regression bound). Empty on engine self-build
    (REPO_ROOT == ENGINE_ROOT → not a consumer) so the engine's own delivery is byte-unchanged. Reuses
    ENGINE_ROOT / _is_consumer_build()."""
    if not _is_consumer_build():
        return []
    d = ENGINE_ROOT / subdir
    return sorted(d.glob(pattern)) if d.is_dir() else []


