# consume these globals at call-time, inside main()).
_AUDIENCE_VIEW_DERIVED_PATHS = frozenset(
    f"{GRAPH_DIR}/{n}" for n in graph.audience_view_files(ENGINE_ROOT / GRAPH_DIR))
_DERIVED_MERGE_ARTIFACTS |= _AUDIENCE_VIEW_DERIVED_PATHS
