def _parse_iso_utc(s: "str | None"):
    """Parse an ISO-8601 ts/date to a tz-AWARE UTC datetime — the single window-boundary normalizer
    (audit-pre pass-2 F0: the same query must slice the SAME window on every host). A bare date
    (`2026-06-01`) means that day's MIDNIGHT UTC; a naive datetime is ASSUMED UTC; a tz-qualified
    one is converted to UTC. Returns None for a falsy input. Raises ValueError on an unparseable
    string (the caller `_die`s with a clear message)."""
    if not s:
        return None
    import datetime as _dt
    txt = str(s).strip()
    iso = txt.replace("Z", "+00:00") if txt.endswith("Z") else txt
    try:
        d = _dt.datetime.fromisoformat(iso)
    except ValueError:
        d = _dt.datetime.fromisoformat(iso + "T00:00:00")   # bare date → midnight
    if d.tzinfo is None:
        d = d.replace(tzinfo=_dt.timezone.utc)
    return d.astimezone(_dt.timezone.utc)
















# T-0603 (SPEC-0059): the LOCKED canonical read_gate_refused `kind` enum (SPEC-0025 / SPEC-0059 — the
# three blocking legs of the universal stage contract). The discipline-ratio lens emits ONE ratio PER
# kind — NEVER a single mixed ratio summing them (plan-check F3). All three are ALWAYS reported, even at
# zero (fail-visible: a zero verification-exists ratio is shown, never silently absent).
# The T-0531 interim literal "stage" is the read-check leg's PRE-reconciliation name (the
# `_emit_read_gate_refused` docstring: the "stage" literal is reconciled to "read-check"). Fold it so
# the historical read-check refusals bucket into the MAIN read-check ratio, not an other-bucket.




def _iter_events(events_path: "Path | None" = None, *, types=None, pred=None, segment_cache=None):
    """Yield parsed events.jsonl records (dicts), skipping blank/un-parseable lines. The SAME
    per-line json.loads reader as cmd_journal_query (Principle 1 — one journal reader, no new
    parse path). Physical order is preserved; callers that need chronology sort by `ts`.
    `events_path` (T-0603, additive) defaults to the live `EVENTS_PATH`; a caller may pass an explicit
    path to read an ISOLATED journal (e.g. a view-lens test sandbox) through the SAME single reader.
    `types` (T-13139) DECLARES the event types the caller reads — `journal.segment_rows`' declared
    form: only those rows, served from the debt seam's one-pass scope or one bounded walk.

    T-13296 — two more declarations, both requiring `types`, both no-ops at their default:
    `pred` keeps only the rows the caller's OWN filter keeps, applied per row while walking
    (`journal.scan_journal`), so a caller that wants one ref's rows never holds the corpus;
    `segment_cache` is a caller-owned dict scoped to ONE decision. Each segment's kept rows are held
    there under the segment's stat signature (inode, size, mtime_ns) — stored only when the signature
    taken BEFORE the walk equals the one taken AFTER it, i.e. the bytes did not move under the read.
    A repeat call re-walks a segment only when its signature changed: an append, an in-place rewrite
    (the T-10409 torn-read case a retry exists for) or a new segment after a rotation. Unchanged bytes
    are never folded twice, and changed bytes are never served stale."""
    path = events_path if events_path is not None else EVENTS_PATH
    if types is not None and (pred is not None or segment_cache is not None):
        segs = tuple(events.segment_paths(path))

        def _walk(walked):
            # The fold family's own line source: streamed, and an undecodable line is skipped, never raised.
            return journal_mod.scan_journal(path, types=types, pred=pred, lines=journal_mod._FoldLineSource(walked),
                                            collector=journal_mod.ListCollector())

        def _sig(seg):
            try:
                st = os.stat(seg)
            except OSError:
                return None
            return (st.st_ino, st.st_size, st.st_mtime_ns)

        if segment_cache is None:
            yield from _walk(segs)
            return
        for seg in segs:
            before, held = _sig(seg), segment_cache.get(seg)
            if before is not None and held is not None and held[0] == before:
                yield from held[1]
                continue
            rows = _walk((seg,))
            if before is not None and _sig(seg) == before:
                segment_cache[seg] = (before, rows)
            else:
                segment_cache.pop(seg, None)
            yield from rows
        return
    # T-11453 — the physical read is the ONE shared fold (`journal.fold_rows`), so inside a
    # `rows_memo` scope this reader and its ~14 debt-echo siblings parse the journal once between
    # them instead of once each. Outside a scope it is a plain fold of the same file: this is the
    # SAME reader re-pointed at a memo of its own result, never a second parse path (Principle 1).
    # The missing-file case and the non-dict skip are the fold's, unchanged.
    # T-11444 — and that fold now spans the SEGMENT SET (`journal.segment_rows`, SPEC-0190 rule 4):
    # this is the single edit that makes all 17 iterator call sites A1's census names segment-aware,
    # since every one of them reaches the journal through here. `segment_rows` folds each segment
    # through the SAME `fold_rows` primitive, so the memo collapse above is unchanged. With rotation
    # off and no archive the set is `(path,)` and this is byte-for-byte the previous read.
    rows = (journal_mod.segment_rows(path) if types is None
            else journal_mod.segment_rows(path, types=types))
    for e in rows:
        if isinstance(e, dict):
            yield e


# T-10396 — the read-gate/receipt machinery's TAIL-WINDOWED snapshot (the sibling of T-10387's
# tail-window for the recency STATUS readers; same primitive, `journal._tail_window_start`, REUSED —
# no second window implementation, P1 F1).
#
# The gate helpers (`_session_started_lower_bound` / `_fetched_spec_ids` / `_seed_receipt_epochs`)
# each parsed the WHOLE journal (~90MB / 200k lines here): measured 0.89s per scan, so
# `_ref_current_epoch_anchored` (anchor + receipts) cost 1.79s and EVERY gated verb materialized
# `list(_iter_events)` per candidate journal. Receipts are session/epoch-scoped, so the physical read
# can be bounded to the journal TAIL.
#
# WHY THE WINDOW IS SAFE AT ANY SIZE (this is NOT the T-10387 fail-closed bound — it is stronger).
# The window here carries NO correctness role; it is a PURE PERFORMANCE knob. The caller pairs it with
# a full-read fallback, and the pairing is exact by MONOTONICITY:
#   - a tail snapshot is a SUFFIX of the full one, so the earliest anchor it can find is >= the true
#     one (it can MISS an older anchor; it can never INVENT one) — i.e. lb_tail >= lb_full;
#   - every receipt predicate is `ts >= lower_bound`, so a LATER lower-bound only ever EXCLUDES
#     receipts — it can turn a PASS into a REFUSE, never a REFUSE into a PASS;
#   - therefore a tail-window CREDIT is provably also a credit under the full read (SOUND — a tail
#     pass is never a false credit), while a tail-window REFUSAL may be a FALSE refusal.
# So the caller may TRUST a tail credit, and MUST re-decide a tail refusal on the full snapshot.
# Semantics are preserved EXACTLY (a stale-epoch receipt still refuses: it fails on the tail, the
# fallback re-reads in full, and it still fails) — a mis-sized window can only cost a fallback read,
# never change a verdict. Shrinking/growing `_GATE_TAIL_WINDOW_SEC` is therefore a safe tuning act.
# SIZING THE WINDOW — measured, not chosen by taste (T-11329, 2026-08-25). The original 7 days was
# INERT on the engine: against the live 44.5MB / 81667-line journal `journal._tail_window_start` at a
# 7d cutoff returned start=0, i.e. the "fast path" parsed 100% of the file. The live segment WAS THEN
# younger than 7 days (SPEC-0190 rotation), so the declared horizon EQUALLED the live window and cut
# nothing — which is why T-11327 measured the PASS arm at 0.937s, a full parse wearing a fast-path
# name. Tail bytes by cutoff on that journal: 7d 100.0% | 3d 39.1% | 2d 39.1% | 1d 9.1% | 12h 9.1%.
# The ONLY cost a smaller window can add is a full-read FALLBACK for a call whose `session_started`
# anchor predates it — same verdict, one extra read (see the monotonicity proof above). Counted
# CALL-weighted over all 81676 journal rows (each row's age since its own session_ref's first row),
# the fraction of calls whose anchor falls OUTSIDE the window is: 12h 18.12% | 1d 14.36% | 2d 8.85% |
# 3d 6.80% | 7d 0.67%. Expected relative bytes = P(in)*tail + P(out)*(tail+full) gives 1d 0.235
# (4.2x cheaper), 12h 0.272, 2d 0.479, 3d 0.459 — so ONE DAY is the optimum of the measured grid.
# Re-derive with `journal._tail_window_start` + the same call-weighted count if the journal's shape
# changes; nothing here is a correctness input, so re-tuning it needs no re-proof of the gate.
_GATE_TAIL_WINDOW_SEC = 24 * 60 * 60       # PERFORMANCE ONLY (see above): how far back the fast path
                                           # looks before it falls back to the full read. Sized by the
                                           # measurement above so an ordinary session's
                                           # `session_started` anchor sits inside it; a longer-lived
                                           # session merely pays the full read it already pays today.


# ── T-13289: the SESSION-HORIZON read of the per-invocation preamble (SPEC-0190 rules 4 + 10) ────────
# Every reader the preamble runs over a journal — the seed-read gate, the help-read gate and the
# carried-ref backing check (`_ref_current_epoch_anchored`, reached by the session-ref resolution and
# by the cli_invoked envelope) — admits ONLY rows whose `session_ref` equals the ref being decided
# (`gates._session_started_lower_bound` / `_fetched_spec_ids` / `_seed_receipt_epochs`). The 24h tail
# each of them used to take parsed and HELD every row of that window (measured 2026-09-30 on the
# kernel: ~1.1 s and a 265 MB maxrss on `task show`, whose own work is a card read), and the same
# window was folded again by the next reader. Now ONE backward walk per (journal, ref) serves them all:
# newest segment first, block by block, skipping any block that cannot hold one of the ref's rows,
# keeping only those rows — and it stops as soon as the CALLER's own credit test (`settled`) holds.
#
# WHY STOPPING ON CREDIT IS SOUND, and why the walk is the SESSION HORIZON. Walking backward only ever
# ADDS older rows. For the three readers that is monotone toward credit: an older `session_started`
# can only LOWER the earliest-anchor bound (admitting more receipts), an older receipt can only add
# an entry — so once the rows seen credit, no older row can un-credit them (the suffix argument the
# 24h tail already rested on: a credit on a suffix is a credit on the whole). The walk therefore reads
# back exactly as far as this session's own evidence needs — to the anchor that makes the credit, even
# when that is an EARLIER anchor of a session that re-ran `session start`, or an anchor in an ARCHIVE
# segment. A walk that never credits stops at the SPEC-0190 SUMMARY WINDOW (T-13331, owner 2026-10-01):
# it never opens a segment wholly older than the window, whatever the anchor's shape — a refusal is
# fail-closed and cheap to recover (`session start` / `--help`), so it needs no exact first start, and
# crediting keeps "this session, after its start" with the start found INSIDE the window (a reused
# ref's run older than the window cannot credit the current run). It still answers
# `bounded=True` — never "this was the full read" — so the caller's unchanged full-read retry loop
# (T-10115: exactly `_READ_GATE_RETRY_ATTEMPTS` full reads decide every refusal) is untouched: the walk
# only ever makes a CREDIT cheaper, a refusal is decided exactly as before.
#
# The block pre-filter is `journal._prefilter_needle`'s proof narrowed to the escapes that can spell
# ASCII: a line decodes to the string `ref` (only `[A-Za-z0-9_.:-]`) only if it holds the verbatim
# `"<ref>"` or a `\u00XX` escape, so a line or block with neither is skipped unparsed.
_SESSION_TAIL_TLS = threading.local()


@contextlib.contextmanager
def _preamble_read_scope():
    """THE ONE request-scoped ReadScope of the invocation preamble (SPEC-0190 rule 10, T-13289) —
    installed by `main()` at the CLI entry wiring site, so the seed gate, the help gate, the ref
    backing check and the envelope resolution RESUME one backward walk of each journal instead of each
    folding it. Not a cache: it lives exactly as long as the request, is thread-local with the prior
    value saved and restored (the `rows_memo` discipline), and a walk is resumed only while its live
    segment's (size, mtime_ns) is the one it started at — a changed journal starts a new walk."""
    prior = getattr(_SESSION_TAIL_TLS, "scope", None)
    _SESSION_TAIL_TLS.scope = {}
    try:
        yield _SESSION_TAIL_TLS.scope
    finally:
        _SESSION_TAIL_TLS.scope = prior


class _SessionWalk:
    """ONE backward walk of `ref`'s rows over the segment set of the journal at `path` (see above).
    Resumable: `rows_until(settled)` continues from where the previous call stopped, so every reader
    in the request shares ONE physical pass. Each segment's read is reported through
    `journal_mod.note_fold` once, when the walk leaves it (or at the stop inside it).

    The live segment is walked from its last NEWLINE down; an unterminated final line (a row caught
    mid-append) is parsed on its own and re-read by `refresh`, so it is never lost nor duplicated."""

    _BLOCK = 1 << 20

    def __init__(self, path: Path, ref: str, *, peer: "_SessionWalk | None" = None):
        self.ref = ref
        self._needle = f'"{ref}"'.encode()
        # T-13331 — the walk's HORIZON is the SPEC-0190 SUMMARY WINDOW (rule 4 class 2): no segment
        # wholly older than it is ever opened, the refusal walk included, whatever the anchor's shape.
        self._since = events.summary_window_floor()
        self._segs = list(reversed(events.segment_paths_since(path, self._since)))  # live first
        self._blocks: list = []          # kept rows per block, in WALK order (newest block first)
        self._seg = -1
        self._pos = 0
        self._carry = b""
        self._fh = None
        self._scanned = 0
        self._t0 = 0.0
        self._reported: set = set()
        self._sigs: dict = {}            # seg index -> (size, mtime_ns, ino) when last validated
        self._live_end = 0               # live-segment offset just past its last complete line
        self._live_tail: list = []       # rows parsed from the unterminated bytes after `_live_end`
        self._live_digests: list = []    # (start, end, digest) of every live byte range the walk read
        self.exhausted = False
        self._head = None                # T-13370 — (start, end, bytes) of the newest live block read
        self._tail_raw = b""             # T-13370 — the unterminated live bytes after `_live_end`
        self._lazy = False               # T-13370 — positioned in the live segment, file not yet opened
        if peer is not None:
            self._adopt_head(peer)

    def _adopt_head(self, peer: "_SessionWalk") -> None:
        """T-13370 — a second ref's walk in the same request starts from the newest live block the
        PEER walk already read (same segment set, same live signature — the caller checked the
        (size, mtime_ns) it keys walks by): that block is parsed for THIS ref without re-opening the
        live segment, and the file is opened only if this walk must go further back. The cron sweep
        carry's refusal walk is the peer; the seed gate's walk for the resolved session is this one —
        a fresh session settles inside the newest block, so it adds no second fold of the live
        segment. Nothing outlives the request: the bytes are the peer walk's own, held by the scope."""
        if peer._head is None or [str(p) for p in peer._segs] != [str(p) for p in self._segs] \
                or 0 not in peer._sigs:
            return
        start, end, raw = peer._head
        self._seg, self._lazy = 0, True
        self._sigs[0], self._live_end = peer._sigs[0], peer._live_end
        self._live_tail = self._keep(peer._tail_raw, live=True)
        self._tail_raw = peer._tail_raw
        self._head = peer._head
        self._live_digests.append((start, end, hashlib.blake2b(raw).digest()))
        self._pos = start
        if start > 0:
            nl = raw.find(b"\n")
            if nl < 0:
                self._carry, region = raw, b""
            else:
                self._carry, region = raw[:nl], raw[nl + 1:]
        else:
            self._carry, region = b"", raw
        kept = self._keep(region, live=True) if region else []
        if kept:
            self._blocks.append(kept)
        journal_mod.note_rows_parsed(self._scanned)
        self._scanned = 0

    def rows(self) -> list:
        return [e for kept in reversed(self._blocks) for e in kept] + self._live_tail

    @staticmethod
    def _sig(st) -> tuple:
        return (st.st_size, st.st_mtime_ns, st.st_ino)

    def _open_next(self) -> bool:
        self._close()
        while self._seg + 1 < len(self._segs):
            self._seg += 1
            seg = self._segs[self._seg]
            try:
                self._fh = seg.open("rb")
                st = os.fstat(self._fh.fileno())
                self._pos = st.st_size
                self._sigs[self._seg] = self._sig(st)
                if self._seg == 0:
                    self._pos = self._live_end = self._last_newline_end(self._fh, st.st_size)
                    self._fh.seek(self._live_end)
                    self._tail_raw = self._fh.read(st.st_size - self._live_end)
                    self._live_tail = self._keep(self._tail_raw, live=True)
            except OSError:
                if self._seg == 0:
                    raise                 # the live segment unreadable → the caller's full read
                continue                  # an unreadable archive is skipped, as the resolver does
            self._carry, self._scanned, self._t0 = b"", 0, time.monotonic()
            return True
        return False

    def _last_newline_end(self, fh, size: int) -> int:
        pos = size
        while pos > 0:
            lo = max(0, pos - 65536)
            fh.seek(lo)
            nl = fh.read(pos - lo).rfind(b"\n")
            if nl >= 0:
                return lo + nl + 1
            pos = lo
        return 0

    def _report(self):
        """Account the rows parsed since the last report; the segment's FOLD is counted once — a walk
        resumed by a later reader continues the SAME physical pass over it, it does not re-read it."""
        journal_mod.note_rows_parsed(self._scanned)
        if self._seg not in self._reported:
            self._reported.add(self._seg)
            journal_mod.note_fold(self._segs[self._seg], self._scanned, time.monotonic() - self._t0)
        self._scanned, self._t0 = 0, time.monotonic()

    def _close(self):
        if self._fh is not None:
            self._report()
            self._fh.close()
            self._fh = None

    def _keep(self, region: bytes, *, live: bool) -> list:
        kept = []
        for raw in region.split(b"\n"):
            if self._needle not in raw and b"\\u00" not in raw:
                continue
            ln = raw.strip()
            if not ln:
                continue
            self._scanned += 1
            try:
                e = json.loads(ln)
            except ValueError:
                continue
            # T-13337: the window bounds SEGMENTS. The LIVE segment (`live`, stated by every caller —
            # never inferred from the walk position, which `refresh` reads past) is read WHOLE — rotation
            # keeps it <=7 days in production, and fixed-date fixtures stay visible. Only an ARCHIVE
            # segment straddling the floor (audit-pre fp1:e4d4387958097798) drops its pre-floor rows,
            # so a reused ref's run older than the window cannot credit the current run from it.
            if (isinstance(e, dict) and e.get("session_ref") == self.ref
                    and not (not live and self._since
                             and str(e.get("ts") or "") < self._since)):
                kept.append(e)
        return kept

    def _step(self) -> "bool | None":
        """Read ONE block. Returns True if it kept a row, False if not, None when the walk is over."""
        if self._lazy:
            # T-13370 — the adopted head did not settle this walk: open the live segment now, at the
            # offset the head stopped at, and only if it is still the file the peer read.
            self._lazy = False
            if self._pos > 0:
                self._fh = self._segs[0].open("rb")
                if self._sig(os.fstat(self._fh.fileno())) != self._sigs[0]:
                    self._fh.close()
                    self._fh = None
                    raise OSError("live segment moved since the peer walk read it")
                self._t0 = time.monotonic()
        if self._fh is None or self._pos <= 0:
            if not self._open_next():
                self.exhausted = True
                return None
        bstart = max(0, self._pos - self._BLOCK)
        self._fh.seek(bstart)
        raw = self._fh.read(self._pos - bstart)
        if self._seg == 0:
            self._live_digests.append((bstart, self._pos, hashlib.blake2b(raw).digest()))
            if self._head is None:
                self._head = (bstart, self._pos, raw)
        chunk = raw + self._carry
        self._pos = bstart
        if bstart > 0:
            nl = chunk.find(b"\n")
            if nl < 0:
                self._carry = chunk
                return False
            self._carry, region = chunk[:nl], chunk[nl + 1:]
        else:
            self._carry, region = b"", chunk
        if self._needle not in region and b"\\u00" not in region:
            return False
        kept = self._keep(region, live=self._seg == 0)
        if kept:
            self._blocks.append(kept)
        return bool(kept)

    def _live_prefix_intact(self, fh, st) -> bool:
        """Is every live byte the walk already read still the same? Cheap when nothing moved; else the
        read ranges are re-hashed (bytes only, no parse) — an in-place rewrite anywhere below the
        walked offset, not only near EOF, starts a fresh walk (T-10115)."""
        if self._sig(st) == self._sigs.get(0):
            return True
        if st.st_size < self._live_end:
            return False
        for lo, hi, digest in self._live_digests:
            fh.seek(lo)
            if hashlib.blake2b(fh.read(hi - lo)).digest() != digest:
                return False
        return True

    def refresh(self) -> "list | None":
        """The FULL-READ answer for the gates' refusal retries (fp1:72f442162d197019): finish the
        walk to the summary-window horizon, then take ONLY the rows appended to the live segment
        since the walk read it (streamed block by block, a line split across the old EOF re-joined) —
        never a re-fold. Returns None when the history is not provably the one walked plus appends
        (the segment set moved, an archive's signature changed, the live segment shrank, was replaced,
        or any byte the walk read changed — a torn / rewritten read, T-10115): the caller then starts
        a FRESH walk, so a torn read is still re-read, not trusted."""
        self.rows_until(None)
        if ([str(p) for p in reversed(events.segment_paths_since(self._segs[0], self._since))]
                != [str(p) for p in self._segs]):
            return None
        try:
            for i, seg in enumerate(self._segs):
                if i != 0 and i in self._sigs and self._sig(seg.stat()) != self._sigs[i]:
                    return None
            if 0 not in self._sigs:
                return self.rows()
            with self._segs[0].open("rb") as fh:
                st = os.fstat(fh.fileno())
                if st.st_ino != self._sigs[0][2] or not self._live_prefix_intact(fh, st):
                    return None
                pos, carry, fresh = self._live_end, b"", []
                fh.seek(pos)
                while pos < st.st_size:
                    raw = fh.read(min(self._BLOCK, st.st_size - pos))
                    if not raw:
                        break
                    self._live_digests.append((pos, pos + len(raw), hashlib.blake2b(raw).digest()))
                    pos += len(raw)
                    chunk = carry + raw
                    nl = chunk.rfind(b"\n")
                    if nl < 0:
                        carry = chunk
                        continue
                    carry = chunk[nl + 1:]
                    fresh.extend(self._keep(chunk[:nl + 1], live=True))
                self._live_end = pos - len(carry)
                self._live_tail = self._keep(carry, live=True)
                self._sigs[0] = self._sig(st)
        except OSError:
            return None
        journal_mod.note_rows_parsed(self._scanned)
        self._scanned = 0
        if fresh:
            self._blocks.insert(0, fresh)
        return self.rows()

    def rows_until(self, settled) -> "tuple[list, bool]":
        """Walk until `settled(rows)` holds or the history is exhausted → `(rows, True)` — always
        `bounded`, so a caller re-decides a refusal on its own full read (see the block above)."""
        if settled is not None and self._blocks and settled(self.rows()):
            return self.rows(), True
        while not self.exhausted:
            got = self._step()
            if got and settled is not None and settled(self.rows()):
                break
        if self._fh is not None:
            self._report()      # the stop is inside a segment: account what this request read
        return self.rows(), True


def _scoped_session_window(path: Path, ref: str, settled, full: bool):
    """T-13337 — the preamble's session rows SERVED BY THE REQUEST'S ONE SCAN (Controller decision
    2026-10-01T23:32:13Z, option 1). Inside a keep_all ReadScope (`task close` / `stage` / `task plan`
    install it around the whole invocation, T-13330) the journal is already walked once for the
    request; a `_SessionWalk` beside it read the live segment a SECOND time. So the seed gate, the help
    gate and the receipt emit take `ref`'s rows from that scope instead — no physical read of their own.

    The same window as the walk: rows of the LIVE segment whole, of an archive segment only those dated
    at or after the SPEC-0190 summary-window floor, and no segment wholly older than the floor. A
    credit is tried first on the scope's walked horizon (never extended for it — credit is monotone, as
    in `_SessionWalk`); a non-credit, and every FULL request, answers from the window, extending the
    same walk down to the floor when the scope's horizon is younger (recorded in `scope.extensions`).
    None when no keep_all scope holds `path` — the caller then walks for itself, as before."""
    scope = journal_mod.scope_of(path)
    if scope is None or not getattr(scope, "_keep_all", False):
        return None
    floor = events.summary_window_floor()
    day = floor[:10] if floor else None
    needle = f'"{ref}"'
    scope._ensure()
    live = len(scope._segs) - 1

    def _rows(since):
        out = []
        for _seq, seg, line in scope._keep_all_entries(since, reason="preamble"):
            if needle not in line and "\\u00" not in line:
                continue
            try:
                e = json.loads(line)
            except ValueError:
                continue
            if (isinstance(e, dict) and e.get("session_ref") == ref
                    and (seg == live or not floor or str(e.get("ts") or "") >= floor)):
                out.append(e)
        return out

    if not full and settled is not None:
        walked = scope.horizon
        rows = _rows(max(walked, day) if (walked and day) else (walked or day))
        if settled(rows):
            return rows, True
    return _rows(day), not full


def _iter_events_tail(events_path: "Path | None" = None, *, window_sec: int = _GATE_TAIL_WINDOW_SEC,
                      session_ref: "str | None" = None, settled=None, full: bool = False):
    """The tail-windowed twin of `_iter_events` — returns `(events, bounded)`.

    `events` is the parsed record list; `bounded` is True only when the physical read was actually
    NARROWED to a tail (a genuinely smaller snapshot than the full file). `bounded=False` means the
    snapshot IS the full file — the whole journal is younger than the cutoff, the file is missing, the
    boundary was unprovable, or the read failed — so a caller that would otherwise fall back to a full
    read can skip that redundant second pass (there is nothing more to see).

    The window boundary comes from `journal._tail_window_start`, which is itself FAIL-CLOSED: it returns
    0 (== read everything) unless it can POSITIVELY establish a cut, and it tolerates the journal's
    append disorder (a `land` union-merge appends an old-ts batch at the tail).

    WHEN THERE IS NO TAIL TO CUT, THIS *IS* THE FULL READER — it DELEGATES to `_iter_events` rather than
    re-implementing it (P5: one parse path; and it keeps a monkeypatched `_iter_events` authoritative, so
    an unbounded read is byte-identical to the pre-T-10396 one — the reason the read-gate's own
    torn-read/retry accounting is unchanged). Only a genuinely NARROWED read parses here, over the tail
    bytes alone, with the same per-line `json.loads` semantics (blank + unparseable lines skipped)."""
    # T-11444 / SPEC-0190 rules 4+6 — WHERE THE SEGMENT SET ENTERS THIS READER, and why not here.
    # The bounded fast path below reads the LIVE segment's tail and nothing else. That is correct
    # rather than a gap: this window carries NO correctness role (see the block above — it is a pure
    # performance knob whose contract is SOUNDNESS, a tail credit is provably also a full credit),
    # and rule 6 records that the tail reader measurably becomes MORE complete on the live segment.
    # The archive branch is reached through the FALLBACK: every unbounded path below delegates to
    # `_iter_events`, which folds the segment set. WHAT CARRIES THAT is the SOUNDNESS property
    # proved in the block above the constant — a tail snapshot is a SUFFIX of the full one, so a
    # tail CREDIT is provably also a full credit while a tail REFUSAL may be false — and soundness
    # holds at ANY window size, so this paragraph does NOT depend on how the declared horizon
    # compares to the live window.
    # A tail REFUSAL is already re-decided on that full snapshot by every caller, so no receipt that
    # lives in an archive segment can be lost to the fast path.
    # WITHDRAWN (T-11630): this paragraph used to rest on a different premise — that the DECLARED
    # horizon (stated as 7 days) EQUALS the live window, i.e. rule 4's equality case. T-11329
    # retuned `_GATE_TAIL_WINDOW_SEC` to 24h and that premise died with it: the sentence outlived
    # its number. Do not restore it — an equality argument is the wrong SHAPE here regardless.
    # OBSERVATION, NOT THE BASIS (measured 2026-08-29): at 24h the horizon is STRICTLY SMALLER than
    # the live window — the live segment then spanned ~7.6 days — so this reader does not even meet
    # rule 4's `horizon >= live window` archive-branch test. But that relation is a DRIFTING
    # empirical fact (rotation is size-bounded, SPEC-0190), so it is recorded to save the next
    # reader a measurement, NEVER to be reasoned from: any argument comparing the two is wrong
    # again at the next rotation — which is exactly how the withdrawn sentence went stale.
    path = events_path if events_path is not None else EVENTS_PATH
    if not path.exists():
        return [], False
    # T-12035 (SPEC-0190 rule 10) — CONSULT THE INSTALLED SCOPE BEFORE READING. Inside a composed
    # seam's ReadScope this journal is already folded ONCE for the request, so the tail seek below
    # would charge a SECOND physical fold of a segment the scope owns — measured at the session-start
    # debt echo, where the identity gate behind `_unresolved_halt_view` re-read the live segment
    # inside a correctly-installed scope. Delegating to the full reader is not a widening: the memo's
    # fold IS the whole file, and `bounded=False` says exactly that — the snapshot is the full file,
    # which is the honest answer and a SUPERSET of any tail (the soundness property this reader's
    # window already rests on). Outside a scope `rows_memo_holds` is False and the branch is inert,
    # so no caller's read shape moves.
    if journal_mod.rows_memo_holds(path):
        return list(_iter_events(events_path)), False
    # T-13289 — the SESSION HORIZON (see `_SessionWalk`). A ref the needle proof cannot cover keeps
    # the 24h window below, unchanged — and so does a history that fits in ONE walk block when no
    # preamble scope is installed: there is nothing to narrow and nothing to share, so the full reader
    # stays authoritative (T-10115's torn-read contract, above). Inside the scope the walk is shared.
    try:
        trivial = len(events.segment_paths(path)) <= 1 and path.stat().st_size <= _SessionWalk._BLOCK
    except OSError:
        trivial = True
    scope = getattr(_SESSION_TAIL_TLS, "scope", None)
    if session_ref and journal_mod._prefilter_needle(session_ref) and (scope is not None or not trivial):
        shared = _scoped_session_window(path, session_ref, settled, full)
        if shared is not None:
            return shared     # T-13337 — the request's one scan already holds this journal
        try:
            st = path.stat()
            key = (str(path.resolve()), session_ref)
            sig = (st.st_size, st.st_mtime_ns)
            held = scope.get(key) if scope is not None else None
            # T-13370 — another ref's walk of this same journal state in the request: a new walk
            # starts from the newest live block that walk already read (`_SessionWalk._adopt_head`).
            peer = next((w for (p, _r), (s, w) in (scope or {}).items()
                         if p == key[0] and s == sig and w._head is not None), None)
            if full:
                # fp1:72f442162d197019 — a refusal retry's FULL read resumes the request's walk
                # (see `_SessionWalk.refresh`); `bounded=False`: the answer IS the whole history.
                rows = held[1].refresh() if held is not None else None
                if rows is None:
                    held = (sig, _SessionWalk(path, session_ref, peer=peer))
                    rows = held[1].refresh()
                    if scope is not None:
                        scope[key] = held
                return (rows if rows is not None else list(_iter_events(events_path))), False
            if held is None or held[0] != sig:
                held = (sig, _SessionWalk(path, session_ref, peer=peer))
                if scope is not None:
                    scope[key] = held
            return held[1].rows_until(settled)
        except OSError:
            return list(_iter_events(events_path)), False
    if full:
        return list(_iter_events(events_path)), False     # a FULL request never takes the window
    cutoff = (_dt.datetime.now(_dt.timezone.utc)
              - _dt.timedelta(seconds=window_sec)).strftime("%Y-%m-%dT%H:%M:%SZ")
    # T-13330 — inside task close's keep_all ReadScope the live segment is ALREADY walked once for the
    # invocation: serve the window from it (its rows dated >= the cutoff — a SUBSET of the journal, so a
    # credit on it is a full credit, and `bounded=True` sends any non-credit to the full re-read, which
    # the same scope serves) instead of a second physical read of the live segment.
    scoped = journal_mod.scope_live_rows_since(path, cutoff)
    if scoped is not None:
        return scoped, True
    # T-12209 (SPEC-0190 rule 4) — ONE PHYSICAL READ OF THIS ARTIFACT, not two. `_tail_window_start`
    # json.loads EVERY line it walks backward over to find the ts boundary; this reader then seeked to
    # that offset and read + parsed the SAME lines a second time. Measured on this repo 2026-09-07
    # (98 segments / ~650k rows): one `_ref_current_epoch_anchored` credit cost folds 2, rows_parsed
    # 22493 over rows 14020 — ratio 1.604, BOTH folds on the live segment. That was the whole
    # ~1.6-1.8x floor every gated light verb paid, and 3.6x on `--help`, which asks twice. So the scan
    # now hands its rows back (`collect=`) and the window is built from them: no second open, no
    # second `note_fold`, no second parse.
    collected: list = []
    try:
        start = journal_mod._tail_window_start(path, cutoff, collect=collected)
        if start <= 0:
            return list(_iter_events(events_path)), False   # no bound → BE the full reader (P5)
    except OSError:
        # Any read fault degrades to the full reader — never a silent partial snapshot.
        return list(_iter_events(events_path)), False
    if collected:
        # The window, in FILE order, from the scan's own parse. `collect` arrives in SCAN order
        # (backward across blocks), so sort by byte offset; keep only what is at or past the boundary;
        # keep the SAME `isinstance(e, dict)` filter, so the admitted set is unchanged.
        #
        # TWO SEMANTIC DELTAS vs the seek-and-re-read this replaces, both stated rather than glossed,
        # and both SOUND under this reader's OWN monotonicity proof (see the block above the constant:
        # a tail snapshot is a SUFFIX of the full one, so a tail CREDIT is provably also a full credit
        # while a tail REFUSAL is re-decided by every caller on the full snapshot):
        #  1. ONE SNAPSHOT INSTEAD OF TWO. A row APPENDED between the scan and the window read is no
        #     longer seen. That can only ever NARROW the snapshot — credit → refusal at worst, never
        #     refusal → credit — and it makes the snapshot self-consistent, the same property
        #     `_dispatch_status_events` argues for at its own union.
        #  2. NO WHOLE-WINDOW STRICT DECODE. The removed path did `read().decode("utf-8")` and
        #     degraded the ENTIRE window to a full read on one bad byte. Parsing is now per line, and
        #     `_tail_window_start` catches `ValueError` (which covers `UnicodeDecodeError`), so a
        #     malformed line is skipped — narrowing the tail rather than widening it to the whole
        #     file. Narrowing is the sound direction, and the resulting refusal is re-decided on the
        #     full read anyway. It is also one less parse/decode path over the journal (CHARTER §P5).
        return [e for _off, e in sorted(collected, key=lambda t: t[0])
                if _off >= start and isinstance(e, dict)], True
    # FALL-SAFE — the scan proved a boundary but handed back nothing. Unreachable in practice (a
    # POSITIVE `start` IS the offset of a line whose `ts` parsed, so at least one row was collected),
    # and kept because the alternative is returning a silently EMPTY snapshot where the pre-change
    # reader returned the window — the same posture as the OSError degradation above. It is also the
    # differential handle the T-12209 regression mutates: perturb the collection and this branch
    # fires, the artifact is physically read a second time, and the fold bound reddens.
    try:
        _t0 = time.monotonic()
        with path.open("rb") as fh:
            fh.seek(start)
            text = fh.read().decode("utf-8")
    except (OSError, UnicodeDecodeError):
        return list(_iter_events(events_path)), False
    # T-12034 — THE PARSE GOES THROUGH THE ONE PARSER PRIMITIVE, and the physical read is reported.
    # This reader used to spell its own `for line in ...: json.loads(line)`, which is a second parse
    # path over the journal (CHARTER §P5 no-parallel-paths) AND an uncounted one: it is part of the
    # per-verb read FLOOR — measured ~20.4k rows on a bare `bin/yitc-v2 --help`, beside
    # `journal._tail_window_start`'s ~33.6k — so leaving it uninstrumented would have left the floor
    # exactly as invisible as it was. The BOUNDED branch keeps its own `note_fold` because the tail
    # read is genuinely its own physical read (it seeks past `start`); the UNBOUNDED branches above
    # delegate to `_iter_events` and are counted by the primitives underneath it, never twice here.
    #
    # THE ADMITTED SET IS UNCHANGED, which is what makes this a re-point and not a behaviour change:
    # `_rows_from_lines` skips an unparseable line exactly as the `json.DecodeError: continue` did,
    # a blank line strips to "" and is dropped by the same `if not line` filter kept below, and the
    # `isinstance(e, dict)` guard stays HERE rather than moving into the primitive (the primitive
    # deliberately returns every parsed value and leaves that judgement to each caller).
    lines = [ln for ln in (raw.strip() for raw in text.splitlines()) if ln]
    journal_mod.note_fold(path, len(lines), time.monotonic() - _t0)
    out = [e for e in journal_mod._rows_from_lines(lines) if isinstance(e, dict)]
    return out, True








def _run_view(view_path: "Path", index: dict, arg: "str | None" = None, since=None, until=None) -> None:
    """Execute a saved view's lens against the CURRENT index (recomputed fresh — D-0053: store the
    query, never the output, so the result can't go stale). `arg` is the optional second positional
    forwarded to a lens that takes a target (e.g. task-scorecard's T-XXXX); other lenses ignore it."""
    import yaml
    view = _read_yaml(view_path)
    lens = (view.get("lens") if isinstance(view, dict) else None) or {}
    kind = lens.get("kind")
    if kind == "node-list":
        nt = lens.get("node_type")
        if not _emit_node_list(index, nt):
            _die(f"view {view_path.name}: lens.node_type {nt!r} is not a known node type")
        return
    if kind == "verb-map":
        print(state.dump(_view_verb_map(index)).rstrip())
        return
    if kind == "binding-bundle":
        # T-9443: the specs carrying one binding token (e.g. before-project-dimension-judgement) —
        # membership read from the SAME verb_to_specs carrier the floor-trigger-map is built from.
        tok = lens.get("binding_token")
        if not tok:
            _die(f"view {view_path.name}: lens.binding_token required for kind binding-bundle")
        print(state.dump(_view_binding_bundle(index, tok)).rstrip())
        return
    if kind == "projection-currency":
        print(state.dump(_view_projection_currency(index)).rstrip())
        return
    if kind == "plans-pending-finalization":
        print(state.dump(_view_plans_pending_finalization(index)).rstrip())
        return
    if kind == "propagation-surfaces":
        # T-0668: an arg-taking lens (like task-scorecard) — `arg` is the SPEC id; reuses the existing
        # tasks_citing / code_to_specs reverse-index, no new store.
        print(state.dump(_view_propagation_surfaces(index, arg)).rstrip())
        return
    if kind == "postcheck-plans-readiness":
        print(state.dump(_view_postcheck_plans_readiness(index)).rstrip())
        return
    if kind == "token-rollup":
        print(state.dump(_view_token_rollup(index)).rstrip())
        return
    if kind == "trend-report":
        print(state.dump(_view_trend_report(index, since, until)).rstrip())
        return
    if kind == "task-scorecard":
        print(state.dump(_view_task_scorecard(index, arg)).rstrip())
        return
    if kind == "stage-profile":
        # T-12008: the per-stage AGGREGATE of task-scorecard over the tasks CLOSED in the window —
        # journal-reading and windowed by the SAME --since/--until pair trend-report established
        # (T-0396), not a second dialect. With neither bound the lens defaults to its own 14-day
        # window (see its docstring); an explicit window is honored as given.
        print(state.dump(_view_stage_profile(index, since, until)).rstrip())
        return
    if kind == "observation":
        # T-10123 (SPEC-0135): per-project provider×model×effort observation slices — a journal-reading
        # lens (session_started enriched fields) + the token-rollup cost lens. `arg` = optional project filter.
        print(state.dump(_view_observation(index, arg)).rstrip())
        return
    if kind == "observation-rollup":
        # T-10124 (SPEC-0135 §2/§4): the KERNEL cross-project worker×auditor PAIR rollup — a
        # registry-enumerating lens (reuses the read-only nightly._v2_projects scan, SPEC-0105 §2 seam)
        # reading each v2 project's events.jsonl. DERIVED review view, no stored state, NO gate/event.
        print(state.dump(_view_observation_rollup()).rstrip())
        return
    if kind == "displacement-retention":
        print(state.dump(_view_displacement_retention(index)).rstrip())
        return
    if kind == "triage-state":
        # T-0533: a journal-reading lens (per-capture routed-marker) — like displacement-retention it
        # reads EVENTS_PATH, not the index (the slim index lacks per-event ts/data; SPEC-0031).
        print(state.dump(_view_triage_state(EVENTS_PATH)).rstrip())
        return
    if kind == "journal-hygiene":
        # T-9738: a journal-reading digest lens (journal growth + untriaged-capture pressure) — like
        # triage-state / displacement-retention it reads EVENTS_PATH, not the index (per-event ts/data +
        # file size; SPEC-0031). Report-only; composes the existing readers, no new store.
        print(state.dump(_view_journal_hygiene(EVENTS_PATH)).rstrip())
        return
    if kind == "discipline-ratio":
        # T-0603: a journal-reading lens (kind-aware read-gate discipline ratio) — reads EVENTS_PATH for
        # the cli_invoked denominator + read_gate_refused numerator (per-event data; not in the index).
        # T-10361: WINDOWED — the shared --since/--until pair bounds the scan (trend-report semantics).
        print(state.dump(_view_discipline_ratio(EVENTS_PATH, since, until)).rstrip())
        return
    if kind == "outcome-ratio":
        # T-10361: the aggregate lifecycle-outcome lens (audits-per-close, first-pass-GREEN percent per
        # gate, deviations-per-close) — journal-reading like discipline-ratio, and windowed the same way.
        print(state.dump(_view_outcome_ratio(EVENTS_PATH, since, until)).rstrip())
        return
    if kind == "admission-series":
        # T-11047 / SPEC-0132 Rule 4: the PER-DAY verify-admission queueing series — journal-reading like
        # outcome-ratio and windowed by the same --since/--until pair. When the caller gives NO window it
        # defaults to the SEVEN days the rule governs, because the rule's unit IS a seven-day run: an
        # all-time reading cannot adjudicate "7 consecutive days" and would quietly answer a different
        # question. An explicit window is always honored as given.
        _since, _until = since, until
        if _since is None and _until is None:
            import datetime as _dt
            _now = _dt.datetime.now(_dt.timezone.utc)
            _since = _now - _dt.timedelta(days=7)
        print(state.dump(_view_admission_series(EVENTS_PATH, _since, _until)).rstrip())
        return
    if kind == "consult-postcheck":
        # T-12181 / SPEC-0200 rule 9: the ceiling-consult EPISODE fold — journal-reading like
        # outcome-ratio / admission-series and windowed by the same --since/--until pair, so a
        # windowed run is never mistaken for an all-time one.
        #
        # THE ONE REQUEST-SCOPED ReadScope FOR THIS SEAM (SPEC-0190 rule 10, T-12144's primitive
        # REUSED at a fourth wiring site — never a per-view cache, rule 10's named retirement). The
        # lens folds the whole logical journal once, and the same request's `_find_task_yaml` /
        # `_read_yaml` card reads sit behind `state.load_path`'s own memo; declaring the journal here
        # means the fold is charged ONCE for the request even when a composed caller has already read
        # it. `graph query` already reads well over its bound, so this branch adds no new fold to it.
        # Nothing survives the `with` — including after an exception — so no answer can move, only
        # the number of times the same bytes are read.
        with journal_mod.rows_memo([EVENTS_PATH]):
            print(state.dump(_view_consult_postcheck(EVENTS_PATH, since, until)).rstrip())
        return
    if kind == "audit-ceiling-clusters":
        # T-10742 / X-0587: the ceiling ROOT-CAUSE clustering — a decisions-corpus lens (reads the saved
        # audit records, not the index/journal), grouping ceiling cases by the per-pass finding_class tag,
        # split per gate. Report-only; recomputed fresh; writes nothing.
        print(state.dump(_view_ceiling_clusters()).rstrip())
        return
    if kind == "not-adopted":
        # T-9392 / SPEC-0094 §2: a journal+git lens (shipped-but-not-live) — reads EVENTS_PATH for the
        # latest deploy_completed revision + git ancestry to HEAD. `arg` is the optional project filter.
        print(state.dump(_view_not_adopted(EVENTS_PATH, arg)).rstrip())
        return
    if kind == "extensions-catalog":
        # T-9489 / SPEC-0101 rule 2: the DERIVED extensions catalog — a pure filter over the index
        # spec corpus (the `extension:`-marked specs), recomputed fresh on read. Discovered via
        # `graph query --type view`; this branch emits the per-entry adoptability + entry-points.
        print(state.dump(_view_extensions_catalog(index)).rstrip())
        return
    if kind == "overdue-recheck":
        # T-9394 / SPEC-0094 §3: a task-YAML-scanning lens (user-facing `none` waivers past recheck_by)
        # — the overdue-recheck_by revisit path raised at the weekly Review sweep (QUEUE §Re-review
        # triggers). DERIVED over the live_probe carrier + today; no stored state.
        print(state.dump(_view_overdue_recheck()).rstrip())
        return
    if kind == "test-orientation":
        # T-9720 / X-0140 Card 3: a yitc-ops.yaml-reading lens (the project's declared test rows bound to
        # their moment/layer — class×moment taxonomy + the moment:verify land layers). Read-only
        # orientation, DERIVED from the SPEC-0093 carrier; no stored state, NO gate, NO event.
        print(state.dump(_view_test_orientation()).rstrip())
        return
    if kind == "consumer-deploy-policy":
        # T-10047 / X-0187 / SPEC-0097: a registry-enumerating lens (each yitc_v2 CONSUMER's
        # deploy-autonomy stance side by side) — reuses the read-only nightly._v2_projects scan +
        # reads each consumer's yitc-ops.yaml. DERIVED review view, no stored state, NO gate/event.
        print(state.dump(_view_consumer_deploy_policy()).rstrip())
        return
    if kind == "mandatory-concern-gaps":
        # T-11016 / SPEC-0128 / SPEC-0093: the fleet-altitude "who owes what right now" read — every
        # registry yitc_v2 project with an UNANSWERED MANDATORY concern, without waiting for a session
        # to open there. Same registry-enumerating shape as consumer-deploy-policy; the stance comes
        # from the ONE `_ops_carrier_violations` evaluator the init sweep uses (P5). DERIVED, no stored
        # state, NO gate/event; mandatory-only, so an opt-in concern never manufactures debt.
        print(state.dump(_view_mandatory_concern_gaps()).rstrip())
        return
    if kind == "sandbox-family":
        # T-11018 / SPEC-0169 / SPEC-0172 / SPEC-0175 / X-0852: the sandbox question answered from ANY
        # ONE of its three concern key names — same registry-enumerating shape as mandatory-concern-gaps,
        # with the family MEMBERSHIP carried as the stored query (`lens.members`, the node-list
        # `lens.node_type` precedent) and everything else derived from the kernel concern registry on
        # read. Navigation only: DERIVED, no stored state, NO gate/event, and the opt-in `sandbox_entry`
        # gains no obligation.
        print(state.dump(_view_sandbox_family(lens.get("members"))).rstrip())
        return
    if kind == "capture-routing":
        # T-10539 / SPEC-0157: the situation->home routing table — a pure filter over the index spec
        # corpus (each row anchored to its owning spec's live title/status), recomputed fresh on read.
        # Discovered via `graph query --type view`; names the escalation-doc convention + env-facts
        # flavors. View over existing homes, no new store (D-0053 / CHARTER §P1).
        print(state.dump(_view_capture_routing(index)).rstrip())
        return
    _die(f"view {view_path.name}: unknown lens.kind {kind!r}")


def _node_source_path(nid: str, node_type: str, *, force_engine: bool=False):
    return graph._node_source_path(nid, node_type, force_engine=force_engine, ENGINE_ROOT=ENGINE_ROOT, LESSONS_DIR=LESSONS_DIR, PATTERNS_DIR=PATTERNS_DIR, SCENARIOS_DIR=SCENARIOS_DIR, _find_draft=_find_draft, _find_error_yaml=_find_error_yaml, _find_spec_path=_find_spec_path, _is_consumer_build=_is_consumer_build, _kernel_pattern_path=_kernel_pattern_path, _pattern_frontmatter=_pattern_frontmatter)


@contextlib.contextmanager
def _graph_query_read_scope(declare_journal: bool = False):
    """T-12204 (SPEC-0190 rule 10) — the ONE request-scoped ReadScope for the `graph query` seam.

    THE SHAPE IT REMOVES, MEASURED ON THIS REPO 2026-09-07: most of this verb's modes compose no
    journal view at all (a point lookup, `--projected`, `--carve-out`, `--type spec` and
    `--type view` each report `folds: 0` — there is nothing there for a scope to collapse). ONE mode
    composes more than one, and it is the whole finding: `--type error --recurring` calls THREE views
    — `_capture_fingerprint_counts`, `_capture_cluster_counts`, `_discovery_stem_clusters` — and the
    second and third each call the first internally. Each streams the WHOLE logical journal through
    `triage._scan_captures` -> `journal.segment_lines`, so one request folded all 98 segments THREE
    times: folds 294 / segments 98 = folds_per_segment 3.000, wall 16.3s. The live `cli_invoked`
    maximum for this verb that day was 296/98 — the same shape, in production.

    That is rule 10 exactly: three individually rule-4-correct views, each folding the same segment
    set for itself, and the seam paying the corpus three times. The remedy the rule names is ONE
    request-scoped ReadScope at the WIRING SITE — here, where the composition is decided — never a
    per-view cache (rule 10's named retirement (a)). ONE declaration buys every mode the verb
    dispatches, the `_debt_echo_lines` / `_advisory_read_scope` / `graph conformance` property.

    WHY THIS MEMO AND NOT `journal_mod.rows_memo`. Both were prototyped on the real corpus (98
    segments / 644k rows / 325 MB) and both hold the bound at 294 -> 98 folds. `rows_memo` costs peak
    RSS 153 MB -> 657 MB for wall 16.7s -> 14.6s, because `segment_lines` streams precisely so a
    325 MB journal is never materialised and nothing else in this scope has materialised it. The
    capture-scan RESULT memo holds the same bound at 152 MB (flat) and 16.7s -> 10.9s. It wins on
    both axes it does not tie on, so `rows_memo` is DELIBERATELY NOT installed here — the
    measured-omission precedent T-12144 set at the sibling `journal query` seam, for the same reason:
    a ReadScope is only free where the reader was going to read the whole declared journal anyway.

    IT IS NOT A CACHE: nothing survives the scope, it memoises its OWN reader's result and never a
    second reader (CHARTER §P5), and outside itself `_scan_captures` is a plain pass-through — so no
    answer this verb gives moves. The card side needs no scope: `state.load_path` is already
    memoised, so this seam's card parses sit at card_parse_ratio 1.0, at the floor already."""
    # T-12840: the seam's reads SPAN opens with its scope, so every caller of this wiring site — `main`
    # or the in-process stage-bundle render — is measured against this seam's own work.
    #
    # T-13108 — `declare_journal`: a SAVED VIEW is the one mode where the omission above does not
    # hold. `journal-hygiene` / `postcheck-plans-readiness` compose three STREAMING readers
    # (`triage._scan_captures`, `triage._last_triage_watermark`, the view's own `segment_lines`) and
    # `triage-state` calls the watermark twice, so each request streamed the whole journal 2-3 times
    # (consumer rows 2026-09-27: 3.00 / 3.00 / 2.00 folds per segment). They are three DIFFERENT
    # readers, so the capture-scan result memo cannot merge them; declaring the journal lets
    # `segment_lines` serve every stream after the first from one fold. No view uses the dispatch
    # tail reader, so the declaration changes no reader's path choice — the only price is holding
    # the journal's lines for the request, which is exactly what `session start` already does.
    with journal_mod.reads_span("graph query"):
        with triage.capture_scan_memo():
            if declare_journal:
                with journal_mod.rows_memo([EVENTS_PATH]):
                    yield
            else:
                yield


def cmd_graph_query(args: argparse.Namespace) -> None:
    # T-13108: declare the journal only for a SAVED-VIEW run — the same resolution graph.py makes
    # (`not want_kernel and view_path.exists()`; `--kernel` never runs a view).
    _nid = getattr(args, "id", None)
    _is_view = bool(_nid) and not getattr(args, "kernel", False) and \
        _kernel_content_file(f"views/{_nid}.yaml").exists()
    with _graph_query_read_scope(declare_journal=_is_view):
        return graph.cmd_graph_query(args, GRAPH_PATH=GRAPH_PATH, REPO_ROOT=REPO_ROOT, _anchor_file=_anchor_file, _carve_out_selection=_carve_out_selection, _cross_self=_cross_self, _die=_die, _emit_node_list=_emit_node_list, _engine_index=_engine_index, _find_error_yaml=_find_error_yaml, _find_spec_path=_find_spec_path, _graph_query_projected=_graph_query_projected, _graph_query_recurring=_graph_query_recurring, _is_consumer_build=_is_consumer_build, _kernel_content_file=_kernel_content_file, _list_views=_list_views, _load_index_as_of=_load_index_as_of, _node_source_path=_node_source_path, _parse_iso_utc=_parse_iso_utc, _read_yaml=_read_yaml, _report_graft_parse_errors=_report_graft_parse_errors, _run_view=_run_view, _with_live_nodes=_with_live_nodes)


# ---------------------------------------------------------------------------
# draft / idea lifecycle verbs (T-0061, per D-0034). Planning artifacts as tracked
# first-class entities: plans/<slug>.md (FSM draft→accepted→{realized|partial|rejected})
# + ideas/<slug>.md (flat, no FSM). Verb shape mirrors T-0056 task lifecycle verbs:
# load → mutate → atomic write → emit ONE event → D-0033 stdout reminder. Mid-state
# verbs AUTO-SYNC the journal by default (D-0049); they do NOT rebuild the graph (that stays
# with the heavier verbs). Discipline lives in patterns/plan-lifecycle.md
# (CHARTER §6 — V2 informs, не enforces); these verbs surface reminders, never gate.
# ---------------------------------------------------------------------------


def _split_frontmatter(path: Path) -> tuple[dict, str]:
    """Return (frontmatter_dict, body_text) for а markdown file with а leading ---/--- block.
    Same parse as _pattern_frontmatter but also returns the prose body. Dies on malformed
    frontmatter — draft verbs act on а single known file, so fail loud (unlike graph build
    which tolerates + reports across many files)."""
    try:
        return split_frontmatter_text(path.read_text(encoding="utf-8"))
    except ValueError as e:
        if e.__cause__ is None:
            _die(f"{path.name}: frontmatter is not a mapping")
        _die(f"{path.name}: malformed frontmatter: {e.__cause__}")


# T-13353 — the ONE frontmatter parse lives in state (release.py reads pattern frontmatter and cannot
# import cli); re-exported under its old name so every caller here is unchanged.
split_frontmatter_text = state.split_frontmatter_text


def _write_draft(path: Path, fm: dict, body: str) -> None:
    """Serialize frontmatter + body to а markdown file atomically; SPEC-0001 self-test on the
    frontmatter block (round-trips as а mapping with the same id)."""
    import yaml
    fm_text = state.dump(fm)
    try:
        rt = state.load_str(fm_text)
        if not isinstance(rt, dict) or rt.get("id") != fm.get("id"):
            _die("SPEC-0001 self-test failed: draft frontmatter did not round-trip cleanly")
    except yaml.YAMLError as e:
        _die(f"SPEC-0001 self-test failed: {e}")
    write_text_atomic(path, f"---\n{fm_text}---\n\n{body.rstrip()}\n")


def _plan_content_hash(body: str) -> str:
    """Content hash of a plan BODY — the freshness basis for the accept-gate (D-0034 amended
    T-0114 §B; NOT mtime/ts). `plan check` records it; `plan accept` recomputes + compares, so
    any edit since the check ⇒ hash mismatch ⇒ stale ⇒ refuse."""
    return hashlib.sha256(body.strip().encode("utf-8")).hexdigest()


def _find_draft(slug: str, dirs=None) -> Path | None:
    """Locate <slug>.md in plans/ then ideas/ (or the given dirs). Returns Path или None."""
    for d in (dirs or (PLANS_DIR, IDEAS_DIR)):
        p = d / f"{slug}.md"
        if p.exists():
            return p
    return None


def _load_draft(slug: str, dirs=None):
    """Validate slug shape, locate the file, parse it. Dies on bad slug / not-found.
    Returns (path, frontmatter, body)."""
    slug = (slug or "").strip()
    if not PLAN_SLUG_RE.match(slug):
        _die(f"slug must be kebab-case [a-z0-9-]; got {slug!r}")
    path = _find_draft(slug, dirs=dirs)
    if path is None:
        looked = ", ".join(str((d).relative_to(REPO_ROOT)) for d in (dirs or (PLANS_DIR, IDEAS_DIR)))
        _die(f"draft/idea not found: {slug} (looked in {looked})")
    fm, body = _split_frontmatter(path)
    return path, fm, body


