# ---------------------------------------------------------------------------
# T-0226 — `plan check` STRUCTURAL pre-pass (single normative home: SPEC-0012).
# Deterministic, local, REPORT-NOT-BLOCK (mirrors D-0036): the findings are recorded in the
# `plan check` verdict but NEVER flip the auditor verdict — they are the grep-able subset of the
# big-plan-checklist that no longer relies on a skippable manual memo (the T-0188 incident).
# TWO honestly-distinct halves: (i) REUSE the existing tree-resolvers for id/path resolution;
# (ii) a NARROW NEW prose-deferral validator (the declared new machinery, anti-cx F2 — bounded
# phrase set + tight carrier, NOT a general markdown-semantics engine).
# ---------------------------------------------------------------------------

# Fixed, small deferral phrase set (HIGH-1 (ii)) — the exact phrases the deferral rule names.
PLAN_DEFERRAL_PHRASES = ("deferred to part", "doctrinal-only-until", "until tooling")
_PLAN_ID_RE = re.compile(r"\b(?:T|SPEC|D)-\d{4,}\b")
_PLAN_DEPENDS_RE = re.compile(r"(?im)^\s*[-*]?\s*depends on:?\s*(.+?)\s*$")


def _plan_id_resolves(idstr: str) -> bool:
    """REUSE (HIGH-1 (i)): resolve a referenced T-/SPEC-/D-XXXX id against the live tree via the
    EXISTING finders — the D-0036 'resolve against the current tree, report-not-block' shape applied
    to plan refs (no parallel resolver).

    SPEC ids resolve via the SAME -C-aware `engine_fallback=True` path `graph query` uses (T-0860 /
    T-9203): under -C a kernel-provided spec absent from the consumer's specs/ still resolves from
    ENGINE_ROOT/specs, so a consumer task/plan citing a kernel spec (the normal case) no longer earns
    a false 'does not resolve' WARN. engine_fallback is a no-op unless `_is_consumer_build()` — so the
    engine's own pre-pass is byte-identical, and a genuinely non-existent SPEC id (absent in BOTH the
    consumer and engine corpora) still resolves to None → still WARNs (no-regression)."""
    if idstr.startswith("SPEC-"):
        return _find_spec_path(idstr, engine_fallback=True) is not None
    if idstr.startswith("T-"):
        return _find_task_yaml(idstr) is not None
    if idstr.startswith("D-"):
        return _find_decision_yaml(idstr) is not None
    return True


def _plan_unresolved_ids(body: str) -> list:
    """Each referenced T-/SPEC-/D-XXXX id that does NOT resolve against the live tree → one finding."""
    findings, seen = [], set()
    for m in _PLAN_ID_RE.finditer(body):
        idstr = m.group(0)
        if idstr in seen:
            continue
        seen.add(idstr)
        if not _plan_id_resolves(idstr):
            findings.append({
                "severity": "low", "source": "structural",
                "what": f"referenced id {idstr} does not resolve against the live tree",
                "where": f"plan body (id {idstr})",
                "fix": f"file/cite the real artifact for {idstr}, or correct the id "
                       "(D-0036 resolve-not-block)"})
    return findings


def _plan_unresolved_depends_paths(body: str) -> list:
    """REUSE (HIGH-1 (i)): each 'Depends on' code-path resolves against the live tree via the D-0036
    resolver (`_resolve_implements_anchor`, report-not-block). Path tokens = backtick-quoted, else
    whitespace/comma-split tokens that look like a path (contain '/')."""
    findings = []
    for m in _PLAN_DEPENDS_RE.finditer(body):
        rest = m.group(1)
        tokens = re.findall(r"`([^`]+)`", rest) or re.split(r"[\s,]+", rest)
        for tok in tokens:
            tok = tok.strip().strip("`'\".,")
            if "/" not in tok:
                continue
            warn = _resolve_implements_anchor(tok)
            if warn:
                findings.append({
                    "severity": "low", "source": "structural",
                    "what": f"'Depends on' code-path does not resolve: {warn}",
                    "where": "plan body ('Depends on' line)",
                    "fix": "correct the path/anchor or file the dependency (D-0036 resolve-not-block)"})
    return findings


def _plan_mapping_block_spans(body: str) -> list:
    """Char spans of every fenced block containing a `deliverables_mapping` key — the dedicated
    decomposition-mapping carrier (HIGH-2): inside such a block a deferral counts as tracked."""
    return [(m.start(), m.end())
            for m in re.finditer(r"```[a-zA-Z]*\n(.*?)```", body, flags=re.DOTALL)
            if "deliverables_mapping" in m.group(1)]


def _plan_prose_only_deferrals(body: str) -> list:
    """NEW narrow validator (HIGH-1 (ii) + HIGH-2): a fixed-phrase deferral is satisfied ONLY by a
    tracked id in the SAME bullet/paragraph OR inside a deliverables_mapping fenced block (the tight
    carrier — not free-form 'adjacent'; a tracked id in a DIFFERENT bullet does NOT satisfy it).
    Else → prose-only-deferral finding. Carrier unit = one bullet ITEM (a `-`/`*`/`N.` line + its
    wrapped continuation lines) OR a blank-line-separated non-bullet paragraph."""
    findings = []
    map_spans = _plan_mapping_block_spans(body)
    in_map = lambda pos: any(s <= pos < e for s, e in map_spans)
    lines = body.split("\n")
    offsets, acc = [], 0
    for ln in lines:                       # char offset of each line's start (lines join with \n)
        offsets.append(acc)
        acc += len(ln) + 1
    bullet_re = re.compile(r"^\s*(?:[-*]|\d+[.)])\s+")
    units, cur = [], []                    # each unit = a list of contiguous source line indices
    for i, ln in enumerate(lines):
        if not ln.strip():
            if cur:
                units.append(cur); cur = []
            continue
        if bullet_re.match(ln):
            if cur:
                units.append(cur)
            cur = [i]
        else:
            cur.append(i)
    if cur:
        units.append(cur)
    for idxs in units:
        text = "\n".join(lines[k] for k in idxs)
        low = text.lower()
        for phrase in PLAN_DEFERRAL_PHRASES:
            j = low.find(phrase)
            if j < 0:
                continue
            if _PLAN_ID_RE.search(text) or in_map(offsets[idxs[0]] + j):
                continue
            findings.append({
                "severity": "low", "source": "structural",
                "what": f"prose-only deferral ('{phrase}') with no tracked task/id carrier",
                "where": "plan body (deferral bullet/paragraph)",
                "fix": "carry the deferral as a tracked parked/blocked task (with return_trigger) in "
                       "the same bullet/paragraph or a deliverables_mapping block — never prose "
                       "(SPEC-0012)"})
    return findings


def _plan_unproven_named_targets(body: str) -> list:
    """NARROW (MED-4): ONLY inside a deliverables_mapping fenced block, an `artifact:` value that is
    neither a tracked id (T/SPEC/D) nor a resolvable path AND has no co-located `graph_query:` proof
    → finding. Bounded to the structured block so it is NOT citation-theater on free prose. Extends
    Stage-1 'cite the proof' (T-0133) to the F/3 lesson the id-resolve cannot catch (a NAMED but
    nonexistent target has no id to resolve)."""
    findings = []
    for m in re.finditer(r"```[a-zA-Z]*\n(.*?)```", body, flags=re.DOTALL):
        block = m.group(1)
        if "deliverables_mapping" not in block:
            continue
        lines = block.split("\n")
        for i, ln in enumerate(lines):
            am = re.match(r"\s*artifact:\s*(.+?)\s*$", ln)
            if not am:
                continue
            val = am.group(1).strip().strip("`'\"")
            if not val or val.lower() in ("none", "~", "null"):
                continue
            if _PLAN_ID_RE.fullmatch(val):
                continue
            if "/" in val and _resolve_implements_anchor(val) is None:
                continue
            window = "\n".join(lines[max(0, i - 3):i + 4])
            if "graph_query" in window:
                continue
            findings.append({
                "severity": "low", "source": "structural",
                "what": f"deliverables_mapping artifact '{val}' is a bare name (no tracked id / "
                        "resolvable path) and carries no graph_query existence proof",
                "where": "plan deliverables_mapping block",
                "fix": "map the deliverable to a tracked id/path, or cite a `graph_query:` proving "
                       "the named target exists (SPEC-0012; extends Stage-1 'cite the proof', T-0133)"})
    return findings


def _plan_structural_findings(slug: str, body: str) -> list:
    """T-0226 structural pre-pass aggregate (single normative home: SPEC-0012). Deterministic, local,
    REPORT-NOT-BLOCK — every finding is WARN-level (severity:low, source:structural) and is recorded
    in the `plan check` verdict but NEVER flips the auditor verdict (mirror of D-0036)."""
    return (_plan_unresolved_ids(body)
            + _plan_unresolved_depends_paths(body)
            + _plan_prose_only_deferrals(body)
            + _plan_unproven_named_targets(body))


# T-0320 — LARGE-plan `checklist_pass`-presence WARN. Extends the structural pre-pass family above
# (SPEC-0012; the big-plan self-traversal home is patterns/big-plan-checklist.md §Filing format) —
# NO new gate engine (CHARTER §P1; D-0033/D-0050: extend the verb that is "before X"). REPORT-NOT-BLOCK
# and LARGE-only, so it is gated at the `cmd_plan_check` call site where `large` is already computed,
